namespace WagePerks;

internal static class AddictOfficerEvent
{
	private const string NS = "addict_officer";

	private const string KEY_NEXT = "next_trigger_day";

	private const string KEY_GRUDGE = "grudge_flag";

	private const string KEY_LAST = "last_trigger_day";

	internal static void OnNewDay()
	{
		try
		{
			if (PlayerStore.Instance == null)
			{
				return;
			}
			int day = GetDay();
			if (WageSaveStore.GetBool("addict_officer", "grudge_flag"))
			{
				WageSaveStore.SetBool("addict_officer", "grudge_flag", value: false);
				RunInspection(day);
				return;
			}
			int num = WageSaveStore.GetInt("addict_officer", "next_trigger_day", -1);
			if (num < 0)
			{
				num = day + 3 + Core.Rng.Next(3);
				WageSaveStore.SetInt("addict_officer", "next_trigger_day", num);
			}
			if (day >= num && day != WageSaveStore.GetInt("addict_officer", "last_trigger_day", -1))
			{
				SpawnDisguisedOfficer(day);
				WageSaveStore.SetInt("addict_officer", "next_trigger_day", day + 2 + Core.Rng.Next(3));
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[AddictOfficer] OnNewDay失败: " + ex.Message);
		}
	}

	internal static void OnDayStartPostfix()
	{
		try
		{
			OnNewDay();
		}
		catch (Exception ex)
		{
			Core.LogMsg("[AddictOfficer] OnDayStart失败: " + ex.Message);
		}
	}

	private static void SpawnDisguisedOfficer(int day)
	{
		WageSaveStore.SetInt("addict_officer", "last_trigger_day", day);
		try
		{
			StoreClient val = StoreClientList.CreateFlexiBuyer();
			if (val == null)
			{
				Core.LogMsg("[AddictOfficer] 创建伪装客户失败");
				return;
			}
			try
			{
				val.isSecurity = false;
			}
			catch
			{
			}
			try
			{
				val.spriteName = SpriteDict.GetRandomLowerLevelSpriteName();
			}
			catch
			{
			}
			val.eventSourceId = "addict_officer";
			SetDialogue(val, LangHelper.T("一名神色疲惫的男子压低帽檐走入店内，眼神躲闪，似乎在寻找特殊货品。", "A weary man pulls his cap low, eyes darting as he scans for something special."));
			StoreClientManager storeClientManager = GetStoreClientManager();
			if (storeClientManager != null)
			{
				storeClientManager.AddClient(val);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[AddictOfficer] 伪装进店失败: " + ex.Message);
		}
	}

	internal static void OnClientArrived(StoreClient client)
	{
		try
		{
			if (client == null)
			{
				return;
			}
			string text = "";
			try
			{
				text = client.eventSourceId ?? "";
			}
			catch
			{
			}
			if (!(text != "addict_officer"))
			{
				if (HasNarcoticInShop())
				{
					SetDialogue(client, LangHelper.T("男子快速交易后迅速离开，街道一切如常。", "The man completes his deal quickly and slips away. All is quiet."));
					return;
				}
				WageSaveStore.SetBool("addict_officer", "grudge_flag", value: true);
				SetDialogue(client, LangHelper.T("对方扫视货架后一无所获，面色阴沉，默不作声离去，你隐隐感到不安。", "He scans the shelves, finds nothing, and leaves in grim silence. Unease settles in."));
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[AddictOfficer] 判定失败: " + ex.Message);
		}
	}

	private static void RunInspection(int day)
	{
		List<(GameItem, GameInventory, int)> list = new List<(GameItem, GameInventory, int)>();
		try
		{
			GameGridInventory hiddenElement = EmporiumEntry.Instance.hiddenElement;
			if (hiddenElement != null && ((GameInventory)hiddenElement).childItems != null)
			{
				for (int i = 0; i < ((GameInventory)hiddenElement).childItems.Count; i++)
				{
					GameItem val = ((GameInventory)hiddenElement).childItems[i];
					if (val == null)
					{
						continue;
					}
					try
					{
						int contrabandLevel = ContrabandHelper.GetContrabandLevel(val);
						if (contrabandLevel > 0)
						{
							list.Add((val, (GameInventory)(object)hiddenElement, contrabandLevel));
						}
					}
					catch (Exception ex)
					{
						Core.LogMsg("[AddictOfficerEvent] 异常: " + ex.Message);
					}
				}
			}
			Enumerator<GameItem> enumerator = EmporiumEntry.Instance.GetAllItems().GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null || !IsSmugglerBay(current))
				{
					continue;
				}
				GameInventory innerInventory = GetInnerInventory(current);
				if (innerInventory == null || innerInventory.childItems == null)
				{
					continue;
				}
				for (int j = 0; j < innerInventory.childItems.Count; j++)
				{
					GameItem val2 = innerInventory.childItems[j];
					if (val2 == null)
					{
						continue;
					}
					try
					{
						int contrabandLevel2 = ContrabandHelper.GetContrabandLevel(val2);
						if (contrabandLevel2 > 0)
						{
							list.Add((val2, innerInventory, contrabandLevel2));
						}
					}
					catch (Exception ex2)
					{
						Core.LogMsg("[AddictOfficerEvent] 异常: " + ex2.Message);
					}
				}
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[AddictOfficer] 扫描暗格/海报失败: " + ex3.Message);
		}
		List<(GameItem, GameInventory, int)> list2 = list.OrderByDescending(((GameItem item, GameInventory inv, int lvl) x) => x.lvl).Take(2).ToList();
		if (list2.Count == 0)
		{
			return;
		}
		foreach (var item in list2)
		{
			try
			{
				item.Item2.Expel(item.Item1);
			}
			catch (Exception ex4)
			{
				Core.LogMsg("[AddictOfficer] 没收失败: " + ex4.Message);
			}
		}
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null)
			{
				instance.AddNightLog(LangHelper.T("例行公务巡查！执勤警官严格检查了所有隐秘区域，从你的暗格中查获并没收了 " + list2.Count + " 件违禁品。", "Routine inspection! Officers searched hidden compartments and confiscated " + list2.Count + " contraband items."), "#7FC97F");
			}
		}
		catch
		{
		}
		Core.AddNightReportLine(LangHelper.T("例行公务巡查！执勤警官严格检查了所有隐秘区域，从你的暗格中查获并没收了 " + list2.Count + " 件违禁品。", "Routine inspection! Officers searched hidden compartments and confiscated " + list2.Count + " contraband items."));
	}

	private static bool HasNarcoticInShop()
	{
		try
		{
			Enumerator<GameItem> enumerator = EmporiumEntry.Instance.GetAllItems().GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				try
				{
					if (ChemicalFeedbackHelper.IsNarcotic(current))
					{
						return true;
					}
				}
				catch
				{
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[AddictOfficerEvent] 异常: " + ex.Message);
		}
		return false;
	}

	internal static bool IsSmugglerBay(GameItem item)
	{
		try
		{
			string identifier = item.identifier;
			if (!string.IsNullOrEmpty(identifier) && identifier.StartsWith("smuggler_bay"))
			{
				return true;
			}
		}
		catch
		{
		}
		try
		{
			if (item.IsTag("ITEM_HIDDEN_TAG") && item.IsTag("CONTAINER_TAG"))
			{
				return true;
			}
		}
		catch
		{
		}
		return false;
	}

	internal static GameInventory GetInnerInventory(GameItem container)
	{
		try
		{
			PixelWindow contentWindow = container.contentWindow;
			if (contentWindow == null)
			{
				return null;
			}
			try
			{
				object? obj = ((object)contentWindow).GetType().GetProperty("inventory", BindingFlags.Instance | BindingFlags.Public)?.GetValue(contentWindow);
				GameInventory val = (GameInventory)((obj is GameInventory) ? obj : null);
				if (val != null)
				{
					return val;
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[AddictOfficerEvent] 异常: " + ex.Message);
			}
			try
			{
				GameGridInventory containerGrid = ContainerUpgradeV2.GetContainerGrid(container);
				if (containerGrid != null)
				{
					return (GameInventory)(object)containerGrid;
				}
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[AddictOfficerEvent] 异常: " + ex2.Message);
			}
			return null;
		}
		catch
		{
			return null;
		}
	}

	private static StoreClientManager GetStoreClientManager()
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				return null;
			}
			return instance.storeClientManager;
		}
		catch
		{
			return null;
		}
	}

	private static void SetDialogue(StoreClient client, string text)
	{
		//IL_002d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0033: Expected Obj, but got Unknown
		try
		{
			string text2 = (client.displayName ?? "").Trim();
			if (client.mainDialogue != null)
			{
				client.mainDialogue.SetText(text2, text);
				return;
			}
			Dialogue val = new Dialogue();
			val.SetText(text2, text);
			client.mainDialogue = val;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[AddictOfficerEvent] 异常: " + ex.Message);
		}
	}

	private static int GetDay()
	{
		try
		{
			return StoreStation.GetDayCounter();
		}
		catch
		{
			return 1;
		}
	}

	private static string GetId(GameItem it)
	{
		try
		{
			return it.identifier ?? "?";
		}
		catch
		{
			return "?";
		}
	}
}
internal sealed class AlcoholMerchantPerk : CustomStartingPerk
{
	internal const string PerkId = "酒商之友";

	private static int _lastVisitDay = -1;

	private static int _berrySellCount = 0;

	internal override string Id => "酒商之友";

	internal override string DisplayName => LangHelper.T("酒商之友", "Alcohol Merchant Friend");

	internal override string Description => LangHelper.T("一位精明的收酒商每周第 6 天准时登门，专门收购你自酿的各类美酒，出价公道。他同时售卖优质酿酒原料——精选葡萄、特级酵母和纯净水源，助你酿出更好的酒。下层区的酒鬼们都等着你的佳酿，而这位收酒商就是你最好的合作伙伴。选择此特性，收酒商每周第 6 天到访，高价收购你的自酿酒并售卖酿酒原料。", "A shrewd wine buyer visits every week on day 6, specializing in purchasing your homemade wines at fair prices. He also sells quality brewing supplies - premium grapes, super yeast, and pure water to help you craft better wines. Drunks in the lower levels are waiting for your brew, and this buyer is your best partner. Choose this perk: the wine buyer arrives on day 6 of each week, buying your homemade wines at good prices and selling brewing supplies.");

	internal override int Cost => 2;

	internal override int Type => 0;

	private static int VISIT_INTERVAL => BuildConfig.AlcoholVisitInterval;

	internal override void OnNewGame()
	{
		_lastVisitDay = -1;
	}

	internal static bool IsActive()
	{
		return Core.PerkActive("酒商之友");
	}

	internal static bool ShouldVisitToday(int currentDay)
	{
		int num = ((VISIT_INTERVAL > 0) ? VISIT_INTERVAL : 7);
		return currentDay % num == 6 % num;
	}

	internal static void RecordVisit(int currentDay)
	{
		_lastVisitDay = currentDay;
	}

	internal static void ForceVisit()
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				Core.LogMsg("[酒商] ForceVisit: PlayerStore为空");
			}
			else
			{
				instance.QueueFuturClient("retired_winemaker", 0);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[酒商] ForceVisit异常: " + ex.Message);
		}
	}

	internal static List<string> GenerateItems()
	{
		return MerchantHelper.GenerateCardLockPairs();
	}

	internal static void AddSpecialSellItems()
	{
		try
		{
			if (PlayerStore.Instance == null)
			{
				Core.LogMsg("[酒商] PlayerStore.Instance为null，无法添加售卖");
				return;
			}
			int num = 0;
			string[] array = new string[3] { "wine_yeast", "wine_superyeast", "bottled_water" };
			for (int i = 0; i < 3; i++)
			{
				try
				{
					GameItem val = DirectoryMaster.Item("wine_berry", true);
					if (val == null)
					{
						Core.LogMsg("[酒商] 加葡萄 wine_berry 不存在(null)");
						break;
					}
					_berrySellCount++;
					int num2 = 10;
					try
					{
						WineHelper.InitBerry(val);
					}
					catch
					{
					}
					try
					{
						WineHelper.SetBerryCondition(val, num2, 0);
					}
					catch
					{
					}
					if (MerchantHelper.AddItemToCounter(val, 100) != null)
					{
						num++;
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[酒商] 加葡萄失败: " + ex.Message);
				}
			}
			string[] array2 = array;
			foreach (string text in array2)
			{
				try
				{
					GameItem val2 = DirectoryMaster.Item(text, true);
					if (val2 == null)
					{
						Core.LogMsg("[酒商] 加酒 " + text + " 不存在(null)");
						continue;
					}
					if (text == "bottled_water")
					{
						GameItem val3 = null;
						try
						{
							FoodItemDirectory val4 = Object.FindObjectOfType<FoodItemDirectory>();
							if ((Object)(object)val4 != (Object)null)
							{
								val3 = ((Directory<GameItem>)(object)val4).Create("bottled_water");
							}
						}
						catch
						{
						}
						if (val3 == null)
						{
							val3 = DirectoryMaster.Item("bottled_water", true);
						}
						if (val3 != null)
						{
							try
							{
								WaterHelper.FillWithHighQualityWater(val3);
							}
							catch
							{
							}
							val2 = val3;
						}
					}
					if (string.IsNullOrEmpty(val2.name))
					{
						string fallbackName = GetFallbackName(text);
						if (fallbackName != null)
						{
							try
							{
								GeneralHelper.SetCustomName(val2, fallbackName);
							}
							catch
							{
							}
						}
					}
					if (MerchantHelper.AddItemToCounter(val2, 100) != null)
					{
						num++;
					}
				}
				catch (Exception ex2)
				{
					Core.LogMsg("[酒商] 加酒 " + text + " 失败: " + ex2.Message);
				}
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[酒商] AddSpecialSellItems 失败: " + ex3.Message + "\n" + ex3.StackTrace);
		}
	}

	private static string GetFallbackName(string id)
	{
		return id switch
		{
			"wine_berry" => LangHelper.T("莓果酿", "Berry Wine"), 
			"wine_bottle" => LangHelper.T("酒瓶", "Wine Bottle"), 
			"beer_case" => LangHelper.T("一箱啤酒", "Case of Beer"), 
			"red_beer" => LangHelper.T("红魔鬼啤酒", "Red Devil Beer"), 
			"empty_beer_bottle" => LangHelper.T("空啤酒瓶", "Empty Beer Bottle"), 
			"wine_superyeast" => LangHelper.T("超级酵母", "Super Yeast"), 
			"wine_yeast" => LangHelper.T("酿酒酵母", "Brewing Yeast"), 
			"wine_yeast_infinite" => LangHelper.T("永续酵母", "Perpetual Yeast"), 
			"wine_yeast_red" => LangHelper.T("红酵母", "Red Yeast"), 
			"permit_gun_1" => LangHelper.T("枪支许可证（一级）", "Gun Permit (Tier 1)"), 
			"permit_gun_2" => LangHelper.T("枪支许可证（二级）", "Gun Permit (Tier 2)"), 
			"permit_gun_3" => LangHelper.T("枪支许可证（三级）", "Gun Permit (Tier 3)"), 
			"blank_keycard" => LangHelper.T("空白钥匙卡", "Blank Keycard"), 
			_ => null, 
		};
	}
}
