internal static class BatchDragUpgrade
{
	private static readonly List<GameItem> _pending = new List<GameItem>();

	private static GameItem _target = null;

	private static bool _armed = false;

	public static void PrefixEndGroupDrag(ItemMultiSelectHandler __instance)
	{
		try
		{
			Core.LogMsg("[批量升级] Prefix 触发");
			_pending.Clear();
			_target = null;
			_armed = false;
			GameItem val = null;
			try
			{
				val = __instance.hoverItem;
			}
			catch
			{
			}
			if (val == null)
			{
				return;
			}
			bool flag = false;
			bool flag2 = false;
			bool flag3 = false;
			try
			{
				flag = DestinyDice.IsDice(val);
			}
			catch
			{
			}
			try
			{
				flag2 = ContainerUpgradeV2.IsWageBox(val);
			}
			catch
			{
			}
			try
			{
				flag3 = LuckScoutBackpackUpgrade.IsBead(val);
			}
			catch
			{
			}
			if (!flag && !flag2 && !flag3)
			{
				return;
			}
			List<GameItemElement> selectedItems = __instance.selectedItems;
			if (selectedItems == null)
			{
				Core.LogMsg("[批量升级] selectedItems 为 null");
				return;
			}
			Core.LogMsg("[批量升级] selectedItems 数量=" + selectedItems.Count);
			Enumerator<GameItemElement> enumerator = selectedItems.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItemElement current = enumerator.Current;
				try
				{
					GameItem val2 = (GameItem)(object)current;
					if (val2 != null && !(((Il2CppObjectBase)val2).Pointer == ((Il2CppObjectBase)val).Pointer))
					{
						_pending.Add(val2);
					}
				}
				catch
				{
				}
			}
			if (_pending.Count != 0)
			{
				_target = val;
				_armed = true;
				Core.LogMsg("[批量升级] 识别目标: " + val.identifier + " 待吸收 " + _pending.Count + " 件");
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[批量升级] Prefix 异常: " + ex.Message);
			_armed = false;
			_pending.Clear();
			_target = null;
		}
	}

	public static void PostfixEndGroupDrag(ItemMultiSelectHandler __instance)
	{
		if (!_armed)
		{
			return;
		}
		try
		{
			if (_target == null || _pending.Count == 0)
			{
				return;
			}
			int num = 0;
			int num2 = 0;
			try
			{
				LuckScoutBackpackUpgrade.ClearDebounce();
			}
			catch
			{
			}
			foreach (GameItem item in _pending)
			{
				try
				{
					if (DestinyDice.IsDice(_target))
					{
						DestinyDice.AbsorbItem(_target, item);
						num++;
					}
					else if (ContainerUpgradeV2.IsWageBox(_target))
					{
						if (!ContainerUpgradeV2.IsNuts(item))
						{
							num2++;
						}
						else if (ContainerUpgradeV2.ConsumeNutsDirectly(_target, item))
						{
							num++;
						}
						else
						{
							num2++;
						}
					}
					else
					{
						if (!LuckScoutBackpackUpgrade.IsBead(_target))
						{
							continue;
						}
						if (!LuckScoutBackpackUpgrade.IsJunk(item))
						{
							num2++;
							continue;
						}
						try
						{
							LuckScoutBackpackUpgrade.ClearDebounce();
						}
						catch
						{
						}
						if (LuckScoutBackpackUpgrade.DoUpgrade(item, _target))
						{
							num++;
						}
						else
						{
							num2++;
						}
						continue;
					}
				}
				catch (Exception ex)
				{
					num2++;
					Core.LogMsg("[批量升级] 单件失败: " + ((item != null) ? item.identifier : "null") + " - " + ex.Message);
				}
			}
			Core.LogMsg("[批量升级] 完成: 成功 " + num + " 失败 " + num2);
			try
			{
				_target.SyncModifiedState();
			}
			catch
			{
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[批量升级] Postfix 异常: " + ex2.Message);
		}
		finally
		{
			_armed = false;
			_pending.Clear();
			_target = null;
		}
	}

	public static Exception FinalizerEndGroupDrag(ItemMultiSelectHandler __instance, Exception __exception)
	{
		_armed = false;
		_pending.Clear();
		_target = null;
		if (__exception != null)
		{
			Core.LogMsg("[批量升级] Finalizer 兜住异常: " + __exception.Message);
			return null;
		}
		return null;
	}
}
