	private static List<GameItem> CollectBatteries()
	{
		List<GameItem> list = new List<GameItem>();
		try
		{
			List<GameItem> list2 = new List<GameItem>();
			try
			{
				List<GameItem> val = PlayerStore.Instance.FindAllItem(true);
				if (val != null)
				{
					Enumerator<GameItem> enumerator = val.GetEnumerator();
					while (enumerator.MoveNext())
					{
						GameItem current = enumerator.Current;
						if (current != null)
						{
							list2.Add(current);
						}
					}
				}
			}
			catch
			{
			}
			foreach (GameItem item in list2)
			{
				if (item == null || !RobinCrusoePerk.IsMachine(item))
				{
					continue;
				}
				string text = "";
				try
				{
					text = item.identifier ?? "";
				}
				catch
				{
				}
				if (text != "wage_gu_machine")
				{
					continue;
				}
				GameGridInventory guGrid = GuMachineSystem.GetGuGrid(item);
				if (guGrid == null || ((GameInventory)guGrid).childItems == null)
				{
					continue;
				}
				Enumerator<GameItem> enumerator3 = ((GameInventory)guGrid).childItems.GetEnumerator();
				while (enumerator3.MoveNext())
				{
					GameItem current3 = enumerator3.Current;
					if (current3 != null)
					{
						bool flag = false;
						try
						{
							flag = current3.IsTag("power_source_item");
						}
						catch
						{
						}
						if (flag)
						{
							list.Add(current3);
						}
					}
				}
			}
		}
		catch
		{
		}
		return list;
	}

	private static int BatteryScore(GameItem b)
	{
		int num = 0;
		try
		{
			num += RobinCrusoePerk.GetTagIntSafe(b, "power_source_item_energy");
		}
		catch
		{
		}
		try
		{
			num += RobinCrusoePerk.GetTagIntSafe(b, "power_source_item_max_energy");
		}
		catch
		{
		}
		try
		{
			num += RobinCrusoePerk.GetTagIntSafe(b, "power_source_item_recharge");
		}
		catch
		{
		}
		try
		{
			num += (int)b.unitBaseValue;
		}
		catch
		{
		}
		return num;
	}

	private static int BatteryDim(GameItem b)
	{
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		try
		{
			num = RobinCrusoePerk.GetTagIntSafe(b, "power_source_item_energy");
		}
		catch
		{
		}
		try
		{
			num2 = RobinCrusoePerk.GetTagIntSafe(b, "power_source_item_max_energy");
		}
		catch
		{
		}
		try
		{
			num3 = RobinCrusoePerk.GetTagIntSafe(b, "power_source_item_recharge");
		}
		catch
		{
		}
		if (num >= num2 && num >= num3)
		{
			return 0;
		}
		if (num2 >= num && num2 >= num3)
		{
			return 1;
		}
		if (num3 >= num && num3 >= num2)
		{
			return 2;
		}
		return 3;
	}

	private static void TrySelfRecharge()
	{
		try
		{
			List<GameItem> allRechargeableBatteries = GetAllRechargeableBatteries();
			if (allRechargeableBatteries.Count == 0)
			{
				return;
			}
			int num = 0;
			foreach (GameItem item in allRechargeableBatteries)
			{
				int num2 = ChargeOneBattery(item);
				num += num2;
			}
			if (num > 0)
			{
				NotifyHelper.NightLogRaw("自充电：" + allRechargeableBatteries.Count + " 块电池 +" + num + " 电量");
				Core.LogMsg("[电池] 自充电: " + allRechargeableBatteries.Count + " 块 +" + num + " 电量");
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[电池] 自充电异常: " + ex.Message);
		}
	}

	private static List<GameItem> GetAllRechargeableBatteries()
	{
		List<GameItem> list = new List<GameItem>();
		try
		{
			Enumerator<GameItem> enumerator = EmporiumEntry.Instance.GetAllItems().GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				try
				{
					if (!current.IsTag("BREEDER_POWER_SOURCE_ITEM_TAG"))
					{
						continue;
					}
				}
				catch
				{
					continue;
				}
				list.Add(current);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[BatteryCannibalism] 异常: " + ex.Message);
		}
		return list;
	}

	private static int ChargeOneBattery(GameItem bat)
	{
		try
		{
			int num = TagHelper.GetInt(bat, "power_source_item_energy");
			int num2 = TagHelper.GetInt(bat, "power_source_item_max_energy");
			int num3 = TagHelper.GetInt(bat, "power_source_item_recharge");
			if (num3 <= 0)
			{
				return 0;
			}
			if (num >= num2)
			{
				return 0;
			}
			int num4 = Math.Min(num2, num + num3);
			int result = num4 - num;
			TagHelper.SetInt(bat, "power_source_item_energy", num4);
			return result;
		}
		catch
		{
			return 0;
		}
	}
}
