	private static string GetStr(string key, string def)
	{
		try
		{
			return MelonPreferences.GetEntryValue<string>("WagesPerks", key);
		}
		catch
		{
			return def;
		}
	}

	private static int[] ParseIntList(string s)
	{
		List<int> list = new List<int>();
		try
		{
			string[] array = s.Split(',');
			for (int i = 0; i < array.Length; i++)
			{
				if (int.TryParse(array[i].Trim(), out var result))
				{
					list.Add(result);
				}
			}
		}
		catch
		{
		}
		return list.ToArray();
	}

	private static int[] PadToLast(int[] arr, int minLen)
	{
		if (arr.Length >= minLen)
		{
			return arr;
		}
		List<int> list = new List<int>(arr);
		int item = ((arr.Length != 0) ? arr[^1] : 0);
		while (list.Count < minLen)
		{
			list.Add(item);
		}
		return list.ToArray();
	}

	private static float GetFloat(string key, float def)
	{
		try
		{
			return MelonPreferences.GetEntryValue<float>("WagesPerks", key);
		}
		catch
		{
			return def;
		}
	}

	private static int GetInt(string key, int def)
	{
		try
		{
			return MelonPreferences.GetEntryValue<int>("WagesPerks", key);
		}
		catch
		{
			return def;
		}
	}

	private static int FenceCountKey(string key, string defStr, int idx)
	{
		try
		{
			int[] array = ParseIntList(GetStr(key, defStr));
			if (array.Length > idx)
			{
				return array[idx];
			}
			int[] array2 = ParseIntList(defStr);
			return (array2.Length <= idx) ? 1 : array2[idx];
		}
		catch
		{
			return 1;
		}
	}
}
internal static class CompatibilityPatches
{
	private static readonly Dictionary<StoreClient, int> _origBudget = new Dictionary<StoreClient, int>();

	public static void PostfixGetNegociatedValue(GameItem __instance, ref long __result)
	{
		try
		{
			if (BuildConfig.CompatTradeClamp && __result < 0)
			{
				Core.LogMsg("[兼容] 价格兜底: " + __result + " → 0 (" + __instance.identifier + ")");
				__result = 0L;
			}
		}
		catch
		{
		}
	}

	public static void PrefixApplyBudgetModifier(StoreClient __instance)
	{
		try
		{
			if (__instance != null)
			{
				_origBudget[__instance] = __instance.clientBudget;
			}
		}
		catch
		{
		}
	}

	public static void PostfixApplyBudgetModifier(StoreClient __instance)
	{
		try
		{
			if (__instance != null && _origBudget.TryGetValue(__instance, out var value))
			{
				_origBudget.Remove(__instance);
				if (BuildConfig.CompatBudgetRestore && value > 0 && __instance.clientBudget <= 0)
				{
					Core.LogMsg("[兼容] 预算兜底: " + __instance.clientBudget + " → " + value + " (客户=" + __instance.identifier + ")");
					__instance.clientBudget = value;
				}
			}
		}
		catch
		{
		}
	}
}
internal static class ContainerShapeHelper
{
	public static int GetTargetWidth(int origW, int stage)
	{
		if (origW <= 0)
		{
			return 0;
		}
		return (int)((double)origW * (0.5 + 0.3 * (double)stage));
	}

	public static void RestoreToStage(GameItem box, int stage)
	{
		try
		{
			if (box == null)
			{
				return;
			}
			GameGridInventory containerGrid = GetContainerGrid(box);
			if (containerGrid != null)
			{
				int targetWidth = GetTargetWidth(GetOrigWidth(box), stage);
				int height = containerGrid.inventoryShape.height;
				if (containerGrid.inventoryShape.width != targetWidth)
				{
					SetFullRect(containerGrid, targetWidth, height);
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ContainerShapeHelper] 异常: " + ex.Message);
		}
	}

	private static GameGridInventory GetContainerGrid(GameItem box)
	{
		try
		{
			PixelWindow contentWindow = box.contentWindow;
			if (contentWindow == null || contentWindow.childElement == null)
			{
				return null;
			}
			return ((Il2CppObjectBase)contentWindow.childElement).TryCast<GameGridInventory>();
		}
		catch
		{
			return null;
		}
	}

	private static int GetOrigWidth(GameItem box)
	{
		try
		{
			return ContainerUpgradeV2.GetTagIntSafe(box, "wb_orig_w");
		}
		catch
		{
			return 0;
		}
	}

	private static void SetFullRect(GameGridInventory grid, int w, int h)
	{
		try
		{
			grid.SetShape(new string('0', w * h), w);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ContainerShapeHelper] 异常: " + ex.Message);
		}
	}
}
