			{
				return false;
			}
			if (item.IsTag("CUSTOM_STORAGE_TAG"))
			{
				return true;
			}
			if (item.IsTag("WAGE_BOX_TAG"))
			{
				return true;
			}
			if (item.IsTag("wage_box_type"))
			{
				return true;
			}
			return (item.identifier ?? "").ToLowerInvariant() == "custom_storage_box";
		}
