	public static bool IsUpgradeableContainer(GameItem item)
	{
		try
		{
			if (item == null)
			{
				return false;
			}
			if (!BuildConfig.ContainerUpgradeEnabled)
			{
				return false;
			}
			if (IsExcludedContainer(item))
			{
				return false;
			}
			if (item.IsTag("VOID_BEAD_TAG") || IsWageBox(item))
			{
				return false;
			}
			if (IsVoidBeadStorage(item))
			{
				return false;
			}
			try
			{
				if (item.IsTag("CONTAINER_TAG"))
				{
					return true;
				}
			}
			catch
			{
			}
			return IsBuildingContainerId(item.identifier ?? "");
		}
		catch
		{
			return false;
		}
	}

