	public static void RestoreWageBoxShape(GameItem box)
	{
		try
		{
			if (box == null)
			{
				return;
			}
			GameGridInventory containerGrid = GetContainerGrid(box);
			if (containerGrid == null)
			{
				return;
			}
			int w = 0;
			int h = 0;
			GetShapeWH(containerGrid, ref w, ref h);
			if (w <= 0 || h <= 0)
			{
				return;
			}
			bool flag = box.IsTag("wb_stage");
			int num = GetTagIntSafe(box, "wb_stage");
			if (!flag)
			{
				if (w > WAGE_BOX_W[0] || h > WAGE_BOX_H[0])
				{
					num = MAX_STAGE;
					SetTagIntValue(box, "wb_stage", MAX_STAGE);
				}
				else
				{
					num = 0;
					SetTagIntValue(box, "wb_stage", 0);
				}
			}
			if (num < 0)
			{
				num = 0;
			}
			if (num > MAX_STAGE)
			{
				num = MAX_STAGE;
			}
			if (num >= MAX_STAGE && !box.IsTag("wb_second_given"))
			{
				TryGiveSecondWageBox(box);
			}
			int num2 = WAGE_BOX_W[num];
			int num3 = WAGE_BOX_H[num];
			if (w != num2 || h != num3)
			{
				SetFullRect(containerGrid, num2, num3);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ContainerUpgradeV2] 异常: " + ex.Message);
		}
	}

	public static int FindBoxInHidden(GameItem box)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || box == null)
			{
				return -1;
			}
			GameGridInventory hiddenElement = instance.hiddenElement;
			if (hiddenElement == null || ((GameInventory)hiddenElement).childItems == null)
			{
				return -1;
			}
			for (int i = 0; i < ((GameInventory)hiddenElement).childItems.Count; i++)
			{
				if (((GameInventory)hiddenElement).childItems[i] != null && ((Il2CppObjectBase)((GameInventory)hiddenElement).childItems[i]).Pointer == ((Il2CppObjectBase)box).Pointer)
				{
					return i;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ContainerUpgradeV2] 异常: " + ex.Message);
		}
		return -1;
	}

