	public static void RestoreWageBoxToStage(GameItem box, int stage)
	{
		try
		{
			if (box == null || stage <= 0)
			{
				return;
			}
			GameGridInventory containerGrid = GetContainerGrid(box);
			if (containerGrid == null)
			{
				return;
			}
			int w = 0;
			int h = 0;
			GetShapeWH(containerGrid, ref w, ref h);
			if (w <= 0 || h <= 0)
			{
				return;
			}
			if (stage > MAX_STAGE)
			{
				stage = MAX_STAGE;
			}
			int num = WAGE_BOX_W[stage];
			int num2 = WAGE_BOX_H[stage];
			if (w == num && h == num2)
			{
				return;
			}
			SetFullRect(containerGrid, num, num2);
			try
			{
				SetTagIntValue(box, "wb_stage", stage);
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ContainerUpgradeV2] 异常: " + ex.Message);
		}
	}

	public static int GetCrusoeTargetWidth(int origW, int stage)
	{
		try
		{
			if (origW <= 0)
			{
				return 1;
			}
			int num = Math.Max(0, Math.Min(MAX_STAGE, stage));
			return Math.Max(1, (int)Math.Floor((double)origW * (0.5 + 0.3 * (double)num)));
		}
		catch
		{
			return 1;
		}
	}

	public static bool RestoreCrusoeShape(GameItem box)
	{
		try
		{
			if (box == null)
			{
				return false;
			}
			GameGridInventory containerGrid = GetContainerGrid(box);
			if (containerGrid == null)
			{
				return false;
			}
			int w = 0;
			int h = 0;
			GetShapeWH(containerGrid, ref w, ref h);
			if (w <= 0 || h <= 0)
			{
				return false;
			}
			bool flag = box.IsTag("wb_stage");
			int num = GetTagIntSafe(box, "wb_stage");
			int num2 = GetTagIntSafe(box, "wb_orig_w");
			if (!flag)
			{
				if (GetTagIntSafe(box, "wageUpgradeCap") <= 0)
				{
					return false;
				}
				num = MAX_STAGE;
				SetTagIntValue(box, "wb_stage", MAX_STAGE);
				if (num2 <= 0)
				{
					num2 = w;
					SetTagIntValue(box, "wb_orig_w", w);
				}
			}
			int num3 = ((num2 <= 0) ? (w + num) : GetCrusoeTargetWidth(num2, num));
			if (w == num3)
			{
