	public static void ConsumeNutsAtClose()
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			Core.LogMsg("[妙妙箱] ConsumeNutsAtClose Prefix 跑了, emporium=" + ((Object)(object)instance != (Object)null));
			if ((Object)(object)instance == (Object)null)
			{
				return;
			}
			List<GameInventory> list = new List<GameInventory>();
			try
			{
				GameInventory backInvinvElement = (GameInventory)(object)instance.backInvinvElement;
				if (backInvinvElement != null)
				{
					list.Add(backInvinvElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory backInvinvElementCounter = (GameInventory)(object)instance.backInvinvElementCounter;
				if (backInvinvElementCounter != null)
				{
					list.Add(backInvinvElementCounter);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory showcaseElement = (GameInventory)(object)instance.showcaseElement;
				if (showcaseElement != null)
				{
					list.Add(showcaseElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory invElement = (GameInventory)(object)instance.invElement;
				if (invElement != null)
				{
					list.Add(invElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory frontInvinvElement = (GameInventory)(object)instance.frontInvinvElement;
				if (frontInvinvElement != null)
				{
					list.Add(frontInvinvElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory hiddenElement = (GameInventory)(object)instance.hiddenElement;
				if (hiddenElement != null)
				{
					list.Add(hiddenElement);
				}
			}
			catch
			{
			}
			HashSet<IntPtr> hashSet = new HashSet<IntPtr>();
			Stack<GameInventory> stack = new Stack<GameInventory>(list);
			while (stack.Count > 0)
			{
				GameInventory val = stack.Pop();
				if (val == null || val.childItems == null)
				{
					continue;
				}
				for (int i = 0; i < val.childItems.Count; i++)
				{
					GameItem val2 = val.childItems[i];
					if (val2 != null)
					{
						if (!hashSet.Contains(((Il2CppObjectBase)val2).Pointer))
						{
							hashSet.Add(((Il2CppObjectBase)val2).Pointer);
						}
						if (IsWageBox(val2))
						{
							ConsumeNutsInBox(val2);
						}
						GameGridInventory containerGrid = GetContainerGrid(val2);
						if (containerGrid != null && !hashSet.Contains(((Il2CppObjectBase)containerGrid).Pointer))
						{
							hashSet.Add(((Il2CppObjectBase)containerGrid).Pointer);
							stack.Push((GameInventory)(object)containerGrid);
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ContainerUpgradeV2] 异常: " + ex.Message);
		}
	}

	private static void ConsumeNutsInBox(GameItem box)
	{
		try
		{
			int num = GetTagIntSafe(box, "wb_stage");
			if (num >= MAX_STAGE)
			{
				return;
			}
			GameGridInventory containerGrid = GetContainerGrid(box);
			if (containerGrid == null || ((GameInventory)containerGrid).childItems == null)
			{
				return;
			}
			List<GameItem> list = new List<GameItem>();
			for (int i = 0; i < ((GameInventory)containerGrid).childItems.Count; i++)
			{
				GameItem val = ((GameInventory)containerGrid).childItems[i];
				if (val != null && IsNuts(val))
				{
					list.Add(val);
				}
			}
			if (list.Count == 0)
			{
				return;
			}
			int tagIntSafe = GetTagIntSafe(box, "wb_progress");
			int num2 = UPGRADE_COSTS[num];
			int num3 = 0;
			for (int j = 0; j < list.Count; j++)
			{
				try
				{
					ConsumeOne(list[j]);
					num3++;
				}
				catch
				{
				}
			}
			tagIntSafe += num3;
			while (tagIntSafe >= num2 && num < MAX_STAGE)
			{
				int w = WAGE_BOX_W[num + 1];
				int h = WAGE_BOX_H[num + 1];
				SetFullRect(containerGrid, w, h);
				AddTagInt(box, "wb_stage", 1);
				tagIntSafe -= num2;
				num++;
				num2 = UPGRADE_COSTS[Math.Min(num, MAX_STAGE - 1)];
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("妙妙箱升级！段位 " + num + "/5", "Wage Box upgraded! Stage " + num + "/5"), "white");
				}
				catch
				{
				}
			}
			SetTagIntValue(box, "wb_progress", tagIntSafe);
			if (num >= MAX_STAGE)
			{
				TryGiveSecondWageBox(box);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ContainerUpgradeV2] 异常: " + ex.Message);
		}
	}

	internal static bool ConsumeNutsDirectly(GameItem box, GameItem nuts)
	{
		try
		{
			int tagIntSafe = GetTagIntSafe(box, "wb_stage");
			if (tagIntSafe >= MAX_STAGE)
			{
				return false;
			}
			GameGridInventory containerGrid = GetContainerGrid(box);
			if (containerGrid == null)
			{
				return false;
			}
			ConsumeOne(nuts);
			int num = GetTagIntSafe(box, "wb_progress") + 1;
			int num2 = UPGRADE_COSTS[tagIntSafe];
			if (num < num2)
			{
				SetTagIntValue(box, "wb_progress", num);
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("妙妙箱升级进度 " + num + "/" + num2, "Wage Box progress " + num + "/" + num2), "white");
				}
				catch
				{
				}
				return true;
			}
			int w = WAGE_BOX_W[tagIntSafe + 1];
			int h = WAGE_BOX_H[tagIntSafe + 1];
			SetFullRect(containerGrid, w, h);
			AddTagInt(box, "wb_stage", 1);
			SetTagIntValue(box, "wb_progress", num - num2);
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T("妙妙箱升级！段位 " + (tagIntSafe + 1) + "/5", "Wage Box upgraded! Stage " + (tagIntSafe + 1) + "/5"), "white");
			}
			catch
			{
			}
			if (tagIntSafe + 1 >= MAX_STAGE)
			{
				TryGiveSecondWageBox(box);
			}
			return true;
		}
		catch
		{
			return false;
		}
	}

	public static void TryGiveSecondWageBox(GameItem box)
	{
		try
		{
			if (box == null || _secondGiven.Contains(((Il2CppObjectBase)box).Pointer) || box.IsTag("wb_second_given"))
			{
				return;
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.backInvinvElement == null)
			{
				return;
			}
			GameItem val = CustomStorageContainer.CreateContainer();
			if (val == null)
			{
				Core.LogMsg("[容器v2] 创建第二个妙妙箱失败");
				return;
			}
			val.DisableTag("TAG_NOT_PURCHASED", true);
			val.DisableTag("not_purchased", true);
			instance.backInvinvElement.TryFindOneValidInventorySlot(val, false);
			bool flag = true;
			try
			{
				List<GameItem> val2 = new List<GameItem>();
				val2.Add(val);
				((GameInventory)instance.backInvinvElement).UncheckedAcceptAll(val2);
			}
			catch
			{
				flag = false;
			}
			if (!flag)
			{
				return;
			}
			instance.TransferOwnershipBackInv();
			instance.TransferOwnedItemBackToInv();
			box.EnableTag("wb_second_given", true);
			_secondGiven.Add(((Il2CppObjectBase)box).Pointer);
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T("满级！第二个妙妙箱已放入背包", "Maxed! Second Wage Box added to inventory"), "white");
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[容器v2] 发第二个妙妙箱异常: " + ex.Message);
		}
	}
