internal static class CounterfeitWineTradeFix
{
	public static void Postfix(GameItem item, GameCharacterItem trader, ref double __result)
	{
		try
		{
			if (__result > 0.0 || item == null)
			{
				return;
			}
			string text = item.identifier ?? "";
			string text2 = item.name ?? "";
			switch (text)
			{
			default:
				if (!text.EndsWith("_wine") && !text.EndsWith("_beer") && !text2.Contains("酒") && !text2.Contains("啤") && !text2.Contains("wine") && !text2.Contains("beer"))
				{
					break;
				}
				goto case "wine_bottle";
			case "wine_bottle":
			case "red_beer":
			case "nudka":
			case "beer":
			case "alcohol":
				__result = 1.0;
				break;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[假酒修复] Postfix异常: " + ex.Message);
		}
	}
}
