	}

	internal StartingPerk Create()
	{
		//IL_0028: Unknown result type (might be due to invalid IL or missing references)
		//IL_002d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0039: Unknown result type (might be due to invalid IL or missing references)
		//IL_0045: Unknown result type (might be due to invalid IL or missing references)
		//IL_0051: Unknown result type (might be due to invalid IL or missing references)
		//IL_0059: Expected Obj, but got Unknown
		List<string> val = new List<string>();
		string[] incompatibleIds = IncompatibleIds;
		foreach (string text in incompatibleIds)
		{
			val.Add(text);
		}
		StartingPerk val2 = new StartingPerk
		{
			id = Id,
			cost = Cost,
			maxSlot = MaxSlot,
			incompatiblePerks = val
		};
		try
		{
			val2.type = (StartingPerkType)Type;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[特性] " + Id + " 直接赋值type失败: " + ex.Message);
			try
			{
				FieldInfo field = typeof(StartingPerk).GetField("type", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (field != null)
				{
					field.SetValue(val2, Enum.ToObject(field.FieldType, Type));
				}
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[特性] " + Id + " 反射type也失败: " + ex2.Message);
			}
		}
		return val2;
	}
}
