	private static readonly Dictionary<string, StartingPerk> Created = new Dictionary<string, StartingPerk>();

	private static string _lastDayKey;

	internal static string CommunityNote => LangHelper.T("\n\n参考了群内网友的热心建议（群号：1109707341）！快来加入，你的建议也有可能被采纳。", "\n\nInspired by suggestions from our community (QQ Group: 1109707341)! Join us - your idea could be featured.");

	private static string CleanId(string id)
	{
		if (string.IsNullOrEmpty(id))
		{
			return "";
		}
		return id.Replace("\0", "").Trim();
	}

	internal static CustomStartingPerk Find(string id)
	{
		if (string.IsNullOrEmpty(id))
		{
			return null;
		}
		string text = CleanId(id);
		CustomStartingPerk[] all = All;
		foreach (CustomStartingPerk customStartingPerk in all)
		{
			if (CleanId(customStartingPerk.Id) == text)
			{
				return customStartingPerk;
			}
		}
		return null;
	}

	internal static bool TryGetLoc(string id, out string displayName, out string description)
	{
		displayName = "";
		description = "";
		CustomStartingPerk customStartingPerk = Find(id);
		if (customStartingPerk == null)
		{
			return false;
		}
		displayName = CleanId(customStartingPerk.DisplayName);
		description = CleanId(customStartingPerk.Description) + CommunityNote;
		return true;
	}

	internal static StartingPerk GetOrCreate(CustomStartingPerk custom)
	{
		if (Created.TryGetValue(custom.Id, out var value) && value != null)
		{
			return value;
		}
		value = custom.Create();
		Created[custom.Id] = value;
		return value;
	}

	internal static void EnsureRegistered()
	{
		Created.Clear();
		List<StartingPerk> perks = StartingPerkList.Perks;
		if (perks == null)
		{
			return;
		}
		CustomStartingPerk[] all = All;
		foreach (CustomStartingPerk customStartingPerk in all)
		{
			if (IndexOf(perks, customStartingPerk.Id) < 0)
			{
				perks.Add(GetOrCreate(customStartingPerk));
				Core.LogMsg("已注册特性: " + customStartingPerk.Id);
			}
		}
	}

