		EnsureRegistered();
		bool flag = false;
		CustomStartingPerk[] all = All;
		foreach (CustomStartingPerk customStartingPerk in all)
		{
			StartingPerkElement val = FindElement(ui.availablePerks, customStartingPerk.Id);
			Core.LogMsg("[特性UI] " + customStartingPerk.Id + " element=" + (((Object)(object)val != (Object)null) ? "找到" : "没找到"));
			if ((Object)val != (Object)null)
			{
				ApplyToElement(val, customStartingPerk);
				continue;
			}
			AddPickerElement(ui, customStartingPerk);
			flag = true;
		}
		if (flag)
		{
			ui.SortPerkContainer(ui.availablePerks);
		}
	}

	internal static void EnsureElement(StartingPerkElement element)
	{
		//IL_0001: Unknown result type (might be due to invalid IL or missing references)
		//IL_000c: Expected Obj, but got Unknown
		if ((Object)element != (Object)null)
		{
			CustomStartingPerk customStartingPerk = Find(element.id);
			if (customStartingPerk != null)
			{
				ApplyToElement(element, customStartingPerk);
			}
		}
	}

	private static void Drive(string hook, Action<CustomStartingPerk> call, bool gateActive)
	{
		CustomStartingPerk[] all = All;
		foreach (CustomStartingPerk customStartingPerk in all)
		{
			try
			{
				if (!gateActive || StartingPerk.IsPerkActive(customStartingPerk.Id))
				{
					call(customStartingPerk);
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[特性] " + hook + "异常 " + customStartingPerk.Id + ": " + ex.Message);
			}
		}
	}

	internal static void NotifyNewGame()
	{
		_lastDayKey = null;
		Drive("OnNewGame", (CustomStartingPerk p) =>
		{
			p.OnNewGame();
		}, gateActive: false);
	}

	private static string DayKey()
	{
		try
		{
			string text = "";
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null)
			{
				text = instance.runID ?? "";
			}
			return text + "|" + StoreStation.GetDayCounter();
		}
		catch
		{
			return null;
		}
	}

	internal static void NotifyDayStart()
	{
		string text = DayKey();
		if (text != null && text == _lastDayKey)
		{
			Core.LogMsg("[特性] OnDayStart 同日重复调用已跳过: " + text);
			return;
		}
		_lastDayKey = text;
		Drive("OnDayStart", (CustomStartingPerk p) =>
		{
			p.OnDayStart();
		}, gateActive: true);
	}

	internal static void NotifySaveGame()
	{
		Drive("OnSaveGame", (CustomStartingPerk p) =>
		{
			p.OnSaveGame();
		}, gateActive: false);
	}

	internal static void NotifyGameLoaded()
	{
		Drive("OnGameLoaded", (CustomStartingPerk p) =>
		{
			p.OnGameLoaded();
		}, gateActive: false);
	}

