			Core.LogMsg("[特性] 漏登记断言自身异常: " + ex2.Message);
		}
	}

	private static void AddPickerElement(PerkUIController ui, CustomStartingPerk custom)
	{
		GameObject val = Object.Instantiate<GameObject>(ui.perkElementPrefab, ui.availablePerks.transform);
		StartingPerkElement component = val.GetComponent<StartingPerkElement>();
		component.id = custom.Id.Replace("\0", "").Trim();
		component.isSelected = false;
		ApplyToElement(component, custom);
		val.SetActive(true);
	}

	private static void ApplyToElement(StartingPerkElement element, CustomStartingPerk custom)
	{
		StartingPerk orCreate = GetOrCreate(custom);
		orCreate.maxSlot = custom.MaxSlot;
		element.perk = orCreate;
		try
		{
			if (PerkIconLoader.HasCustomIcon(custom.Id))
			{
				Sprite perkIcon = PerkIconLoader.GetPerkIcon(custom.Id);
				if ((Object)(object)perkIcon != (Object)null)
				{
					try
					{
						PropertyInfo property = ((object)element).GetType().GetProperty("icon", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
						if (property != null)
						{
							object value = property.GetValue(element);
							if (value != null)
							{
								PropertyInfo property2 = value.GetType().GetProperty("sprite");
								if (property2 != null)
								{
									property2.SetValue(value, perkIcon);
									PropertyInfo property3 = value.GetType().GetProperty("enabled");
									if (property3 != null)
									{
										property3.SetValue(value, true);
									}
								}
							}
						}
					}
					catch (Exception ex)
					{
						Core.LogMsg("[特性UI] 设置icon失败: " + ex.Message);
					}
				}
			}
			string rawName = custom.DisplayName.Replace("\0", "").Trim();
			string rawDescription = custom.Description.Replace("\0", "").Trim() + CommunityNote;
			orCreate.rawName = rawName;
			orCreate.rawDescription = rawDescription;
		}
		catch (Exception ex2)
		{
			MelonLogger.Error("[特性UI] 失败: " + ex2.Message + "\n" + ex2.StackTrace);
		}
	}

	private static StartingPerkElement FindElement(GameObject root, string id)
	{
		//IL_002d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0038: Expected Obj, but got Unknown
		string text = id.Replace("\0", "").Trim();
		foreach (StartingPerkElement componentsInChild in root.GetComponentsInChildren<StartingPerkElement>(true))
		{
			if ((Object)componentsInChild != (Object)null && ((componentsInChild.id != null) ? componentsInChild.id.Replace("\0", "").Trim() : "") == text)
			{
				return componentsInChild;
			}
		}
		return null;
	}

	private static int IndexOf(List<StartingPerk> perks, string id)
	{
		string text = id.Replace("\0", "").Trim();
		for (int i = 0; i < perks.Count; i++)
		{
			if (perks[i] != null && ((perks[i].id != null) ? perks[i].id.Replace("\0", "").Trim() : "") == text)
			{
				return i;
			}
		}
		return -1;
	}
