	private static void SetPrivateField(object obj, string fieldName, object value)
	{
		try
		{
			FieldInfo field = obj.GetType().GetField(fieldName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (field != null)
			{
				field.SetValue(obj, value);
				return;
			}
			PropertyInfo property = obj.GetType().GetProperty(fieldName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (property != null && property.CanWrite)
			{
				property.SetValue(obj, value);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[自定义储物箱] SetPrivateField失败(" + fieldName + "): " + ex.Message);
		}
	}

	public static void FillWithRandomLockedBoxes(GameItem storageBox, int count)
	{
		try
		{
			var source = new[]
			{
				new
				{
					BoxId = "sec_box",
					Name = LangHelper.T("治安战利品箱", "Security Loot Crate")
				},
				new
				{
					BoxId = "med_box",
					Name = LangHelper.T("医疗战利品箱", "Medical Loot Crate")
				},
				new
				{
					BoxId = "eng_box",
					Name = LangHelper.T("工程战利品箱", "Engineering Loot Crate")
				},
				new
				{
					BoxId = "service_box",
					Name = LangHelper.T("服务战利品箱", "Service Loot Crate")
				},
				new
				{
					BoxId = "evidence_box",
					Name = LangHelper.T("证物箱", "Evidence Box")
				}
			};
			GameInventory val = _lastCreatedInventory;
			if (val == null)
			{
				try
				{
					PixelWindow contentWindow = storageBox.contentWindow;
					if (contentWindow != null)
					{
						PropertyInfo property = ((object)contentWindow).GetType().GetProperty("inventory", BindingFlags.Instance | BindingFlags.Public);
						if (property != null)
						{
							object? value = property.GetValue(contentWindow);
							val = (GameInventory)((value is GameInventory) ? value : null);
						}
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[蛙哥妙妙箱] 从contentWindow获取内部库存失败: " + ex.Message);
				}
			}
			if (val == null)
			{
				Core.LogMsg("[蛙哥妙妙箱] 内部库存为null，无法填充");
				return;
			}
			Random random = Core.Rng;
			var array = source.OrderBy(x => random.Next()).Take(count).ToArray();
			foreach (var anon in array)
			{
				try
				{
					GameItem val2 = CreateLootCrate(anon.BoxId);
					if (val2 != null)
					{
						try
						{
							val2.DisableTag("TAG_NOT_PURCHASED", true);
						}
						catch
						{
						}
						try
						{
							val2.DisableTag("not_purchased", true);
						}
						catch
						{
						}
						try
						{
							List<GameItem> val3 = new List<GameItem>();
							val3.Add(val2);
							val.UncheckedAcceptAll(val3);
						}
						catch
						{
						}
					}
					GameItem val4 = DirectoryMaster.Item("cmd_keycard", true);
					if (val4 != null)
					{
						try
						{
							val4.DisableTag("TAG_NOT_PURCHASED", true);
						}
						catch
						{
						}
						try
						{
							val4.DisableTag("not_purchased", true);
						}
						catch
						{
						}
						try
						{
							List<GameItem> val5 = new List<GameItem>();
							val5.Add(val4);
							val.UncheckedAcceptAll(val5);
						}
						catch
						{
						}
					}
				}
				catch (Exception ex2)
				{
					Core.LogMsg("[蛙哥妙妙箱] 放入" + anon.Name + "失败: " + ex2.Message);
				}
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[蛙哥妙妙箱] FillWithRandomLockedBoxes异常: " + ex3.Message + "\n" + ex3.StackTrace);
		}
	}

	public static void RegisterToDirectory(ItemDirectory dir)
	{
		try
		{
			if ((Object)(object)dir == (Object)null || ((Directory<GameItem>)(object)dir).Has("custom_storage_box"))
			{
				return;
			}
			if ((Delegate)(object)_registeredFactory == (Delegate)null)
			{
				_registeredFactory = DelegateSupport.ConvertDelegate<Func<GameItem>>((Delegate)(Func<GameItem>)(() => CreateRegisteredContainer()));
			}
			bool flag = ((Directory<GameItem>)(object)dir).Add("custom_storage_box", _registeredFactory);
			Core.LogMsg($"[自定义储物箱] {(flag ? "★ 已注册" : "?\ufe0f 注册失败")} {"custom_storage_box"} 到 {((object)dir).GetType().Name}（读档原生恢复窗口）");
		}
		catch (Exception ex)
		{
			Core.LogMsg("[自定义储物箱] 注册到目录异常: " + ex.Message);
		}
	}
