internal sealed class DarkGridInspectorPerk : CustomStartingPerk
{
	internal const string PerkId = "治安部眼线";

	internal override string Id => "治安部眼线";

	internal override string DisplayName => LangHelper.T("治安部眼线", "Security Informant");

	internal override string Description => LangHelper.T("治安部的眼睛从未离开过你——你的一举一动都被记录在案。每15天他们上门突击检查，翻出暗格和海报夹层里的违禁品，一律没收，不限数量。满星信誉也拦不住他们。", "The Security Department's eyes never leave you - every move you make is on record. Every 15 days they raid your shop, uncovering contraband even in hidden compartments and behind posters - all confiscated, no limit. Full reputation won't stop them.");

	internal override int Cost => -15;

	internal override int Type => 1;

	internal override void OnNewGame()
	{
	}

	internal static bool IsActive()
	{
		return Core.PerkActive("治安部眼线");
	}

	internal override void OnDayStart()
	{
		try
		{
			if (IsActive() && PlayerStore.Instance != null)
			{
				int num = 1;
				try
				{
					num = StoreStation.GetDayCounter();
				}
				catch
				{
				}
				if (num > 0 && num % BuildConfig.InspectInterval == 0 && num != WageSaveStore.GetInt("dark_grid_inspector", "last_trigger_day", -1))
				{
					WageSaveStore.SetInt("dark_grid_inspector", "last_trigger_day", num);
					RunInspection(num);
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[治安部眼线] 调度失败: " + ex.Message);
		}
	}

	private static void RunInspection(int day)
	{
		List<(GameItem, GameInventory, int)> list = new List<(GameItem, GameInventory, int)>();
		try
		{
			GameGridInventory hiddenElement = EmporiumEntry.Instance.hiddenElement;
			if (hiddenElement != null && ((GameInventory)hiddenElement).childItems != null)
			{
				for (int i = 0; i < ((GameInventory)hiddenElement).childItems.Count; i++)
				{
					GameItem val = ((GameInventory)hiddenElement).childItems[i];
					if (val == null)
					{
						continue;
					}
					try
					{
						int contrabandLevel = ContrabandHelper.GetContrabandLevel(val);
						if (contrabandLevel > 0)
						{
							list.Add((val, (GameInventory)(object)hiddenElement, contrabandLevel));
						}
					}
					catch
					{
					}
				}
			}
			Enumerator<GameItem> enumerator = EmporiumEntry.Instance.GetAllItems().GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				GameInventory innerInventory = AddictOfficerEvent.GetInnerInventory(current);
				if (innerInventory == null || innerInventory.childItems == null)
				{
					continue;
				}
				for (int j = 0; j < innerInventory.childItems.Count; j++)
				{
					GameItem val2 = innerInventory.childItems[j];
					if (val2 == null)
					{
						continue;
					}
					bool flag = false;
					for (int k = 0; k < list.Count; k++)
					{
						if (list[k].Item1 == val2)
						{
							flag = true;
							break;
						}
					}
					if (flag)
					{
						continue;
					}
					try
					{
						int contrabandLevel2 = ContrabandHelper.GetContrabandLevel(val2);
						if (contrabandLevel2 > 0)
						{
							list.Add((val2, innerInventory, contrabandLevel2));
						}
					}
					catch
					{
					}
				}
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance != (Object)null)
			{
				GameInventory[] array = new GameInventory[5]
				{
					(GameInventory)instance.invElement,
					(GameInventory)instance.backInvinvElement,
					(GameInventory)instance.backInvinvElementCounter,
					(GameInventory)instance.frontInvinvElement,
					(GameInventory)instance.showcaseElement
				};
				foreach (GameInventory val3 in array)
				{
					if (val3 == null || val3.childItems == null)
					{
						continue;
					}
					for (int m = 0; m < val3.childItems.Count; m++)
					{
						GameItem val4 = val3.childItems[m];
						if (val4 == null || AddictOfficerEvent.IsSmugglerBay(val4))
						{
							continue;
						}
						try
						{
							int contrabandLevel3 = ContrabandHelper.GetContrabandLevel(val4);
							if (contrabandLevel3 > 0)
							{
								list.Add((val4, val3, contrabandLevel3));
							}
						}
						catch
						{
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[治安部眼线] 扫描失败: " + ex.Message);
		}
		if (list.Count == 0)
		{
			try
			{
				PlayerStore instance2 = PlayerStore.Instance;
				if (instance2 != null)
				{
					instance2.AddNightLog(LangHelper.T("治安部突击检查！眼线把暗格和海报夹层翻了个底朝天，这次没搜到违禁品。", "Security raid! Informants tore through hidden compartments and behind posters - nothing found this time."), "#7FC97F");
				}
			}
			catch
			{
			}
			Core.AddNightReportLine(LangHelper.T("治安部突击检查！眼线把暗格和海报夹层翻了个底朝天，这次没搜到违禁品。", "Security raid! Informants tore through hidden compartments and behind posters - nothing found this time."));
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T("治安部突击检查！这次没搜到违禁品", "Security raid! Nothing found this time"), "yellow");
				return;
			}
			catch
			{
				return;
			}
		}
		int num = 0;
		foreach (var item in list)
		{
			try
			{
				item.Item2.Expel(item.Item1);
				num++;
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[治安部眼线] 没收失败: " + ex2.Message);
			}
		}
		if (num == 0)
		{
			return;
		}
		List<string> list2 = new List<string>();
		foreach (var item2 in list)
		{
			string text = "";
			try
			{
				text = item2.Item1.name ?? item2.Item1.identifier ?? "";
			}
			catch
			{
			}
			if (!string.IsNullOrEmpty(text) && !list2.Contains(text))
			{
				list2.Add(text);
			}
			if (list2.Count >= 5)
			{
				break;
			}
		}
		string text2 = ((list2.Count > 0) ? string.Join("、", list2) : "");
		if (list2.Count >= 5 && list.Count > 5)
		{
			text2 += " 等";
		}
		try
		{
			PlayerStore instance3 = PlayerStore.Instance;
			if (instance3 != null)
			{
				instance3.AddNightLog(LangHelper.T("治安部突击检查！眼线翻出了所有隐秘角落，没收了 " + num + " 件违禁品" + ((text2.Length > 0) ? ("：" + text2) : "") + "。", "Security raid! Informants confiscated " + num + " contraband items" + ((text2.Length > 0) ? (": " + text2) : "") + " from hidden compartments."), "#7FC97F");
			}
		}
		catch
		{
		}
		Core.AddNightReportLine(LangHelper.T("治安部突击检查！眼线翻出了所有隐秘角落，没收了 " + num + " 件违禁品" + ((text2.Length > 0) ? ("：" + text2) : "") + "。", "Security raid! Informants confiscated " + num + " contraband items" + ((text2.Length > 0) ? (": " + text2) : "") + " from hidden compartments."));
		try
		{
			StoreUIManager.Instance.Notify(LangHelper.T("治安部突击检查！没收 " + num + " 件违禁品", "Security raid! " + num + " contraband confiscated"), "red");
		}
		catch
		{
		}
	}
}
