	private static bool IsFakeOrTampered(GameItem item)
	{
		try
		{
			if (item == null)
			{
				return false;
			}
			if (item.IsAlreadyContainFeatureWithId("realCounterfeit"))
			{
				return true;
			}
			if (item.IsAlreadyContainFeatureWithId("fakeGenuine"))
			{
				return true;
			}
			ItemFeature val = item.FindItemFeatureByCategory("CATEGORY_GENUINE_INJECTOR");
			if (val != null && val.GetBaseFakeDisplay() != val.GetBaseRealDisplay())
			{
				return true;
			}
			if (item.IsTag("ISSUE_LABEL"))
			{
				return true;
			}
			if (IsMislabeledWater(item))
			{
				return true;
			}
			return false;
		}
		catch
		{
			return false;
		}
	}

	private static bool IsMislabeledWater(GameItem item)
	{
		try
		{
			if (!item.IsTag("LIQUID_CONTAINER_TAG"))
			{
				return false;
			}
			ItemFeature waterFeature = WaterFeatureHelper.GetWaterFeature(item);
			if (waterFeature == null)
			{
				return false;
			}
			return waterFeature.GetBaseFakeDisplay() != waterFeature.GetBaseRealDisplay();
		}
		catch
		{
			return false;
		}
	}

	private static int GetFakeItemValue(GameItem item)
	{
		try
		{
			int num = (int)item.GetCurrentValue(false, true, true, false, 0L);
			if (num <= 0)
			{
				num = 1;
			}
			ItemFeature val = item.FindItemFeatureByID("realCounterfeit") ?? item.FindItemFeatureByID("fakeGenuine") ?? item.FindItemFeatureByCategory("CATEGORY_GENUINE_INJECTOR");
			if (val != null)
			{
				int num2 = num * (100 + val.GetFakeValueModifier()) / 100;
				if (num2 > 0)
				{
					return num2;
				}
			}
			return num / 10;
		}
		catch
		{
			return 1;
		}
	}

	public static void AbsorbItem(GameItem dice, GameItem absorbedItem)
	{
		try
		{
			if (dice == null || absorbedItem == null)
			{
				return;
			}
			int num = 0;
			try
			{
				num = (int)(IsFakeOrTampered(absorbedItem) ? GetFakeItemValue(absorbedItem) : absorbedItem.GetCurrentValue(false, true, true, false, 0L));
			}
			catch (Exception ex)
			{
				Core.LogMsg("[DestinyDice.Core] 异常: " + ex.Message);
			}
			if (num <= 0)
			{
				num = 1;
			}
			int value = GetTagInt(dice, "destinyDiceValue") + num;
			SetTagInt(dice, "destinyDiceValue", value);
			try
			{
				absorbedItem.Destroy();
			}
			catch
			{
				try
				{
					absorbedItem.Destroy();
				}
				catch
				{
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[命运骰子] 吸收物品失败: " + ex2.Message);
		}
	}

	public static void RollDice(GameItem dice)
	{
		try
		{
			if (dice == null || !IsDice(dice))
			{
				return;
			}
			int tagInt = GetTagInt(dice, "destinyDiceValue");
			int num = GetTagInt(dice, "destinyDiceThreshold");
			if (num < DICE_BASE_THRESHOLD)
			{
				num = DICE_BASE_THRESHOLD;
			}
			if (tagInt < num)
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("价值不足，还需 " + (num - tagInt) + " 才能掷骰", "Need " + (num - tagInt) + " more value to roll"), "orange");
					return;
				}
				catch
				{
					return;
				}
			}
			tagInt -= num;
			SetTagInt(dice, "destinyDiceValue", tagInt);
			SetTagInt(dice, "destinyDiceThreshold", num + DICE_BASE_THRESHOLD);
			SetTagInt(dice, "destinyDiceLastCost", num);
			int tagInt2 = GetTagInt(dice, "destinyDiceTriggers");
			SetTagInt(dice, "destinyDiceTriggers", tagInt2 + 1);
			string text = TriggerRandomEvent(dice);
			if (!string.IsNullOrEmpty(text))
			{
				SetTagString(dice, "destinyDicePendingEventId", text);
				string value = text;
				try
				{
					EventZhName.TryGetValue(text, out value);
				}
				catch
				{
				}
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("掷骰成功！明日事件：" + value, "Rolled! Tomorrow: " + text), "green");
				}
				catch
				{
				}
			}
			_activeDice = dice;
			UpdateDicePanelTitle(dice, tagInt);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DestinyDice.Core] 异常: " + ex.Message);
		}
	}

	public static void UnloadEvent(GameItem dice)
	{
		try
		{
			if (dice == null || !IsDice(dice))
			{
				return;
			}
			string tagString = GetTagString(dice, "destinyDicePendingEventId");
			if (string.IsNullOrEmpty(tagString))
			{
				return;
			}
			try
			{
				StoreEventManager val = ((StoreStation.instance != null) ? StoreStation.instance.storeEventManager : null);
				if (val != null)
				{
					val.RemoveAllEvent(tagString);
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[DestinyDice.Core] 异常: " + ex.Message);
			}
			int tagInt = GetTagInt(dice, "destinyDiceLastCost");
			if (tagInt > 0)
			{
				int num = (int)((float)(tagInt * BuildConfig.DiceUninstallRefund) / 100f);
				int tagInt2 = GetTagInt(dice, "destinyDiceValue");
				SetTagInt(dice, "destinyDiceValue", tagInt2 + num);
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("已卸载事件，返还 " + num + " 价值", "Event unloaded, +" + num + " value"), "green");
				}
				catch
				{
				}
			}
			SetTagInt(dice, "destinyDiceLastCost", 0);
			SetTagString(dice, "destinyDicePendingEventId", "");
			_unloadConfirm = false;
			UpdateDicePanelTitle(dice, GetTagInt(dice, "destinyDiceValue"));
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[DestinyDice.Core] 异常: " + ex2.Message);
		}
	}

	public static bool PrefixDoubleClickAction(GameItem newItem, Vector2 mousePosition)
	{
		try
		{
			if (newItem != null && IsDice(newItem))
			{
				RollDice(newItem);
				return false;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DestinyDice.Core] 异常: " + ex.Message);
		}
		return true;
	}

	public static void DiceOnGUI()
	{
		//IL_008b: Unknown result type (might be due to invalid IL or missing references)
		//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
		//IL_0053: Unknown result type (might be due to invalid IL or missing references)
		//IL_00dd: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			GameItem activeDice = _activeDice;
			if (activeDice == null || string.IsNullOrEmpty(GetTagString(activeDice, "destinyDicePendingEventId")))
			{
				return;
			}
			float num = 170f;
			float num2 = 30f;
			float num3 = 16f;
			float num4 = (float)Screen.height - num2 - 16f;
			if (!_unloadConfirm)
			{
				if (GUI.Button(new Rect(num3, num4, num, num2), LangHelper.T("卸载事件（返还50%）", "Unload Event (50% refund)")))
				{
