			if (GUI.Button(new Rect(num3, num4, 80f, num2), LangHelper.T("确认", "Yes")))
			{
				UnloadEvent(activeDice);
			}
			if (GUI.Button(new Rect(num3 + 90f, num4, 80f, num2), LangHelper.T("取消", "No")))
			{
				_unloadConfirm = false;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DestinyDice.Core] 异常: " + ex.Message);
		}
	}

	public static void RecedeDiceThreshold()
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return;
			}
			GameInventory[] array = new GameInventory[4]
			{
				(GameInventory)instance.backInvinvElement,
				(GameInventory)instance.backInvinvElementCounter,
				(GameInventory)instance.showcaseElement,
				(GameInventory)instance.invElement
			};
			foreach (GameInventory val in array)
			{
				if (val == null)
				{
					continue;
				}
				Enumerator<GameItem> enumerator = val.childItems.GetEnumerator();
				while (enumerator.MoveNext())
				{
					GameItem current = enumerator.Current;
					if (current != null && IsDice(current))
					{
						int tagInt = GetTagInt(current, "destinyDiceThreshold");
						if (tagInt > DICE_BASE_THRESHOLD)
						{
							SetTagInt(current, "destinyDiceThreshold", tagInt - DICE_BASE_THRESHOLD);
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DestinyDice.Core] 异常: " + ex.Message);
		}
	}

	public static string GetTagString(GameItem item, string tag)
	{
		try
		{
			if (item == null || !item.IsTag(tag))
			{
				return "";
			}
			TagState tagReadonly = item.GetTagReadonly(tag);
			return (tagReadonly != null) ? tagReadonly.GetString() : "";
		}
		catch
		{
			return "";
		}
	}

	public static void SetTagString(GameItem item, string tag, string value)
	{
		try
		{
			if (item != null)
			{
				if (!item.IsTag(tag))
				{
					item.EnableTag(tag, true);
				}
				Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState state) =>
				{
					state.SetString(value);
				}));
				item.ModifyTag(tag, val, false);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DestinyDice.Core] 异常: " + ex.Message);
		}
	}

