	private static void UpdateDicePanelTitle(GameItem dice, int value)
	{
		try
		{
			if (dice == null)
			{
				return;
			}
			int tagInt = GetTagInt(dice, "destinyDiceTriggers");
			int num = GetTagInt(dice, "destinyDiceThreshold");
			if (num < DICE_BASE_THRESHOLD)
			{
				num = DICE_BASE_THRESHOLD;
			}
			string tagString = GetTagString(dice, "destinyDicePendingEventId");
			string value2 = "";
			if (tagString != "")
			{
				try
				{
					if (!EventZhName.TryGetValue(tagString, out value2))
					{
						value2 = tagString;
					}
				}
				catch
				{
					value2 = tagString;
				}
			}
			dice.SetName(LangHelper.T("命运骰子（价值" + value + " / 门槛" + num + " / 触发" + tagInt + "）", "Dice of Fate (value " + value + " / cost " + num + " / triggers " + tagInt + ")"));
			string text = dice.shortDescription ?? "";
			int num2 = text.IndexOf("【命运事件】");
			string text2 = ((num2 >= 0) ? text.Substring(0, num2) : text);
			if (value2 != "")
			{
				dice.shortDescription = (string.IsNullOrEmpty(text2.Trim()) ? "" : (text2.TrimEnd('。', ' ') + "。")) + "【命运事件】" + LangHelper.T("明日事件：" + value2 + "。拖物品累积价值，双击掷骰。", "Tomorrow: " + value2 + ". Drag to absorb, double-click to roll.");
			}
			else
			{
				dice.shortDescription = text2.TrimEnd('。', ' ');
			}
			try
			{
				dice.SyncModifiedState();
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DestinyDice.Core] 异常: " + ex.Message);
		}
	}

