	public static void ModdedEventLinks()
	{
		StoreEventManager val = ((StoreStation.instance != null) ? StoreStation.instance.storeEventManager : null);
		if (val == null)
		{
			return;
		}
		try
		{
			if (val.IsEventActive("lower_level_alcohol_shortage"))
			{
				PlayerStore.Instance.QueueFuturClient("retired_winemaker", 0);
			}
			if (val.IsEventActive("upper_level_auction_week"))
			{
				PlayerStore.Instance.QueueFuturClient("ul_gun_buyer", 0);
			}
			if (!val.IsEventActive("wandering_merchant_legacy") || _legacyGranted)
			{
				return;
			}
			_legacyGranted = true;
			try
			{
				GameItem val2 = DirectoryMaster.Item("sec_box", true);
				if (val2 != null)
				{
					PlayerStore.Instance.AddDirectSellingItemToTable(val2, false, false, false, 0);
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[Wage's Perks] 遗赠发箱失败: " + ex.Message);
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[Wage's Perks] 事件联动内部异常: " + ex2.Message);
		}
	}

	public static void EnsureModdedEventBlueprints()
	{
		try
		{
			if (_moddedEventsRegistered)
			{
				return;
			}
			List<StoreEventBlueprint> normalEventBlueprints = StoreEventManager.normalEventBlueprints;
			if (normalEventBlueprints == null)
			{
				return;
			}
			for (int i = 0; i < normalEventBlueprints.Count; i++)
			{
				try
				{
					if (normalEventBlueprints[i] != null && normalEventBlueprints[i].identifier == "lower_level_alcohol_shortage")
					{
						_moddedEventsRegistered = true;
						return;
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[DestinyDice.EventsFactory.Entry] 异常: " + ex.Message);
				}
			}
			RegisterModdedEvent(normalEventBlueprints, "lower_level_alcohol_shortage", () => CreateLowerLevelAlcoholShortage(), 10);
			RegisterModdedEvent(normalEventBlueprints, "security_undercover_patrol", () => CreateSecurityUndercoverPatrol(), 8);
			RegisterModdedEvent(normalEventBlueprints, "nutrifruit_new_release", () => CreateNutrifruitNewRelease(), 6);
			RegisterModdedEvent(normalEventBlueprints, "dumping_grounds_cleanup", () => CreateDumpingGroundsCleanup(), 7);
			RegisterModdedEvent(normalEventBlueprints, "black_market_sweep", () => CreateBlackMarketSweep(), 6);
			RegisterModdedEvent(normalEventBlueprints, "upper_level_luxury_expo", () => CreateUpperLevelLuxuryExpo(), 5);
			RegisterModdedEvent(normalEventBlueprints, "black_market_arms_flow", () => CreateBlackMarketArmsFlow(), 5);
			RegisterModdedEvent(normalEventBlueprints, "upper_level_auction_week", () => CreateUpperLevelAuctionWeek(), 5);
			RegisterModdedEvent(normalEventBlueprints, "nutrifruit_crisis_hoard", () => CreateNutrifruitCrisisHoard(), 4);
			RegisterModdedEvent(normalEventBlueprints, "train_heist_aftermath", () => CreateTrainHeistAftermath(), 5);
			RegisterModdedEvent(normalEventBlueprints, "wandering_merchant_legacy", () => CreateWanderingMerchantLegacy(), 2);
			RegisterModdedEvent(normalEventBlueprints, "drunk_riot", () => CreateDrunkRiot(), 5);
			_moddedEventsRegistered = true;
			Core.LogMsg("[Wage's Perks] 事件池注入: 12个mod事件已注册");
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[Wage's Perks] 事件池注入失败: " + ex2.Message);
		}
	}

	private static void RegisterModdedEvent(List<StoreEventBlueprint> blueprints, string id, Func<StoreEvent> factory, int weight)
	{
		//IL_0008: Unknown result type (might be due to invalid IL or missing references)
		//IL_000e: Expected Obj, but got Unknown
		try
		{
			StoreEventBlueprint val = new StoreEventBlueprint(DelegateSupport.ConvertDelegate<Func<StoreEvent>>((Delegate)factory), weight, id);
			blueprints.Add(val);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[Wage's Perks] 事件注册失败 " + id + ": " + ex.Message);
		}
	}

	public static string TriggerRandomEvent(GameItem dice)
	{
		try
		{
			StoreEventManager val = ((StoreStation.instance != null) ? StoreStation.instance.storeEventManager : null);
			if (val == null)
			{
				return null;
			}
			List<StoreEventBlueprint> normalEventBlueprints = StoreEventManager.normalEventBlueprints;
			if (normalEventBlueprints == null || normalEventBlueprints.Count == 0)
			{
				return null;
			}
			StoreEventBlueprint val2 = null;
			for (int i = 0; i < 5; i++)
			{
				int num = Random.Range(0, normalEventBlueprints.Count);
				StoreEventBlueprint val3 = normalEventBlueprints[num];
				if (val3 == null || (Delegate)(object)val3.storeEventFunc == (Delegate)null)
				{
					continue;
				}
				try
				{
					if (!val.IsEventActive(val3.identifier))
					{
						val2 = val3;
						break;
					}
				}
				catch
				{
					val2 = val3;
					break;
				}
			}
			if (val2 == null)
			{
				for (int j = 0; j < normalEventBlueprints.Count; j++)
				{
					StoreEventBlueprint val4 = normalEventBlueprints[j];
					if (val4 != null && (Delegate)(object)val4.storeEventFunc != (Delegate)null)
					{
						val2 = val4;
						break;
					}
				}
			}
			if (val2 == null)
			{
				Core.LogMsg("[命运骰子] 事件蓝图全为空");
				return null;
			}
			StoreEvent val5 = val2.storeEventFunc.Invoke();
			if (val5 == null)
			{
				Core.LogMsg("[命运骰子] 事件实例化失败");
				return null;
			}
			LocalizeEvent(val5);
			val.QueueFuturEvent(val5, 1, true);
			if (dice != null)
			{
				int tagInt = GetTagInt(dice, "destinyDiceTriggers");
				SetTagInt(dice, "destinyDiceTriggers", tagInt + 1);
				int tagInt2 = GetTagInt(dice, "destinyDiceValue");
				UpdateDicePanelTitle(dice, tagInt2);
			}
			return val5.identifier;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[命运骰子] 触发事件异常: " + ex.Message);
			return null;
		}
	}

