		return null;
	}

	public static void LocalizeEvent(StoreEvent evt)
	{
		try
		{
			if (evt == null || string.IsNullOrEmpty(evt.identifier) || LangHelper.IsEnglish())
			{
				return;
			}
			string identifier = evt.identifier;
			if (EventZhName.TryGetValue(identifier, out var value))
			{
				evt.displayName = value;
				if (EventZhNews.TryGetValue(identifier, out var value2))
				{
					evt.newsName = value2;
				}
				if (EventZhDesc.TryGetValue(identifier, out var value3))
				{
					evt.newsDescription = value3;
				}
			}
			else if (!string.IsNullOrEmpty(evt.newsName) && TitleZhName.TryGetValue(evt.newsName, out value))
			{
				evt.displayName = value;
				evt.newsName = value;
				if (TitleZhDesc.TryGetValue(evt.newsName, out var value4))
				{
					evt.newsDescription = value4;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[命运骰子] 汉化事件失败: " + ex.Message);
		}
	}

