	public static void ApplyNewsPage()
	{
		_newsPaging = true;
		try
		{
			NewsUIManager instance = NewsUIManager.Instance;
			if ((Object)(object)instance == (Object)null || _newsAllEvents == null)
			{
				return;
			}
			List<StoreEvent> val = SlicePage(_newsPage);
			if ((Object)(object)instance.layout1 != (Object)null)
			{
				instance.layout1.SetActive(false);
			}
			if ((Object)(object)instance.layout2 != (Object)null)
			{
				instance.layout2.SetActive(false);
			}
			if ((Object)(object)instance.layout3 != (Object)null)
			{
				instance.layout3.SetActive(false);
			}
			if ((Object)(object)instance.layout4 != (Object)null)
			{
				instance.layout4.SetActive(false);
			}
			int count = val.Count;
			GameObject val2;
			List<NewsUIElement> val3;
			if (count > 3)
			{
				val2 = instance.layout4;
				val3 = instance.layout4Elements;
			}
			else
			{
				switch (count)
				{
				case 3:
					val2 = instance.layout3;
					val3 = instance.layout3Elements;
					break;
				case 2:
					val2 = instance.layout2;
					val3 = instance.layout2Elements;
					break;
				default:
					val2 = instance.layout1;
					val3 = instance.layout1Elements;
					break;
				}
			}
			if ((Object)(object)val2 != (Object)null)
			{
				val2.SetActive(true);
			}
			if (val3 != null)
			{
				for (int i = 0; i < val3.Count; i++)
				{
					try
					{
						if ((Object)(object)val3[i] != (Object)null)
						{
							if ((Object)(object)((Component)val3[i]).gameObject != (Object)null)
							{
								((Component)val3[i]).gameObject.SetActive(false);
							}
							val3[i].ClearElement();
						}
					}
					catch (Exception ex)
					{
						Core.LogMsg("[DestinyDice.EventsZh.News] 异常: " + ex.Message);
					}
				}
			}
			if (val3 != null)
			{
				int num = Mathf.Min(count, val3.Count);
				for (int j = 0; j < num; j++)
				{
					try
					{
						if (!((Object)(object)val3[j] == (Object)null) && !((Object)(object)((Component)val3[j]).gameObject == (Object)null))
						{
							((Component)val3[j]).gameObject.SetActive(true);
							val3[j].PopulateUI(val[j]);
						}
					}
					catch (Exception ex2)
					{
						Core.LogMsg("[DestinyDice.EventsZh.News] 异常: " + ex2.Message);
					}
				}
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[报纸翻页] ApplyPage异常: " + ex3.Message);
		}
		_newsPaging = false;
	}

	public static void PostfixNewsPopulateUI()
	{
		try
		{
			_newsOpen = true;
			StoreStation instance = StoreStation.Instance;
			if (instance == null || instance.storeEventManager == null)
			{
				Core.LogMsg("[报纸翻页] StoreStation/EventManager为空");
				return;
			}
			try
			{
				_newsAllEvents = instance.storeEventManager.GetActiveEvents();
				if (_newsAllEvents != null)
				{
					for (int num = _newsAllEvents.Count - 1; num >= 0; num--)
					{
						try
						{
							if (_newsAllEvents[num].isHiddenFromNewsPaper)
							{
								_newsAllEvents.RemoveAt(num);
							}
						}
						catch
						{
						}
					}
				}
				if (_newsAllEvents != null)
				{
					for (int i = 0; i < _newsAllEvents.Count; i++)
					{
						try
						{
							LocalizeEvent(_newsAllEvents[i]);
						}
						catch
						{
						}
					}
				}
				try
				{
					if (NewsSerialInjector != null)
					{
						NewsSerialInjector(_newsAllEvents);
					}
				}
				catch
				{
				}
				_newsPage = 0;
				ApplyNewsPage();
				EnsureNewsButtons();
			}
			catch (Exception ex)
			{
				Core.LogMsg("[报纸翻页] GetActiveEvents异常: " + ex.Message);
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[报纸翻页] PopulateUI异常: " + ex2.Message);
		}
	}

	public static List<StoreEvent> SlicePage(int page)
	{
		List<StoreEvent> val = new List<StoreEvent>();
		if (_newsAllEvents == null)
		{
			return val;
		}
		int num = page * 4;
		for (int i = num; i < num + 4 && i < _newsAllEvents.Count; i++)
		{
			try
			{
				val.Add(_newsAllEvents[i]);
			}
			catch
			{
			}
		}
		return val;
	}

