	public static void PostfixNewsInputUpdate()
	{
		try
		{
			if (!_newsOpen || _newsAllEvents == null || _newsAllEvents.Count <= 4)
			{
				return;
			}
			bool keyDown = Input.GetKeyDown((KeyCode)276);
			bool keyDown2 = Input.GetKeyDown((KeyCode)275);
			if (keyDown || keyDown2)
			{
				int num = (_newsAllEvents.Count + 3) / 4;
				_newsPage += (keyDown2 ? 1 : (-1));
				if (_newsPage < 0)
				{
					_newsPage = num - 1;
				}
				if (_newsPage >= num)
				{
					_newsPage = 0;
				}
				ApplyNewsPage();
			}
		}
