	internal static bool TryGroupDragging(GameItem item)
	{
		try
		{
			Type type = Type.GetType("ItemMultiSelectHandler, Assembly-CSharp");
			if (type == (Type)null)
			{
				return false;
			}
			PropertyInfo property = type.GetProperty("current");
			if (property == (PropertyInfo)null)
			{
				return false;
			}
			Object val = ((MethodBase)property.GetGetMethod()).Invoke((Object)null, (Il2CppReferenceArray<Object>)null);
			if (val == null)
			{
				return false;
			}
			MethodInfo method = type.GetMethod("IsGroupDraggingItem");
			if (method == (MethodInfo)null)
			{
				return false;
			}
			Il2CppReferenceArray<Object> val2 = new Il2CppReferenceArray<Object>(1L);
			((Il2CppArrayBase<Object>)(object)val2)[0] = (Object)(object)item;
			Object val3 = ((MethodBase)method).Invoke(val, val2);
			if (val3 == null)
			{
				return false;
			}
			return ((Il2CppObjectBase)val3).Unbox<bool>();
		}
		catch
		{
			return false;
		}
	}

	public static bool PrefixCanTarget(GameItem __instance, GameItem targetItem, ref bool __result)
