	public static bool PrefixTarget(GameItem __instance, GameItem targetItem)
	{
		try
		{
			ItemSelectHandler current = ItemSelectHandler.current;
			if ((Object)(object)current != (Object)null && current.IsEquipped)
			{
				return true;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DestinyDice.Interaction] 异常: " + ex.Message);
		}
		GameItem val = null;
		GameItem val2 = null;
		ItemMouseDragHandler current2 = ItemMouseDragHandler.current;
		bool flag = (Object)(object)current2 != (Object)null && current2.IsDraggingItem;
		if (!flag)
		{
			flag = TryGroupDragging(__instance);
		}
		if (!flag)
		{
			return true;
		}
		if (IsDice(targetItem) && __instance != null && !IsDice(__instance))
		{
			val = targetItem;
			val2 = __instance;
		}
		if (val != null && val2 != null)
		{
			DoAbsorb(val2, val);
			return false;
		}
		return true;
	}

	private static bool DoAbsorb(GameItem item, GameItem dice)
	{
		if (item == null || dice == null)
		{
			return false;
		}
		long num = 0L;
		try
		{
			num = ((Il2CppObjectBase)item).Pointer.ToInt64();
		}
		catch
		{
		}
		if (num != 0L)
		{
			if (!_absorbedPointers.Add(num))
			{
				return false;
			}
			if (_absorbedPointers.Count > 512)
			{
				try
				{
					_absorbedPointers.Clear();
				}
				catch
				{
				}
			}
		}
		if (IsNonPlayerOwned(item))
		{
			return false;
		}
		try
		{
			int num2 = 0;
			try
			{
				num2 = (int)item.GetCurrentValue(false, true, true, false, 0L);
			}
			catch
			{
			}
			if (num2 <= 0)
			{
				num2 = 1;
			}
			int value = GetTagInt(dice, "destinyDiceValue") + num2;
			SetTagInt(dice, "destinyDiceValue", value);
			UpdateDicePanelTitle(dice, value);
			try
			{
				item.Destroy();
			}
			catch
			{
				try
				{
					GameInventory parentInventory = item.parentInventory;
					if (parentInventory != null)
					{
						parentInventory.Expel(item);
					}
				}
				catch
				{
				}
			}
			return true;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[命运骰子] 吸收异常: " + ex.Message);
			return false;
		}
	}

	private static bool TryGameIsItemOwned(GameItem item, out bool owned)
	{
		owned = false;
		try
		{
			if (!_gameIsItemOwnedInited)
			{
				_gameIsItemOwnedInited = true;
				Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
				foreach (Assembly assembly in assemblies)
				{
					if (assembly.GetName().Name != "Assembly-CSharp")
					{
						continue;
					}
					Type type = assembly.GetType("GeneralHelper");
					if (!(type != null))
					{
						break;
					}
					MethodInfo[] methods = type.GetMethods(BindingFlags.Static | BindingFlags.Public);
					foreach (MethodInfo methodInfo in methods)
					{
						if (methodInfo.Name == "IsItemOwned" && methodInfo.GetParameters().Length == 1)
						{
							_gameIsItemOwned = methodInfo;
							break;
						}
					}
					break;
				}
			}
			if (_gameIsItemOwned == null)
			{
				return false;
			}
			owned = (bool)_gameIsItemOwned.Invoke(null, new object[1] { item });
			return true;
		}
		catch
		{
			return false;
		}
	}

	private static bool IsNonPlayerOwned(GameItem item)
	{
		try
		{
			if (item == null)
			{
				return false;
			}
			if (TryGameIsItemOwned(item, out var owned))
			{
				return !owned;
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.afterhourInventory == null)
			{
				return false;
			}
			long num = (long)((Il2CppObjectBase)item).Pointer;
			if (((GameInventory)instance.afterhourInventory).childItems != null)
			{
				for (int i = 0; i < ((GameInventory)instance.afterhourInventory).childItems.Count; i++)
				{
					GameItem val = ((GameInventory)instance.afterhourInventory).childItems[i];
					if (val != null && (long)((Il2CppObjectBase)val).Pointer == num)
					{
						return true;
					}
				}
			}
			return false;
		}
		catch
		{
			return false;
		}
	}

