	private static GameItem CreateRegisteredDice()
	{
		try
		{
			GameItem val = CreateDestinyDice();
			if (val != null)
			{
				return val;
			}
			val = CreateMinimalDice();
			if (val != null)
			{
				return val;
			}
			return null;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[命运骰子] 工厂创建异常: " + ex.Message);
			return null;
		}
	}
