internal static class DeterministicRandom
{
	private static uint Fnv1aHash(string input)
	{
		if (string.IsNullOrEmpty(input))
		{
			return 0u;
		}
		uint num = 2166136261u;
		foreach (char c in input)
		{
			num ^= c;
			num *= 16777619;
		}
		return num;
	}

	private static string GetRunId()
	{
		try
		{
			if (PlayerStore.Instance != null && !string.IsNullOrEmpty(PlayerStore.Instance.runID))
			{
				return PlayerStore.Instance.runID;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DeterministicRandom] 异常: " + ex.Message);
		}
		return "default_run";
	}

	internal static double NextDouble(string type, int day)
	{
		return (double)(Fnv1aHash(GetRunId() + "_" + type + "_" + day) % 10000) / 10000.0;
	}

	internal static int Next(string type, int day, int maxValue)
	{
		if (maxValue <= 0)
		{
			return 0;
		}
		return (int)(Fnv1aHash(GetRunId() + "_" + type + "_" + day) % (uint)maxValue);
	}

	internal static int Next(string type, int day, int minValue, int maxValue)
	{
		if (maxValue <= minValue)
		{
			return minValue;
		}
		return minValue + Next(type, day, maxValue - minValue);
	}

	internal static bool NextBool(string type, int day, double probability)
	{
		return NextDouble(type, day) < probability;
	}

	internal static T Choose<T>(string type, int day, T[] array)
	{
		if (array == null || array.Length == 0)
		{
			return default;
		}
		int num = Next(type, day, array.Length);
		return array[num];
	}

	internal static T Choose<T>(string type, int day, List<T> list)
	{
		if (list == null || list.Count == 0)
		{
			return default;
		}
		int index = Next(type, day, list.Count);
		return list[index];
	}
}
internal static class DeterministicSchedule
{
	internal static int CurrentDay
	{
		get
		{
			try
			{
				return Math.Max(0, StoreStation.GetDayCounter());
			}
			catch
			{
				return 0;
			}
		}
	}

	internal static int CurrentWeek => Math.Max(0, (CurrentDay - 1) / 7);

	internal static string GetRunKey()
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null && !string.IsNullOrEmpty(instance.runID))
			{
				return instance.runID;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DeterministicSchedule] 异常: " + ex.Message);
		}
		return "no-run";
	}

	internal static int GetRunHash()
	{
		string runKey = GetRunKey();
		using MD5 mD = MD5.Create();
		return BitConverter.ToInt32(mD.ComputeHash(Encoding.UTF8.GetBytes(runKey)), 0);
	}

	internal static string GetDailyKey()
	{
		return GetRunKey() + "|" + CurrentDay;
	}

	internal static string GetWeeklyKey()
	{
		return GetRunKey() + "|" + CurrentWeek;
	}

	internal static double DeterministicRandom(string salt)
	{
		string s = GetRunKey() + "|" + CurrentDay + "|" + salt;
		using MD5 mD = MD5.Create();
		return (double)BitConverter.ToUInt32(mD.ComputeHash(Encoding.UTF8.GetBytes(s)), 0) / 4294967295.0;
	}

	internal static int DeterministicRange(int min, int max, string salt)
	{
		if (max <= min)
		{
			return min;
		}
		double num = DeterministicRandom(salt);
		return min + (int)(num * (double)(max - min));
	}

	internal static bool DeterministicChance(double probability, string salt)
	{
		return DeterministicRandom(salt) < probability;
	}
}
public static class ContainerDiagnostics
{
	private static bool _initialized = false;

	private static float _lastDumpTime = 0f;

	private static string _dumpFile = "";

	private static bool _autoDumpDone = false;

	public static void Init()
	{
		if (!_initialized)
		{
			_initialized = true;
			_dumpFile = Path.Combine(Application.dataPath, "..", "Mods", "container_diagnostics.txt");
			Core.LogMsg("[容器诊断] 初始化完成，按F8 dump MiniSmugglerBay和MachineBayExt结构");
		}
	}

	public static void OnUpdate()
	{
		if (!Core.DebugMode || !_initialized)
		{
			return;
		}
		try
		{
			if (!_autoDumpDone)
			{
				try
				{
					if (PlayerStore.Instance != null && PlayerStore.Instance.playerCash > 0)
					{
						_autoDumpDone = true;
						DumpContainers();
					}
				}
				catch
				{
				}
			}
			if (Input.GetKeyDown((KeyCode)289) && Time.time - _lastDumpTime > 1f)
			{
				_lastDumpTime = Time.time;
				DumpContainers();
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[容器诊断] 异常: " + ex.Message);
		}
	}

	private static void DumpContainers()
	{
		try
		{
			using StreamWriter streamWriter = new StreamWriter(_dumpFile, append: false, Encoding.UTF8);
			streamWriter.WriteLine($"===== 容器结构诊断 =====\n时间: {DateTime.Now}\n");
			streamWriter.WriteLine("===== 0. 各容器shape大小对比 =====");
			string[] array = new string[8] { "storage_bay", "storage_bay_large", "machine_bay", "machine_bay_ext", "mini_smuggler_bay", "smuggler_bay", "backpack_medium", "backpack_large" };
			foreach (string text in array)
			{
				try
				{
					GameItem val = DirectoryMaster.Item(text, true);
					if (val != null && val.shape != null)
					{
						streamWriter.WriteLine($"  {text}: width={val.shape.width}, height={val.shape.height}, globalWidth={val.shape.globalWidth}, globalHeight={val.shape.globalHeight}");
					}
					else
					{
						streamWriter.WriteLine("  " + text + ": 创建失败或shape为null");
					}
				}
				catch (Exception ex)
				{
					streamWriter.WriteLine("  " + text + ": 异常 " + ex.Message);
				}
			}
			streamWriter.WriteLine("");
			streamWriter.WriteLine("===== 1. MiniSmugglerBay（迷你走私者暗格） =====");
			try
			{
				GameItem val2 = DirectoryMaster.Item("mini_smuggler_bay", true);
				if (val2 != null)
				{
					DumpGameItem(streamWriter, val2, "MiniSmugglerBay");
