				{
					streamWriter.WriteLine("  创建失败，返回null");
				}
			}
			catch (Exception ex2)
			{
				streamWriter.WriteLine("  创建异常: " + ex2.Message + "\n" + ex2.StackTrace);
			}
			streamWriter.WriteLine("\n");
			streamWriter.WriteLine("===== 2. MachineBayExt（机器区扩建） =====");
			try
			{
				GameItem val3 = DirectoryMaster.Item("machine_bay_ext", true);
				if (val3 != null)
