			{
				streamWriter.WriteLine("  创建异常: " + ex3.Message + "\n" + ex3.StackTrace);
			}
			streamWriter.WriteLine("\n");
			streamWriter.WriteLine("===== 3. StorageBayLarge（大储物箱） =====");
