				text += $"组件({array.Length}):";
				for (int i = 0; i < Math.Min(array.Length, 5); i++)
				{
					if ((Object)(object)array[i] != (Object)null)
					{
						text += ((object)array[i]).GetType().Name;
						if (i < Math.Min(array.Length, 5) - 1)
						{
							text += ",";
						}
					}
				}
				if (array.Length > 5)
				{
					text += "...";
				}
				text += " | ";
			}
			string keyFields = GetKeyFields(obj);
			if (!string.IsNullOrEmpty(keyFields))
			{
				text = text + "Key:" + keyFields;
			}
			return text;
		}
		catch (Exception ex)
		{
			return "构建信息失败:" + ex.Message;
		}
	}

	private static string GetHierarchyPath(Transform transform)
	{
		try
		{
			string text = ((Object)transform).name;
			Transform parent = transform.parent;
			int num = 0;
			while ((Object)(object)parent != (Object)null && num < 8)
			{
				text = ((Object)parent).name + "/" + text;
				parent = parent.parent;
				num++;
			}
			return text;
		}
		catch
		{
			return "未知";
		}
	}

	private static string GetKeyFields(GameObject obj)
	{
		try
		{
			List<string> list = new List<string>();
			Component[] array = Il2CppArrayBase<Component>.op_Implicit(obj.GetComponents<Component>());
			foreach (Component val in array)
			{
				if ((Object)(object)val == (Object)null)
				{
					continue;
				}
				Type type = ((object)val).GetType();
				FieldInfo[] fields = type.GetFields(BindingFlags.Instance | BindingFlags.Public);
				foreach (FieldInfo fieldInfo in fields)
				{
					string text = fieldInfo.Name.ToLower();
					if (!text.Contains("id") && !text.Contains("key") && !text.Contains("identifier") && !text.Contains("clientid") && !text.Contains("itemid") && !text.Contains("tag"))
					{
						continue;
					}
					try
					{
						object value = fieldInfo.GetValue(val);
						if (value != null)
						{
							list.Add($"{fieldInfo.Name}={value}");
						}
					}
					catch
					{
					}
				}
				PropertyInfo[] properties = type.GetProperties(BindingFlags.Instance | BindingFlags.Public);
				foreach (PropertyInfo propertyInfo in properties)
				{
					string text2 = propertyInfo.Name.ToLower();
					if (!text2.Contains("id") && !text2.Contains("key") && !text2.Contains("identifier") && !text2.Contains("clientid") && !text2.Contains("itemid") && !text2.Contains("tag"))
					{
						continue;
					}
					try
					{
						if (propertyInfo.CanRead && propertyInfo.GetIndexParameters().Length == 0)
						{
							object value2 = propertyInfo.GetValue(val, null);
							if (value2 != null)
							{
								list.Add($"{propertyInfo.Name}={value2}");
							}
						}
					}
					catch
					{
					}
				}
			}
			return (list.Count > 0) ? string.Join(",", list.ToArray()) : "无key字段";
		}
		catch
		{
			return "无key字段";
		}
	}

	private static void DumpObjectToFile(GameObject obj)
	{
		//IL_0095: Unknown result type (might be due to invalid IL or missing references)
		//IL_009a: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			using StreamWriter streamWriter = new StreamWriter(Path.Combine(Application.dataPath, "..", "Mods", "inspector_dump.txt"), append: false, Encoding.UTF8);
			streamWriter.WriteLine("===== Runtime Inspector Dump =====");
			streamWriter.WriteLine($"时间: {DateTime.Now}");
			streamWriter.WriteLine("对象名: " + ((Object)obj).name);
			streamWriter.WriteLine("类型: " + ((object)obj).GetType().FullName);
			Scene scene = obj.scene;
			streamWriter.WriteLine("场景: " + scene.name);
			streamWriter.WriteLine("路径: " + GetHierarchyPath(obj.transform));
			streamWriter.WriteLine("");
			Component[] array = Il2CppArrayBase<Component>.op_Implicit(obj.GetComponents<Component>());
			streamWriter.WriteLine($"===== 组件列表 ({array.Length}) =====");
			Component[] array2 = array;
			foreach (Component val in array2)
			{
				if ((Object)(object)val == (Object)null)
				{
					continue;
				}
				streamWriter.WriteLine("\n--- " + ((object)val).GetType().FullName + " ---");
				FieldInfo[] fields = ((object)val).GetType().GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				streamWriter.WriteLine($"  字段 ({fields.Length}):");
				FieldInfo[] array3 = fields;
				foreach (FieldInfo fieldInfo in array3)
				{
					try
					{
						object value = fieldInfo.GetValue(val);
						string text = ((value != null) ? value.ToString() : "null");
						if (text.Length > 200)
						{
							text = text.Substring(0, 200) + "...";
						}
						streamWriter.WriteLine($"    {fieldInfo.FieldType.Name} {fieldInfo.Name} = {text}");
					}
					catch (Exception ex)
					{
						streamWriter.WriteLine($"    {fieldInfo.Name} = [读取失败: {ex.Message}]");
					}
				}
				PropertyInfo[] properties = ((object)val).GetType().GetProperties(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				streamWriter.WriteLine($"  属性 ({properties.Length}):");
				PropertyInfo[] array4 = properties;
				foreach (PropertyInfo propertyInfo in array4)
				{
					try
					{
						if (propertyInfo.CanRead && propertyInfo.GetIndexParameters().Length == 0)
						{
							object value2 = propertyInfo.GetValue(val, null);
							string text2 = ((value2 != null) ? value2.ToString() : "null");
							if (text2.Length > 200)
							{
								text2 = text2.Substring(0, 200) + "...";
							}
							streamWriter.WriteLine($"    {propertyInfo.PropertyType.Name} {propertyInfo.Name} = {text2}");
						}
					}
					catch (Exception ex2)
					{
						streamWriter.WriteLine($"    {propertyInfo.Name} = [读取失败: {ex2.Message}]");
					}
				}
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[RuntimeInspector] Dump失败: " + ex3.Message);
		}
	}
