		{
		}
	}

	private static IEnumerator RunTestsCoroutine()
	{
		if (!_testModeEnabled)
		{
			yield break;
		}
		yield return (object)new WaitForEndOfFrame();
		Thread.Sleep(3000);
		for (float autoSaveWait = 0f; autoSaveWait < 55f; autoSaveWait++)
		{
			if (!_continueTried)
			{
				try
				{
					SaveUIManager val = FindComponentInScene<SaveUIManager>();
					if ((Object)(object)val != (Object)null)
					{
						val.OpenUI();
						_continueTried = true;
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[AutoSave] OpenUI失败: " + ex.Message);
					_continueTried = true;
				}
			}
			if (_continueTried && !_slotLoadTried)
			{
				try
				{
					List<SaveSlotElement> list = new List<SaveSlotElement>();
					try
					{
						Scene activeScene = SceneManager.GetActiveScene();
						if (activeScene.IsValid())
						{
							foreach (GameObject item in (Il2CppArrayBase<GameObject>)(object)activeScene.GetRootGameObjects())
							{
								if (!((Object)(object)item == (Object)null))
								{
									Il2CppArrayBase<SaveSlotElement> componentsInChildren = item.GetComponentsInChildren<SaveSlotElement>(true);
									if (componentsInChildren != null && componentsInChildren.Length > 0)
									{
										list.AddRange((IEnumerable<SaveSlotElement>)componentsInChildren);
									}
								}
							}
						}
					}
					catch (Exception ex2)
					{
						Core.LogMsg("[AutoSave] 遍历槽位异常: " + ex2.Message);
					}
					if (list != null && list.Count > 0)
					{
						int num = -1;
						SaveSlotElement val2 = null;
						foreach (SaveSlotElement item2 in list)
						{
							if ((Object)(object)item2 != (Object)null && item2.slotId > num)
							{
								num = item2.slotId;
								val2 = item2;
							}
						}
						if ((Object)(object)val2 != (Object)null)
						{
							AccessTools.Method(AccessTools.TypeByName("SaveSlotElement"), "LoadSlot", (Type[])null, (Type[])null).Invoke(val2, null);
							_slotLoadTried = true;
						}
					}
				}
				catch (Exception ex3)
				{
					Core.LogMsg("[AutoSave] LoadSlot失败: " + ex3.Message);
					_slotLoadTried = true;
				}
			}
			try
			{
				if (!((Object)(object)MainMenuUIController.Instance != (Object)null) && PlayerStore.Instance != null)
				{
					break;
				}
			}
			catch
			{
			}
			yield return (object)new WaitForSeconds(1f);
		}
		yield return (object)new WaitForSeconds(2f);
		UpdateHeartbeat("测试初始化完成");
		UpdateHeartbeat("读取飞书测试目标");
		RunTargetTests();
		UpdateHeartbeat("Mod加载状态测试");
		RunTestCase("Mod加载状态", TestCase_ModLoaded);
		UpdateHeartbeat("关键类存在性测试");
		RunTestCase("关键类存在性", TestCase_KeyClassesExist);
		UpdateHeartbeat("关键方法存在性测试");
		RunTestCase("关键方法存在性", TestCase_KeyMethodsExist);
		UpdateHeartbeat("蛙哥物品池完整性测试");
		RunTestCase("蛙哥物品池完整性", TestCase_ItemPoolIntegrity);
		UpdateHeartbeat("自定义储物箱测试");
		RunTestCase("自定义储物箱创建和shape", TestCase_CustomStorageContainer);
		UpdateHeartbeat("物品shape大小dump");
		RunTestCase("物品shape大小dump", TestCase_DumpItemShapes);
		UpdateHeartbeat("游戏流程测试");
		yield return RunGameFlow();
		UpdateHeartbeat("全部测试完成，准备退出");
		Core.LogMsg($"[TestRunner] 通过: {_passed}  失败: {_failed}  跳过: {_skipped}");
		try
		{
			string contents = $"\n===== 汇总 =====\n通过: {_passed}\n失败: {_failed}\n跳过: {_skipped}\n总耗时: {_totalStopwatch.ElapsedMilliseconds}ms\n";
			File.AppendAllText(_resultFile, contents);
		}
		catch
		{
		}
		if (!_testModeEnabled)
		{
			yield break;
		}
		UpdateHeartbeat("退出中_L1_Application.Quit");
		try
		{
			Application.Quit();
		}
		catch (Exception ex4)
		{
			Core.LogMsg("[TestRunner] L1失败: " + ex4.Message);
		}
		yield return (object)new WaitForSeconds(1f);
		UpdateHeartbeat("退出中_L2_Environment.Exit");
		try
		{
			Environment.Exit(0);
		}
		catch (Exception ex5)
		{
			Core.LogMsg("[TestRunner] L2失败: " + ex5.Message);
		}
		yield return (object)new WaitForSeconds(0.5f);
		UpdateHeartbeat("退出中_L3_Process.Kill");
		try
		{
			Process.GetCurrentProcess().Kill();
		}
		catch (Exception ex6)
		{
			Core.LogMsg("[TestRunner] L3失败: " + ex6.Message);
		}
		yield return (object)new WaitForSeconds(0.5f);
		try
		{
			Process.GetCurrentProcess().CloseMainWindow();
			Process.GetCurrentProcess().Kill();
		}
		catch
		{
		}
	}

	private static void RunTestCase(string name, Action testAction)
	{
		Stopwatch stopwatch = Stopwatch.StartNew();
		string text = "PASS";
		string text2 = "";
		try
		{
			testAction();
			_passed++;
			text = "PASS";
			text2 = "执行成功";
		}
		catch (Exception ex)
		{
			_failed++;
			text = "FAIL";
			text2 = ex.Message;
			if (ex.InnerException != null)
			{
				text2 = text2 + " | Inner: " + ex.InnerException.Message;
			}
		}
		stopwatch.Stop();
		try
		{
			string contents = $"{name}|{text}|{text2}|{stopwatch.ElapsedMilliseconds}ms\n";
			File.AppendAllText(_resultFile, contents);
		}
		catch
		{
		}
	}

