		}
		if (AccessTools.Method(type3, "CreateDoctor", (Type[])null, (Type[])null) == null)
		{
			throw new Exception("TraderFactory.CreateDoctor()方法未找到");
		}
	}

	private static void TestCase_ItemPoolIntegrity()
	{
		string[] itemPool = WagePowerPerk.ItemPool;
		if (itemPool == null || itemPool.Length == 0)
		{
			throw new Exception("蛙哥物品池为空");
		}
		int num = itemPool.Distinct().Count();
		if (num != itemPool.Length)
		{
			throw new Exception($"物品池有重复: 总{itemPool.Length}个，去重后{num}个");
		}
		string[] array = new string[2] { "raw_meat", "beer_case" };
		foreach (string value in array)
		{
			Enumerable.Contains(itemPool, value);
		}
		string[] array2 = new string[7] { "node", "node_medium", "node_small", "stun_baton", "surgery_tool", "tazer", "backpack_medium_military" };
		int num2 = 0;
		array = array2;
		foreach (string value2 in array)
		{
			if (Enumerable.Contains(itemPool, value2))
			{
				num2++;
			}
		}
	}

