	private static IEnumerator FlowTrade()
	{
		PlayerStore ps = PlayerStore.Instance;
		int totalClient = 0;
		int soldCount = 0;
		int boughtCount = 0;
		int dismissedCount = 0;
		int loopGuard = 0;
		while (loopGuard < 30)
		{
			loopGuard++;
			int num = -1;
			int num2 = -1;
			try
			{
				StoreClientManager val = ((ps != null) ? ps.storeClientManager : null);
				num = ((val != null && val.clientStack != null) ? val.clientStack.Count : (-1));
				num2 = ((ps != null && ps.futurStoreClientIdQueue != null) ? ps.futurStoreClientIdQueue.Count : (-1));
			}
			catch (Exception ex)
			{
				Core.LogMsg("[Flow] 队列读取异常: " + ex.Message);
			}
			Core.LogMsg("[Flow] 当前 clientStack=" + num + " futurQueue=" + num2 + " currentClient=" + ((ps != null && ps.currentClientInstance != null) ? "存在" : "null"));
			if (ps == null)
			{
				try
				{
					ps = PlayerStore.Instance;
				}
				catch
				{
				}
			}
			if (ps == null)
			{
				break;
			}
			if (ps.currentClientInstance == null)
			{
				bool clientArrived = false;
				int callRetry = 0;
				while (callRetry < 3)
				{
					callRetry++;
					try
					{
						ps.TryCallNextClient();
					}
					catch (Exception ex2)
					{
						Core.LogMsg("[Flow] TryCallNextClient异常: " + ex2.Message);
					}
					try
					{
						StoreUIManager instance = StoreUIManager.Instance;
						if ((Object)(object)instance != (Object)null)
						{
							instance.QueueClientArriveAnimation();
						}
					}
					catch (Exception ex3)
					{
						Core.LogMsg("[Flow] 进场动画异常: " + ex3.Message);
					}
					float cwait = 0f;
					float maxWait = callRetry switch
					{
						2 => 10f, 
						1 => 8f, 
						_ => 12f, 
					};
					while (cwait < maxWait)
					{
						yield return (object)new WaitForSeconds(1f);
						cwait++;
						try
						{
							ps = PlayerStore.Instance;
						}
						catch
						{
						}
						if (ps != null && ps.currentClientInstance != null)
						{
							clientArrived = true;
							break;
						}
					}
					if (clientArrived)
					{
						break;
					}
					int num3 = -1;
					int num4 = -1;
					try
					{
						StoreClientManager val2 = ((ps != null) ? ps.storeClientManager : null);
						num3 = ((val2 != null && val2.clientStack != null) ? val2.clientStack.Count : (-1));
					}
					catch
					{
					}
					try
					{
						num4 = ((ps != null && ps.futurStoreClientIdQueue != null) ? ps.futurStoreClientIdQueue.Count : (-1));
					}
					catch
					{
					}
					if (num3 <= 0 && num4 <= 0)
					{
						yield break;
					}
				}
				if (!clientArrived)
				{
					Core.LogMsg("[Flow] 重试" + 3 + "次后客户仍未到店（重试仍失败，继续）");
					yield return (object)new WaitForSeconds(2f);
					continue;
				}
			}
			totalClient++;
			int intent = -1;
			try
			{
				intent = (int)ps.GetCurrentClientIntent();
			}
			catch (Exception ex4)
			{
				Core.LogMsg("[Flow] intent 读取异常: " + ex4.Message);
			}
			bool handled = false;
			if (intent == 1 || intent == 3)
			{
				GameItem toSell = null;
				try
				{
					List<GameItem> val3 = ps.FindAllItem(true);
					if ((val3?.Count ?? 0) > 0 && val3[0] != null)
					{
						toSell = val3[0];
						int num5 = 0;
						bool flag = false;
						while (num5 < 2 && !flag)
						{
							num5++;
							try
							{
								ps.PlacedItemForSelling(toSell);
								flag = true;
							}
							catch (Exception ex5)
							{
								Core.LogMsg("[Flow] PlacedItemForSelling异常(第" + num5 + "次): " + ex5.Message);
							}
							if (!flag)
							{
								Thread.Sleep(3000);
							}
						}
						if (!flag)
						{
							Core.LogMsg("[Flow] PlacedItemForSelling 重试仍失败");
						}
					}
				}
				catch (Exception ex6)
				{
					Core.LogMsg("[Flow] 出售流程异常: " + ex6.Message);
				}
				yield return (object)new WaitForSeconds(2f);
				if (toSell != null)
				{
					NegociationUIManager instance2 = NegociationUIManager.Instance;
					if ((Object)(object)instance2 != (Object)null)
					{
						int num6 = 0;
						bool flag2 = false;
						while (num6 < 2 && !flag2)
						{
							num6++;
							try
							{
								instance2.OnOfferAcceptClick();
								flag2 = true;
								soldCount++;
							}
							catch (Exception ex7)
							{
								Core.LogMsg("[Flow] OnOfferAcceptClick异常(第" + num6 + "次): " + ex7.Message);
							}
							if (!flag2)
							{
								Thread.Sleep(3000);
							}
						}
						if (!flag2)
						{
							Core.LogMsg("[Flow] OnOfferAcceptClick 重试仍失败");
						}
					}
					handled = true;
				}
			}
			if (intent == 2 || intent == 3)
			{
				try
				{
					NegociationUIManager instance3 = NegociationUIManager.Instance;
					if ((Object)(object)instance3 != (Object)null)
					{
						int num7 = 0;
						bool flag3 = false;
						while (num7 < 2 && !flag3)
						{
							num7++;
							try
							{
								instance3.BuyItem();
								flag3 = true;
								boughtCount++;
							}
							catch (Exception ex8)
							{
								Core.LogMsg("[Flow] BuyItem异常(第" + num7 + "次): " + ex8.Message);
							}
							if (!flag3)
							{
								Thread.Sleep(3000);
							}
						}
						if (!flag3)
						{
							Core.LogMsg("[Flow] BuyItem 重试仍失败");
						}
						handled = true;
					}
					else
					{
						Core.LogMsg("[Flow] 交易UI为null，跳过购买");
					}
				}
				catch (Exception ex9)
				{
					Core.LogMsg("[Flow] 购买流程异常: " + ex9.Message);
				}
			}
			if (!handled)
			{
				try
				{
					NegociationUIManager instance4 = NegociationUIManager.Instance;
					if ((Object)(object)instance4 != (Object)null)
					{
						instance4.OnOfferAcceptClick();
					}
				}
				catch (Exception ex10)
				{
					Core.LogMsg("[Flow] 通用接受异常: " + ex10.Message);
				}
			}
			yield return (object)new WaitForSeconds(2f);
			int num8 = 0;
			bool flag4 = false;
			while (num8 < 2 && !flag4)
			{
				num8++;
				try
				{
					ps.DismissCurrentClient(true, true, true);
					flag4 = true;
					dismissedCount++;
				}
				catch (Exception ex11)
				{
					Core.LogMsg("[Flow] DismissCurrentClient异常(第" + num8 + "次): " + ex11.Message);
				}
				if (!flag4)
				{
					Thread.Sleep(3000);
				}
			}
			if (!flag4)
			{
				Core.LogMsg("[Flow] DismissCurrentClient 重试仍失败");
			}
			yield return (object)new WaitForSeconds(2f);
			int num9 = -1;
			int num10 = -1;
			try
			{
				StoreClientManager storeClientManager = ps.storeClientManager;
				num9 = ((storeClientManager != null && storeClientManager.clientStack != null) ? storeClientManager.clientStack.Count : (-1));
			}
			catch
			{
			}
			try
			{
				num10 = ((ps != null && ps.futurStoreClientIdQueue != null) ? ps.futurStoreClientIdQueue.Count : (-1));
			}
			catch
			{
			}
			if (num9 <= 0 && num10 <= 0)
			{
				break;
			}
		}
	}

