	private static void RunTargetTests()
	{
		if (!File.Exists(_targetsFile))
		{
			WriteResult("AutoSelfTest", "SKIP", "test_targets.txt 不存在（先运行 sync_test_targets.py 同步飞书任务）", 0L);
			return;
		}
		string[] array = File.ReadAllLines(_targetsFile);
		int num = 0;
		string[] array2 = array;
		foreach (string text in array2)
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				string[] array3 = text.Split('|');
				if (array3.Length >= 2)
				{
					num++;
					string rid = array3[0].Trim();
					string name = array3[1].Trim();
					string desc = ((array3.Length > 3) ? array3[3].Trim() : "");
					RunTargetTestCase(rid, name, desc);
				}
			}
		}
	}

	private static void RunTargetTestCase(string rid, string name, string desc)
	{
		Stopwatch stopwatch = Stopwatch.StartNew();
		string text = "FAIL";
		string text2 = "";
		string text3 = "[" + rid + "] " + name;
		UpdateHeartbeat(text3);
		try
		{
			text2 = RunMatchedTest(name, desc);
			text = "PASS";
		}
		catch (Exception ex)
		{
			if (ex.Message.StartsWith("SKIP:"))
			{
				text = "SKIP";
				text2 = ex.Message.Substring(5);
			}
			else
			{
				text = "FAIL";
				text2 = ex.Message;
			}
			if (ex.InnerException != null)
			{
				text2 = text2 + " | Inner:" + ex.InnerException.Message;
			}
		}
		stopwatch.Stop();
		WriteResult(text3, text, text2, stopwatch.ElapsedMilliseconds);
	}

	private static string RunMatchedTest(string name, string desc)
	{
		string text = (name + " " + desc).ToLowerInvariant();
		StringBuilder stringBuilder = new StringBuilder();
		if (text.Contains("对话") || text.Contains("台词") || text.Contains("空白") || text.Contains("first"))
		{
			Test_P0Dialogue(stringBuilder);
			return stringBuilder.ToString();
		}
		if (text.Contains("酵母") || text.Contains("owned") || text.Contains("未拥有"))
		{
			Test_YeastOwned(stringBuilder);
			return stringBuilder.ToString();
		}
		if (text.Contains("盗窃") || text.Contains("stolen"))
		{
			Test_Stolen(stringBuilder);
			return stringBuilder.ToString();
		}
		if (text.Contains("捡漏") || text.Contains("拾荒") || text.Contains("工具箱") || text.Contains("探测器"))
		{
			Test_LuckScout(stringBuilder);
			return stringBuilder.ToString();
		}
		if (text.Contains("稀有率"))
		{
			Test_RareRate(stringBuilder);
			return stringBuilder.ToString();
		}
		Test_Generic(stringBuilder);
		return stringBuilder.ToString();
	}

	private static bool HasTag(GameItem item, string tagName)
	{
		try
		{
			return item.GetTagReadonly(tagName) != null;
		}
		catch
		{
			return false;
		}
	}

	private static T FindComponentInScene<T>() where T : Component
	{
		//IL_0000: Unknown result type (might be due to invalid IL or missing references)
		//IL_0005: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			Scene activeScene = SceneManager.GetActiveScene();
			if (!activeScene.IsValid())
			{
				return default;
			}
			foreach (GameObject item in (Il2CppArrayBase<GameObject>)(object)activeScene.GetRootGameObjects())
			{
				if (!((Object)(object)item == (Object)null))
				{
					T componentInChildren = item.GetComponentInChildren<T>(true);
					if ((Object)(object)componentInChildren != (Object)null)
					{
						return componentInChildren;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[SceneScan] FindComponent异常: " + ex.Message);
		}
		return default;
	}

