	private static void Test_YeastOwned(StringBuilder log)
	{
		GameItem val = SafeCreateItem("wine_yeast");
		if (val == null)
		{
			throw new Exception("wine_yeast 创建失败");
		}
		GameItem val2 = val.CloneLinked() ?? throw new Exception("CloneLinked 返回 null");
		if (((Il2CppObjectBase)val2).Pointer == ((Il2CppObjectBase)val).Pointer)
		{
			throw new Exception("克隆与共享实例同指针（克隆失败）");
		}
		val2.EnableTag("AUTO_TEST_ISOLATION", true);
		if (!HasTag(val2, "AUTO_TEST_ISOLATION"))
		{
			throw new Exception("克隆标签添加失败");
		}
		if (HasTag(val, "AUTO_TEST_ISOLATION"))
		{
			throw new Exception("克隆修改污染共享实例（未隔离）");
		}
		log.Append("wine_yeast创建? 克隆指针独立? 克隆改标签不污染共享实例?");
	}

	private static void Test_Stolen(StringBuilder log)
