	private static bool IsJackson(StoreClient client)
	{
		if (client == null)
		{
			return false;
		}
		string text = client.displayName ?? client.identifier ?? "";
		if (!text.Contains("博士") && !text.Contains("Jackson"))
		{
			return text.Contains("jackson");
		}
		return true;
	}

	private static int GetCurrentDay()
	{
		try
		{
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				if (!assembly.GetName().Name.StartsWith("Assembly-CSharp"))
				{
					continue;
				}
				Type[] types;
				try
				{
					types = assembly.GetTypes();
				}
				catch (ReflectionTypeLoadException ex)
				{
					types = ex.Types;
				}
				Type[] array = types;
				foreach (Type type in array)
				{
					if (type == null)
					{
						continue;
					}
					PropertyInfo[] properties = type.GetProperties(BindingFlags.Static | BindingFlags.Public);
					foreach (PropertyInfo propertyInfo in properties)
					{
						if ((!(propertyInfo.Name == "currentDay") && !(propertyInfo.Name == "CurrentDay") && !(propertyInfo.Name == "day")) || !(propertyInfo.PropertyType == typeof(int)))
						{
							continue;
						}
						try
						{
							object value = propertyInfo.GetValue(null);
							if (value != null && (int)value > 0)
							{
								return (int)value;
							}
						}
						catch (Exception ex2)
						{
							Core.LogMsg("[DrJacksonFriendPerk] 异常: " + ex2.Message);
						}
					}
				}
			}
		}
		catch
		{
		}
		return -1;
	}

