	internal static void RegisterInventorStockHook()
	{
		try
		{
			if ((Delegate)(object)_onInventorStock == (Delegate)null)
			{
				_onInventorStock = DelegateSupport.ConvertDelegate<Action<List<GameItem>>>((Delegate)new Action<List<GameItem>>(OnInventorStock));
				ModHook.OnPlaceInventorInventoryItemEarly += _onInventorStock;
				ModHook.OnPlaceInventorInventoryItemLate += _onInventorStock;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[博士之友] RegisterInventorStockHook 异常: " + ex.Message);
		}
