	private static void OnInventorStock(List<GameItem> playerItems)
	{
		try
		{
			if (!IsActive())
			{
				return;
			}
			StoreClient client = null;
			try
			{
				if (PlayerStore.Instance != null && PlayerStore.Instance.currentClientInstance != null)
				{
					client = PlayerStore.Instance.currentClientInstance.GetClientBlueprint();
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[DrJacksonFriendPerk] 异常: " + ex.Message);
			}
			AddJacksonGoodsToCounter(client);
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[博士之友] OnInventorStock 异常: " + ex2.Message);
		}
	}

	private static bool CounterHasOnFront(string itemId)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.frontInvinvElement == null || instance.frontInvinvElement.items == null)
			{
				return false;
			}
			Enumerator<GameItem> enumerator = instance.frontInvinvElement.items.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current != null && current.identifier == itemId)
				{
					return true;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[DrJacksonFriendPerk] 异常: " + ex.Message);
		}
		return false;
	}

	internal static void AddJacksonGoodsToCounter(StoreClient client)
	{
		if (!IsActive())
		{
			return;
		}
		try
		{
			if (PlayerStore.Instance == null)
			{
				return;
			}
			List<string> list = new List<string> { "machine_bay_ext", "storage_bay_large" };
			if (BuildConfig.HardMode)
			{
				list.Add("system_capped_neural_core");
			}
			int num = 0;
			foreach (string item in list)
			{
				try
				{
					if (CounterHasOnFront(item) || !DirectoryMaster.Has<GameItem>(item))
					{
						continue;
					}
					GameItem val = DirectoryMaster.Item(item, true);
					if (val == null)
					{
						continue;
					}
					if (IsActive())
					{
						try
						{
							Patches.ApplyFriendDiscountToItem(val);
						}
						catch
						{
						}
					}
					GameItem val2 = MerchantHelper.AddItemToCounter(val);
					if (val2 != null)
					{
						num++;
						try
						{
							val2.GetTagReadonly("STOLEN_VALUE_INT");
							StolenHelper.IsStolenItem(val2);
						}
						catch
						{
						}
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[博士之友] 添加" + item + "失败: " + ex.Message);
				}
			}
			try
			{
				client.clientIntent = (ClientIntent)3;
			}
			catch
			{
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[博士之友] AddJacksonGoodsToCounter失败: " + ex2.Message);
		}
	}

	private static void AddNeuralCoreToDoctorInv(EmporiumEntry instance)
	{
		try
		{
			GameGridInventory afterhourInventory = instance.afterhourInventory;
			if (afterhourInventory == null)
			{
				return;
			}
			PropertyInfo property = ((object)afterhourInventory).GetType().GetProperty("Count");
			if (property != null)
			{
				_ = (int)property.GetValue(afterhourInventory);
			}
			GameItem val = DirectoryMaster.Item("system_capped_neural_core", true);
			if (val == null)
			{
				return;
			}
			MethodInfo method = ((object)afterhourInventory).GetType().GetMethod("UncheckedAccept");
			if (method != null)
			{
				if (!(bool)method.Invoke(afterhourInventory, new object[1] { val }))
				{
				}
				return;
			}
			MethodInfo method2 = ((object)afterhourInventory).GetType().GetMethod("Add");
			if (method2 != null)
			{
				method2.Invoke(afterhourInventory, new object[1] { val });
			}
		}
		catch (Exception ex)
		{
			MelonLogger.Error("[博士之友] AddNeuralCoreToDoctorInv失败: " + ex.Message);
		}
	}

	private static void AddToAfterhourInventoryDirectly(EmporiumEntry instance, GameItem item)
	{
		try
		{
			if (instance.afterhourInventory == null)
			{
				return;
			}
			MethodInfo method = ((object)instance.afterhourInventory).GetType().GetMethod("AddItem", BindingFlags.Instance | BindingFlags.Public);
			if (method != null)
			{
				method.Invoke(instance.afterhourInventory, new object[1] { item });
				return;
			}
			MethodInfo method2 = ((object)instance.afterhourInventory).GetType().GetMethod("InsertItem", BindingFlags.Instance | BindingFlags.Public);
			if (method2 != null)
			{
				method2.Invoke(instance.afterhourInventory, new object[3] { item, 0, 0 });
				return;
			}
			MethodInfo method3 = ((object)instance.afterhourInventory).GetType().GetMethod("Add", BindingFlags.Instance | BindingFlags.Public);
			if (method3 != null)
			{
				method3.Invoke(instance.afterhourInventory, new object[1] { item });
			}
		}
		catch (Exception ex)
		{
			MelonLogger.Error("[博士之友] 直接添加到afterhourInventory失败: " + ex.Message);
		}
	}
