					Core.LogMsg("[养蛊机] 懒加载图标: gu=" + (((Object)(object)_guSprite != (Object)null) ? "?" : "?") + " ai=" + (((Object)(object)_aiSprite != (Object)null) ? "?" : "?") + " prot=" + (((Object)(object)_protectorSprite != (Object)null) ? "?" : "?"));
				}
				if (name == "gu_machine" && (Object)(object)_guSprite != (Object)null)
