	private static Sprite LoadPngSprite(string fileName)
	{
		//IL_0079: Unknown result type (might be due to invalid IL or missing references)
		//IL_0080: Expected Obj, but got Unknown
		//IL_017b: Unknown result type (might be due to invalid IL or missing references)
		//IL_018a: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			Assembly executingAssembly = Assembly.GetExecutingAssembly();
			string text = null;
			string[] manifestResourceNames = executingAssembly.GetManifestResourceNames();
			foreach (string text2 in manifestResourceNames)
			{
				if (text2.EndsWith(fileName))
				{
					text = text2;
					break;
				}
			}
			if (text == null)
			{
				Core.LogMsg("[养蛊机] 图标资源未找到: " + fileName);
				return null;
			}
			using Stream stream = executingAssembly.GetManifestResourceStream(text);
			byte[] array = new byte[stream.Length];
			stream.Read(array, 0, array.Length);
			Texture2D val = new Texture2D(2, 2, (TextureFormat)4, false);
			((Texture)val).filterMode = (FilterMode)0;
			((Texture)val).wrapMode = (TextureWrapMode)1;
			Type type = null;
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				Type[] types;
				try
				{
					types = assembly.GetTypes();
				}
				catch (ReflectionTypeLoadException ex)
				{
					types = ex.Types;
				}
				Type[] array2 = types;
				foreach (Type type2 in array2)
				{
					if (type2 != null && type2.Name == "ImageConversion")
					{
						type = type2;
						break;
					}
				}
				if (type != null)
				{
					break;
				}
			}
			type.GetMethod("LoadImage", new Type[2]
			{
				typeof(Texture2D),
				typeof(Il2CppStructArray<byte>)
			}).Invoke(null, new object[2]
			{
				val,
				Il2CppStructArray<byte>.op_Implicit(array)
			});
			return Sprite.Create(val, new Rect(0f, 0f, (float)((Texture)val).width, (float)((Texture)val).height), new Vector2(0.5f, 0.5f), 200f);
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[养蛊机] 图标加载失败 " + fileName + ": " + ex2.Message);
			return null;
		}
	}

	public static void OnDayStartPostfix()
	{
		try
		{
			int currentDay = DeterministicSchedule.CurrentDay;
			Core.LogMsg("[养蛊机] OnDayStart day=" + currentDay);
			List<GameItem> list = FindGuMachines();
			Core.LogMsg("[养蛊机] FindGuMachines=" + list.Count);
			foreach (GameItem item in list)
			{
				TryGuMachineTick(item, currentDay);
			}
			foreach (GameItem item2 in FindAiGenerators())
			{
				TryAiGeneratorTick(item2, currentDay);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[GuMachineSystem.DayLoop] 异常: " + ex.Message);
		}
	}

	private static List<GameItem> FindGuMachines()
	{
		List<GameItem> list = new List<GameItem>();
		HashSet<GameItem> hashSet = new HashSet<GameItem>();
		try
		{
			List<GameItem> val = PlayerStore.Instance.FindAllItem(true);
			if (val != null)
			{
				Enumerator<GameItem> enumerator = val.GetEnumerator();
				while (enumerator.MoveNext())
				{
					GameItem current = enumerator.Current;
					if (current != null && current.identifier == "wage_gu_machine" && hashSet.Add(current))
					{
						list.Add(current);
					}
				}
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance != (Object)null)
			{
				GameInventory[] array = new GameInventory[4]
				{
					(GameInventory)instance.backInvinvElement,
					(GameInventory)instance.showcaseElement,
					(GameInventory)instance.invElement,
					(GameInventory)instance.frontInvinvElement
				};
				foreach (GameInventory val2 in array)
				{
					if (val2 == null || val2.childItems == null)
					{
						continue;
					}
					Enumerator<GameItem> enumerator = val2.childItems.GetEnumerator();
					while (enumerator.MoveNext())
					{
						GameItem current2 = enumerator.Current;
						if (current2 != null && current2.identifier == "wage_gu_machine" && hashSet.Add(current2))
						{
							list.Add(current2);
						}
					}
				}
			}
			Core.LogMsg("[养蛊] FindGuMachines=" + list.Count);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[GuMachineSystem.DayLoop] 异常: " + ex.Message);
		}
		return list;
	}

	internal static GameGridInventory GetGuGrid(GameItem gu)
	{
		try
		{
			if (gu == null || gu.contentWindow == null || gu.contentWindow.childElement == null)
			{
				return null;
			}
			return ((Il2CppObjectBase)gu.contentWindow.childElement).TryCast<GameGridInventory>();
		}
		catch
		{
			return null;
		}
	}

	private static void LockGuModules(GameGridInventory grid)
	{
		try
		{
			if (grid == null || ((GameInventory)grid).childItems == null)
			{
				return;
			}
			Enumerator<GameItem> enumerator = ((GameInventory)grid).childItems.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				bool flag = false;
				try
				{
					flag = current.IsTag("MODULE_TAG") && !RobinCrusoePerk.IsExcludedModule(current);
				}
				catch
				{
				}
				if (flag)
				{
					try
					{
						current.EnableTag("MODULE_STUCK_TAG", false);
					}
					catch
					{
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[GuMachineSystem.DayLoop] 异常: " + ex.Message);
		}
	}

	private static void UnlockGuModules(GameGridInventory grid)
	{
		try
		{
			if (grid == null || ((GameInventory)grid).childItems == null)
			{
				return;
			}
			Enumerator<GameItem> enumerator = ((GameInventory)grid).childItems.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				try
				{
					if (current.IsTag("MODULE_STUCK_TAG"))
					{
						current.DisableTag("MODULE_STUCK_TAG", false);
					}
				}
				catch
				{
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[GuMachineSystem.DayLoop] 异常: " + ex.Message);
		}
	}

	public static void RegisterToDirectory(ItemDirectory dir)
	{
		try
		{
			if (!((Object)(object)dir == (Object)null))
			{
				RegisterOne(dir, "wage_gu_machine", ref _guFactory, CreateGuMachine);
				RegisterOne(dir, "wage_ai_generator", ref _aiFactory, CreateAiGenerator);
				RegisterOne(dir, "wage_protector_core", ref _protectorFactory, CreateProtectorCore);
				RegisterOne(dir, "wage_ai_module", ref _aiModuleFactory, CreateAiModule);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[养蛊机] 注册异常: " + ex.Message);
		}
	}

	private static void RegisterOne(ItemDirectory dir, string id, ref Func<GameItem> cache, Func<GameItem> factory)
	{
		try
		{
			if (((Directory<GameItem>)(object)dir).Has(id))
			{
				return;
			}
			if ((Delegate)(object)cache == (Delegate)null)
			{
				Func<GameItem> func = () => factory();
				cache = DelegateSupport.ConvertDelegate<Func<GameItem>>((Delegate)func);
			}
			bool flag = ((Directory<GameItem>)(object)dir).Add(id, cache);
			Core.LogMsg("[养蛊机] " + (flag ? ("★ " + id + " 已注册") : ("?\ufe0f " + id + " 注册失败")));
		}
		catch (Exception ex)
		{
			Core.LogMsg("[养蛊机] 注册 " + id + " 异常: " + ex.Message);
		}
	}

	private static void ApplyIcon(GameItem it, string iconKey, string nativeId)
	{
		Sprite val = null;
		try
		{
			switch (iconKey)
			{
			case "gu_machine":
				val = _guSprite;
				break;
			case "ai_generator":
				val = _aiSprite;
				break;
			case "protector_core":
				val = _protectorSprite;
				break;
			case "ai_module":
				val = _aiModuleSprite;
				break;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[GuMachineSystem.Entity] 异常: " + ex.Message);
		}
		if (Core.DebugMode)
		{
			Core.LogMsg("[养蛊机] ApplyIcon key=" + iconKey + " sp=" + (((Object)(object)val != (Object)null) ? "ok" : "null"));
		}
		if ((Object)(object)val != (Object)null)
		{
			try
			{
				it.SetSprite("custom_atlas", iconKey);
				return;
			}
			catch
			{
			}
		}
		BorrowNativeSprite(it, nativeId);
	}

	private static void BorrowNativeSprite(GameItem it, string nativeId)
	{
		try
		{
			GameItem val = DirectoryMaster.Item(nativeId, true);
			if (val != null)
			{
				string text = "";
				string text2 = "";
				try
				{
					text = val.spriteAtlasPath ?? "";
				}
				catch
				{
				}
				try
				{
					text2 = val.spritePath ?? "";
				}
				catch
				{
				}
				if (!string.IsNullOrEmpty(text) && !string.IsNullOrEmpty(text2))
				{
					it.SetSpriteAndShape(text, text2);
					return;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[GuMachineSystem.Entity] 异常: " + ex.Message);
		}
		try
		{
			it.SetSpriteAndShape("custom_atlas", "custom_storage_box_sprite");
		}
		catch
		{
		}
	}

	private static GameItem CreateGuMachine()
	{
		//IL_0078: Unknown result type (might be due to invalid IL or missing references)
		//IL_007f: Expected Obj, but got Unknown
		try
		{
			GameItem val = ItemDirectory.CreateEmptyItem((string)null);
			if (val == null)
			{
				return null;
			}
			ApplyIcon(val, "gu_machine", "blender");
			try
			{
				ValueTuple<PixelWindow, GameInventory> val2 = DirectoryUtils.CreateInventoryWindow(8, 8, true);
				PixelWindow item = val2.Item1;
				GameInventory item2 = val2.Item2;
				if (item != null && item2 != null)
				{
					val.SetContentWindow(item);
					item2.identifier = "wage_gu_machine";
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[GuMachineSystem.Entity] 异常: " + ex.Message);
			}
			val.EnableTag("STANDARD_MACHINE_TAG", false);
			try
			{
				GridShapeBuilder val3 = new GridShapeBuilder();
				val3.SetDataFill(2, 2, (byte)1);
				val.SetShape(val3.Build());
				val.modifiedShape = val3.Build();
			}
			catch
			{
			}
			val.SetGameItemType("MACHINE");
			val.SetName(LangHelper.T("蛙哥养蛊机", "Wage's Swarm Forge"));
			SetField(val, "_identifier_k__BackingField", "wage_gu_machine");
			SetField(val, "_identifierName_k__BackingField", "TYPE-STRING_wage_gu_machine");
			val.shortDescription = LangHelper.T("蛙哥养蛊机——传奇当铺主蛙哥（Wage）留下的炼蛊机器\n打烊充能（3天）后自动炼蛊，舱内≥2模组 → 1强化模组（三属性之和×1.2，上限150%，产出在机器舱内，打开机器取出）\n舱内≥2只老鼠自动互食（高属性存活，次数叠加，鼠王免计数）\n违禁：以活体模组与老鼠互相吞噬炼制，安保部明令禁止。", "Wage's Swarm Forge - a forging machine left by Wage\nAfter 3 days of charging (at close), auto-forges >=2 modules in bay -> 1 empowered module (sum of 3 stats x1.2, cap 150%, output stays in the bay)\n>=2 rats in bay auto-devour (higher stats survive, counts stack, Rat King exempt)\nContraband: live module & rat cannibalism is outlawed by Security.");
			val.longDescription = LangHelper.T("蛙哥养蛊机——传奇当铺主蛙哥（Wage）留下的炼蛊机器\n打烊充能（3天）后自动炼蛊，舱内≥2模组 → 1强化模组（三属性之和×1.2，上限150%，产出在机器舱内，打开机器取出）\n舱内≥2只老鼠自动互食（高属性存活，次数叠加，鼠王免计数）\n违禁：以活体模组与老鼠互相吞噬炼制，安保部明令禁止。", "Wage's Swarm Forge - a forging machine left by Wage\nAfter 3 days of charging (at close), auto-forges >=2 modules in bay -> 1 empowered module (sum of 3 stats x1.2, cap 150%, output stays in the bay)\n>=2 rats in bay auto-devour (higher stats survive, counts stack, Rat King exempt)\nContraband: live module & rat cannibalism is outlawed by Security.");
			val.unitValue = BuildConfig.GuMachinePrice;
			val.unitBaseValue = BuildConfig.GuMachinePrice;
			try
			{
				ContrabandHelper.InitContrabandItem(val, 3);
			}
			catch
			{
			}
			try
			{
				RobinCrusoePerk.SetTagIntValue(val, "wage_gu_last_day", DeterministicSchedule.CurrentDay);
			}
			catch
			{
			}
			return val;
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[养蛊机] 创建养蛊机失败: " + ex2.Message);
