	private static void TryGuMachineTick(GameItem gu, int day)
	{
		try
		{
			GameGridInventory guGrid = GetGuGrid(gu);
			Core.LogMsg("[养蛊] tick: grid=" + ((guGrid != null) ? "ok" : "null") + " contentWindow=" + (gu.contentWindow != null));
			if (guGrid == null)
			{
				return;
			}
			TryBeastEat(gu, guGrid, day);
			int tagIntSafe = RobinCrusoePerk.GetTagIntSafe(gu, "wage_gu_charge");
			if (tagIntSafe > 0)
			{
				LockGuModules(guGrid);
			}
			else
			{
				UnlockGuModules(guGrid);
			}
			if (tagIntSafe < 3)
			{
				RobinCrusoePerk.GetTagIntSafe(gu, "wage_gu_last_day");
				int delta = 1;
				RobinCrusoePerk.AddTagInt(gu, "wage_gu_charge", delta);
				RobinCrusoePerk.SetTagIntValue(gu, "wage_gu_last_day", day);
				return;
			}
			List<GameItem> list = new List<GameItem>();
			if (((GameInventory)guGrid).childItems != null)
			{
				Enumerator<GameItem> enumerator = ((GameInventory)guGrid).childItems.GetEnumerator();
				while (enumerator.MoveNext())
				{
					GameItem current = enumerator.Current;
					if (current == null)
					{
						continue;
					}
					string text = "";
					try
					{
						text = current.identifier ?? "";
					}
					catch
					{
					}
					if (text == "system_module_ruined")
					{
						continue;
					}
					bool flag = false;
					try
					{
						flag = current.IsTag("power_source_item");
					}
					catch
					{
					}
					if (!flag)
					{
						bool flag2 = false;
						try
						{
							flag2 = current.IsTag("MODULE_TAG") && !RobinCrusoePerk.IsExcludedModule(current);
						}
						catch
						{
						}
						if (flag2)
						{
							list.Add(current);
						}
					}
				}
			}
			if (list.Count < 2)
			{
				return;
			}
			GameItem val = null;
			int num = -1;
			foreach (GameItem item in list)
			{
				int num2 = 0;
				num2 += RobinCrusoePerk.GetTagIntSafe(item, "BONUS_PERCENTAGE_PERFORMANCE_INT");
				num2 += RobinCrusoePerk.GetTagIntSafe(item, "BONUS_PERCENTAGE_EFFICIENCY_INT");
				num2 += RobinCrusoePerk.GetTagIntSafe(item, "BONUS_PERCENTAGE_QUALITY_INT");
				if (num2 > num)
				{
					num = num2;
					val = item;
				}
			}
			if (val == null)
			{
				val = list[0];
			}
			string text2 = "system_module_overclock";
			try
			{
				string text3 = val.identifier ?? "";
				if (text3.Length > 0)
				{
					text2 = text3;
				}
			}
			catch
			{
			}
			int num3 = 0;
			int num4 = 0;
			int num5 = 0;
			foreach (GameItem item2 in list)
			{
				num3 += RobinCrusoePerk.GetTagIntSafe(item2, "BONUS_PERCENTAGE_PERFORMANCE_INT");
				num4 += RobinCrusoePerk.GetTagIntSafe(item2, "BONUS_PERCENTAGE_EFFICIENCY_INT");
				num5 += RobinCrusoePerk.GetTagIntSafe(item2, "BONUS_PERCENTAGE_QUALITY_INT");
			}
			int num6 = Math.Min(150, (int)((float)(num3 * 120) / 100f));
			int num7 = Math.Min(150, (int)((float)(num4 * 120) / 100f));
			int num8 = Math.Min(150, (int)((float)(num5 * 120) / 100f));
			GameItem val2 = null;
			try
			{
				val2 = DirectoryMaster.Item(text2, true);
			}
			catch
			{
			}
			if (val2 == null)
			{
				foreach (GameItem item3 in list)
				{
					try
					{
						item3.Destroy();
					}
					catch
					{
					}
				}
				GameItem val3 = null;
				try
				{
					val3 = DirectoryMaster.Item("system_module_ruined", true);
				}
				catch
				{
				}
				if (val3 != null)
				{
					try
					{
						RobinCrusoePerk.SetTagIntValue(val3, "BONUS_PERCENTAGE_PERFORMANCE_INT", 0);
					}
					catch
					{
					}
					try
					{
						RobinCrusoePerk.SetTagIntValue(val3, "BONUS_PERCENTAGE_EFFICIENCY_INT", 0);
					}
					catch
					{
					}
					try
					{
						RobinCrusoePerk.SetTagIntValue(val3, "BONUS_PERCENTAGE_QUALITY_INT", 0);
					}
					catch
					{
					}
					try
					{
						GraphUtils.TryAcceptAllMid(guGrid, val3, -1);
					}
					catch
					{
					}
				}
				string text4 = LangHelper.T("养蛊机炼蛊失败：投入模组报废", "Swarm Forge forging failed: input modules scrapped");
				try
				{
					StoreUIManager.Instance.Notify(text4, "default");
				}
				catch
				{
				}
				try
				{
					PlayerStore instance = PlayerStore.Instance;
					if (instance != null)
					{
						instance.AddNightLog(text4, "#7FC97F");
					}
				}
				catch
				{
				}
				Core.AddNightReportLine(text4);
				RobinCrusoePerk.AddTagInt(gu, "wage_gu_charge", -3);
				return;
			}
			try
			{
				RobinCrusoePerk.SetTagIntValue(val2, "BONUS_PERCENTAGE_PERFORMANCE_INT", 0);
			}
			catch
			{
			}
			try
			{
				RobinCrusoePerk.SetTagIntValue(val2, "BONUS_PERCENTAGE_EFFICIENCY_INT", 0);
			}
			catch
			{
			}
			try
			{
				RobinCrusoePerk.SetTagIntValue(val2, "BONUS_PERCENTAGE_QUALITY_INT", 0);
			}
			catch
			{
			}
			if (num6 > 0)
			{
				RobinCrusoePerk.AddTagInt(val2, "BONUS_PERCENTAGE_PERFORMANCE_INT", num6);
			}
			if (num7 > 0)
			{
				RobinCrusoePerk.AddTagInt(val2, "BONUS_PERCENTAGE_EFFICIENCY_INT", num7);
			}
			if (num8 > 0)
			{
				RobinCrusoePerk.AddTagInt(val2, "BONUS_PERCENTAGE_QUALITY_INT", num8);
			}
			try
			{
				val2.EnableTag("MODULE_TAG", false);
			}
			catch
			{
			}
			try
			{
				ContrabandHelper.InitContrabandItem(val2, 3);
			}
			catch
			{
			}
			try
			{
				val2.shortDescription += LangHelper.T("（违禁原因：炼蛊融合产物，蕴含被禁的模组融合技术）", " (Contraband: forged fusion product with outlawed module-merging tech)");
			}
			catch
			{
			}
			foreach (GameItem item4 in list)
			{
				try
				{
					item4.Destroy();
				}
				catch
				{
				}
			}
			try
			{
				GraphUtils.TryAcceptAllMid(guGrid, val2, -1);
			}
			catch
			{
			}
			RobinCrusoePerk.AddTagInt(gu, "wage_gu_charge", -3);
			string text5 = "养蛊模组";
			try
			{
				text5 = val2.GetDisplayName(false);
			}
			catch
			{
				try
				{
					text5 = val2.name ?? text2;
				}
				catch
				{
				}
			}
			string text6 = LangHelper.T("养蛊机炼成 " + text5 + " · 性能+" + num6 + " 效率+" + num7 + " 质量+" + num8 + "（×1.2）", "Swarm Forge forged " + text5 + " · Perf+" + num6 + " Eff+" + num7 + " Qual+" + num8 + " (x1.2)");
			try
			{
				StoreUIManager.Instance.Notify(text6, "default");
			}
			catch
			{
			}
			try
			{
				PlayerStore instance2 = PlayerStore.Instance;
				if (instance2 != null)
				{
					instance2.AddNightLog(text6, "#7FC97F");
				}
