			Core.LogMsg("[GuMachineSystem.Tick] 异常: " + ex.Message);
		}
	}

	private static List<GameItem> FindAiGenerators()
	{
		List<GameItem> list = new List<GameItem>();
		try
		{
			if ((Object)(object)EmporiumEntry.Instance != (Object)null)
			{
				List<GameItem> allItems = EmporiumEntry.Instance.GetAllItems();
				if (allItems != null)
				{
					Enumerator<GameItem> enumerator = allItems.GetEnumerator();
					while (enumerator.MoveNext())
					{
						GameItem current = enumerator.Current;
						if (current != null && current.identifier == "wage_ai_generator")
						{
							list.Add(current);
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[GuMachineSystem.Tick] 异常: " + ex.Message);
		}
		return list;
	}

