	private static void TryBeastEat(GameItem gu, GameGridInventory grid, int day)
	{
		try
		{
			if (grid == null || ((GameInventory)grid).childItems == null)
			{
				return;
			}
			List<GameItem> list = new List<GameItem>();
			Enumerator<GameItem> enumerator = ((GameInventory)grid).childItems.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				bool flag = false;
				try
				{
					flag = current.IsTag("ANIMAL_ITEM_TAG");
				}
				catch
				{
				}
				if (!flag)
				{
					string text = "";
					try
					{
						text = current.identifier ?? "";
					}
					catch
					{
					}
					if (text != "rat")
					{
						continue;
					}
				}
				list.Add(current);
			}
			if (list.Count < 2)
			{
				return;
			}
			GameItem val = null;
			foreach (GameItem item in list)
			{
				if (IsKing(item))
				{
					val = item;
					break;
				}
			}
			int num = ((WageSaveStore.GetInt("GuBeast", "eat_day", -1) == day) ? WageSaveStore.GetInt("GuBeast", "eat_count") : 0);
			if (num >= 3 && val == null)
			{
				return;
			}
			GameItem val2 = null;
			if (val != null)
			{
				val2 = val;
			}
			else
			{
				float num2 = -1f;
				foreach (GameItem item2 in list)
				{
					float num3 = TagHelper.GetFloat(item2, "ANIMAL_LONGEVITY_TAG");
					if (num3 > num2)
					{
						num2 = num3;
						val2 = item2;
					}
				}
			}
			GameItem val3 = null;
			foreach (GameItem item3 in list)
			{
				if (item3 != val2 && (val == null || !IsKing(item3)))
				{
					val3 = item3;
					break;
				}
			}
			if (val3 == null)
			{
				foreach (GameItem item4 in list)
				{
					if (item4 != val2)
					{
						val3 = item4;
						break;
					}
				}
			}
			if (val3 == null)
			{
				return;
			}
			float val4 = 999f;
			try
			{
				float val5 = TagHelper.GetFloat(val2, "ANIMAL_LONGEVITY_TAG") + TagHelper.GetFloat(val3, "ANIMAL_LONGEVITY_TAG");
				TagHelper.SetFloat(val2, "ANIMAL_LONGEVITY_TAG", Math.Min(val4, val5));
			}
			catch
			{
			}
			try
			{
				float val6 = TagHelper.GetFloat(val2, "ANIMAL_IMMUNITY_TAG") + TagHelper.GetFloat(val3, "ANIMAL_IMMUNITY_TAG");
				TagHelper.SetFloat(val2, "ANIMAL_IMMUNITY_TAG", Math.Min(val4, val6));
			}
			catch
			{
			}
			try
			{
				float val7 = TagHelper.GetFloat(val2, "ANIMAL_MAX_HEALTH_TAG") + TagHelper.GetFloat(val3, "ANIMAL_MAX_HEALTH_TAG");
				TagHelper.SetFloat(val2, "ANIMAL_MAX_HEALTH_TAG", Math.Min(val4, val7));
			}
			catch
			{
			}
			try
			{
				float val8 = TagHelper.GetFloat(val2, "ANIMAL_GROWTH_RATE_TAG") + TagHelper.GetFloat(val3, "ANIMAL_GROWTH_RATE_TAG");
				TagHelper.SetFloat(val2, "ANIMAL_GROWTH_RATE_TAG", Math.Min(val4, val8));
			}
			catch
			{
			}
			try
			{
				float value = TagHelper.GetFloat(val2, "ANIMAL_LONGEVITY_TAG");
				TagHelper.SetFloat(val2, "ANIMAL_LONGEVITY_TAG_ALLELE_A", value);
				TagHelper.SetFloat(val2, "ANIMAL_LONGEVITY_TAG_ALLELE_B", value);
			}
			catch
			{
			}
			try
			{
				float value2 = TagHelper.GetFloat(val2, "ANIMAL_IMMUNITY_TAG");
				TagHelper.SetFloat(val2, "ANIMAL_IMMUNITY_TAG_ALLELE_A", value2);
				TagHelper.SetFloat(val2, "ANIMAL_IMMUNITY_TAG_ALLELE_B", value2);
			}
			catch
			{
			}
			try
			{
				float value3 = TagHelper.GetFloat(val2, "ANIMAL_MAX_HEALTH_TAG");
				TagHelper.SetFloat(val2, "ANIMAL_MAX_HEALTH_TAG_ALLELE_A", value3);
				TagHelper.SetFloat(val2, "ANIMAL_MAX_HEALTH_TAG_ALLELE_B", value3);
			}
			catch
			{
			}
			try
			{
				float value4 = TagHelper.GetFloat(val2, "ANIMAL_GROWTH_RATE_TAG");
				TagHelper.SetFloat(val2, "ANIMAL_GROWTH_RATE_TAG_ALLELE_A", value4);
				TagHelper.SetFloat(val2, "ANIMAL_GROWTH_RATE_TAG_ALLELE_B", value4);
			}
			catch
			{
			}
			try
			{
				RobinCrusoePerk.SetTagIntValue(val2, "ANIMAL_AGE_TAG", 0);
			}
			catch
			{
			}
			try
			{
				RobinCrusoePerk.SetTagIntValue(val2, "ANIMAL_HUNGER_TAG", 0);
			}
			catch
			{
			}
			try
			{
				TagHelper.SetFloat(val2, "ANIMAL_IMMUNITY_TAG", 99999f);
			}
			catch
			{
			}
			if (!IsKing(val2))
			{
				try
				{
					val2.EnableTag("wage_king_rat", false);
				}
				catch
				{
				}
				try
				{
					val2.SetName("鼠王");
				}
				catch
				{
				}
				try
				{
					StoreUIManager.Instance.Notify("老鼠吞噬了同类，进化成了鼠王！", "default");
				}
				catch
				{
				}
			}
			try
			{
				val3.Destroy();
			}
			catch
			{
			}
			if (val == null)
			{
				WageSaveStore.SetInt("GuBeast", "eat_day", day);
				WageSaveStore.SetInt("GuBeast", "eat_count", num + 1);
			}
			Core.LogMsg("[练兽] 老鼠互食完成" + ((val != null) ? "（鼠王，免计数）" : ("（第" + (num + 1) + "/3次）")));
			try
			{
				float num4 = TagHelper.GetFloat(val2, "ANIMAL_LONGEVITY_TAG");
				float num5 = TagHelper.GetFloat(val2, "ANIMAL_IMMUNITY_TAG");
				float num6 = TagHelper.GetFloat(val2, "ANIMAL_MAX_HEALTH_TAG");
				float num7 = TagHelper.GetFloat(val2, "ANIMAL_GROWTH_RATE_TAG");
				Core.LogMsg("[练兽] survivor tag值: 寿命=" + num4 + " 免疫=" + num5 + " 血=" + num6 + " 生长=" + num7);
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[练兽] TryBeastEat异常: " + ex.Message);
		}
		static bool IsKing(GameItem r)
		{
			bool result = false;
			try
			{
				result = r.IsTag("wage_king_rat");
			}
			catch
			{
			}
			return result;
		}
	}

	private static Sprite SpriteFromPixels(Color[] pixels, int w, int h)
	{
		//IL_0004: Unknown result type (might be due to invalid IL or missing references)
		//IL_0009: Unknown result type (might be due to invalid IL or missing references)
		//IL_0010: Unknown result type (might be due to invalid IL or missing references)
		//IL_0017: Unknown result type (might be due to invalid IL or missing references)
		//IL_001f: Unknown result type (might be due to invalid IL or missing references)
		//IL_002b: Unknown result type (might be due to invalid IL or missing references)
		//IL_003f: Unknown result type (might be due to invalid IL or missing references)
		//IL_004e: Unknown result type (might be due to invalid IL or missing references)
		//IL_005d: Expected Obj, but got Unknown
		try
		{
			Texture2D val = new Texture2D(w, h, (TextureFormat)4, false)
			{
				filterMode = (FilterMode)0,
				wrapMode = (TextureWrapMode)1,
				hideFlags = (HideFlags)52
			};
			val.SetPixels(Il2CppStructArray<Color>.op_Implicit(pixels));
			val.Apply();
			Sprite val2 = Sprite.Create(val, new Rect(0f, 0f, (float)w, (float)h), new Vector2(0.5f, 0.5f), 100f);
			((Object)val2).hideFlags = (HideFlags)52;
			return val2;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[养蛊机] SpriteFromPixels 异常: " + ex.Message);
			return null;
		}
	}

	private static void SetField(GameItem it, string field, object val)
	{
		try
		{
			FieldInfo field2 = typeof(GameItem).GetField(field, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (field2 != null)
			{
				field2.SetValue(it, val);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[GuMachineSystem.Tools] 异常: " + ex.Message);
		}
	}
}
internal sealed class HatedByAllPerk : CustomStartingPerk
{
	internal const string PerkId = "人神共愤";

	internal override string Id => "人神共愤";

	internal override string DisplayName => LangHelper.T("人神共愤", "Hated by All");

	internal override string Description => LangHelper.T("人神共愤：每天自动扣现金（可扣成负数）。扣款上限 = 第 1 周 500 / 一周后 1500，再叠加天数×50（天数越多扣越狠）；存款超过 10000 时上限再 +1000。（你过去的所作所为已经传遍整个空间站——治安部的罚款、被你坑过的商户索赔、落魄顾客的纠缠、无赖的敲诈……每一天都有人登门，从你钱袋里刮走一笔，哪怕把你刮成负数也在所不惜。）", "Hated by All: lose cash every day (can go negative). Loss cap = 500 in week 1 / 1500 after, plus day×50 (more days = heavier loss); cap +1000 extra when cash over 10000. (Your past deeds are known across the station - security fines, claims from merchants you cheated, destitute customers hounding you, thugs extorting you... every day someone comes knocking to take a cut, even if it drags you into the red.)");

	internal override int Cost => -20;

	internal override int Type => 1;

	internal static bool IsActive()
	{
		return Core.PerkActive("人神共愤");
	}

	internal override void OnNewGame()
	{
	}

	internal override void OnDayStart()
	{
		try
		{
			if (!IsActive())
			{
				return;
			}
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				return;
			}
			int num = StoreStation.GetDayCounter();
			if (num <= 0)
			{
				num = WageSaveStore.GetInt("hated", "day", 1);
			}
			num++;
			WageSaveStore.SetInt("hated", "day", num);
			if (Core.DebugMode)
			{
				Core.LogMsg("[人神共愤] day=" + num + " runID=" + ((instance != null) ? (instance.runID ?? "null") : "null"));
			}
			int num2 = ((num <= 7) ? 500 : 1500);
			int num3 = ((num > 7) ? ((num - 7) * 50) : 0);
			int num4 = ((instance.playerCash > 10000) ? 1000 : 0);
			int num5 = num2 + num3 + num4;
			int num6 = DeterministicRandom.Next("hated_cash", num, 1, num5 + 1);
			int playerCash = instance.playerCash;
			instance.playerCash = playerCash - num6;
			string text = LangHelper.T("人神共愤：现金 -" + num6, "Hated by All: cash -" + num6);
			try
			{
				instance.AddNightLog(text, "#7FC97F");
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[HatedByAllPerk] 异常: " + ex.Message);
		}
	}
}
