	internal override string Id => "声名狼藉";

	internal override string DisplayName => LangHelper.T("声名狼藉-各个势力", "Infamous - Factions");

	internal override string Description => LangHelper.T("你在空间站臭名昭著——五势力声望 -99，做一点坏事就被通缉。第二天会收到 5000 信用点补偿金。高风险高回报，活着回来再说。", "You are infamous across the station - all five factions at -99 rep. One wrong move and you are wanted. You get 5000 credits on day 2. High risk, high reward.");

	internal override int Cost => -10;

	internal override int Type => 1;

	internal override void OnNewGame()
	{
	}

	internal static bool IsActive()
	{
		return Core.PerkActive("声名狼藉");
	}

	public static void PostfixStartNewGame()
	{
		try
		{
			if (!IsActive())
			{
				return;
			}
			Core.LogMsg("[声名狼藉] PostfixStartNewGame 触发");
			string[] array = new string[5] { "FACTION_SECURITY", "FACTION_UPPER_LEVEL", "FACTION_REVOLUTION", "FACTION_LOWER_LEVEL", "FACTION_BLACK_MARKET" };
			int[] array2 = new int[5] { -99, -99, -99, -99, -99 };
			for (int i = 0; i < array.Length; i++)
			{
				try
				{
					StoreReputation storeReputation = StoreReputation.GetStoreReputation(array[i]);
					if (storeReputation == null)
					{
						Core.LogMsg("[声名狼藉] " + array[i] + " = null");
						continue;
					}
					int num = (int)storeReputation.GetReputationExact();
					if (num <= array2[i])
					{
						Core.LogMsg("[声名狼藉] " + array[i] + " cur=" + num + " 已更负/达标，跳过");
						continue;
					}
					int num2 = array2[i] - num;
					storeReputation.ModReputation((double)num2);
					int num3 = (int)storeReputation.GetReputationExact();
					Core.LogMsg("[声名狼藉] " + array[i] + " cur=" + num + " diff=" + num2 + " after=" + num3);
					if (array[i] == "FACTION_BLACK_MARKET" && num3 != -99)
					{
						storeReputation.ModReputation((double)(-99 - num3));
						Core.LogMsg("[声名狼藉] 黑市兜底修正: after=" + (int)storeReputation.GetReputationExact());
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[声名狼藉] " + array[i] + " 异常: " + ex.Message);
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[声名狼藉] PostfixStartNewGame 异常: " + ex2.Message);
		}
	}

	internal override void OnDayStart()
	{
		try
		{
			bool flag = IsActive();
			int dayCounter = StoreStation.GetDayCounter();
			int num = WageSaveStore.GetInt("声名狼藉", "got_money");
			Core.LogMsg("[声名狼藉] OnDayStart: active=" + flag + " day=" + dayCounter + " got=" + num);
			if (flag && dayCounter == 2 && num <= 0)
			{
				WageSaveStore.SetInt("声名狼藉", "got_money", 1);
				PlayerStore instance = PlayerStore.Instance;
				if (instance != null)
				{
					instance.playerCash += 5000;
				}
				NotifyHelper.NightLogRaw("声名狼藉：你收到了 5000 补偿金");
				Core.LogMsg("[声名狼藉] 第2天送5000 OK");
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[声名狼藉] OnDayStart 异常: " + ex.Message);
		}
	}

	public static void PostfixUpdateCost(StoreService __instance)
	{
		try
		{
			if (!IsActive() || __instance == null)
			{
				return;
			}
			string text = "";
			try
			{
				text = __instance.id;
			}
			catch
			{
			}
			Core.LogMsg("[声名狼藉] UpdateCost: sid=" + text + " unlocked=" + __instance.unlocked + " cost=" + __instance.cost);
			if (!(text != "INSURANCE_SERVICE"))
			{
				__instance.unlocked = true;
				if (WageSaveStore.GetInt("声名狼藉", "insurance_doubled") == 0)
				{
					__instance.cost *= 2;
					WageSaveStore.SetInt("声名狼藉", "insurance_doubled", 1);
				}
				Core.LogMsg("[声名狼藉] 保险服务强开 unlocked=true cost=" + __instance.cost);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[声名狼藉] PostfixUpdateCost 异常: " + ex.Message);
		}
	}
}
internal static class ItemHelper
{
	private static readonly HashSet<string> FOOD_IDS = new HashSet<string>
	{
		"beis_icecream", "processed_milk", "processed_juice", "processed_meat", "bottle_hot_sauce", "cat_bar", "li_eat_snackbar", "processed_cheese", "raw_meat", "small_raw_meat",
		"morsel", "small_morsel", "fat_meat", "meat_scrap", "cup_noodle", "wine_berry", "bloomberry"
	};

	private static readonly HashSet<string> DRINK_IDS = new HashSet<string>
	{
		"bottled_water", "bottled_water_premium", "small_bottled_water", "large_bottled_water", "water_jug", "mini_bottle", "soda_red", "energy_drink", "nudka", "galaxy_blend",
		"red_beer", "empty_beer_bottle", "water_ration", "water_ration_small"
	};

	internal const string CAL_LEFT_TAG = "WAGES_CAL_LEFT";

	public static bool IsFood(GameItem item)
	{
		if (item == null)
		{
			return false;
		}
		try
		{
			return FOOD_IDS.Contains(GetId(item));
		}
		catch
		{
			return false;
		}
	}

	public static bool IsDrink(GameItem item)
	{
		if (item == null)
		{
			return false;
		}
		try
		{
			return DRINK_IDS.Contains(GetId(item));
		}
		catch
		{
			return false;
		}
	}

	public static bool IsDailyNeed(GameItem item)
	{
		return RobinCrusoePerk.IsDailyNeed(item);
	}

	public static int GetCalorie(GameItem item)
	{
		if (item == null)
		{
			return 0;
		}
		try
		{
			if (item.IsTag("CALORIE_VALUE_TAG"))
			{
				TagState tagReadonly = item.GetTagReadonly("CALORIE_VALUE_TAG");
				if (tagReadonly != null)
				{
					return Math.Max(0, tagReadonly.GetInt());
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ItemHelper] 异常: " + ex.Message);
		}
		try
		{
			if (item.IsTag("CALORIE"))
			{
				TagState tagReadonly2 = item.GetTagReadonly("CALORIE");
				if (tagReadonly2 != null)
				{
					return Math.Max(0, tagReadonly2.GetInt());
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[ItemHelper] 异常: " + ex2.Message);
		}
		return 300;
	}

	public static int GetCalLeft(GameItem item)
	{
		if (item == null)
		{
			return 0;
		}
		try
		{
			if (item.IsTag("WAGES_CAL_LEFT"))
			{
				TagState tagReadonly = item.GetTagReadonly("WAGES_CAL_LEFT");
				if (tagReadonly != null)
				{
					return Math.Max(0, tagReadonly.GetInt());
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ItemHelper] 异常: " + ex.Message);
		}
		return GetCalorie(item);
	}

	public static void SetCalLeft(GameItem item, int value)
	{
		if (item == null)
		{
			return;
		}
		try
		{
			if (value <= 0)
			{
				item.DisableTag("WAGES_CAL_LEFT", true);
				return;
			}
			if (!item.IsTag("WAGES_CAL_LEFT"))
			{
				item.EnableTag("WAGES_CAL_LEFT", true);
			}
			Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState state) =>
			{
				state.SetInt(value);
			}));
			item.ModifyTag("WAGES_CAL_LEFT", val, false);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ItemHelper] 异常: " + ex.Message);
		}
	}

	public static int GetWaterMl(GameItem item)
	{
		if (item == null)
		{
			return 0;
		}
		try
		{
			if (item.IsTag("LIQUID_CONTAINER_CURRENT"))
			{
				TagState tagReadonly = item.GetTagReadonly("LIQUID_CONTAINER_CURRENT");
				if (tagReadonly != null)
				{
					try
					{
						return Math.Max(0, (int)tagReadonly.GetFloat());
					}
					catch
					{
						return Math.Max(0, tagReadonly.GetInt());
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ItemHelper] 异常: " + ex.Message);
		}
		try
		{
			return Math.Max(0, WaterHelper.GetCurrentCapacityML(item));
		}
		catch
		{
		}
		return 2000;
	}

	private static string GetId(GameItem item)
	{
		try
		{
			return (item.identifier ?? "").ToLowerInvariant();
		}
		catch
		{
			return "";
		}
	}
}
internal static class LangHelper
{
	public static bool IsEnglish()
	{
		//IL_00a8: Unknown result type (might be due to invalid IL or missing references)
		//IL_00af: Invalid comparison between Unknown and I4
		//IL_00b1: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b8: Invalid comparison between Unknown and I4
		//IL_00ba: Unknown result type (might be due to invalid IL or missing references)
		//IL_00c0: Invalid comparison between Unknown and I4
		try
		{
			string currentLocaleCode = LocHelper.GetCurrentLocaleCode();
			if (!string.IsNullOrEmpty(currentLocaleCode))
			{
				return !currentLocaleCode.StartsWith("zh", StringComparison.OrdinalIgnoreCase);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[LangHelper] 异常: " + ex.Message);
		}
		try
		{
			Locale selectedLocale = LocalizationSettings.SelectedLocale;
			if ((Object)(object)selectedLocale != (Object)null)
			{
				string text = "";
				try
				{
					text = selectedLocale.Identifier.Code ?? "";
				}
				catch
				{
				}
				if (!string.IsNullOrEmpty(text))
				{
					return !text.StartsWith("zh", StringComparison.OrdinalIgnoreCase);
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[LangHelper] 异常: " + ex2.Message);
		}
		try
		{
			return (int)Application.systemLanguage != 40 && (int)Application.systemLanguage != 41 && (int)Application.systemLanguage != 6;
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[LangHelper] 异常: " + ex3.Message);
		}
		return false;
	}

	public static string T(string zh, string en)
	{
		if (!IsEnglish())
		{
			return zh;
		}
		return en;
	}

	public static string SafeT(string zh, string en)
	{
		try
		{
			return T(zh, en);
		}
		catch
		{
			return zh;
		}
	}
}
