	public static bool PrefixMayTarget(GameItem __instance, GameItem targetItem, ref bool __result)
	{
		if ((IsBead(__instance) && IsJunk(targetItem)) || (IsBead(targetItem) && IsJunk(__instance)))
		{
			__result = true;
			return false;
		}
		return true;
	}

	public static bool PrefixCanTarget(GameItem __instance, GameItem targetItem, ref bool __result)
	{
		return PrefixMayTarget(__instance, targetItem, ref __result);
	}

	public static bool PrefixTarget(GameItem __instance, GameItem targetItem)
	{
		GameItem val = null;
		GameItem junk = null;
		if (IsBead(__instance) && IsJunk(targetItem))
		{
			val = __instance;
			junk = targetItem;
		}
		else if (IsBead(targetItem) && IsJunk(__instance))
		{
			val = targetItem;
			junk = __instance;
		}
		if (val != null)
		{
			DoUpgrade(junk, val);
			return false;
		}
		return true;
	}

	public static void PostfixSetContentWindow(GameItem __instance)
	{
		//IL_006e: Unknown result type (might be due to invalid IL or missing references)
		//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			if (__instance == null || !__instance.IsTag("VOID_BEAD_TAG"))
			{
				return;
			}
			try
			{
				if (!_beadItems.Contains(__instance))
				{
					_beadItems.Add(__instance);
				}
			}
			catch
			{
			}
			try
			{
				PixelWindow contentWindow = __instance.contentWindow;
				if (contentWindow != null)
				{
					IntPtr intPtr = Marshal.ReadIntPtr((IntPtr)(((Il2CppObjectBase)contentWindow).Pointer.ToInt64() + 40));
					if (intPtr != IntPtr.Zero)
					{
						MonoBehaviour val = ((Il2CppObjectBase)new Object(intPtr)).Cast<MonoBehaviour>();
						if ((Object)(object)val != (Object)null)
						{
							Image component = ((Component)val).GetComponent<Image>();
							if ((Object)(object)component != (Object)null)
							{
								((Graphic)component).color = new Color(0.12f, 0.12f, 0.15f, 1f);
							}
						}
					}
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[虚空珠] 读档改背景异常: " + ex.Message);
			}
			int num = GetTagInt(__instance, "VOID_BEAD_SLOTS_TAG");
			if (num <= 0)
			{
				num = 1;
			}
			try
			{
				if (__instance.contentWindow != null)
				{
					__instance.contentWindow.titleString = LangHelper.T("虚空珠 (", "Void Bead (") + num + LangHelper.T("/200格)", "/200 slots)");
				}
			}
			catch
			{
			}
			try
			{
				PixelWindow contentWindow2 = __instance.contentWindow;
				if (contentWindow2 != null && contentWindow2.childElement != null)
				{
					string name = ((object)contentWindow2.childElement).GetType().Name;
					GameGridInventory val2 = ((Il2CppObjectBase)contentWindow2.childElement).TryCast<GameGridInventory>();
					if (val2 != null)
					{
						ApplyLockedShape(val2, num);
					}
					else
					{
						Core.LogMsg("[虚空珠] 读档警告: 内部库存类型" + name + "不是GameGridInventory，Cast失败，无法恢复SetShape（将在打开窗口时双保险恢复）");
					}
				}
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[虚空珠] 读档恢复SetShape异常: " + ex2.Message);
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[虚空珠] PostfixSetContentWindow异常: " + ex3.Message);
		}
	}

