			Enumerator<GameItem> enumerator2 = item.childItems.GetEnumerator();
			while (enumerator2.MoveNext())
			{
				GameItem current2 = enumerator2.Current;
				if (current2 == null)
				{
					continue;
				}
				try
				{
					if (!current2.IsTag("VOID_BEAD_TAG"))
