	internal static void ProcessPendingValidate()
	{
		try
		{
			if (_pendingShapes.Count == 0)
			{
				return;
			}
			for (int num = _pendingShapes.Count - 1; num >= 0; num--)
			{
				Tuple<GameItem, int> tuple = _pendingShapes[num];
				GameItem item = tuple.Item1;
				if (item == null)
				{
					_pendingShapes.RemoveAt(num);
				}
				else
				{
					PixelWindow contentWindow = item.contentWindow;
					if (contentWindow != null && contentWindow.childElement != null)
					{
						GameGridInventory val = ((Il2CppObjectBase)contentWindow.childElement).TryCast<GameGridInventory>();
						if (val != null)
						{
							int slots = Math.Max(tuple.Item2, GetTagInt(item, "VOID_BEAD_SLOTS_TAG"));
							ApplyLockedShape(val, slots);
							try
							{
								contentWindow.titleString = LangHelper.T("虚空珠 (", "Void Bead (") + slots + LangHelper.T("/200格)", "/200 slots)");
							}
							catch
							{
							}
						}
						_pendingShapes.RemoveAt(num);
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[LuckScoutBackpackUpgrade] 异常: " + ex.Message);
		}
	}

	private static string BuildLockedShape(int slots, int width, int height)
	{
		int num = width * height;
		char[] array = new char[num];
		for (int i = 0; i < num; i++)
		{
			array[i] = ((i < slots) ? '0' : '1');
		}
		return new string(array);
	}

	private static void ApplyLockedShape(GameGridInventory inv, int slots)
	{
		try
		{
			if (inv != null)
			{
				if (slots < 1)
				{
					slots = 1;
				}
				if (slots > 200)
				{
					slots = 200;
				}
				string text = BuildLockedShape(slots, 20, 10);
				text.Substring(0, Math.Min(20, text.Length));
				inv.SetShape(text, 20);
				((GameInventory)inv).Validate();
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[虚空珠] ApplyLockedShape异常: " + ex.Message);
		}
	}

