	internal static void ClearDebounce()
	{
		try
		{
			_lastConsumeByBead.Clear();
		}
		catch
		{
		}
	}

	internal static bool DoUpgrade(GameItem junk, GameItem bead)
	{
		if (junk == null || bead == null)
		{
			return false;
		}
		if (_lastConsumeByBead.TryGetValue(((Il2CppObjectBase)bead).Pointer, out var value) && (DateTime.UtcNow - value).TotalSeconds < 0.5)
		{
			return false;
		}
		try
		{
			int tagInt = GetTagInt(bead, "VOID_BEAD_SLOTS_TAG");
			if (tagInt >= 200)
			{
				Core.LogMsg("[虚空珠] 失败: 已满级 slots=" + tagInt);
				try
				{
					PixelWindow contentWindow = bead.contentWindow;
					if (contentWindow != null && contentWindow.childElement != null)
					{
						GameGridInventory val = ((Il2CppObjectBase)contentWindow.childElement).TryCast<GameGridInventory>();
						if (val != null)
						{
							ApplyLockedShape(val, tagInt);
						}
					}
				}
				catch
				{
				}
				return false;
			}
			int num = tagInt + 1;
			SetTagInt(bead, "VOID_BEAD_SLOTS_TAG", num);
			try
			{
				if (bead.contentWindow != null)
				{
					bead.contentWindow.titleString = LangHelper.T("虚空珠 (", "Void Bead (") + num + LangHelper.T("/200格) · 拖垃圾升级", "/200 slots) · drag junk to upgrade");
				}
			}
			catch
			{
			}
			try
			{
				PixelWindow contentWindow2 = bead.contentWindow;
				if (contentWindow2 != null && contentWindow2.childElement != null)
				{
					GameGridInventory val2 = ((Il2CppObjectBase)contentWindow2.childElement).TryCast<GameGridInventory>();
					if (val2 != null)
					{
						ApplyLockedShape(val2, num);
					}
				}
			}
			catch
			{
			}
			int num2 = junk.unitCount - 1;
			if (num2 <= 0)
			{
				junk.Destroy();
			}
			else
			{
				junk.SetUnitCount(num2);
			}
			_lastConsume = DateTime.UtcNow;
			_lastConsumeByBead[((Il2CppObjectBase)bead).Pointer] = DateTime.UtcNow;
			return true;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[虚空珠] 升级异常: " + ex.Message);
			return false;
		}
	}

	internal static bool IsBead(GameItem item)
	{
		try
		{
			return item != null && item.IsTag("VOID_BEAD_TAG");
