		catch
		{
			return false;
		}
	}

	internal static bool IsJunk(GameItem item)
	{
		try
		{
			return item != null && item.identifier == "junk";
		}
		catch
		{
			return false;
		}
	}

	private static void SetTagInt(GameItem item, string tag, int value)
	{
		try
		{
			item.EnableTag(tag, true);
			Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState st) =>
			{
				st.SetInt(value);
			}));
			item.ModifyTag(tag, val, false);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[虚空珠] 写标签失败: " + ex.Message);
		}
	}

	private static int GetTagInt(GameItem item, string tag)
	{
		try
		{
			if (item == null || !item.IsTag(tag))
			{
				return 0;
			}
			TagState tagReadonly = item.GetTagReadonly(tag);
			return (tagReadonly != null) ? tagReadonly.GetInt() : 0;
		}
		catch
		{
			return 0;
		}
	}

	public static bool PrefixMayHaveValidInventorySlot(GameItem __instance, GameItem item, ref bool __result)
	{
		try
		{
			if (IsJunk(item) && IsBead(__instance))
			{
				__result = false;
				return false;
			}
			if (IsJunk(__instance) && IsBead(item))
			{
				__result = false;
				return false;
			}
		}
		catch
		{
		}
		return true;
	}
