		}
	}

	private static GameItem FindScannerInOwned()
	{
		if (_inAfterhourScan)
		{
			return null;
		}
		_inAfterhourScan = true;
		try
		{
			Enumerator<GameItem> enumerator = EmporiumEntry.Instance.GetAllAfterhourOwnedItems().GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				try
				{
					if (current.identifier == "luck_scout_toolbox")
					{
						GameItem val = FindScannerInContainer(current);
						if (val != null)
						{
							return val;
						}
					}
				}
				catch
				{
				}
				try
				{
					if (current.identifier == "metal_scanner" && current.IsTag("SCAV_SCANNER_DOUBLE_CHANCE"))
					{
						return current;
					}
				}
				catch
				{
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[LuckScoutPerk.Find] 异常: " + ex.Message);
		}
		finally
		{
			_inAfterhourScan = false;
		}
		return null;
	}

