		}
		return null;
	}

	internal static void TryGiveKit()
	{
		try
		{
			if (!_initialItemHandled)
			{
				_initialItemHandled = true;
				FullReset();
			}
			if (!IsActive() || _kitGiven)
			{
				return;
			}
			if (LuckScoutBackpackUpgrade.HasAnyVoidBeadStorage())
			{
				_kitGiven = true;
				return;
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.backInvinvElement == null)
			{
				Core.LogMsg("[捡漏直觉] EmporiumEntry未就绪，入队重试");
				_pendingGive = true;
				_pendingGiveFrames = 600;
				return;
			}
			int num = 0;
			GameItem val = CreateToolbox(null);
			if (val != null)
			{
				try
				{
					val.DisableTag("not_purchased", true);
					val.DisableTag("TAG_NOT_PURCHASED", true);
				}
				catch
				{
				}
				instance.backInvinvElement.TryFindOneValidInventorySlot(val, false);
				bool flag = true;
				try
				{
					List<GameItem> val2 = new List<GameItem>();
					val2.Add(val);
					((GameInventory)instance.backInvinvElement).UncheckedAcceptAll(val2);
				}
				catch
				{
					flag = false;
				}
				if (flag)
				{
					instance.TransferOwnershipBackInv();
					instance.TransferOwnedItemBackToInv();
					_kitOk = true;
					num++;
				}
				else
				{
					Core.LogMsg("[捡漏直觉] 工具箱添加到后背包失败");
				}
			}
			else
			{
				Core.LogMsg("[捡漏直觉] 工具箱创建失败（原版toolbox）");
			}
			GameItem val3 = CreateEnhancedScanner();
			if (val3 != null)
			{
				try
				{
					val3.DisableTag("not_purchased", true);
					val3.DisableTag("TAG_NOT_PURCHASED", true);
				}
				catch
				{
				}
				instance.backInvinvElement.TryFindOneValidInventorySlot(val3, false);
				bool flag2 = true;
				try
				{
					List<GameItem> val4 = new List<GameItem>();
					val4.Add(val3);
					((GameInventory)instance.backInvinvElement).UncheckedAcceptAll(val4);
				}
				catch
				{
					flag2 = false;
				}
				if (flag2)
				{
					instance.TransferOwnershipBackInv();
					instance.TransferOwnedItemBackToInv();
					_scannerOk = true;
					num++;
				}
				else
				{
					Core.LogMsg("[捡漏直觉] 探测器添加到后背包失败");
				}
			}
			else
			{
				Core.LogMsg("[捡漏直觉] 探测器创建失败");
			}
			GameItem val5 = LuckScoutBackpackUpgrade.CreateScrollableScavBackpack();
			if (val5 != null)
			{
				try
				{
					val5.DisableTag("not_purchased", true);
					val5.DisableTag("TAG_NOT_PURCHASED", true);
				}
				catch
				{
				}
				instance.backInvinvElement.TryFindOneValidInventorySlot(val5, false);
				bool flag3 = true;
				try
				{
					List<GameItem> val6 = new List<GameItem>();
					val6.Add(val5);
					((GameInventory)instance.backInvinvElement).UncheckedAcceptAll(val6);
				}
				catch
				{
					flag3 = false;
				}
				if (flag3)
				{
					instance.TransferOwnershipBackInv();
					instance.TransferOwnedItemBackToInv();
					_beadOk = true;
					num++;
				}
				else
				{
					Core.LogMsg("[捡漏直觉] 虚空珠添加到后背包失败");
				}
			}
			else
			{
				Core.LogMsg("[捡漏直觉] 虚空珠创建失败");
			}
			if (_kitOk && _scannerOk && _beadOk)
			{
				_kitGiven = true;
				_pendingGive = false;
				return;
			}
			_pendingGive = true;
			_pendingGiveFrames = 600;
			Core.LogMsg("[捡漏直觉] 发放未全成功（工具箱=" + _kitOk + " 探测器=" + _scannerOk + " 虚空珠=" + _beadOk + "），入队重试");
		}
		catch (Exception ex)
		{
			Exception ex2 = ex.InnerException ?? ex;
			Core.LogMsg("[捡漏直觉] TryGiveKit异常: " + ex2.Message + "\n" + ex2.StackTrace);
		}
	}

