	private static GameItem CreateRareItem()
	{
		try
		{
			if (!BuildConfig.HardMode)
			{
				double num = Core.Rng.NextDouble();
				string text = null;
				if (num < (double)((float)BuildConfig.NeuralRollChance / 100f))
				{
					text = "system_capped_neural_core";
				}
				if (text != null)
				{
					try
					{
						GameItem val = DirectoryMaster.Item(text, true);
						if (val != null)
						{
							try
							{
								val.DisableTag("not_purchased", true);
								val.DisableTag("TAG_NOT_PURCHASED", true);
							}
							catch
							{
							}
							return val;
						}
					}
					catch (Exception ex)
					{
						Core.LogMsg("[LuckScoutPerk.Rare] 异常: " + ex.Message);
					}
				}
			}
			int num2 = Core.Rng.Next(RARE_VALUE_POOL.Length);
			for (int i = 0; i < Math.Min(5, RARE_VALUE_POOL.Length); i++)
			{
				string text2 = RARE_VALUE_POOL[(num2 + i) % RARE_VALUE_POOL.Length];
				GameItem val2 = null;
				try
				{
					val2 = DirectoryMaster.Item(text2, true);
				}
				catch
				{
				}
				if (val2 != null)
				{
					try
					{
						val2.DisableTag("not_purchased", true);
						val2.DisableTag("TAG_NOT_PURCHASED", true);
					}
					catch
					{
					}
					return val2;
				}
			}
			try
			{
				GameItem val3 = DirectoryMaster.Item("skincare_cream", true);
				if (val3 != null)
				{
					try
					{
						val3.DisableTag("not_purchased", true);
					}
					catch
					{
					}
				}
				return val3;
			}
			catch
			{
				return null;
			}
		}
		catch
		{
			return null;
		}
	}

