	internal static void Roll(PerkUIController ui)
	{
		if ((Object)(object)ui == (Object)null)
		{
			try
			{
				ui = PerkUIController.Instance;
			}
			catch
			{
			}
		}
		if ((Object)(object)ui == (Object)null)
		{
			return;
		}
		try
		{
			List<StartingPerk> perks = StartingPerkList.Perks;
			if (perks == null)
			{
				return;
			}
			Core.LogMsg("[精神错乱] === 开始随机抽特性 ===");
			int currentPerkCount = ui.currentPerkCount;
			int maxPerkCount = ui.maxPerkCount;
			int currentPerkPoint = ui.currentPerkPoint;
			int maxPerkPoint = ui.maxPerkPoint;
			Core.LogMsg($"[精神错乱] 当前: {currentPerkCount}/{maxPerkCount} 点数={currentPerkPoint}/{maxPerkPoint}");
			List<StartingPerk> val = SnapshotSelected(ui);
			HashSet<string> hashSet = new HashSet<string>();
			Enumerator<StartingPerk> enumerator = val.GetEnumerator();
			while (enumerator.MoveNext())
			{
				StartingPerk current = enumerator.Current;
				if (!string.IsNullOrEmpty(current.id))
				{
					hashSet.Add(current.id);
				}
			}
			int num = 0;
			Dictionary<string, HashSet<string>> incompat = BuildIncompatMap(perks);
			int num2 = 0;
			while (ui.currentPerkCount < ui.maxPerkCount && num2 < 128)
			{
				num2++;
				StartingPerk val2 = PickNext(ui, perks, val, hashSet, incompat);
				if (val2 == null || !TrySelect(ui, val2))
				{
					break;
				}
				val.Add(val2);
				hashSet.Add(val2.id);
				num++;
			}
			int num3 = 0;
			while (ui.currentPerkPoint > ui.maxPerkPoint && ui.currentPerkCount < ui.maxPerkCount && num3 < 128)
			{
				num3++;
				StartingPerk val3 = PickRefundPerk(perks, hashSet, incompat);
				if (val3 == null || !TrySelect(ui, val3))
				{
					break;
				}
				val.Add(val3);
				hashSet.Add(val3.id);
				num++;
				Core.LogMsg("[精神错乱] 阶段3 负面补偿: " + val3.id);
			}
			int num4 = 0;
			while (ui.currentPerkPoint > ui.maxPerkPoint && num4 < 10)
			{
				num4++;
				StartingPerk val4 = null;
				int num5 = 0;
				enumerator = val.GetEnumerator();
				while (enumerator.MoveNext())
				{
					StartingPerk current2 = enumerator.Current;
					if (current2 != null && current2.cost > num5)
					{
						num5 = current2.cost;
						val4 = current2;
					}
				}
				if (val4 == null)
				{
					break;
				}
				try
				{
					StartingPerkElement val5 = FindElement(ui.selectedPerks, val4.id);
					if ((Object)(object)val5 != (Object)null)
					{
						ui.SelectPerk(val5);
					}
				}
				catch
				{
				}
				val.Remove(val4);
				hashSet.Remove(val4.id);
				Core.LogMsg($"[精神错乱] 阶段4 反选: {val4.id} cost={val4.cost}");
			}
			try
			{
				ui.OnChange();
			}
			catch
			{
			}
			try
			{
				ui.SortPerkContainer(ui.availablePerks);
			}
			catch
			{
			}
			Core.LogMsg($"[精神错乱] === 抽完 共{num}条 已选{ui.currentPerkCount}/{ui.maxPerkCount} 点数{ui.currentPerkPoint}/{ui.maxPerkPoint} ===");
			if (num > 0)
			{
				LockAndHide(ui);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[精神错乱] 抽取出错: " + ex.Message);
		}
	}

	private static void LockAndHide(PerkUIController ui)
	{
		try
		{
			GameObject selectedPerks = ui.selectedPerks;
			if ((Object)(object)selectedPerks != (Object)null)
			{
				Transform transform = selectedPerks.transform;
				for (int i = 0; i < transform.childCount; i++)
				{
					Transform child = transform.GetChild(i);
					StartingPerkElement component = ((Component)child).gameObject.GetComponent<StartingPerkElement>();
					if ((Object)(object)component != (Object)null && component.id != "精神错乱")
					{
						((Component)child).gameObject.SetActive(false);
					}
				}
			}
			IsLocked = true;
			Core.LogMsg("[精神错乱] 已锁定特性选择");
		}
		catch
		{
			IsLocked = true;
		}
	}

	private static List<StartingPerk> SnapshotSelected(PerkUIController ui)
	{
		List<StartingPerk> val = new List<StartingPerk>();
		try
		{
			GameObject selectedPerks = ui.selectedPerks;
			if ((Object)(object)selectedPerks == (Object)null)
			{
				return val;
			}
			Transform transform = selectedPerks.transform;
			for (int i = 0; i < transform.childCount; i++)
			{
				StartingPerkElement component = ((Component)transform.GetChild(i)).gameObject.GetComponent<StartingPerkElement>();
				if ((Object)(object)component != (Object)null && !string.IsNullOrEmpty(component.id))
				{
					StartingPerk perk = component.perk;
					if (perk != null)
					{
						val.Add(perk);
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		return val;
	}

	private static StartingPerk PickSlotBonusPerk(List<StartingPerk> pool, List<StartingPerk> chosen, HashSet<string> chosenIds)
