				{
					string id = current2.id;
					if (!string.IsNullOrEmpty(id) && !Excluded.Contains(id) && !chosenIds.Contains(id) && current2.maxSlot > 0 && !IsIncompatible(current2, chosen) && !WouldBreakReputationFloor(id, currentRep) && (current2.maxSlot > num || (current2.maxSlot == num && current2.cost < num2)))
					{
						num = current2.maxSlot;
						num2 = current2.cost;
						val = current2;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		if (val == null)
		{
			return null;
		}
		if (num3 >= num)
		{
			return null;
		}
		return val;
	}

	private static StartingPerk PickRefundPerk(List<StartingPerk> pool, HashSet<string> chosenIds, Dictionary<string, HashSet<string>> incompat)
	{
		StartingPerk val = null;
		int num = 0;
		Dictionary<string, int> currentRep = BuildRepState(chosenIds);
		try
		{
			Enumerator<StartingPerk> enumerator = pool.GetEnumerator();
			while (enumerator.MoveNext())
			{
				StartingPerk current = enumerator.Current;
				if (current != null)
				{
					string id = current.id;
					if (!string.IsNullOrEmpty(id) && !Excluded.Contains(id) && !chosenIds.Contains(id) && current.cost < 0 && !IsBlockedBy(id, chosenIds, incompat) && !WouldBreakReputationFloor(id, currentRep) && (val == null || current.cost < num))
					{
						val = current;
						num = current.cost;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		return val;
	}

	private static StartingPerk PickNext(PerkUIController ui, List<StartingPerk> pool, List<StartingPerk> chosen, HashSet<string> chosenIds, Dictionary<string, HashSet<string>> incompat)
	{
		int num = ui.maxPerkPoint - ui.currentPerkPoint;
		List<StartingPerk> val = new List<StartingPerk>();
		Dictionary<string, int> currentRep = BuildRepState(chosenIds);
		try
		{
			Enumerator<StartingPerk> enumerator = pool.GetEnumerator();
			while (enumerator.MoveNext())
			{
				StartingPerk current = enumerator.Current;
				if (current != null)
				{
					string id = current.id;
					if (!string.IsNullOrEmpty(id) && !Excluded.Contains(id) && !chosenIds.Contains(id) && !IsBlockedBy(id, chosenIds, incompat) && !WouldBreakReputationFloor(id, currentRep) && current.cost <= num && current.maxSlot <= 0)
					{
						val.Add(current);
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		if (val.Count > 0)
		{
			return val[Rng.Next(val.Count)];
		}
		return null;
	}

	private static Dictionary<string, HashSet<string>> BuildIncompatMap(List<StartingPerk> pool)
	{
		Dictionary<string, HashSet<string>> dictionary = new Dictionary<string, HashSet<string>>();
		try
		{
			Enumerator<StartingPerk> enumerator = pool.GetEnumerator();
			while (enumerator.MoveNext())
			{
				StartingPerk current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				string id = current.id;
				if (string.IsNullOrEmpty(id))
				{
					continue;
				}
				HashSet<string> hashSet = new HashSet<string>();
				if (current.incompatiblePerks != null)
				{
					Enumerator<string> enumerator2 = current.incompatiblePerks.GetEnumerator();
					while (enumerator2.MoveNext())
					{
						string current2 = enumerator2.Current;
						if (!string.IsNullOrEmpty(current2))
						{
							hashSet.Add(current2);
						}
					}
				}
				dictionary[id] = hashSet;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		return dictionary;
	}

	private static bool IsBlockedBy(string candidateId, HashSet<string> chosenIds, Dictionary<string, HashSet<string>> incompat)
	{
		try
		{
			if (incompat.TryGetValue(candidateId, out var value))
			{
				foreach (string item in value)
				{
					if (chosenIds.Contains(item))
					{
						return true;
					}
				}
			}
			foreach (string chosenId in chosenIds)
			{
				if (incompat.TryGetValue(chosenId, out var value2) && value2.Contains(candidateId))
				{
					return true;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		return false;
	}

	private static bool IsIncompatible(StartingPerk candidate, List<StartingPerk> chosen)
	{
		try
		{
			string id = candidate.id;
			if (string.IsNullOrEmpty(id))
			{
				return false;
			}
			HashSet<string> hashSet = new HashSet<string>();
			Enumerator<StartingPerk> enumerator = chosen.GetEnumerator();
			while (enumerator.MoveNext())
			{
				StartingPerk current = enumerator.Current;
				if (!string.IsNullOrEmpty(current.id))
				{
					hashSet.Add(current.id);
				}
			}
			if (candidate.incompatiblePerks != null)
			{
				Enumerator<string> enumerator2 = candidate.incompatiblePerks.GetEnumerator();
				while (enumerator2.MoveNext())
				{
					string current2 = enumerator2.Current;
					if (!string.IsNullOrEmpty(current2) && hashSet.Contains(current2))
					{
						return true;
					}
				}
			}
			enumerator = chosen.GetEnumerator();
			while (enumerator.MoveNext())
			{
				StartingPerk current3 = enumerator.Current;
				if (current3.incompatiblePerks == null)
				{
					continue;
				}
				Enumerator<string> enumerator2 = current3.incompatiblePerks.GetEnumerator();
				while (enumerator2.MoveNext())
				{
					string current4 = enumerator2.Current;
					if (!string.IsNullOrEmpty(current4) && current4 == id)
					{
						return true;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		return false;
	}

	private static StartingPerk FindInPool(List<StartingPerk> pool, string id)
	{
		try
		{
			for (int i = 0; i < pool.Count; i++)
			{
				StartingPerk val = pool[i];
				if (val != null && val.id == id)
				{
					return val;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		return null;
	}

	private static bool TrySelect(PerkUIController ui, StartingPerk perk)
	{
		if (perk == null)
		{
			return false;
		}
		try
		{
			string id = perk.id;
			if (string.IsNullOrEmpty(id))
			{
				return false;
			}
			StartingPerkElement val = FindElement(ui.selectedPerks, id) ?? FindElement(ui.availablePerks, id);
			if ((Object)(object)val == (Object)null)
			{
				val = CreateElement(ui, perk);
				if ((Object)(object)val == (Object)null)
				{
					return false;
				}
			}
			try
			{
				val.perk = perk;
			}
			catch
			{
			}
			ui.SelectPerk(val);
			try
			{
				val.isSelected = true;
			}
			catch
			{
			}
			return true;
		}
		catch
		{
			return false;
		}
	}

	private static StartingPerkElement CreateElement(PerkUIController ui, StartingPerk perk)
	{
		try
		{
			GameObject perkElementPrefab = ui.perkElementPrefab;
			GameObject availablePerks = ui.availablePerks;
			if ((Object)(object)perkElementPrefab == (Object)null || (Object)(object)availablePerks == (Object)null)
			{
				return null;
			}
			GameObject val = Object.Instantiate<GameObject>(perkElementPrefab, availablePerks.transform);
			StartingPerkElement component = val.GetComponent<StartingPerkElement>();
			if ((Object)(object)component == (Object)null)
			{
				Object.Destroy((Object)(object)val);
				return null;
			}
			component.id = perk.id;
			component.isSelected = false;
			component.perk = perk;
			val.SetActive(true);
			return component;
		}
		catch
		{
			return null;
		}
	}

	private static StartingPerkElement FindElement(GameObject container, string id)
	{
		if ((Object)(object)container == (Object)null || string.IsNullOrEmpty(id))
		{
			return null;
		}
		try
		{
			Transform transform = container.transform;
			for (int i = 0; i < transform.childCount; i++)
			{
				StartingPerkElement component = ((Component)transform.GetChild(i)).gameObject.GetComponent<StartingPerkElement>();
				if ((Object)(object)component != (Object)null && component.id == id)
				{
					return component;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MadnessRoller] 异常: " + ex.Message);
		}
		return null;
	}

	private static Dictionary<string, int> BuildRepState(HashSet<string> perkIds)
	{
		Dictionary<string, int> dictionary = new Dictionary<string, int>();
		string[] array = new string[5] { "SECURITY", "REVOLUTION", "BLACK_MARKET", "LOWER_LEVEL", "UPPER_LEVEL" };
		string[] array2 = array;
		foreach (string key in array2)
		{
			dictionary[key] = 0;
		}
		foreach (string perkId in perkIds)
		{
			if (perkId == null || !RepEffects.TryGetValue(perkId, out var value))
			{
				continue;
			}
			foreach (KeyValuePair<string, int> item in value)
			{
				if (item.Key == "ALL")
				{
					array2 = array;
					for (int i = 0; i < array2.Length; i++)
					{
						dictionary[array2[i]] += item.Value;
					}
				}
				else if (dictionary.ContainsKey(item.Key))
				{
					dictionary[item.Key] += item.Value;
				}
			}
		}
		return dictionary;
	}

	private static bool WouldBreakReputationFloor(string candidateId, Dictionary<string, int> currentRep)
	{
		if (string.IsNullOrEmpty(candidateId) || !RepEffects.TryGetValue(candidateId, out var value))
		{
			return false;
		}
		foreach (KeyValuePair<string, int> item in value)
		{
			string[] array = ((!(item.Key == "ALL")) ? new string[1] { item.Key } : new string[5] { "SECURITY", "REVOLUTION", "BLACK_MARKET", "LOWER_LEVEL", "UPPER_LEVEL" });
			foreach (string key in array)
			{
				if ((currentRep.TryGetValue(key, out var value2) ? value2 : 0) + item.Value < -100)
				{
					return true;
				}
			}
		}
		return false;
	}
}
internal static class ManualPatcher
{
	private static Harmony _harmony;

	private static readonly List<string> _patchFailDetails = new List<string>();

	internal static int PatchOkCount { get; private set; }

	internal static int PatchFailCount { get; private set; }

	private static void MarkOk()
	{
		PatchOkCount++;
	}

	private static void MarkFail(string what, string why)
	{
		PatchFailCount++;
		if (_patchFailDetails.Count < 60)
		{
			_patchFailDetails.Add(what + (string.IsNullOrEmpty(why) ? "" : ("  —  " + why)));
		}
	}

	internal static void LogPatchSummary()
	{
		try
		{
			Core.LogMsg($"[Patch自检] 补丁挂载: 成功 {PatchOkCount} / 失败 {PatchFailCount}");
			if (PatchFailCount == 0)
			{
				Core.LogMsg("[Patch自检] 全部补丁已应用 ?");
				return;
			}
			Core.LogMsg("[Patch自检] ===== 以下补丁未应用（对应功能不会生效）=====");
			foreach (string patchFailDetail in _patchFailDetails)
			{
				Core.LogMsg("[Patch自检]   " + patchFailDetail);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ManualPatcher] 异常: " + ex.Message);
		}
	}

	internal static void Init(Harmony harmony)
	{
		_harmony = harmony;
	}

	internal static void TryPatch(Type type, string name, string prefix = null, string postfix = null, Type[] parameterTypes = null, Type patchHost = null, int? priority = null, string finalizer = null)
	{
		//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b8: Unknown result type (might be due to invalid IL or missing references)
		//IL_00c9: Unknown result type (might be due to invalid IL or missing references)
		Type type2 = patchHost ?? typeof(Patches);
		try
		{
			MethodBase methodBase = ((parameterTypes != null) ? AccessTools.Method(type, name, parameterTypes, (Type[])null) : AccessTools.Method(type, name, (Type[])null, (Type[])null));
			if (methodBase == null)
			{
				Core.LogMsg($"[Patch失败] {type.Name}.{name} 未找到，补丁未应用");
				MarkFail(type.Name + "." + name, "方法未找到");
				return;
			}
			HarmonyMethod val = ((prefix == null) ? ((HarmonyMethod)null) : new HarmonyMethod(type2, prefix, (Type[])null));
			HarmonyMethod val2 = ((postfix == null) ? ((HarmonyMethod)null) : new HarmonyMethod(type2, postfix, (Type[])null));
			HarmonyMethod val3 = ((finalizer == null) ? ((HarmonyMethod)null) : new HarmonyMethod(type2, finalizer, (Type[])null));
			if (priority.HasValue)
			{
				if (val != null)
				{
					val.priority = priority.Value;
				}
				if (val2 != null)
				{
					val2.priority = priority.Value;
				}
			}
			_harmony.Patch(methodBase, val, val2, (HarmonyMethod)null, val3, (HarmonyMethod)null);
			MarkOk();
		}
		catch (Exception ex)
		{
			Core.LogMsg($"[Patch失败] {type.Name}.{name}: {ex.Message}");
			MarkFail(type.Name + "." + name, ex.Message);
		}
	}

	internal static void TryPatchByName(Type type, string name, string prefix = null, string postfix = null, Type patchHost = null)
	{
		//IL_00dd: Unknown result type (might be due to invalid IL or missing references)
		//IL_00eb: Unknown result type (might be due to invalid IL or missing references)
		Type type2 = patchHost ?? typeof(Patches);
		try
		{
			MethodBase methodBase = null;
			foreach (MethodInfo declaredMethod in AccessTools.GetDeclaredMethods(type))
			{
				if (declaredMethod.Name == name)
				{
					methodBase = declaredMethod;
					break;
				}
			}
			if (methodBase == null)
			{
				Core.LogMsg($"[Patch失败] {type.Name}.{name} 按名未找到，补丁未应用");
				MarkFail(type.Name + "." + name + "（按名）", "方法未找到");
			}
			else
			{
				_harmony.Patch(methodBase, (prefix == null) ? ((HarmonyMethod)null) : new HarmonyMethod(type2, prefix, (Type[])null), (postfix == null) ? ((HarmonyMethod)null) : new HarmonyMethod(type2, postfix, (Type[])null), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
				MarkOk();
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg($"[Patch失败] {type.Name}.{name}: {ex.Message}");
			MarkFail(type.Name + "." + name + "（按名）", ex.Message);
		}
	}

	internal static void TryPatchAllOverloads(Type type, string name, string prefix = null, string postfix = null, Type patchHost = null)
	{
		//IL_004a: Unknown result type (might be due to invalid IL or missing references)
		//IL_0058: Unknown result type (might be due to invalid IL or missing references)
		Type type2 = patchHost ?? typeof(Patches);
		try
		{
			int num = 0;
			foreach (MethodInfo declaredMethod in AccessTools.GetDeclaredMethods(type))
			{
				if (declaredMethod.Name != name)
				{
					continue;
				}
				try
				{
					_harmony.Patch((MethodBase)declaredMethod, (prefix == null) ? ((HarmonyMethod)null) : new HarmonyMethod(type2, prefix, (Type[])null), (postfix == null) ? ((HarmonyMethod)null) : new HarmonyMethod(type2, postfix, (Type[])null), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
					num++;
				}
				catch (Exception ex)
				{
					Core.LogMsg($"[Patch失败] {type.Name}.{name}({string.Join(", ", from p in declaredMethod.GetParameters()
						select p.ParameterType.Name)}): {ex.Message}");
					MarkFail(type.Name + "." + name + "（重载）", ex.Message);
				}
			}
			if (num > 0)
			{
				PatchOkCount += num;
				return;
			}
			Core.LogMsg($"[Patch失败] {type.Name}.{name} 无匹配重载");
			MarkFail(type.Name + "." + name + "（重载）", "无匹配重载");
		}
		catch (Exception ex2)
		{
			Core.LogMsg($"[Patch失败] {type.Name}.{name}: {ex2.Message}");
			MarkFail(type.Name + "." + name + "（重载）", ex2.Message);
		}
	}
}
internal static class MerchantHelper
{
	internal static GameItem AddItemToCounter(string itemId, int heat = 0, bool isOwend = false)
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				Core.LogMsg("[MerchantHelper] PlayerStore.Instance为null");
				return null;
			}
			if (!DirectoryMaster.Has<GameItem>(itemId))
			{
				return null;
			}
			GameItem val = DirectoryMaster.Item(itemId, true);
			if (val == null)
			{
				Core.LogMsg("[MerchantHelper] 创建物品失败: " + itemId);
				return null;
			}
			ClearAllBadTags(val);
			GameItem val2 = val;
			ClearAllBadTags(val2);
			instance.AddDirectSellingItemToTable(val2, isOwend, false, false, heat);
			ClearAllBadTags(val2);
			return val2;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MerchantHelper] AddItemToCounter异常(" + itemId + "): " + ex.Message);
			return null;
		}
	}

	internal static GameItem AddItemToCounter(GameItem item, int heat = 0, bool isOwend = false)
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				Core.LogMsg("[MerchantHelper] PlayerStore.Instance为null");
				return null;
			}
			if (item == null)
			{
				return null;
			}
			ClearAllBadTags(item);
			ClearAllBadTags(item);
			instance.AddDirectSellingItemToTable(item, isOwend, false, false, heat);
			ClearAllBadTags(item);
			return item;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[MerchantHelper] AddItemToCounter(item)异常: " + ex.Message);
			return null;
		}
	}

	internal static void ClearAllBadTags(GameItem item)
	{
		if (item == null)
		{
			return;
		}
		try
		{
			item.DisableTag("stolen", true);
		}
		catch
		{
		}
		try
		{
			item.DisableTag("TAG_STOLEN", true);
		}
		catch
		{
		}
		try
		{
			item.DisableTag("STOLEN_VALUE_INT", true);
		}
		catch
		{
		}
	}

	internal static bool IsItemClean(GameItem item)
	{
		if (item == null)
		{
			return false;
		}
		try
		{
			bool num = item.IsTag("stolen") || item.IsTag("TAG_STOLEN");
			TagState tagReadonly = item.GetTagReadonly("STOLEN_VALUE_INT");
			bool flag = tagReadonly != null && tagReadonly.GetInt() > 0;
			bool flag2 = item.IsTag("not_purchased") || item.IsTag("TAG_NOT_PURCHASED");
			return !num && !flag && !flag2;
		}
		catch
		{
			return false;
		}
	}

	internal static List<string> GenerateCardLockPairs()
	{
		List<string> list = new List<string>();
		string[][] array = new string[7][]
		{
			new string[2] { "eng_keycard", "eng_box" },
			new string[2] { "med_keycard", "med_box" },
			new string[2] { "sec_keycard", "sec_box" },
			new string[2] { "ser_keycard", "service_box" },
			new string[2] { "cmd_keycard", "expedition_box" },
			new string[2] { "sci_keycard", "evidence_box" },
			new string[2] { "sup_keycard", "toolbox" }
		};
		int num = Core.Rng.Next(3, 6);
		for (int i = 0; i < num; i++)
		{
			int num2 = Core.Rng.Next(array.Length);
			list.Add(array[num2][0]);
			list.Add(array[num2][1]);
		}
		string[] array2 = new string[3] { "permit_gun_1", "permit_gun_2", "permit_gun_3" };
		list.Add(array2[Core.Rng.Next(array2.Length)]);
		if (Core.Rng.Next(2) == 0)
		{
			list.Add("blank_keycard");
		}
		return list;
	}
}
internal static class ModCannibalism
{
	private static readonly string[] MOD_TAGS = new string[3] { "BONUS_PERCENTAGE_PERFORMANCE_INT", "BONUS_PERCENTAGE_EFFICIENCY_INT", "BONUS_PERCENTAGE_QUALITY_INT" };

	internal static string LastNewsLine = null;

	private static bool _nightTabInserted = false;

	public static void OnDayStartPostfix()
	{
		try
		{
			if (!BuildConfig.CannibalismSeasonEnabled)
			{
				if (RiskTakerPerk.IsActive() && DeterministicSchedule.CurrentDay % BuildConfig.CannibalInterval <= 2)
				{
					Core.LogMsg("[吞噬季] 已停用（CannibalismSeasonEnabled=false），跳过今日互食");
				}
			}
			else
			{
				if (!RiskTakerPerk.IsActive())
				{
					return;
				}
				int num = DeterministicSchedule.CurrentDay % BuildConfig.CannibalInterval;
				if (num == 0)
				{
					string text = LangHelper.T("吞噬季开始：机器里的模组将互相吞噬，持续 3 天", "Cannibalism Season begins: modules in machines will devour each other for 3 days");
					try
					{
						StoreUIManager.Instance.Notify(text, "default");
					}
					catch
					{
					}
					LastNewsLine = text;
				}
				if (num > 2)
				{
					return;
