	private static List<Tuple<GameItem, List<GameItem>>> CollectMachines()
	{
		List<Tuple<GameItem, List<GameItem>>> list = new List<Tuple<GameItem, List<GameItem>>>();
		try
		{
			List<GameItem> list2 = new List<GameItem>();
			try
			{
				List<GameItem> val = PlayerStore.Instance.FindAllItem(true);
				if (val != null)
				{
					Enumerator<GameItem> enumerator = val.GetEnumerator();
					while (enumerator.MoveNext())
					{
						GameItem current = enumerator.Current;
						if (current != null)
						{
							list2.Add(current);
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				_ = PlayerStore.Instance;
			}
			catch
			{
			}
			foreach (GameItem item in list2)
			{
				if (item == null || !RobinCrusoePerk.IsMachine(item))
				{
					continue;
				}
				GameGridInventory moduleInv = MachineHelper.GetModuleInv(item);
				if (moduleInv == null || ((GameInventory)moduleInv).childItems == null)
				{
					continue;
				}
				List<GameItem> list3 = new List<GameItem>();
				Enumerator<GameItem> enumerator3 = ((GameInventory)moduleInv).childItems.GetEnumerator();
				while (enumerator3.MoveNext())
				{
					GameItem current3 = enumerator3.Current;
					bool flag = false;
					string text = "";
					try
					{
						text = ((current3 != null) ? (current3.identifier ?? "") : "");
					}
					catch
					{
					}
					if (!(text == "system_module_ruined") && !IsNodeModule(text))
					{
						try
						{
							flag = current3 != null && current3.IsTag("MODULE_TAG") && !RobinCrusoePerk.IsExcludedModule(current3);
						}
						catch
						{
							flag = false;
						}
						if (flag)
						{
							list3.Add(current3);
						}
					}
				}
				if (list3.Count >= 2)
				{
					list.Add(new Tuple<GameItem, List<GameItem>>(item, list3));
				}
			}
		}
		catch
		{
		}
		return list;
	}

	private static bool IsNodeModule(string id)
	{
		if (string.IsNullOrEmpty(id))
		{
			return false;
		}
		switch (id)
		{
		case "node":
		case "node_small":
		case "node_medium":
			return true;
		default:
			return id.StartsWith("node_");
		}
	}

