	private static void TryWriteCannibalismTabLine(AdvCalendarUIManager __instance, string sectionField)
	{
		try
		{
			if (string.IsNullOrEmpty(LastNewsLine) || _nightTabInserted)
			{
				return;
			}
			string lastNewsLine = LastNewsLine;
			LastNewsLine = null;
			GameObject val = null;
			try
			{
				val = Traverse.Create((object)__instance).Field(sectionField).GetValue<GameObject>();
			}
			catch
			{
			}
			GameObject val2 = null;
			try
			{
				StartOfDayUIManager instance = StartOfDayUIManager.Instance;
				if ((Object)(object)instance != (Object)null)
				{
					val2 = instance.startOfDayTMPPrefab;
				}
			}
			catch
			{
			}
			try
			{
				PlayerStore instance2 = PlayerStore.Instance;
				if (instance2 != null)
				{
					instance2.AddNightLog(lastNewsLine, "#7FC97F");
				}
			}
			catch
			{
			}
			_nightTabInserted = true;
			GameObject val3 = Object.Instantiate<GameObject>(val2, val.transform);
			if ((Object)(object)val3 == (Object)null)
			{
				_nightTabInserted = true;
				return;
			}
			val3.SetActive(true);
			try
			{
				Component[] array = Il2CppArrayBase<Component>.op_Implicit(val3.GetComponentsInChildren<Component>(true));
				if (array != null)
				{
					Component[] array2 = array;
					foreach (Component val4 in array2)
					{
						if ((Object)(object)val4 == (Object)null)
						{
							continue;
						}
						string text = "";
						try
						{
							text = ((Object)val4).GetIl2CppType().FullName ?? "";
						}
						catch
						{
						}
						if (string.IsNullOrEmpty(text))
						{
							try
							{
								text = ((object)val4).GetType().Name ?? "";
							}
							catch
							{
							}
						}
						if (!text.Contains("TextMeshProUGUI") && !text.Contains("TMP_Text"))
						{
							continue;
						}
						bool flag = false;
						try
						{
							MethodInfo[] methods = ((object)val4).GetType().GetMethods();
							if (methods != null)
							{
								MethodInfo[] array3 = methods;
								foreach (MethodInfo methodInfo in array3)
								{
									if (methodInfo == null)
									{
										continue;
									}
									string text2 = methodInfo.Name ?? "";
									if (text2 == "set_text" || text2 == "SetText")
									{
										ParameterInfo[] parameters = methodInfo.GetParameters();
										if (parameters != null && parameters.Length == 1)
										{
											methodInfo.Invoke(val4, new object[1] { lastNewsLine });
											flag = true;
											break;
										}
									}
								}
							}
						}
						catch
						{
						}
						if (flag)
						{
							break;
						}
					}
				}
			}
			catch
			{
			}
			_nightTabInserted = true;
		}
		catch
		{
		}
	}

