	public static bool IsSafeCoexistOwner(string owner)
	{
		if (string.IsNullOrEmpty(owner))
		{
			return false;
		}
		string[] sAFE_COEXIST_OWNERS = SAFE_COEXIST_OWNERS;
		foreach (string value in sAFE_COEXIST_OWNERS)
		{
			if (owner.IndexOf(value, StringComparison.OrdinalIgnoreCase) >= 0)
			{
				return true;
			}
		}
		return false;
	}

	public static bool IsLoaded(string assemblyName)
	{
		try
		{
			if (_loadedCache.TryGetValue(assemblyName, out var value) && value.HasValue)
			{
				return value.Value;
			}
			bool flag = false;
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			if (assemblies != null)
			{
				Assembly[] array = assemblies;
				foreach (Assembly assembly in array)
				{
					if (!(assembly == null))
					{
						string text = "";
						try
						{
							text = assembly.GetName().Name ?? "";
						}
						catch
						{
						}
						if (text == assemblyName)
						{
							flag = true;
							break;
						}
					}
				}
			}
			_loadedCache[assemblyName] = flag;
			return flag;
		}
		catch
		{
			return false;
		}
	}

	public static bool ShouldYield(Type type, string methodName, out string modName)
	{
		modName = "";
		try
		{
			string typeFullName = type?.FullName ?? "";
			foreach (ConflictEntry kNOWN_CONFLICT in KNOWN_CONFLICTS)
			{
				if (kNOWN_CONFLICT.YieldOnLoad && kNOWN_CONFLICT.Matches(typeFullName, methodName) && IsLoaded(kNOWN_CONFLICT.ModAssembly))
				{
					modName = kNOWN_CONFLICT.ModAssembly;
					return true;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ModCompat] 异常: " + ex.Message);
		}
		return false;
	}

	public static void LogLoadedConflicts()
	{
		try
		{
			HashSet<string> hashSet = new HashSet<string>();
			foreach (ConflictEntry kNOWN_CONFLICT in KNOWN_CONFLICTS)
			{
				if (hashSet.Add(kNOWN_CONFLICT.ModAssembly) && IsLoaded(kNOWN_CONFLICT.ModAssembly))
				{
					string text = (kNOWN_CONFLICT.YieldOnLoad ? "对应重叠方法将主动让路（功能降级）" : "与对方共存（核心方法不让路，注意测试）");
					Core.LogMsg("[兼容] 检测到第三方 mod「" + kNOWN_CONFLICT.ModAssembly + "」已加载——" + text);
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[ModCompat] 异常: " + ex.Message);
		}
	}
}
