	private static void ReplaceAllText(Transform root, ref int replaced)
	{
		try
		{
			if ((Object)(object)root == (Object)null)
			{
				return;
			}
			Il2CppArrayBase<Component> components = ((Component)root).gameObject.GetComponents<Component>();
			if (components != null)
			{
				foreach (Component item in components)
				{
					if ((Object)(object)item == (Object)null)
					{
						continue;
					}
					string text = "";
					try
					{
						text = ((Object)item).GetIl2CppType().FullName ?? "";
					}
					catch
					{
					}
					if (string.IsNullOrEmpty(text))
					{
						try
						{
							text = ((object)item).GetType().Name ?? "";
						}
						catch
						{
						}
					}
					if (text.Contains("LocalizeStringEvent") || text.Contains("TMPLocalizer"))
					{
						try
						{
							Object.Destroy((Object)(object)item);
						}
						catch
						{
						}
					}
					else
					{
						if (!text.Contains("Text") && !text.Contains("TMP"))
						{
							continue;
						}
						MethodInfo[] array = null;
						try
						{
							array = ((object)item).GetType().GetMethods();
						}
						catch
						{
						}
						if (array != null)
						{
							List<string> list = new List<string>();
							MethodInfo[] array2 = array;
							foreach (MethodInfo methodInfo in array2)
							{
								if (!(methodInfo == null))
								{
									string text2 = methodInfo.Name ?? "";
									if (text2.IndexOf("ext", StringComparison.OrdinalIgnoreCase) >= 0 || text2.IndexOf("m_", StringComparison.OrdinalIgnoreCase) >= 0)
									{
										list.Add(text2);
									}
								}
							}
						}
						bool flag = false;
						if (!flag)
						{
							try
							{
								TextMeshProUGUI val = ((Il2CppObjectBase)item).TryCast<TextMeshProUGUI>();
								if ((Object)(object)val != (Object)null)
								{
									((TMP_Text)val).text = START_NAME;
									replaced++;
									flag = true;
								}
							}
							catch (Exception ex)
							{
								Core.LogMsg("[NewStartTypeUI] 异常: " + ex.Message);
							}
						}
						try
						{
							Type type = Type.GetType("TMPro.TextMeshProUGUI, Unity.TextMeshPro");
							if (type != null)
							{
								PropertyInfo property = type.GetProperty("text");
								if (property != null)
								{
									property.SetValue(item, START_NAME);
									replaced++;
									flag = true;
								}
							}
						}
						catch (Exception ex2)
						{
							Core.LogMsg("[NewStartTypeUI] 异常: " + ex2.Message);
						}
						if (array != null)
						{
							MethodInfo[] array2 = array;
							foreach (MethodInfo methodInfo2 in array2)
							{
								if (methodInfo2 == null)
								{
									continue;
								}
								string text3 = methodInfo2.Name ?? "";
								if (text3 != "set_text" && text3 != "SetText")
								{
									continue;
								}
								ParameterInfo[] parameters = methodInfo2.GetParameters();
								if (parameters != null && parameters.Length == 1)
								{
									try
									{
										methodInfo2.Invoke(item, new object[1] { START_NAME });
										replaced++;
										flag = true;
									}
									catch (Exception ex3)
									{
										Core.LogMsg("[NewStartTypeUI] 异常: " + ex3.Message);
									}
									break;
								}
							}
						}
						if (flag)
						{
							continue;
						}
						try
						{
							PropertyInfo property2 = ((object)item).GetType().GetProperty("text");
							if (property2 != null)
							{
								property2.SetValue(item, START_NAME);
								replaced++;
								flag = true;
							}
						}
						catch (Exception ex4)
						{
							Core.LogMsg("[NewStartTypeUI] 异常: " + ex4.Message);
						}
					}
				}
			}
			for (int j = 0; j < root.childCount; j++)
			{
				ReplaceAllText(root.GetChild(j), ref replaced);
			}
		}
		catch (Exception ex5)
		{
			Core.LogMsg("[NewStartTypeUI] 异常: " + ex5.Message);
		}
	}

