	public static void ForceInspectionToday()
	{
		try
		{
			if (!RiskTakerPerk.IsActive() && !ThiefMagnetPerk.IsActive())
			{
				return;
			}
			int num = 1;
			try
			{
				num = StoreStation.GetDayCounter();
			}
			catch
			{
			}
			if (_inspectionTriggeredDay == num)
			{
				return;
			}
			bool flag = RiskTakerPerk.IsActive();
			bool flag2 = ThiefMagnetPerk.IsActive();
			bool flag3 = flag;
			if (!flag & flag2)
			{
				flag3 = DeterministicRandom.NextBool("thief_magnet_inspection", num, 0.2);
			}
			if (!flag3)
			{
				return;
			}
			try
			{
				if (!RiskTakerPerk.IsActive() && !ThiefMagnetPerk.IsActive())
				{
					return;
				}
				PlayerStore instance = PlayerStore.Instance;
				if (instance == null || instance.secData == null)
				{
					return;
				}
				StoreClientManager val = null;
				try
				{
					PropertyInfo property = typeof(PlayerStore).GetProperty("storeClientManager", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if (property != null)
					{
						object? value = property.GetValue(instance);
						val = (StoreClientManager)((value is StoreClientManager) ? value : null);
					}
					if (val == null)
					{
						FieldInfo field = typeof(PlayerStore).GetField("storeClientManager", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
						if (field != null)
						{
							object? value2 = field.GetValue(instance);
							val = (StoreClientManager)((value2 is StoreClientManager) ? value2 : null);
						}
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[刀尖舔血] 获取storeClientManager失败: " + ex.Message);
				}
				if (val != null)
				{
					try
					{
						val.dayUntilInspection = 0;
						val.daySinceInspection = 100;
						val.inspectionSeeded = true;
						val.ResetInspection();
						val.dayUntilInspection = 0;
						val.daySinceInspection = 100;
						val.inspectionSeeded = true;
						try
						{
							ContrabandHelper.StartInspection(instance.secData.GetInspectorPersonality(), false);
							try
							{
								_inspectionTriggeredDay = StoreStation.GetDayCounter();
							}
							catch
							{
								_inspectionTriggeredDay = num;
							}
						}
						catch (Exception ex2)
						{
							Core.LogMsg("[治安检查] StartInspection失败: " + ex2.Message);
						}
						try
						{
							List<StoreClient> clientStack = val.clientStack;
							int num2 = clientStack?.Count ?? (-1);
							if (clientStack != null && num2 > 0)
							{
								for (int i = 0; i < num2; i++)
								{
									try
									{
										_ = clientStack[i];
									}
									catch
									{
									}
								}
							}
							return;
						}
						catch (Exception ex3)
						{
							Core.LogMsg("[治安检查] clientStack诊断失败: " + ex3.Message);
							return;
						}
					}
					catch (Exception ex4)
					{
						Core.LogMsg("[刀尖舔血] 设置检查条件失败: " + ex4.Message);
						return;
					}
				}
				try
				{
					ContrabandHelper.StartInspection(instance.secData.GetInspectorPersonality(), false);
					try
					{
						_inspectionTriggeredDay = StoreStation.GetDayCounter();
					}
					catch
					{
						_inspectionTriggeredDay = num;
					}
				}
				catch (Exception ex5)
				{
					Core.LogMsg("[刀尖舔血] StartInspection失败: " + ex5.Message);
				}
			}
			catch (Exception ex6)
			{
				Core.LogMsg("[刀尖舔血] 触发检查失败: " + ex6.Message);
			}
		}
		catch (Exception ex7)
		{
			Core.LogMsg("[治安检查] 强制检查失败: " + ex7.Message);
		}
	}

	public static void ApplyBadLuck()
	{
		try
		{
			if (!BadLuckPerk.IsActive())
			{
				return;
			}
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				Core.LogMsg("[霉运缠身] PlayerStore为null");
				return;
			}
			int dayCounter = StoreStation.GetDayCounter();
			if (WageSaveStore.GetInt("BadLuck", "last_day", -1) == dayCounter)
			{
				return;
			}
			int num = DeterministicRandom.Next("bad_luck", dayCounter, 1, 201);
			bool flag = false;
			try
			{
				PropertyInfo property = typeof(PlayerStore).GetProperty("playerCash", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (property != null)
				{
					int num2 = (int)property.GetValue(instance);
					property.SetValue(instance, num2 - num);
					flag = true;
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[霉运缠身] 属性扣款失败: " + ex.Message);
			}
			if (!flag)
			{
				try
				{
					FieldInfo field = typeof(PlayerStore).GetField("playerCash", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if (field != null)
					{
						int num3 = (int)field.GetValue(instance);
						field.SetValue(instance, num3 - num);
						flag = true;
					}
				}
				catch (Exception ex2)
				{
					Core.LogMsg("[霉运缠身] 字段扣款失败: " + ex2.Message);
				}
			}
			if (flag)
			{
				WageSaveStore.SetInt("BadLuck", "last_day", dayCounter);
				try
				{
					PlayerStore instance2 = PlayerStore.Instance;
					if (instance2 != null)
					{
						instance2.AddNightLog("[霉运缠身] " + LangHelper.T("昨晚打烊时，有人趁夜色摸走了你", "Last night after closing, someone slipped in and took") + " " + num + " " + LangHelper.T("信用点。", "credits."), "#7FC97F");
					}
				}
				catch
				{
				}
				Core.AddNightReportLine("[霉运缠身] " + LangHelper.T("昨晚打烊时，有人趁夜色摸走了你", "Last night after closing, someone slipped in and took") + " " + num + " " + LangHelper.T("信用点。", "credits."));
			}
			else
			{
				Core.LogMsg("[霉运缠身] 扣钱失败：playerCash 属性/字段均未找到");
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[霉运缠身] 失败: " + ex3.Message);
		}
	}

	internal static void FrameUpdate()
	{
