	public static void PostfixPerkUiOpen(PerkUIController __instance)
	{
		try
		{
			MadnessRoller.ResetLock();
			if (!RobinCrusoePerk.IsActive())
			{
				if (__instance.maxPerkCount < 10)
				{
					__instance.maxPerkCount = 10;
				}
				return;
			}
			try
			{
				PerkGrowthHelper.ApplyOnPerkUiOpen(__instance);
				if (__instance.maxPerkCount < 10)
				{
					__instance.maxPerkCount = 10;
				}
				try
				{
					if (MelonPreferences.GetEntryValue<bool>("WagesPerks", "HardMode"))
					{
						__instance.maxPerkCount += 1;
						__instance.maxPerkPoint += 1;
					}
				}
				catch
				{
				}
				try
				{
					int num = 0;
					CustomStartingPerk[] all = CustomStartingPerks.All;
					foreach (CustomStartingPerk customStartingPerk in all)
					{
						if (customStartingPerk.Cost < 0 && StartingPerk.IsPerkActive(customStartingPerk.Id))
						{
							num += -customStartingPerk.Cost;
						}
					}
					if (num >= 10)
					{
						__instance.maxPerkCount += 1;
						__instance.maxPerkPoint += 1;
					}
				}
				catch
				{
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[特性] 成长结算异常: " + ex.Message);
			}
			CustomStartingPerks.EnsureRegistered();
			Core.LogMsg("[特性UI] OpenUI时确保特性已注册");
			CustomStartingPerks.EnsurePickerElements(__instance);
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[特性UI] 打开失败: " + ex2.Message);
		}
	}

