	public static void PostfixOnAddClient(StoreClient storeClient)
	{
		if (storeClient == null)
		{
			return;
		}
		try
		{
			DrJacksonFriendPerk.AddClientPatch.Postfix(storeClient);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[博士之友] AddClient Postfix失败: " + ex.Message);
		}
		try
		{
			NormalizeSpecialNpcName(storeClient);
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[特殊NPC] 统一名字失败: " + ex2.Message);
		}
		try
		{
			string identifier = storeClient.identifier;
			if (identifier == "wanted4" || identifier == "wanted4Normal")
			{
				try
				{
					StoreReputation storeReputation = StoreReputation.GetStoreReputation("FACTION_REVOLUTION");
					int num = ((storeReputation != null) ? ((int)storeReputation.GetReputationExact()) : 0);
					if (num <= -99)
					{
						storeClient.sellPriceModifier = -50;
						Core.LogMsg("[奥丁] " + identifier + " 进店 声望" + num + " → sellPriceModifier=-50（实际读回" + storeClient.sellPriceModifier + "）");
					}
					else
					{
						storeClient.sellPriceModifier = 0;
						Core.LogMsg("[奥丁] " + identifier + " 进店 声望" + num + " → 不压价（sellPriceModifier=0）");
					}
				}
				catch (Exception ex3)
				{
					Core.LogMsg("[Patches.Npc.Client] 异常: " + ex3.Message);
				}
			}
		}
		catch (Exception ex4)
		{
			Core.LogMsg("[Patches.Npc.Client] 异常: " + ex4.Message);
		}
		try
		{
			if (!(storeClient.identifier == "retired_winemaker"))
			{
				return;
			}
			storeClient.clientIntent = (ClientIntent)3;
			long num2 = 0L;
			try
			{
				List<GameItem> invItems = EmporiumEntry.Instance.GetInvItems();
				if (invItems != null)
				{
					Enumerator<GameItem> enumerator = invItems.GetEnumerator();
					while (enumerator.MoveNext())
					{
						GameItem current = enumerator.Current;
						if (current == null)
						{
							continue;
						}
						string identifier2 = current.identifier;
						if (!string.IsNullOrEmpty(identifier2) && (identifier2.Contains("wine") || identifier2.Contains("beer") || identifier2.Contains("alcohol") || identifier2 == "wine_bottle"))
						{
							try
							{
								num2 += current.GetCurrentValue(false, true, true, false, 0L);
							}
							catch
							{
							}
						}
					}
				}
			}
			catch
			{
			}
			int num3 = (int)Math.Min((double)num2 * 1.5, 2147483646.0);
			if (num3 < 1000)
			{
				num3 = 1000;
			}
			storeClient.OverrideBudget(num3);
			storeClient.clientCash = num3;
			storeClient.useClientBudget = true;
			string[] array = new string[7] { "beer_case", "red_beer", "wine_bottle", "wine_berry", "wine_bloomberry", "wine_gloomberry", "empty_beer_bottle" };
			if (storeClient.clientBuyingIdList == null)
