	public static void PostfixStoreClientOnDealAccepted(StoreClient __instance)
	{
		try
		{
			if (!RobinCrusoePerk.IsActive())
			{
				return;
			}
			string text = MoodKey(__instance);
			if (__instance != null && text != null && _moodBoostedClients.Add(text))
			{
				RobinCrusoePerk.BoostMood(5, LangHelper.T("成交一单", "Deal closed"));
			}
			RobinCrusoePerk.RecordDeal();
			try
			{
				PlayerStore instance = PlayerStore.Instance;
				StoreClientInstance val = null;
				if (instance != null)
				{
					val = instance.currentClientInstance;
				}
				if (val == null || __instance == null)
				{
					return;
				}
				int num = 0;
				try
				{
					FieldInfo field = ((object)val).GetType().GetField("clientIntent", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if (field == null)
					{
						field = ((object)val).GetType().GetField("intent", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					}
					if (field != null)
					{
						num = (int)field.GetValue(val);
					}
				}
				catch
				{
				}
				if (num != 1)
				{
					return;
				}
				FieldInfo field2 = ((object)val).GetType().GetField("item", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (field2 == null)
				{
					field2 = ((object)val).GetType().GetField("currentItem", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				}
				if (!(field2 != null))
				{
					return;
				}
				object? value = field2.GetValue(val);
				GameItem val2 = (GameItem)((value is GameItem) ? value : null);
				if (val2 == null)
				{
					return;
				}
				try
				{
					RobinCrusoePerk.RecordRevenue((int)val2.GetCurrentValue(false, true, true, false, 0L));
				}
				catch
				{
				}
			}
			catch
			{
			}
		}
		catch
		{
		}
	}

