	public static bool PrefixGameItemGetNegociatedValue(GameItem __instance)
	{
		if (__instance == null || string.IsNullOrEmpty(__instance.identifier))
		{
			return false;
		}
		_inNegociatedCalc = true;
		_currentValueCallsInNegociated = 0;
		return true;
	}

	public static void PostfixGameItemGetNegociatedValue(GameItem __instance, ref long __result)
	{
		_inNegociatedCalc = false;
		if (_currentValueCallsInNegociated == 0)
		{
			TryApplyTradeMarkup(__instance, ref __result);
		}
	}

	public static bool PrefixGameItemGetCurrentValue(GameItem __instance)
	{
		if (__instance == null || string.IsNullOrEmpty(__instance.identifier))
		{
			return false;
		}
		if (_inNegociatedCalc)
		{
			_currentValueCallsInNegociated++;
		}
		return true;
	}

	public static void PostfixGameItemGetCurrentValue(GameItem __instance, ref long __result)
	{
		TryApplyTradeMarkup(__instance, ref __result);
	}

	private static void TryApplyTradeMarkup(GameItem item, ref long result)
	{
		try
		{
			long num = result;
			bool flag = false;
			try
			{
				flag = GeneralHelper.IsItemOwned(item);
			}
			catch (Exception ex)
			{
				flag = CurrentUITradeMode == 2;
				Core.LogMsg("[交易标记] IsItemOwned判定失败，按UI模式回退: " + ex.Message);
			}
			ApplyBadReputationMarkup(item, flag, ref result);
			if (flag && (Core.PerkActive("声名狼藉") || Core.PerkActive("人神共愤")))
			{
				try
				{
					PlayerStore instance = PlayerStore.Instance;
					if (instance != null && instance.currentClientInstance != null)
					{
						StoreClient clientBlueprint = instance.currentClientInstance.GetClientBlueprint();
						if (clientBlueprint != null && clientBlueprint.identifier == "wanted4Normal")
						{
							StoreReputation storeReputation = StoreReputation.GetStoreReputation("FACTION_REVOLUTION");
							double num2 = ((storeReputation != null) ? storeReputation.GetReputationExact() : 0.0);
							double num3 = 1.0 - num2 / -99.0 * 0.5;
							if (num3 < 0.5)
							{
								num3 = 0.5;
							}
							if (num3 > 1.0)
							{
								num3 = 1.0;
							}
							result = (long)((double)result * num3);
							if (num3 < 1.0)
							{
								TryAddOdinFeature(item, num3);
							}
							if (!_odinNotified && num3 < 1.0)
							{
								_odinNotified = true;
								try
								{
									StoreUIManager.Instance.Notify(LangHelper.T("声名狼藉威慑：奥丁收购价已降低", "Infamy deterrent: Odin buyback reduced"), "red");
								}
								catch
								{
								}
							}
						}
					}
				}
				catch
				{
				}
			}
			ApplyFriendMarkup(item, !flag, ref result);
			if (!ApplyRobinsonMarkup(item, flag, ref result) && flag)
			{
				bool flag2 = IsContrabandSafe(item);
				ApplyRiskWineMarkup(item, ref result, flag2);
				ApplyFaceMarkup(item, ref result);
				if (flag && (double)result < (double)num * 0.5)
				{
					result = (long)((double)num * 0.5);
				}
			}
		}
		catch
		{
		}
	}

	private static void ApplyBadReputationMarkup(GameItem item, bool isSell, ref long result)
	{
		bool flag = BadReputationPerk.IsActive();
		bool flag2 = BadReputationPerk.IsCleared();
		if (flag && !flag2)
		{
			if (isSell)
			{
				result = (long)((double)result * 0.8);
				TryAddBadReputationFeature(item, -20);
			}
			else if (!isSell)
			{
				result = (long)((double)result * 1.2);
				TryAddBadReputationFeature(item, 20);
			}
		}
	}

	private static void ApplyFriendMarkup(GameItem item, bool isBuy, ref long result)
	{
		try
		{
			if (isBuy && item != null)
			{
				float friendBuyDiscount = GetFriendBuyDiscount(out var _, out var _);
				if (friendBuyDiscount < 1f)
				{
					result = (long)((double)result * (double)friendBuyDiscount);
				}
			}
		}
		catch
		{
		}
	}

	private static bool ApplyRobinsonMarkup(GameItem item, bool isSell, ref long result)
	{
		if (!RobinCrusoePerk.IsActive())
		{
			return false;
		}
		if (!isSell)
		{
			TryAddNodeBuffFeature(item);
			if (RobinCrusoePerk.IsFood(item))
			{
				result = (long)((double)result * 2.0);
				TryAddRobinsonBuyMarkup(item);
				return true;
			}
			if (RobinCrusoePerk.IsMedicine(item))
			{
				result = (long)((double)result * 2.0);
				TryAddRobinsonBuyMarkup(item);
				return true;
			}
		}
		else if (isSell)
		{
			TryAddNodeBuffFeature(item);
			if (RobinCrusoePerk.IsFood(item))
			{
				int foodQuality = RobinCrusoePerk.GetFoodQuality(item);
				switch (foodQuality)
				{
				case 3:
					result = 0L;
					break;
				case 2:
					result = (long)((double)result * 0.1);
					break;
				default:
					if (RobinCrusoePerk.IsEaten(item))
					{
						result = (long)((double)result * 0.2);
					}
					else if (foodQuality <= 0)
					{
						result = (long)((double)result * 1.3);
					}
					break;
				}
				TryAddFoodQualityFeature(item, foodQuality);
			}
			double num = 1.0 + (double)RobinCrusoePerk.GetSellBonusPct() / 100.0;
			if (num > 1.0)
			{
				result = (long)((double)result * num);
			}
			double contraEffMult = RobinCrusoePerk.GetContraEffMult();
			if (contraEffMult > 1.0 && RobinCrusoePerk.IsContrabandItem(item))
			{
				result = (long)((double)result * contraEffMult);
			}
		}
		return false;
	}

	private static bool IsContrabandSafe(GameItem item)
	{
		bool flag = false;
		try
		{
			flag = ContrabandHelper.IsContraband(item);
		}
		catch
		{
		}
		if (!flag)
		{
			try
			{
				flag = item.IsTag("CONTRABAND");
			}
			catch
			{
			}
		}
		if (!flag)
		{
			try
			{
				flag = item.IsTag("CONTRABAND_ITEM_TAG");
			}
			catch
			{
			}
		}
		return flag;
	}

	private static void ApplyRiskWineMarkup(GameItem item, ref long result, bool flag)
	{
		bool flag2 = TraitEffects.IsAlcohol(item);
		float num = 1f;
		bool flag3 = false;
		try
		{
			flag3 = RiskTakerPerk.IsActive();
		}
		catch
		{
		}
		if (flag3 & flag)
		{
			num *= 1.2f;
		}
		if (WineLoverPerk.IsActive() & flag2)
		{
			num *= 1.25f;
		}
		if (num > 1f)
		{
			result = (long)((float)result * num);
			TryAddTradeFeature(item, flag, flag2);
		}
	}

	private static void ApplyFaceMarkup(GameItem item, ref long result)
	{
		double num = 1.0;
		string labelId = null;
		string display = null;
		if (SmilingFacePerk.IsActive())
		{
			num = 1.25;
			labelId = "smiling_face_markup";
			display = LangHelper.T("笑面虎加价", "Smiling Face Markup");
		}
		else if (SmilingTigerPerk.IsActive())
		{
			num = 0.75;
			labelId = "honest_dealer_discount";
			display = LangHelper.T("童叟无欺折让", "Honest Dealer Discount");
		}
		if (num != 1.0)
		{
			result = (long)((double)result * num);
			int percent = (SmilingFacePerk.IsActive() ? 25 : (-25));
			AddTradeLabel(item, labelId, display, (FeatureType)5, percent);
		}
	}

