				}
				if (num != 0L && !_tradeFeatureItems.ContainsKey(num))
				{
					_tradeFeatureItems[num] = item;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[标签-添加] 失败: " + ex.Message);
		}
