			val.valueStage = (ValueStage)1;
			val.valueModifier = 0;
			val.preExposeValueModifier = 0;
			val.usePreExposeValue = false;
			val.initiallyShown = true;
			val.isFeatureMatch = true;
			val.isFeatureExposed = true;
			val.isExposable = true;
			val.isFeatureDiscovered = false;
			val.publicDisplay = text;
			val.actualDisplay = text;
			item.itemFeatures.Add(val);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[食物品质] feature失败: " + ex.Message);
