	private static void TryAppendNightReport(StartOfDayUIManager __instance)
	{
		try
		{
			if (Core.NightReportQueue.Count == 0)
			{
				return;
			}
			string text = string.Join("\n", Core.NightReportQueue.ToArray());
			if ((Object)(object)__instance == (Object)null || (Object)(object)__instance.startOfDayTMPPrefab == (Object)null || (Object)(object)__instance.contentGroupObject == (Object)null)
			{
				Core.LogMsg("[夜间报告] 报告UI未就绪，无法追加（队列保留不丢）");
				return;
			}
			Core.NightReportQueue.Clear();
			GameObject val = Object.Instantiate<GameObject>(__instance.startOfDayTMPPrefab, __instance.contentGroupObject.transform);
			if (!((Object)(object)val != (Object)null))
			{
				return;
			}
			val.SetActive(true);
			bool flag = false;
			try
			{
				Component[] array = Il2CppArrayBase<Component>.op_Implicit(val.GetComponentsInChildren<Component>(true));
				if (array != null)
				{
					Component[] array2 = array;
					foreach (Component val2 in array2)
					{
						if ((Object)(object)val2 == (Object)null)
						{
							continue;
						}
						string text2 = "";
						try
						{
							text2 = ((Object)val2).GetIl2CppType().FullName ?? "";
						}
						catch
						{
						}
						if (string.IsNullOrEmpty(text2))
						{
							try
							{
								text2 = ((object)val2).GetType().Name ?? "";
							}
							catch
							{
							}
						}
						if (!text2.Contains("TextMeshProUGUI") && !text2.Contains("TMP_Text"))
						{
							continue;
						}
						bool flag2 = false;
						try
						{
							MethodInfo[] methods = ((object)val2).GetType().GetMethods();
							if (methods != null)
							{
								MethodInfo[] array3 = methods;
								foreach (MethodInfo methodInfo in array3)
								{
									if (methodInfo == null)
									{
										continue;
									}
									string text3 = methodInfo.Name ?? "";
									if (text3 == "set_text" || text3 == "SetText")
									{
										ParameterInfo[] parameters = methodInfo.GetParameters();
										if (parameters != null && parameters.Length == 1)
										{
											methodInfo.Invoke(val2, new object[1] { text });
											flag2 = true;
											break;
										}
									}
								}
							}
						}
						catch (Exception ex)
						{
							Core.LogMsg("[夜间报告] set_text 调用失败: " + ex.Message);
						}
						if (flag2)
						{
							flag = true;
							break;
						}
					}
				}
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[夜间报告] 反射设置文本失败: " + ex2.Message);
			}
			if (flag)
			{
				return;
			}
			Core.LogMsg("[夜间报告] 未找到TMP文本组件，无法设置文本");
			try
			{
				Component[] array4 = Il2CppArrayBase<Component>.op_Implicit(val.GetComponentsInChildren<Component>(true));
				if (array4 == null)
				{
					return;
				}
				Component[] array2 = array4;
				foreach (Component val3 in array2)
				{
					if ((Object)(object)val3 == (Object)null)
					{
						continue;
					}
					try
					{
						if (((Object)val3).GetIl2CppType().FullName == null)
						{
							_ = ((object)val3).GetType().Name;
						}
					}
					catch
					{
					}
					try
					{
						if ((Object)(object)val3.gameObject != (Object)null)
						{
							_ = ((Object)val3.gameObject).name;
						}
					}
					catch
					{
					}
				}
			}
			catch (Exception ex3)
			{
				Core.LogMsg("[夜间报告] 诊断dump失败: " + ex3.Message);
			}
		}
		catch (Exception ex4)
		{
			Core.LogMsg("[夜间报告] 追加失败: " + ex4.Message);
		}
	}

