public static class PerkGrowthHelper
{
	private static bool _appliedThisRun;

	public static void OnDayStart()
	{
		try
		{
			Core.LogMsg("[特性成长] OnDayStart触发");
			int entryValue = MelonPreferences.GetEntryValue<int>("WagesPerks", "PerkGrowthTotalDays");
			entryValue++;
			MelonPreferences.SetEntryValue<int>("WagesPerks", "PerkGrowthTotalDays", entryValue);
			Core.LogMsg("[特性成长] total=" + entryValue);
			int num = entryValue / 50;
			int entryValue2 = MelonPreferences.GetEntryValue<int>("WagesPerks", "PerkGrowthApplied");
			int num2 = 0;
			try
			{
				dynamic instance = PlayerStore.Instance;
				num2 = instance.playerCash;
			}
			catch
			{
			}
			Core.LogMsg("[特性成长] cash=" + num2 + " bonusDay=" + num + " applied=" + entryValue2);
			bool flag = false;
			try
			{
				flag = StartingPerk.IsPerkActive("精神错乱");
				Core.LogMsg("[特性成长] IsPerkActive直接=" + flag);
			}
			catch (Exception ex)
			{
				Core.LogMsg("[特性成长] IsPerkActive异常: " + ex.Message);
			}
			try
			{
				flag = flag || MadnessPerk.IsActive();
			}
			catch
			{
			}
			Core.LogMsg("[特性成长] madnessActive=" + flag);
			if ((num2 > 0 && num > entryValue2) & flag)
			{
				MelonPreferences.SetEntryValue<int>("WagesPerks", "PerkGrowthApplied", num);
				Core.LogMsg("[特性成长] 攒满50天, applied=" + num + " total=" + entryValue);
				MelonLogger.Msg("[Wage's Perks] \ud83c\udf89 特性成长里程碑：已累计50天，下次新开局自动 +" + num + "点 +" + num + "槽！");
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[特性成长] OnDayStart异常: " + ex2.Message);
		}
	}

	public static void ApplyOnPerkUiOpen(dynamic ui)
	{
		if (_appliedThisRun)
		{
			return;
		}
		try
		{
			int entryValue = MelonPreferences.GetEntryValue<int>("WagesPerks", "PerkGrowthApplied");
			Core.LogMsg("[特性成长] Apply被调 bonusDay=" + entryValue);
			if (entryValue > 0)
			{
				ui.maxPerkPoint += entryValue;
				ui.maxPerkCount += entryValue;
				Core.LogMsg("[特性成长] 开局应用 +" + entryValue + "点 +" + entryValue + "槽");
			}
			try
			{
				if (MelonPreferences.GetEntryValue<bool>("WagesPerks", "HardMode"))
				{
					ui.maxPerkPoint += 1;
					ui.maxPerkCount += 1;
					Core.LogMsg("[特性成长] HardMode额外+1点+1槽");
				}
			}
			catch
			{
			}
			try
			{
				int num = 0;
				int num2 = 0;
				CustomStartingPerk[] all = CustomStartingPerks.All;
				foreach (CustomStartingPerk customStartingPerk in all)
				{
					if (StartingPerk.IsPerkActive(customStartingPerk.Id))
					{
						if (customStartingPerk.Cost < 0)
						{
							num += -customStartingPerk.Cost;
						}
						else if (customStartingPerk.Cost > 0)
						{
							num2 += customStartingPerk.Cost;
						}
					}
				}
				if (num > num2)
				{
					ui.maxPerkPoint += 1;
					ui.maxPerkCount += 1;
					Core.LogMsg("[特性成长] 负面>正面额外+1点+1槽 neg=" + num + " pos=" + num2);
				}
			}
			catch
			{
			}
			_appliedThisRun = true;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[特性成长] Apply异常: " + ex.Message);
		}
	}
}
