	internal static void Initialize()
	{
		Core.LogMsg("[特性图标] 图标加载器初始化完成（嵌入资源模式）");
	}

	internal static Sprite LoadEmbeddedPng(string resourceSuffix)
	{
		//IL_025e: Unknown result type (might be due to invalid IL or missing references)
		//IL_026d: Unknown result type (might be due to invalid IL or missing references)
		//IL_007a: Unknown result type (might be due to invalid IL or missing references)
		//IL_007f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0086: Unknown result type (might be due to invalid IL or missing references)
		//IL_008d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0097: Expected Obj, but got Unknown
		Assembly assembly = typeof(Core).Assembly;
		string text = null;
		string[] manifestResourceNames = assembly.GetManifestResourceNames();
		foreach (string text2 in manifestResourceNames)
		{
			if (text2.EndsWith(resourceSuffix, StringComparison.OrdinalIgnoreCase))
			{
				text = text2;
				break;
			}
		}
		if (text == null)
		{
			return null;
		}
		using Stream stream = assembly.GetManifestResourceStream(text);
		if (stream == null)
		{
			return null;
		}
		byte[] array = new byte[stream.Length];
		stream.Read(array, 0, array.Length);
		Texture2D val = new Texture2D(2, 2, (TextureFormat)4, false, false)
		{
			filterMode = (FilterMode)0,
			wrapMode = (TextureWrapMode)1,
			hideFlags = (HideFlags)61
		};
		bool flag = false;
		try
		{
			Type type = null;
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly2 in assemblies)
			{
				Type[] types;
				try
				{
					types = assembly2.GetTypes();
				}
				catch (ReflectionTypeLoadException ex)
				{
					types = ex.Types;
				}
				Type[] array2 = types;
				foreach (Type type2 in array2)
				{
					if (type2 != null && type2.Name == "ImageConversion")
					{
						type = type2;
						break;
					}
				}
				if (type != null)
				{
					break;
				}
			}
			if (type != null)
			{
				MethodInfo method = type.GetMethod("LoadImage", BindingFlags.Static | BindingFlags.Public, null, new Type[2]
				{
					typeof(Texture2D),
					typeof(Il2CppStructArray<byte>)
				}, null);
				if (method == null)
				{
					MethodInfo[] methods = type.GetMethods(BindingFlags.Static | BindingFlags.Public);
					foreach (MethodInfo methodInfo in methods)
					{
						if (methodInfo.Name == "LoadImage")
						{
							string.Join(", ", from p in methodInfo.GetParameters()
								select p.ParameterType.Name);
						}
					}
				}
				if (method != null)
				{
					flag = (bool)method.Invoke(null, new object[2]
					{
						val,
						Il2CppStructArray<byte>.op_Implicit(array)
					});
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[特性图标] ImageConversion.LoadImage调用失败: " + ex2.Message);
		}
		if (!flag)
		{
			Object.Destroy((Object)(object)val);
			Core.LogMsg("[特性图标] 加载失败: " + resourceSuffix);
			return null;
		}
		Sprite val2 = Sprite.Create(val, new Rect(0f, 0f, (float)((Texture)val).width, (float)((Texture)val).height), new Vector2(0.5f, 0.5f), 100f);
		((Object)val2).hideFlags = (HideFlags)61;
		return val2;
	}

	internal static Sprite GetPerkIcon(string perkId)
	{
		if (string.IsNullOrEmpty(perkId))
		{
			return null;
		}
		string key = perkId.Replace("\0", "").Trim();
		if (_iconCache.TryGetValue(key, out var value))
		{
			return value;
		}
		if (!PerkIconMap.ContainsKey(key))
		{
			return null;
		}
		Sprite val = LoadEmbeddedPng(PerkIconMap[key]);
		if ((Object)(object)val != (Object)null)
		{
			_iconCache[key] = val;
		}
		return val;
	}

	internal static bool HasCustomIcon(string perkId)
	{
		if (string.IsNullOrEmpty(perkId))
		{
			return false;
		}
		string key = perkId.Replace("\0", "").Trim();
		return PerkIconMap.ContainsKey(key);
	}
}
