	{
		return MerchantHelper.GenerateCardLockPairs();
	}

	public static bool PrefixAddDirectSellingItemToTable(GameItem gameItem)
	{
		try
		{
			if (!IsActive())
			{
				return true;
			}
			if (gameItem == null)
			{
				return true;
			}
			string identifier = gameItem.identifier;
			if (string.IsNullOrEmpty(identifier))
			{
				return true;
			}
			if (identifier.StartsWith("printer_chip_") || identifier == "printer_module_metal")
			{
				return false;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RetiredGunsmithPerk] 异常: " + ex.Message);
		}
		return true;
	}

	internal static void AddSpecialSellItems()
	{
		try
		{
			if (PlayerStore.Instance == null)
			{
				Core.LogMsg("[枪匠] PlayerStore.Instance为null，无法添加售卖");
				return;
			}
			string[] array = new string[11]
			{
				"handmade_pistol", "heavy_handmade_pistol", "smg", "shotgun", "revolver", "small_pistol_ammo", "small_pistol_ammo_p", "small_pistol_ammo_nl", "heavy_pistol_ammo", "heavy_pistol_ammo_p",
				"heavy_pistol_ammo_nl"
			};
			int num = 0;
			string[] array2 = array;
			foreach (string text in array2)
			{
				try
				{
					GameItem val = DirectoryMaster.Item(text, true);
					if (val == null)
					{
						Core.LogMsg("[枪匠] 加 " + text + " 不存在(null)");
						continue;
					}
					if (string.IsNullOrEmpty(val.name))
					{
						string fallbackName = GetFallbackName(text);
						if (fallbackName != null)
						{
							try
							{
								GeneralHelper.SetCustomName(val, fallbackName);
							}
							catch
							{
							}
						}
					}
					if (MerchantHelper.AddItemToCounter(val, 100) != null)
					{
						num++;
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[枪匠] 加 " + text + " 失败: " + ex.Message);
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[枪匠] AddSpecialSellItems 失败: " + ex2.Message + "\n" + ex2.StackTrace);
		}
	}

