	public static bool TrySellBlood()
	{
		try
		{
			if (!IsActive())
			{
				return false;
			}
			if (Patches.CurrentUITradeMode != 0)
			{
				return false;
			}
			if (IsBloodWeak() || IsForcedRest())
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("身体虚弱/恢复期，无法抽血", "Too weak - cannot draw blood"), "red");
				}
				catch
				{
				}
				return false;
			}
			if (GetBlood() < 500)
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("血量不足 500cc，无法抽血", "Not enough blood (need 500cc)"), "red");
				}
				catch
				{
				}
				return false;
			}
			AddBlood(-500);
			if (IsBloodWeak())
			{
				WageSaveStore.SetInt("RobinCrusoe", "blood_rest", 3);
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("你因为失血过多昏迷了三天", "You passed out from blood loss - 3-day coma"), "red");
				}
				catch
				{
				}
				try
				{
					PlayerStore instance = PlayerStore.Instance;
					if (instance != null)
					{
						instance.AddNightLog(LangHelper.T("[鲁滨逊] 你因为失血过多昏迷了三天", "[Robinson] Passed out from blood loss - 3-day coma"), "#7FC97F");
					}
				}
				catch
				{
				}
				Core.AddNightReportLine(LangHelper.T("[鲁滨逊] 你因为失血过多昏迷了三天", "[Robinson] Passed out from blood loss - 3-day coma"));
				ForceComaSkip();
				try
				{
					RefreshStatusPanel();
				}
				catch
				{
				}
			}
			bool flag = false;
			try
			{
				GameItem val = DirectoryMaster.Item("blood_bag", true);
				if (val != null)
				{
					try
					{
						val.SetValue(200L);
					}
					catch
					{
					}
					EmporiumEntry instance2 = EmporiumEntry.Instance;
					if ((Object)(object)instance2 != (Object)null && instance2.backInvinvElement != null)
					{
						SlotMarker val2 = instance2.backInvinvElement.TryFindOneValidInventorySlot(val, false);
						if (val2 != null)
						{
							try
							{
								val2.TryAcceptOnce(-1);
								flag = true;
							}
							catch
							{
							}
						}
						if (!flag)
						{
							try
							{
								List<GameItem> val3 = new List<GameItem>();
								val3.Add(val);
								((GameInventory)instance2.backInvinvElement).UncheckedAcceptAll(val3);
								flag = true;
							}
							catch
							{
							}
						}
					}
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[RobinCrusoePerk.Blood] 异常: " + ex.Message);
			}
			if (!flag)
			{
				Core.LogMsg("[卖血] blood_bag 不存在或发放失败");
			}
			try
			{
				HealthData.ReceiveMinorWound();
			}
			catch
			{
			}
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T("抽血 500cc → 血袋（价值 200，血量 " + GetBlood() + "/6000）", "Drew 500cc -> blood bag (worth 200, blood " + GetBlood() + "/6000)"), "green");
			}
			catch
			{
			}
			RefreshStatusPanel();
			return true;
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[RobinCrusoePerk.Blood] 异常: " + ex2.Message);
		}
		return false;
	}

	internal static int GetBlood()
	{
		try
		{
			if (_memBlood >= 0)
			{
				return _memBlood;
			}
			int num = WageSaveStore.GetInt("RobinCrusoe", "blood", 6000);
			if (!WageSaveStore.LoadComplete)
			{
				return num;
			}
			_memBlood = num;
			return num;
		}
		catch
		{
			return 6000;
		}
	}

	internal static void SetBlood(int v)
	{
		try
		{
			_memBlood = Math.Max(0, Math.Min(6000, v));
		}
		catch
		{
		}
	}

	internal static void ClearMemBlood()
	{
		try
		{
			_memBlood = -1;
		}
		catch
		{
		}
	}

	internal static int AddBlood(int delta)
	{
		if (!WageSaveStore.LoadComplete)
		{
			return 6000;
		}
		int num = Math.Max(0, Math.Min(6000, GetBlood() + delta));
		SetBlood(num);
		if (GetBlood() <= 0)
		{
			try
			{
				ExecuteGameOverBy("blood_loss");
			}
			catch
			{
			}
		}
		return num;
	}

	internal static bool IsBloodWeak()
	{
		try
		{
			return GetBlood() < 3000;
		}
		catch
		{
			return false;
		}
	}

	internal static bool IsForcedRest()
	{
		try
		{
			return WageSaveStore.GetInt("RobinCrusoe", "blood_rest") > 0;
		}
		catch
		{
			return false;
		}
	}

	internal static void TickBloodRest()
	{
		try
		{
			int num = WageSaveStore.GetInt("RobinCrusoe", "blood_rest");
			if (num > 0)
			{
				num--;
				WageSaveStore.SetInt("RobinCrusoe", "blood_rest", num);
				if (num == 0)
				{
					bool flag = Core.Rng.Next(2) == 0;
					int num2 = 1200;
					AddBlood(flag ? num2 : (-num2));
					if (GetBlood() < 3000)
					{
						AddBlood(3000 - GetBlood());
					}
					try
					{
						StoreUIManager.Instance.Notify(LangHelper.T("身体恢复期结束：血量 " + GetBlood() + "/6000", "Recovery over: blood " + GetBlood() + "/6000"), (GetBlood() >= 3000) ? "green" : "red");
					}
					catch
					{
					}
				}
				else
				{
					try
					{
						StoreUIManager.Instance.Notify(LangHelper.T("身体虚弱，强制休息（剩余 " + num + " 天）", "Too weak - forced rest (" + num + "d left)"), "red");
					}
					catch
					{
					}
				}
				RefreshStatusPanel();
			}
			else
			{
				if (!IsBloodWeak())
				{
					return;
				}
				WageSaveStore.SetInt("RobinCrusoe", "blood_rest", 3);
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("身体虚弱到极限，强制休息 3 天", "At your limit - forced 3-day rest"), "red");
				}
				catch
				{
				}
				try
				{
					PlayerStore instance = PlayerStore.Instance;
					if (instance != null)
					{
						instance.AddNightLog(LangHelper.T("[鲁滨逊] 血量过低，强制休息 3 天", "[Robinson] Too weak - forced 3-day rest"), "#7FC97F");
					}
				}
				catch
				{
				}
				Core.AddNightReportLine(LangHelper.T("[鲁滨逊] 血量过低，强制休息 3 天", "[Robinson] Too weak - forced 3-day rest"));
				RefreshStatusPanel();
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Blood] 异常: " + ex.Message);
		}
	}

	public static bool PrefixReceiveWound()
	{
		try
		{
			if (!IsActive())
			{
				return true;
			}
			if (IsHomebrewWineBuffActive())
			{
				return false;
			}
			int moodWoundPct = GetMoodWoundPct();
			float num = 0.3f * (1f + (float)moodWoundPct / 100f);
			if (IsBloodWeak())
			{
				num -= 0.3f;
			}
			if (Random.value < num)
			{
				return false;
			}
		}
		catch (Exception ex)
		{
