	private static bool IsInBackpackOrCounter(GameItem item)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || item == null)
			{
				return false;
			}
			IntPtr pointer = ((Il2CppObjectBase)item).Pointer;
			if (pointer == IntPtr.Zero)
			{
				return false;
			}
			GameInventory[] array = new GameInventory[2]
			{
				(GameInventory)instance.backInvinvElement,
				(GameInventory)instance.frontInvinvElement
			};
			foreach (GameInventory val in array)
			{
				if (val == null || val.childItems == null)
				{
					continue;
				}
				for (int j = 0; j < val.childItems.Count; j++)
				{
					GameItem val2 = val.childItems[j];
					if (val2 != null && ((Il2CppObjectBase)val2).Pointer == pointer)
					{
						return true;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.ContainerUpgrade] 异常: " + ex.Message);
		}
		return false;
	}

	private static bool IsItemOwned(GameItem item)
	{
		if (item == null)
		{
			return false;
		}
		if (!_ownedInited)
		{
			_ownedInited = true;
			try
			{
				Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
				foreach (Assembly assembly in assemblies)
				{
					if (assembly.GetName().Name != "Assembly-CSharp")
					{
						continue;
					}
					Type type = assembly.GetType("GeneralHelper");
					if (type == null)
					{
						Type[] types = assembly.GetTypes();
						foreach (Type type2 in types)
						{
							if (type2.Name == "GeneralHelper")
							{
								type = type2;
								break;
							}
						}
					}
					if (type == null)
					{
						break;
					}
					MethodInfo[] methods = type.GetMethods(BindingFlags.Static | BindingFlags.Public);
					foreach (MethodInfo methodInfo in methods)
					{
						if (methodInfo.Name == "IsItemOwned" && methodInfo.GetParameters().Length == 1)
						{
							_isItemOwned = methodInfo;
							break;
						}
					}
					break;
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[空间站鲁滨逊] IsItemOwned 查找异常 " + ex.Message);
			}
		}
		if (_isItemOwned == null)
		{
			return true;
		}
		try
		{
			return (bool)_isItemOwned.Invoke(null, new object[1] { item });
		}
		catch
		{
			return true;
		}
	}

