					SetSleep(WageSaveStore.GetInt("RobinCrusoe", "saved_sleep", SLEEP_START));
					SetSocial(WageSaveStore.GetInt("RobinCrusoe", "saved_social", SOCIAL_START));
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[RobinCrusoePerk.ContainerUpgrade] 异常: " + ex.Message);
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return;
			}
			List<GameInventory> list = new List<GameInventory>();
			try
			{
				GameInventory backInvinvElement = (GameInventory)(object)instance.backInvinvElement;
				if (backInvinvElement != null)
				{
					list.Add(backInvinvElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory backInvinvElementCounter = (GameInventory)(object)instance.backInvinvElementCounter;
				if (backInvinvElementCounter != null)
				{
					list.Add(backInvinvElementCounter);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory showcaseElement = (GameInventory)(object)instance.showcaseElement;
				if (showcaseElement != null)
				{
					list.Add(showcaseElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory invElement = (GameInventory)(object)instance.invElement;
				if (invElement != null)
				{
					list.Add(invElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory frontInvinvElement = (GameInventory)(object)instance.frontInvinvElement;
				if (frontInvinvElement != null)
				{
					list.Add(frontInvinvElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory hiddenElement = (GameInventory)(object)instance.hiddenElement;
				if (hiddenElement != null)
				{
					list.Add(hiddenElement);
				}
			}
			catch
			{
			}
			HashSet<IntPtr> hashSet = new HashSet<IntPtr>();
			Stack<GameInventory> stack = new Stack<GameInventory>(list);
			while (stack.Count > 0)
			{
				GameInventory val = stack.Pop();
				if (val == null || val.childItems == null)
				{
					continue;
				}
				for (int i = 0; i < val.childItems.Count; i++)
				{
					GameItem val2 = val.childItems[i];
					if (val2 == null || !hashSet.Add(((Il2CppObjectBase)val2).Pointer))
					{
						continue;
					}
					try
					{
						PixelWindow contentWindow = val2.contentWindow;
						if (contentWindow != null && contentWindow.childElement != null)
						{
							GameGridInventory val3 = ((Il2CppObjectBase)contentWindow.childElement).TryCast<GameGridInventory>();
							if (val3 != null && !list.Contains((GameInventory)(object)val3))
							{
								list.Add((GameInventory)(object)val3);
								stack.Push((GameInventory)(object)val3);
							}
						}
					}
					catch (Exception ex2)
					{
						Core.LogMsg("[RobinCrusoePerk.ContainerUpgrade] 异常: " + ex2.Message);
					}
				}
			}
			int num = 0;
			foreach (GameInventory item in list)
			{
				if (item == null || item.childItems == null)
				{
					continue;
				}
				Enumerator<GameItem> enumerator2 = item.childItems.GetEnumerator();
				while (enumerator2.MoveNext())
				{
					GameItem current2 = enumerator2.Current;
					if (current2 == null)
					{
						continue;
					}
					try
					{
						int hiddenStageByIndex = ContainerUpgradeV2.GetHiddenStageByIndex(ContainerUpgradeV2.FindBoxInHidden(current2));
						if (hiddenStageByIndex > 0)
						{
							ContainerUpgradeV2.RestoreWageBoxToStage(current2, hiddenStageByIndex);
							_rcRestoredContainers.Add(((Il2CppObjectBase)current2).Pointer);
							num++;
						}
						else if (ContainerUpgradeV2.IsWageBox(current2))
						{
							try
							{
								if (!current2.IsTag("CUSTOM_STORAGE_TAG"))
								{
									current2.EnableTag("CUSTOM_STORAGE_TAG", false);
								}
							}
							catch
							{
							}
							ContainerUpgradeV2.RestoreWageBoxShape(current2);
							_rcRestoredContainers.Add(((Il2CppObjectBase)current2).Pointer);
							num++;
						}
						else if (current2.IsTag("CONTAINER_TAG") && !current2.IsTag("VOID_BEAD_TAG") && !ContainerUpgradeV2.IsVoidBeadStorage(current2) && !ContainerUpgradeV2.IsExcludedContainer(current2) && ContainerUpgradeV2.RestoreCrusoeShape(current2))
						{
							_rcRestoredContainers.Add(((Il2CppObjectBase)current2).Pointer);
							num++;
						}
					}
					catch (Exception ex3)
					{
						Core.LogMsg("[RobinCrusoePerk.ContainerUpgrade] 异常: " + ex3.Message);
					}
				}
			}
		}
		catch (Exception ex4)
		{
			Core.LogMsg("[空间站鲁滨逊] 读档恢复容器异常: " + ex4.Message);
		}
	}

