	private static void ShrinkContainerItems(GameInventory inv)
	{
		try
		{
			if (inv == null || inv.childItems == null)
			{
				return;
			}
			List<GameItem> list = new List<GameItem>();
			Enumerator<GameItem> enumerator = inv.childItems.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current != null)
				{
					list.Add(current);
				}
			}
			foreach (GameItem item in list)
			{
				try
				{
					if (!item.IsTag("VOID_BEAD_TAG") && !ContainerUpgradeV2.IsWageBox(item) && !ContainerUpgradeV2.IsVoidBeadStorage(item) && !ContainerUpgradeV2.IsExcludedContainer(item) && (item.IsTag("CONTAINER_TAG") || IsMachine(item)) && !ContainerUpgradeV2.HasTag(item, "wb_stage"))
					{
						GameGridInventory containerGrid = GetContainerGrid(item);
						if (containerGrid != null)
						{
							ShrinkInv(containerGrid, GetId(item) + "(储存区/机器箱)", item);
						}
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[RobinCrusoePerk.ContainerUpgrade] 异常: " + ex.Message);
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[RobinCrusoePerk.ContainerUpgrade] 异常: " + ex2.Message);
		}
	}

	private static void ShrinkInv(GameGridInventory inv, string label, GameItem item = null)
	{
		if (inv == null)
		{
			return;
		}
		try
		{
			GridShape inventoryShape = inv.inventoryShape;
			if (inventoryShape == null)
			{
				return;
			}
			int width = inventoryShape.width;
			int height = inventoryShape.height;
			if (width <= 0 || height <= 0)
			{
				Core.LogMsg("[空间站鲁滨逊] " + label + " 宽高异常(" + width + "x" + height + ")，跳过减半");
				return;
			}
			int num = 0;
			try
			{
				num = ((((GameInventory)inv).childItems != null) ? ((GameInventory)inv).childItems.Count : 0);
			}
			catch
			{
			}
			int num2 = Math.Max(4, width / 2);
			int num3 = num2 * height;
			if (num + 5 > num3)
			{
				num2 = Math.Max(4, (int)Math.Ceiling((double)(num + 5) / (double)height));
			}
			if (item != null)
			{
				ContainerUpgradeV2.SetTagIntValue(item, "wb_stage", 0);
				ContainerUpgradeV2.SetTagIntValue(item, "wb_orig_w", width);
			}
			inv.SetShape(new string('0', num2 * height), num2);
			try
			{
				((GameInventory)inv).Validate();
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] " + label + " 减半异常: " + ex.Message);
		}
	}

