	private static bool IsMoreUpdateLoaded()
	{
		try
		{
			if (!_moreUpdateLoaded.HasValue)
			{
				bool value = false;
				Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
				if (assemblies != null)
				{
					Assembly[] array = assemblies;
					foreach (Assembly assembly in array)
					{
						if (!(assembly == null))
						{
							string text = "";
							try
							{
								text = assembly.GetName().Name ?? "";
							}
							catch
							{
							}
							if (text == "MoreDeviceUpgrades")
							{
								value = true;
								break;
							}
						}
					}
				}
				_moreUpdateLoaded = value;
			}
			return _moreUpdateLoaded.Value;
		}
		catch
		{
			return false;
		}
	}

	private static bool IsMoreUpdateOwnedMachine(GameItem target)
	{
		try
		{
			if (!IsMoreUpdateLoaded() || target == null)
			{
				return false;
			}
			string text = (target.identifier ?? "").ToLowerInvariant();
			if (!MOREUPDATE_METAL_INGOT_MACHINES.Contains(text))
			{
				return false;
			}
			if (text == "furnace" && GetTagIntSafe(target, "MOD_FURNACE_INGOT_UPGRADES") >= 10)
			{
				return false;
			}
			if (text == "water_purifier" && GetTagIntSafe(target, "MOD_PURIFIER_INGOT_UPGRADES") >= 10)
			{
				return false;
			}
			if (text == "wine_rack" && GetTagIntSafe(target, "MOD_WINERACK_WINE_WIDTH") >= 6)
			{
				return false;
			}
			return true;
		}
		catch
		{
			return false;
		}
	}

