	internal static bool IsMachine(GameItem item)
	{
		try
		{
			if (item == null)
			{
				return false;
			}
			if (item.IsTag("STANDARD_MACHINE_TAG"))
			{
				return true;
			}
			string item2 = (item.identifier ?? "").ToLowerInvariant();
			return ALL_MACHINE_IDS.Contains(item2);
		}
		catch
		{
			return false;
		}
	}

	private static bool TryUpgradeMachine(GameItem ingot, GameItem target)
	{
		try
		{
			if (IsMoreUpdateOwnedMachine(target))
			{
				return false;
			}
			if (IsBottlePrinter(target))
			{
				AddTagInt(target, "TOTAL_PERCENTAGE_QUALITY_BONUS_INT", 2);
				ConsumeOne(ingot);
				return true;
			}
			if (IsMachine(target) && target.IsTag("STANDARD_MACHINE_TAG"))
			{
				AddTagInt(target, "wageUpgradePct", 1);
				AddTagInt(target, "wageUpgradeEff", 1);
			}
			else
			{
				AddTagInt(target, "TOTAL_PERCENTAGE_PERFORMANCE_BONUS_INT", 2);
				AddTagInt(target, "TOTAL_PERCENTAGE_QUALITY_BONUS_INT", 2);
			}
			ConsumeOne(ingot);
			return true;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] 机器升级异常: " + ex.Message);
			return false;
		}
	}

	private static bool TryUpgradeContainer(GameItem junk, GameItem container)
	{
		try
		{
			if (ContainerUpgradeV2.ConsumedThisFrame(((Il2CppObjectBase)container).Pointer))
			{
				return true;
			}
			GameGridInventory containerGrid = GetContainerGrid(container);
			if (containerGrid == null)
			{
				Core.LogMsg("[空间站鲁滨逊] 容器升级失败：取不到内部库存 " + GetId(container));
				return false;
			}
			int w = 0;
			int h = 0;
			GetShapeWH(containerGrid, ref w, ref h);
			if (w <= 0 || h <= 0)
			{
				Core.LogMsg("[空间站鲁滨逊] 容器升级失败：宽高异常 " + w + "x" + h);
				return false;
			}
			int tagIntSafe = ContainerUpgradeV2.GetTagIntSafe(container, "wb_stage");
			if (tagIntSafe >= ContainerUpgradeV2.MAX_STAGE)
			{
				return false;
			}
			ContainerUpgradeV2.ConsumeOne(junk);
			int num = ContainerUpgradeV2.GetTagIntSafe(container, "wb_progress") + 1;
			int num2 = ContainerUpgradeV2.UPGRADE_COSTS[tagIntSafe];
			if (num < num2)
			{
				ContainerUpgradeV2.SetTagIntValue(container, "wb_progress", num);
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("储存区 升级进度 " + num + "/" + num2, "Storage progress " + num + "/" + num2), "white");
				}
				catch
				{
				}
				return true;
			}
			int num3 = h;
			int num4;
			if (ContainerUpgradeV2.IsWageBox(container))
			{
				num4 = ContainerUpgradeV2.WAGE_BOX_W[tagIntSafe + 1];
				num3 = ContainerUpgradeV2.WAGE_BOX_H[tagIntSafe + 1];
			}
			else
			{
				int tagIntSafe2 = ContainerUpgradeV2.GetTagIntSafe(container, "wb_orig_w");
				num4 = ((tagIntSafe2 <= 0) ? (w + 1) : ContainerUpgradeV2.GetCrusoeTargetWidth(tagIntSafe2, tagIntSafe + 1));
			}
			ContainerUpgradeV2.AddTagInt(container, "wb_stage", 1);
			ContainerUpgradeV2.SetTagIntValue(container, "wb_progress", 0);
			try
			{
				WageSaveStore.SetInt("RobinCrusoe", "wage_stage_u" + container.uniqueId, tagIntSafe + 1);
			}
			catch
			{
			}
			try
			{
				if (ContainerUpgradeV2.IsUpgradeableContainer(container))
				{
					container.EnableTag("CONTAINER_TOOLTIP_TAG", false);
				}
			}
			catch
			{
			}
			try
			{
				containerGrid.SetShape(new string('0', num4 * num3), num4);
			}
			catch
			{
				try
				{
					containerGrid.SetShape("", num4);
				}
				catch
				{
				}
			}
			try
			{
				((GameInventory)containerGrid).Validate();
			}
			catch
			{
			}
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T((tagIntSafe + 1 >= ContainerUpgradeV2.MAX_STAGE) ? ("储存区满级！容量翻倍（宽 " + num4 + "）") : ("储存区升级！段位 " + (tagIntSafe + 1) + "/" + ContainerUpgradeV2.MAX_STAGE + "（宽 " + num4 + "）"), (tagIntSafe + 1 >= ContainerUpgradeV2.MAX_STAGE) ? ("Storage MAX! 2x capacity (width " + num4 + ")") : ("Storage upgraded! Stage " + (tagIntSafe + 1) + "/" + ContainerUpgradeV2.MAX_STAGE + " (width " + num4 + ")")), "white");
			}
			catch
			{
			}
			try
			{
				Core.LogMsg("[容器v2] " + GetId(container) + " 升段 stage=" + (tagIntSafe + 1) + " w=" + w + "->" + num4 + (ContainerUpgradeV2.IsWageBox(container) ? " (妙妙箱)" : ""));
			}
			catch
			{
			}
			return true;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] 容器升级异常: " + ex.Message);
			return false;
		}
	}

