	private static void ConsumeOne(GameItem item)
	{
		try
		{
			int num = item.unitCount - 1;
			if (num <= 0)
			{
				item.Destroy();
			}
			else
			{
				item.SetUnitCount(num);
			}
		}
		catch
		{
