	private static void RescueWater()
	{
		try
		{
			if (WageSaveStore.GetInt("RobinCrusoe", "robinson_hard") == 1)
			{
				return;
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance != (Object)null && instance.backInvinvElement != null)
			{
				GameInventory backInvinvElement = (GameInventory)(object)instance.backInvinvElement;
				for (int i = 0; i < 2; i++)
				{
					GameItem val = DirectoryMaster.Item("bottled_water", true);
					if (val == null)
					{
						val = WaterPremadeHelper.AccurateHighQualityWater("bottled_water");
					}
					else
					{
						try
						{
							WaterHelper.AddWater(val, 2, -1, false, 0, 1, true);
						}
						catch
						{
						}
					}
					try
					{
						val.DisableTag("stolen", true);
					}
					catch
					{
					}
					SlotMarker val2 = instance.backInvinvElement.TryFindOneValidInventorySlot(val, false);
					if (val2 != null)
					{
						try
						{
							val2.TryAcceptOnce(-1);
						}
						catch
						{
							goto IL_00a6;
						}
						continue;
					}
					goto IL_00a6;
					IL_00a6:
					try
					{
						List<GameItem> val3 = new List<GameItem>();
						val3.Add(val);
						backInvinvElement.UncheckedAcceptAll(val3);
					}
					catch
					{
					}
				}
			}
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T("好心客户送来了 2 份水，先撑住", "A kind customer sent 2 waters — hang in there"), "green");
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] RescueWater 异常: " + ex.Message);
		}
	}

