	internal static int GetFoodQuality(GameItem item)
	{
		if (item == null)
		{
			return -1;
		}
		try
		{
			if (!item.IsTag("WAGES_FOOD_Q"))
			{
				return -1;
			}
			TagState tagReadonly = item.GetTagReadonly("WAGES_FOOD_Q");
			return (tagReadonly != null) ? tagReadonly.GetInt() : (-1);
		}
		catch
		{
			return -1;
		}
	}

	internal static void SetFoodQuality(GameItem item, int value)
	{
		if (item == null)
		{
			return;
		}
		try
		{
			if (value < 0)
			{
				item.DisableTag("WAGES_FOOD_Q", true);
				return;
			}
			if (!item.IsTag("WAGES_FOOD_Q"))
			{
				item.EnableTag("WAGES_FOOD_Q", true);
			}
			Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState state) =>
			{
				state.SetInt(value);
			}));
			item.ModifyTag("WAGES_FOOD_Q", val, false);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Attributes] 异常: " + ex.Message);
		}
	}

	internal static int GetCalorie(GameItem item)
	{
		if (item == null)
		{
			return 0;
		}
		try
		{
			if (item.IsTag("CALORIE_VALUE_TAG"))
			{
				TagState tagReadonly = item.GetTagReadonly("CALORIE_VALUE_TAG");
				if (tagReadonly != null)
				{
					return Math.Max(0, tagReadonly.GetInt());
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Attributes] 异常: " + ex.Message);
		}
		try
		{
			if (item.IsTag("CALORIE"))
			{
				TagState tagReadonly2 = item.GetTagReadonly("CALORIE");
				if (tagReadonly2 != null)
				{
					return Math.Max(0, tagReadonly2.GetInt());
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Attributes] 异常: " + ex2.Message);
		}
		return 300;
	}

	internal static bool IsEaten(GameItem item)
	{
		if (item == null || !IsFood(item))
		{
			return false;
		}
		try
		{
			if (!item.IsTag("WAGES_CAL_LEFT"))
			{
				return false;
			}
			return GetCalLeft(item) < GetCalorie(item);
		}
		catch
		{
			return false;
		}
	}

	internal static int GetCalLeft(GameItem item)
	{
		if (item == null)
		{
			return 0;
		}
		try
		{
			if (item.IsTag("WAGES_CAL_LEFT"))
			{
				TagState tagReadonly = item.GetTagReadonly("WAGES_CAL_LEFT");
				if (tagReadonly != null)
				{
					return Math.Max(0, tagReadonly.GetInt());
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Attributes] 异常: " + ex.Message);
		}
		return GetCalorie(item);
	}

	internal static void SetCalLeft(GameItem item, int value)
	{
		if (item == null)
		{
			return;
		}
		try
		{
			if (value <= 0)
			{
				item.DisableTag("WAGES_CAL_LEFT", true);
				return;
			}
			if (!item.IsTag("WAGES_CAL_LEFT"))
			{
				item.EnableTag("WAGES_CAL_LEFT", true);
			}
			Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState state) =>
			{
				state.SetInt(value);
			}));
			item.ModifyTag("WAGES_CAL_LEFT", val, false);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Attributes] 异常: " + ex.Message);
		}
	}

	internal static int GetEffectiveCal(GameItem item)
	{
		int foodQuality = GetFoodQuality(item);
		int calLeft = GetCalLeft(item);
		if (foodQuality >= 3)
		{
			return (int)((double)calLeft * 0.2);
		}
		if (foodQuality == 2)
		{
			return (int)((double)calLeft * 0.5);
		}
		return calLeft;
	}

	internal static int GetWaterMl(GameItem item)
	{
		if (item == null)
		{
			return 0;
		}
		try
		{
			if (item.IsTag("LIQUID_CONTAINER_CURRENT"))
			{
				TagState tagReadonly = item.GetTagReadonly("LIQUID_CONTAINER_CURRENT");
				if (tagReadonly != null)
				{
					try
					{
						return Math.Max(0, (int)tagReadonly.GetFloat());
					}
					catch
					{
						return Math.Max(0, tagReadonly.GetInt());
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Attributes] 异常: " + ex.Message);
		}
		try
		{
			return Math.Max(0, WaterHelper.GetCurrentCapacityML(item));
		}
		catch
		{
		}
		return 1000;
	}

	public static void PostfixDoubleClickAction(GameItem newItem, Vector2 mousePosition)
	{
		try
		{
			if (!IsActive() || newItem == null || Patches.CurrentUITradeMode != 0 || IsInDoctorNightInventory(newItem) || !GeneralHelper.IsItemOwned(newItem))
			{
				return;
			}
			if (IsAlc(newItem))
			{
				DrinkAlcohol(newItem);
				if (!IsEmptyBottle(newItem))
				{
					TryExpel(newItem);
				}
			}
			else if (IsTobacco(newItem))
			{
				BoostMood(10, LangHelper.T("抽烟", "Smoking"));
			}
			else if (IsNarcotic(newItem))
			{
				UseNarcotic(newItem);
			}
			else if (IsLottery(newItem))
			{
				BoostMood(Random.Range(10, 21), LangHelper.T("刮彩票", "Scratch Ticket"));
			}
			else if (IsBeverage(newItem))
			{
				DrinkBeverage(newItem);
			}
			else if (IsFood(newItem))
			{
				if (IsSnack(newItem))
				{
					BoostMood(BuildConfig.SnackMood, LangHelper.T("零食", "Snack"));
					EatBite(newItem);
					TryExpel(newItem);
				}
				else
				{
					EatBite(newItem);
				}
				AddBlood(30);
			}
			else if (IsDrink(newItem))
			{
				DrinkSip(newItem);
				AddBlood(50);
			}
			else if (IsMedicine(newItem))
			{
				TreatWithMedicine(newItem);
			}
			else if (IsDailyNeed(newItem))
			{
				UseDailyNeed(newItem);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] 双击异常: " + ex.Message);
		}
	}

	private static void DrinkAlcohol(GameItem item)
	{
		if (IsEmptyBottle(item))
		{
			return;
		}
		int waterMl = GetWaterMl(item);
		int num = Math.Min(SIP_ML, waterMl);
		bool flag = IsHomebrewWine(item);
		int amount = BuildConfig.AlcoholMood;
		if (flag)
		{
			int itemBaseValue = GetItemBaseValue(item);
			if (itemBaseValue >= 300)
			{
				amount = 30;
			}
			else if (itemBaseValue >= 150)
			{
				amount = 20;
			}
			else
			{
				amount = ((itemBaseValue >= 50) ? 15 : 10);
			}
			if (itemBaseValue >= 1000)
			{
				SetSleep(Math.Min(100, GetSleep() + 25));
				WageSaveStore.SetInt("RobinCrusoe", "hbuffDay", DeterministicSchedule.CurrentDay);
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("顶级自酿：连续3天不受伤、拾荒次数+1", "Top Homebrew: 3d no wound, scav+1"), "green");
				}
				catch
				{
				}
			}
		}
		BoostMood(amount, flag ? LangHelper.T("自酿酒", "Homebrew") : LangHelper.T("喝酒", "Drinking"));
		if (waterMl > 0)
		{
			try
			{
				WaterHelper.Remove(item, num * 1000);
			}
			catch (Exception ex)
			{
				Core.LogMsg("[空间站鲁滨逊] 喝酒Remove异常 " + ex.Message);
			}
		}
		TryExpel(item);
		RefreshStatusPanel();
	}

	private static bool IsHomebrewWineBuffActive()
	{
		try
		{
			if (!IsActive())
			{
				return false;
			}
			int num = WageSaveStore.GetInt("RobinCrusoe", "hbuffDay", -1);
			if (num < 0)
			{
				return false;
			}
			return DeterministicSchedule.CurrentDay - num <= 2;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Consume] 异常: " + ex.Message);
		}
		return false;
	}

	private static bool IsHomebrewWine(GameItem item)
	{
		try
		{
			ItemFeature val = item.FindItemFeatureByCategory("CATEGORY_WINE_QUALITY");
			if (val == null)
			{
				return false;
			}
			if (val.realCondition != null && val.realCondition.identifier == "wine_quality_homebrew")
			{
				return true;
			}
			if (val.fakeCondition != null && val.fakeCondition.identifier == "wine_quality_homebrew")
			{
				return true;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Consume] 异常: " + ex.Message);
		}
		return false;
	}

	private static void EatBite(GameItem item)
	{
		int calLeft = GetCalLeft(item);
		if (calLeft <= 0)
		{
			TryExpel(item);
			return;
		}
		int foodQuality = GetFoodQuality(item);
		if (GetSatiety() >= 100)
		{
			return;
		}
		int val = (100 - GetSatiety()) * 22;
		int val2 = Math.Min(calLeft, val);
		val2 = Math.Max(val2, 50);
		int num = calLeft - val2;
		int num2;
		if (foodQuality >= 3)
		{
			num2 = (int)((double)val2 * 0.2);
		}
		else
		{
			num2 = ((foodQuality == 2) ? ((int)((double)val2 * 0.5)) : val2);
		}
		num2 = (int)((double)num2 * GetEatEffMult());
		int num3 = Math.Max(1, (int)Math.Round((float)num2 / 22f));
		SetSatiety(Math.Min(100, GetSatiety() + num3));
		if (foodQuality >= 2)
		{
			SetHealth(Math.Max(0, GetHealth() - 10));
			TryInfect((foodQuality == 3) ? 0.4 : 0.1);
		}
		try
		{
			StoreUIManager.Instance.Notify(LangHelper.T("进食 +" + num3 + "% 饱食（" + num2 + " 卡）", "Eating +" + num3 + "% Satiety (" + num2 + " kcal)"), "white");
		}
		catch
		{
		}
		if (num <= 0)
		{
			bool flag = TryExpel(item);
			Core.LogMsg("[空间站鲁滨逊] 吃完了一份食物（饱食+" + num3 + "%），移除" + (flag ? "成功" : "失败（TryExpel 未找到物品位置）"));
		}
		else
		{
			SetCalLeft(item, num);
			try
			{
				item.EnableTag("WAGES_EATEN", true);
			}
			catch
			{
			}
		}
		RefreshStatusPanel();
	}

