	private static void DrinkSip(GameItem item)
	{
		int waterMl = GetWaterMl(item);
		if (waterMl > 0)
		{
			int num = Math.Min(SIP_ML, waterMl);
			int num2 = -1;
			try
			{
				num2 = WaterHelper.GetWaterPurity(item);
			}
			catch
			{
			}
			int num3 = ((num2 < 9900) ? ((num2 >= 9600) ? 1 : ((num2 >= 9200) ? 2 : ((num2 >= 8800) ? 3 : 4))) : 0);
			int num4 = (new int[5] { 25, 18, 12, 6, 2 })[num3];
			int num5 = (new int[5] { 5, 2, 0, -5, -10 })[num3];
			int num6 = (new int[5] { 0, 0, 5, 15, 30 })[num3];
			SetThirstPct(Math.Min(100, GetThirstPct() + num4));
			if (num5 != 0)
			{
				SetHealth(Math.Max(0, Math.Min(100, GetHealth() + num5)));
			}
			if (num6 > 0)
			{
				TryInfect((double)num6 / 100.0);
			}
			string text = (new string[5]
			{
				LangHelper.T("优质", "Pure"),
				LangHelper.T("较好", "Good"),
				LangHelper.T("普通", "Plain"),
				LangHelper.T("浑浊", "Cloudy"),
				LangHelper.T("脏水", "Dirty")
			})[num3];
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T("饮水 +" + num4 + "% 口渴（" + text + "）", "Drinking +" + num4 + "% Thirst (" + text + ")"), "white");
			}
			catch
			{
			}
			try
			{
				WaterHelper.Remove(item, num * 1000);
			}
			catch (Exception ex)
			{
				Core.LogMsg("[空间站鲁滨逊] Remove异常 " + ex.Message);
			}
			RefreshStatusPanel();
		}
	}

