	private static int GetFoodDecayDay(GameItem item)
	{
		if (item == null)
		{
			return 0;
		}
		try
		{
			if (item.IsTag("WAGES_FOOD_DECAY_DAY"))
			{
				TagState tagReadonly = item.GetTagReadonly("WAGES_FOOD_DECAY_DAY");
				if (tagReadonly != null)
				{
					return tagReadonly.GetInt();
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Decay] 异常: " + ex.Message);
		}
		return StoreStation.GetDayCounter();
	}

	private static void SetFoodDecayDay(GameItem item, int day)
	{
		if (item == null)
		{
			return;
		}
		try
		{
			if (!item.IsTag("WAGES_FOOD_DECAY_DAY"))
			{
				item.EnableTag("WAGES_FOOD_DECAY_DAY", true);
			}
			Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState state) =>
			{
				state.SetInt(day);
			}));
			item.ModifyTag("WAGES_FOOD_DECAY_DAY", val, false);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Decay] 异常: " + ex.Message);
		}
	}

	private static int DecayFoodsAndCount(out int fresh, out int stale, out int rotten)
	{
		fresh = 0;
		stale = 0;
		rotten = 0;
		try
		{
			int dayCounter = StoreStation.GetDayCounter();
			foreach (GameItem item in CollectAllItems())
			{
				if (item == null || !IsFood(item))
				{
					continue;
				}
				int num = GetFoodQuality(item);
				if (num < 0)
				{
					num = 0;
				}
				int foodDecayDay = GetFoodDecayDay(item);
				if (dayCounter - foodDecayDay >= 2 && num < 3)
				{
					num++;
					SetFoodQuality(item, num);
					SetFoodDecayDay(item, dayCounter);
				}
				if (num <= 0)
				{
					fresh++;
					continue;
				}
				switch (num)
				{
				case 1:
					stale++;
					fresh++;
					break;
				case 2:
					stale++;
					break;
				default:
					rotten++;
					break;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Decay] 异常: " + ex.Message);
		}
		return fresh + stale;
	}

	private static void TryInfect(double chance)
