	internal static void TryDoctorSupply()
	{
		try
		{
			int currentDay = DeterministicSchedule.CurrentDay;
			if (currentDay == _doctorSupplyDay)
			{
				return;
			}
			_doctorSupplyDay = currentDay;
			if (currentDay >= 30)
			{
				string[] array = new string[3] { "system_module_overclock", "system_module_ruined", "system_module_corrupt" };
				int num = Core.Rng.Next(BuildConfig.DoctorSupplyCountMin, BuildConfig.DoctorSupplyCountMax + 1);
				int num2 = 0;
				for (int i = 0; i < num; i++)
				{
					try
					{
						GameItem val = DirectoryMaster.Item(array[Core.Rng.Next(array.Length)], true);
						if (val != null)
						{
							long num3 = 0L;
							try
							{
								num3 = val.GetValue((List<GameCharacterItem>)null, (GameCharacterItem)null, false);
							}
							catch
							{
							}
							int heat = (int)(num3 * BuildConfig.DoctorSupplyPricePct / 100);
							MerchantHelper.AddItemToCounter(val, heat);
							num2++;
						}
					}
					catch (Exception ex)
					{
						Core.LogMsg("[RobinCrusoePerk.Food.Supply] 异常: " + ex.Message);
					}
				}
				Core.LogMsg("[养蛊机] 博士廉价模组供货 " + num2 + " 件（day " + currentDay + "）");
			}
			if (currentDay >= 10 && !HasGoodOnFront("wage_gu_machine"))
			{
				try
				{
					if (MerchantHelper.AddItemToCounter("wage_gu_machine") != null)
					{
						Core.LogMsg("[养蛊机] 博士夜晚商店卖养蛊机（day " + currentDay + "）");
					}
				}
				catch
				{
				}
			}
			if (currentDay >= 30 && !HasGoodOnFront("wage_ai_generator"))
			{
				try
				{
					if (MerchantHelper.AddItemToCounter("wage_ai_generator") != null)
					{
						Core.LogMsg("[养蛊机] 博士夜晚商店卖生成器（day " + currentDay + "）");
					}
				}
				catch
				{
				}
			}
			if (currentDay < 30 || Core.Rng.Next(100) >= 30)
			{
				return;
			}
			try
			{
				if (MerchantHelper.AddItemToCounter("wage_protector_core") != null)
				{
					Core.LogMsg("[养蛊机] 博士夜晚商店小概率卖保护器（day " + currentDay + "）");
				}
			}
			catch
			{
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[养蛊机] TryDoctorSupply 异常: " + ex2.Message);
		}
	}

	public static bool PrefixAutoSipFromContainer(GameItem item, GameCharacterItem GCI)
	{
		try
		{
			if (!IsActive() || item == null || GCI == null)
			{
				return true;
			}
			int waterMl = GetWaterMl(item);
			if (waterMl <= 0)
			{
				return true;
			}
			int num = -1;
			try
			{
				num = WaterHelper.GetWaterPurity(item);
			}
			catch
			{
			}
			int num2 = ((num < 9900) ? ((num >= 9600) ? 1 : ((num >= 9200) ? 2 : ((num >= 8800) ? 3 : 4))) : 0);
			int num3 = (new int[5] { 5, 2, 0, -5, -10 })[num2];
			int num4 = (new int[5] { 0, 0, 5, 15, 30 })[num2];
			int num5 = (new int[5] { 5, 4, 3, 1, 0 })[num2];
			if (num3 != 0)
			{
				SetHealth(Math.Max(0, Math.Min(100, GetHealth() + num3)));
			}
			if (num5 > 0)
			{
				SetClean(Math.Min(100, GetClean() + num5));
			}
			if (num4 > 0)
			{
				TryInfect((double)num4 / 100.0);
			}
			try
			{
				int num6 = 0;
				int num7 = 0;
				try
				{
					num6 = GCI.currentThirst;
				}
				catch
				{
				}
				try
				{
					num7 = GCI.maxThirst;
				}
				catch
				{
				}
				int val = Math.Max(0, num7 - num6);
				int num8 = Math.Min(waterMl, val);
				if (num8 > 0)
				{
					try
					{
						GCI.currentThirst = num6 + num8;
					}
					catch
					{
					}
					try
					{
						WaterHelper.Remove(item, num8 * 1000);
					}
					catch
					{
					}
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[RobinCrusoePerk.Food.Supply] 异常: " + ex.Message);
			}
			return false;
		}
		catch
		{
			return true;
		}
	}

