	private static List<GameItem> CollectAllItems()
	{
		List<GameItem> list = new List<GameItem>();
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return list;
			}
			Enumerator<GameItem> enumerator = instance.GetAllItems().GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current != null)
				{
					list.Add(current);
				}
			}
			GameGridInventory[] array = new GameGridInventory[2] { instance.backInvinvElement, instance.frontInvinvElement };
			for (int i = 0; i < array.Length; i++)
			{
				GameInventory val = (GameInventory)(object)array[i];
				if (val == null || val.childItems == null)
				{
					continue;
				}
				for (int j = 0; j < val.childItems.Count; j++)
				{
					if (val.childItems[j] != null)
					{
						list.Add(val.childItems[j]);
					}
				}
			}
			foreach (GameItem item in new List<GameItem>(list))
			{
				if (item == null)
				{
					continue;
				}
				try
				{
					PixelWindow contentWindow = item.contentWindow;
					if (contentWindow == null)
					{
						continue;
					}
					GameGridInventory val2 = ((contentWindow.childElement != null) ? ((Il2CppObjectBase)contentWindow.childElement).TryCast<GameGridInventory>() : null);
					if (val2 == null || ((GameInventory)val2).childItems == null)
					{
						continue;
					}
					for (int k = 0; k < ((GameInventory)val2).childItems.Count; k++)
					{
						if (((GameInventory)val2).childItems[k] != null)
						{
							list.Add(((GameInventory)val2).childItems[k]);
						}
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[RobinCrusoePerk.Food.Supply] 异常: " + ex.Message);
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Supply] 异常: " + ex2.Message);
		}
		return list;
	}

