			{
				return;
			}
			bool flag = false;
			try
			{
				flag = item.IsTag("WAGES_CAL_LEFT");
			}
			catch
			{
			}
			if (!flag)
			{
				return;
			}
			int foodCalBackup = 0;
			try
			{
				foodCalBackup = GetCalorie(item);
			}
			catch
			{
			}
			int left = GetCalLeft(item);
			_foodCalBackup = foodCalBackup;
			_foodCalBackupValid = true;
			try
			{
				Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState state) =>
				{
					state.SetInt(left);
				}));
				item.ModifyTag("CALORIE_VALUE_TAG", val, false);
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Food.Tooltip] 异常: " + ex.Message);
		}
	}

	public static void PostfixFoodTooltip(GameItem item)
	{
