	internal static int GetCompBuffDays(string eff)
	{
		return WageSaveStore.GetInt("RobinCrusoe", "cb_" + eff);
	}

	internal static void SetCompBuffDays(string eff, int days)
	{
		WageSaveStore.SetInt("RobinCrusoe", "cb_" + eff, (days > 0) ? days : 0);
		InvalidateTradeCaches();
	}

	internal static void TickCompBuffs()
	{
		string[] cOMP_BUFF_KEYS = COMP_BUFF_KEYS;
		foreach (string eff in cOMP_BUFF_KEYS)
		{
			int compBuffDays = GetCompBuffDays(eff);
			if (compBuffDays > 0)
			{
				SetCompBuffDays(eff, compBuffDays - 1);
			}
		}
	}

	internal static double GetEatEffMult()
	{
		if (GetCompBuffDays("eatEff") <= 0)
		{
			return 1.0;
		}
		return 1.5;
	}

	internal static double GetThirstEffMult()
	{
		if (GetCompBuffDays("thirstEff50") > 0)
		{
			return 0.5;
		}
		if (GetCompBuffDays("thirstEff10") > 0)
		{
			return 0.9;
		}
		return 1.0;
	}

	internal static double GetWearEffMult()
	{
		if (GetCompBuffDays("wearEff") <= 0)
		{
			return 1.0;
		}
		return 0.5;
	}

	internal static double GetDrugEffMult()
	{
		if (GetCompBuffDays("drugEff") <= 0)
		{
			return 1.0;
		}
		return 1.5;
	}

