	private static int FxVal(string fx, string prefix)
	{
		if (string.IsNullOrEmpty(fx) || !fx.StartsWith(prefix))
		{
			return 0;
		}
		if (!int.TryParse(fx.Substring(prefix.Length), out var result))
		{
			return 0;
		}
		return result;
	}

	internal static int FxNum(string prefix)
	{
		int num = 0;
		int[] array = AllActiveNodes();
		foreach (int num2 in array)
		{
			if (num2 >= 0 && num2 < NODES.Length)
			{
				string[] array2 = NODES[num2].Lock;
				foreach (string fx in array2)
				{
					num += FxVal(fx, prefix);
				}
			}
		}
		NodeDef nodeDef = CurrentNode();
		if (nodeDef != null)
		{
			int dominantNode = GetDominantNode();
			if (dominantNode >= 0 && nodeDef.Key == NODES[dominantNode].Key)
			{
				string nodeFx = GetNodeFx();
				if (!string.IsNullOrEmpty(nodeFx))
				{
					num += FxVal(nodeFx, prefix);
				}
			}
		}
		return num;
	}

	internal static bool FxBool(string fx)
	{
		int[] array = AllActiveNodes();
		foreach (int num in array)
		{
			if (num >= 0 && num < NODES.Length && Array.IndexOf(NODES[num].Lock, fx) >= 0)
			{
				return true;
			}
		}
		NodeDef nodeDef = CurrentNode();
		if (nodeDef != null)
		{
			int dominantNode = GetDominantNode();
			if (dominantNode >= 0 && nodeDef.Key == NODES[dominantNode].Key && GetNodeFx() == fx)
			{
				return true;
			}
		}
		return false;
	}

