			SocialNode(),
			MoodNode()
		};
	}

	internal static string GetTradeBuffDisplay()
	{
		try
		{
			if (_tradeBuffCache != null)
			{
				return _tradeBuffCache;
			}
			StringBuilder stringBuilder = new StringBuilder();
			int sellBonusPct = GetSellBonusPct();
			int bargainBonusPct = GetBargainBonusPct();
			int budgetBonusPct = GetBudgetBonusPct();
			string text = LangHelper.T("总：", "Total: ");
			if (sellBonusPct != 0)
			{
				text = text + LangHelper.T("售价", "Sell ") + ((sellBonusPct > 0) ? "+" : "") + sellBonusPct + "% ";
			}
			if (bargainBonusPct != 0)
			{
				text = text + LangHelper.T("议价", "Bargaining ") + ((bargainBonusPct > 0) ? "+" : "") + bargainBonusPct + "% ";
			}
			if (budgetBonusPct != 0)
			{
				text = text + LangHelper.T("预算", "Budget ") + ((budgetBonusPct > 0) ? "+" : "") + budgetBonusPct + "% ";
			}
			if (text.Length > 2)
			{
				stringBuilder.Append(text.Trim());
			}
			_tradeBuffCache = stringBuilder.ToString().Trim();
			return _tradeBuffCache;
		}
		catch
		{
			return "";
		}
	}

	private static bool IsTradeFx(string fx)
	{
		if (!fx.StartsWith("sell") && !fx.StartsWith("bargain"))
		{
			return fx.StartsWith("budget");
		}
		return true;
	}

	private static string FxLabel(string fx)
	{
		if (string.IsNullOrEmpty(fx))
		{
			return "";
		}
		switch (fx)
		{
		case "client-2":
			return LangHelper.T("客流-2", "Customers -2");
		case "client-1":
			return LangHelper.T("客流-1", "Customers -1");
		case "noOutside":
			return LangHelper.T("禁外出", "No Outside");
		case "noScav":
			return LangHelper.T("禁拾荒", "No Scavenging");
		case "flavor":
			return "";
		case "heal+10":
			return LangHelper.T("好心人送药", "Kind customer sends medicine");
		case "moodEnc+5":
			return LangHelper.T("路人鼓励", "Passerby cheers you up");
		default:
			if (fx.StartsWith("sell"))
			{
				return LangHelper.T("售价" + fx.Substring(4) + "%", "Sell " + fx.Substring(4) + "%");
			}
			if (fx.StartsWith("bargain"))
			{
				return LangHelper.T("议价" + fx.Substring(7) + "%", "Bargaining " + fx.Substring(7) + "%");
			}
			if (fx.StartsWith("budget"))
			{
				return LangHelper.T("预算" + fx.Substring(6) + "%", "Budget " + fx.Substring(6) + "%");
			}
			if (fx.StartsWith("scav"))
			{
				return LangHelper.T("拾荒" + fx.Substring(4) + "次", "Scavenging " + fx.Substring(4));
			}
			if (fx.StartsWith("mood"))
			{
				return LangHelper.T("心情" + fx.Substring(4), "Mood " + fx.Substring(4));
			}
			if (fx.StartsWith("satD"))
			{
				return LangHelper.T("饱食衰减" + fx.Substring(4) + "%", "Satiety loss " + fx.Substring(4) + "%");
			}
			if (fx.StartsWith("thD"))
			{
				return LangHelper.T("口渴衰减" + fx.Substring(3) + "%", "Thirst loss " + fx.Substring(3) + "%");
			}
			if (fx.StartsWith("hD"))
			{
				return LangHelper.T("健康衰减" + fx.Substring(2) + "%", "Health loss " + fx.Substring(2) + "%");
			}
			if (fx.StartsWith("hR"))
			{
				return LangHelper.T("健康恢复" + fx.Substring(2) + "%", "Health recovery " + fx.Substring(2) + "%");
			}
			if (fx.StartsWith("cleanD"))
			{
				return LangHelper.T("清洁衰减" + fx.Substring(6) + "%", "Cleanliness loss " + fx.Substring(6) + "%");
			}
			if (fx.StartsWith("cleanR"))
			{
				return LangHelper.T("清洁恢复" + fx.Substring(6) + "%", "Cleanliness recovery " + fx.Substring(6) + "%");
			}
			if (fx.StartsWith("sleepR"))
			{
				return LangHelper.T("睡眠恢复" + fx.Substring(6) + "%", "Sleep recovery " + fx.Substring(6) + "%");
			}
			if (fx.StartsWith("socD"))
			{
				return LangHelper.T("社交衰减" + fx.Substring(4) + "%", "Social loss " + fx.Substring(4) + "%");
			}
			if (fx.StartsWith("socR"))
			{
				return LangHelper.T("社交恢复" + fx.Substring(4) + "%", "Social recovery " + fx.Substring(4) + "%");
			}
			if (fx.StartsWith("wound"))
			{
				return LangHelper.T("受伤" + fx.Substring(5) + "%", "Injury " + fx.Substring(5) + "%");
			}
			if (fx.StartsWith("sick"))
			{
				return LangHelper.T("患病" + fx.Substring(4) + "%", "Illness " + fx.Substring(4) + "%");
			}
			if (fx == "lostItem")
			{
				return LangHelper.T("损失货物", "Lost goods");
			}
			if (fx == "lostWaterItem")
			{
				return LangHelper.T("水器损坏", "Water container damaged");
			}
			if (fx.StartsWith("statusClient"))
			{
				return LangHelper.T("状态客户-" + fx.Substring(13) + "%", "Customers from status -" + fx.Substring(13) + "%");
			}
			if (fx.StartsWith("drop"))
			{
				return LangHelper.T("掉落率" + fx.Substring(4) + "%", "Drop rate " + fx.Substring(4) + "%");
			}
			return fx;
		}
	}

	internal static int GetMoodTier()
	{
		int mood = GetMood();
		if (mood >= 80)
		{
			return 0;
		}
		if (mood >= 60)
		{
			return 1;
		}
		if (mood >= 40)
		{
			return 2;
		}
		return 3;
	}

	internal static int GetSellBonusPct()
	{
		if (_sellBonusCache != -999)
		{
			return _sellBonusCache;
		}
		int num = ((GetGranaryDays() >= GRANARY_DAYS) ? 5 : 0);
		int num2 = Math.Min(ELEV_MAX, GetElevCount());
		int num3 = FxNum("sell");
		int num4 = (int)GetCompBuffSellBonus();
		int num5 = ((GetMood() >= 60) ? 10 : ((GetMood() < 40) ? (-10) : 0));
		return _sellBonusCache = num + num2 + num3 + num4 + num5;
	}

	internal static int GetBudgetBonusPct()
	{
		if (_budgetBonusCache != -999)
		{
			return _budgetBonusCache;
		}
		int num = 0;
		int mood = GetMood();
		if (mood >= 80)
		{
			num = 15;
		}
		else
		{
			num = ((mood < 40) ? (-15) : (-5));
		}
		int val = Math.Min(25, GetElevCount() * 5);
		int num2 = Math.Max(num, val);
		int num3 = FxNum("budget");
		_budgetBonusCache = ((num3 < 0) ? (num2 + num3) : Math.Max(num2, num3));
		return _budgetBonusCache;
	}

