	internal static int GetDominantNode()
	{
		int result = -1;
		int num = 0;
		int[] array = new int[7]
		{
			SatietyNode(),
			ThirstNode(),
			HealthNode(),
			CleanNode(),
			SleepNode(),
			SocialNode(),
			MoodNode()
		};
		foreach (int num2 in array)
		{
			if (num2 >= 0 && num2 < NODES.Length)
			{
				int sev = NODES[num2].Sev;
				if (sev > num)
				{
					num = sev;
					result = num2;
				}
			}
		}
		return result;
	}

	internal static string GetStoredNodeKey()
	{
		return WageSaveStore.GetString("RobinCrusoe", "nodeKey");
	}

	internal static int GetNodeFxIdx()
	{
		return WageSaveStore.GetInt("RobinCrusoe", "nodeFxIdx", -1);
	}

	internal static string GetNodeFx()
	{
		int nodeFxIdx = GetNodeFxIdx();
		NodeDef nodeDef = CurrentNode();
		if (nodeDef == null || nodeFxIdx < 0 || nodeFxIdx >= nodeDef.Pool.Length)
		{
			return "";
		}
		return nodeDef.Pool[nodeFxIdx];
	}

	private static NodeDef CurrentNode()
	{
		string storedNodeKey = GetStoredNodeKey();
		if (string.IsNullOrEmpty(storedNodeKey))
		{
			return null;
		}
		NodeDef[] nODES = NODES;
		foreach (NodeDef nodeDef in nODES)
		{
			if (nodeDef.Key == storedNodeKey)
			{
				return nodeDef;
			}
		}
		return null;
	}

	internal static void RollNodeFx()
	{
		int dominantNode = GetDominantNode();
		string text = ((dominantNode >= 0) ? NODES[dominantNode].Key : "");
		if (text == GetStoredNodeKey())
		{
			return;
		}
		WageSaveStore.SetString("RobinCrusoe", "nodeKey", text);
		if (dominantNode >= 0 && NODES[dominantNode].Pool.Length != 0)
		{
			NodeDef nodeDef = NODES[dominantNode];
			if (!nodeDef.IsPositive)
			{
				RollBurst(nodeDef);
			}
			int value = Random.Range(0, nodeDef.Pool.Length);
			WageSaveStore.SetInt("RobinCrusoe", "nodeFxIdx", value);
		}
		else
		{
			WageSaveStore.SetInt("RobinCrusoe", "nodeFxIdx", -1);
		}
	}

	private static void RollBurst(NodeDef d)
	{
		try
		{
			if (d == null || d.IsPositive)
			{
				return;
			}
			string text = "";
			if (d.BurstPunish != null)
			{
				string[] burstPunish = d.BurstPunish;
				foreach (string text2 in burstPunish)
				{
					switch (text2)
					{
					case "lostItem":
					{
						int num = LostSmallItem(1);
						text += ((num > 0) ? LangHelper.T("损失货物 ", "Lost goods ") : LangHelper.T("（无货可失）", "(nothing to lose)"));
						break;
					}
					case "lostWaterItem":
						LostWaterItem();
						text += LangHelper.T("水器损坏 ", "Water container damaged ");
						break;
					case "income-30":
					case "income-20":
					case "income-10":
					{
						int pct = Math.Abs(int.Parse(text2.Substring(6)));
						int num2 = ApplyIncomePunish(pct);
						text += LangHelper.T("收入-" + pct + "%（-" + num2 + "） ", "Income -" + pct + "% (-" + num2 + ") ");
						break;
					}
					case "health-15":
						SetHealth(Math.Max(0, GetHealth() - 15));
						text += LangHelper.T("健康-15 ", "Health -15 ");
						break;
					case "sat+30":
						SetSatiety(Math.Min(100, GetSatiety() + 30));
						text += LangHelper.T("饱食+30 ", "Satiety +30 ");
						break;
					case "mood-15":
						SetMood(Math.Max(0, GetMood() - 15));
						text += LangHelper.T("心情-15 ", "Mood -15 ");
						break;
					case "clientToday-50":
						_burstClientCut = 50;
						text += LangHelper.T("今日客流-50% ", "Today's customers -50% ");
						break;
					case "healChance50":
						if (Random.value < 0.5f)
						{
							SetHealth(Math.Min(100, GetHealth() + 10));
							text += LangHelper.T("好心人送药+10 ", "Kind customer sends medicine +10 ");
						}
						break;
					case "moodEncChance30":
						if (Random.value < 0.3f)
						{
							SetMood(Math.Min(100, GetMood() + 5));
							text += LangHelper.T("自我消化+5 ", "Self-soothe +5 ");
						}
						break;
					}
				}
			}
			if (!string.IsNullOrEmpty(d.CompBuff) && d.CompBuffDur > 0)
			{
				if (GetCompBuffDays(d.CompBuff) < d.CompBuffDur)
				{
					SetCompBuffDays(d.CompBuff, d.CompBuffDur);
				}
				string compBuffLabel = GetCompBuffLabel(d.CompBuff);
				text = text + ((compBuffLabel.Length > 0) ? compBuffLabel : d.CompBuff) + " " + d.CompBuffDur + LangHelper.T("天 ", "d ");
			}
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T("爆发·", "Burst·") + d.DisplayName + LangHelper.T("：", ": ") + text.Trim(), "red");
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] RollBurst 异常: " + ex.Message);
		}
	}

	internal static bool IsStatusClient(StoreClient client)
	{
		if (client == null)
		{
			return false;
		}
		try
		{
			string text = (client.identifier ?? "").ToLowerInvariant();
			foreach (string sTATUS_CLIENT_ID in STATUS_CLIENT_IDS)
			{
				if (text.Contains(sTATUS_CLIENT_ID))
				{
					return true;
				}
			}
			if (_statusClientSet.Contains(client))
			{
				return true;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Nodes.StatusClients] 异常: " + ex.Message);
		}
		return false;
	}

	internal static string GetStatusClientKind(StoreClient client)
	{
		if (client == null)
		{
			return "";
		}
		try
		{
			string text = (client.identifier ?? "").ToLowerInvariant();
			if (text.Contains("thirsty"))
			{
				return "thirsty";
			}
			if (text.Contains("hungry") || text.Contains("chef"))
			{
				return "hungry";
			}
			if (text.Contains("spacermedical"))
			{
				return "injured";
			}
			if (text.Contains("sick"))
			{
				return "sick";
			}
			if (_statusClientSet.Contains(client))
			{
				return _statusClientKind.GetValueOrDefault(client, "");
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Nodes.StatusClients] 异常: " + ex.Message);
		}
		return "";
	}

	public static void PostfixStatusClientFactory(StoreClient __result, string kind)
	{
		try
		{
			if (__result == null || !IsActive())
			{
				return;
			}
			int num = FxNum("statusClient");
			if (num < 0 && Random.value < (float)(-num) / 100f)
			{
				if (_statusClientSet.Contains(__result))
				{
					_statusClientSet.Remove(__result);
					_statusClientKind.Remove(__result);
				}
			}
			else
			{
				_statusClientSet.Add(__result);
				if (!string.IsNullOrEmpty(kind))
				{
					_statusClientKind[__result] = kind;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Nodes.StatusClients] 异常: " + ex.Message);
		}
	}

	internal static double GetStatusClientMarkup(StoreClient client, GameItem item)
	{
		if (client == null || item == null || !IsStatusClient(client))
		{
			return 1.0;
		}
		string statusClientKind = GetStatusClientKind(client);
		bool flag = IsFood(item);
		bool flag2 = IsDrink(item);
		bool flag3 = IsMedicine(item);
		switch (statusClientKind)
		{
		case "thirsty":
			if (!flag2)
			{
				return 0.85;
			}
			return 1.25;
		case "hungry":
			if (!flag)
			{
				return 0.85;
			}
			return 1.2;
		case "injured":
			if (!flag3)
			{
				return 0.85;
			}
			return 1.3;
		case "sick":
			if (!flag3)
			{
				return 0.85;
			}
			return 1.4;
		default:
			return 1.0;
		}
	}

