	private static void QueueWantedClient(string id)
	{
		try
		{
			_ = id == "wanted7";
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null && instance.storeClientManager != null)
			{
				try
				{
					instance.storeClientManager.RemoveDuplicateClientsByIdentifier(id);
				}
				catch
				{
				}
				if (id == "wanted7")
				{
					_wanted7Queued = true;
				}
				else if (id == "wanted6")
				{
					_wanted6Queued = true;
				}
				instance.QueueFuturClient(id, 0);
				Core.LogMsg("[空间站鲁滨逊] 已预约" + ((id == "wanted7") ? "胡安" : "李北文") + "当天到店（" + id + "）");
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] QueueWantedClient(" + id + ") 异常: " + ex.Message);
		}
	}

