			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] UnlockWantedPhone 异常: " + ex.Message);
		}
	}

	private static BarterOffer BuildJuanOffer(int lv)
	{
		BarterOffer val = BarterOfferList.CreateBarterFoodMultiOffer();
		try
		{
			List<string> ids = new List<string>();
			if (lv <= 0)
			{
				ids.Add("processed_meat");
				ids.Add("processed_meat");
				ids.Add("large_bottled_water");
			}
			else if (lv == 1)
			{
				ids.Add("processed_meat");
				ids.Add("processed_meat");
				ids.Add("processed_cheese");
				ids.Add("processed_cheese");
				ids.Add("galaxy_blend");
				ids.Add("galaxy_blend");
				ids.Add("large_bottled_water");
			}
			else
			{
				ids.Add("processed_meat");
				ids.Add("processed_meat");
				ids.Add("processed_meat");
				ids.Add("processed_cheese");
				ids.Add("processed_cheese");
				ids.Add("processed_cheese");
				ids.Add("galaxy_blend");
				ids.Add("galaxy_blend");
				ids.Add("galaxy_blend");
				ids.Add("soda_red");
				ids.Add("soda_red");
				ids.Add("energy_drink");
				ids.Add("energy_drink");
				ids.Add("large_bottled_water");
				ids.Add("large_bottled_water");
			}
			Action val2 = DelegateSupport.ConvertDelegate<Action>((Delegate)(Action)(() =>
			{
				foreach (string item in ids)
				{
					try
					{
						GameItem val3 = DirectoryMaster.Item(item, true);
						if (val3 != null)
						{
							PlayerStore.Instance.AddDirectSellingItemToTable(val3, false, false, false, 0);
						}
					}
					catch
					{
					}
				}
			}));
			try
			{
				val.offerSets.Clear();
			}
			catch
			{
			}
			val.offerSets.Add(val2);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] BuildJuanOffer 异常: " + ex.Message);
		}
		return val;
	}

