	internal static void AddDoctorNightGoods()
	{
		try
		{
			if (!IsActive())
			{
				return;
			}
			int num = 0;
			if (!HasGoodOnFront("processed_meat"))
			{
				for (int i = 0; i < 2; i++)
				{
					try
					{
						if (MerchantHelper.AddItemToCounter("processed_meat") != null)
						{
							num++;
						}
					}
					catch
					{
					}
				}
			}
			if (!HasGoodOnFront("large_bottled_water"))
			{
				try
				{
					GameItem val = WaterPremadeHelper.AccurateHighQualityWater("large_bottled_water");
					if (val != null && MerchantHelper.AddItemToCounter(val) != null)
					{
						num++;
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[RobinCrusoePerk.PhoneVendor] 异常: " + ex.Message);
				}
			}
			if (DrJacksonFriendPerk.IsActive())
			{
				float num2 = (float)(BuildConfig.HardMode ? BuildConfig.NeuralChanceHard : BuildConfig.NeuralChanceNormal) / 100f;
				if (Random.value < num2 && !HasGoodOnFront("system_capped_neural_core"))
				{
					try
					{
						if (MerchantHelper.AddItemToCounter("system_capped_neural_core") != null)
						{
							num++;
						}
					}
					catch
					{
					}
				}
			}
			if (num > 0)
			{
				Core.LogMsg("[空间站鲁滨逊] 博士夜晚商店加货 " + num + " 件（食物水/神经模组）");
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[空间站鲁滨逊] AddDoctorNightGoods 异常: " + ex2.Message);
		}
	}

	private static bool HasGoodOnFront(string itemId)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.frontInvinvElement == null || instance.frontInvinvElement.items == null)
			{
				return false;
			}
			Enumerator<GameItem> enumerator = instance.frontInvinvElement.items.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current != null && current.identifier == itemId)
				{
					return true;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.PhoneVendor] 异常: " + ex.Message);
		}
		return false;
	}

	private static int CountGoodOnFront(string itemId)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.frontInvinvElement == null || instance.frontInvinvElement.items == null)
			{
				return 0;
			}
			int num = 0;
			Enumerator<GameItem> enumerator = instance.frontInvinvElement.items.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current != null && current.identifier == itemId)
				{
					num++;
				}
			}
			return num;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.PhoneVendor] 异常: " + ex.Message);
		}
		return 0;
	}

