	public static bool PrefixStartPhoneDialog(long currentNumber)
	{
		//IL_01ae: Unknown result type (might be due to invalid IL or missing references)
		//IL_01b4: Invalid comparison between Unknown and I4
		try
		{
			if (currentNumber == 51189)
			{
				if (!Core.PerkActive("声名狼藉") && !Core.PerkActive("人神共愤"))
				{
					return true;
				}
				try
				{
					StoreReputation storeReputation = StoreReputation.GetStoreReputation("FACTION_REVOLUTION");
					if (((storeReputation != null) ? ((int)storeReputation.GetReputationExact()) : 0) > -99)
					{
						return true;
					}
				}
				catch
				{
				}
				PlayerStore instance = PlayerStore.Instance;
				if (instance == null || instance.storeClientManager == null)
				{
					return true;
				}
				try
				{
					instance.storeClientManager.RemoveDuplicateClientsByIdentifier("wanted4Normal");
				}
				catch
				{
				}
				instance.QueueFuturClient("wanted4Normal", 2);
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("已联系奥丁，2天后到店", "Odin contacted, arriving in 2 days."), "green");
				}
				catch
				{
				}
				Core.LogMsg("[奥丁] 电话接通 → 排期wanted4Normal 2天到店");
				try
				{
					PhoneUIManager.Instance.StopCall();
				}
				catch
				{
				}
				return false;
			}
			if (!IsActive())
			{
				return true;
			}
			string text = null;
			string text2 = null;
			switch (currentNumber)
			{
			case 8800L:
				text = "wanted7";
				text2 = LangHelper.T("胡安", "Juan");
				break;
			case 8801L:
				text = "wanted6";
				text2 = LangHelper.T("李北文", "Li Beiwen");
				break;
			default:
				return true;
			}
			_ = text == "wanted7";
			if (_wantedPhoneRemoved.Contains(currentNumber))
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T(text2 + "已被举报/击毙，无法再叫货", text2 + " has been reported/killed, cannot order."), "red");
				}
				catch
				{
				}
				try
				{
					PhoneUIManager.Instance.StopCall();
				}
				catch
				{
				}
				return false;
			}
			StorePhoneClient phoneClientByNumber = StorePhoneClient.GetPhoneClientByNumber(currentNumber);
			if (phoneClientByNumber != null && (phoneClientByNumber.currentCooldown > 0 || (int)phoneClientByNumber.phoneState == 5))
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T(text2 + "还在忙，过几天再打", text2 + " is busy, call again in a few days."), "red");
				}
				catch
				{
				}
				try
				{
					PhoneUIManager.Instance.StopCall();
				}
				catch
				{
				}
				return false;
			}
			PlayerStore instance2 = PlayerStore.Instance;
			if (instance2 == null || instance2.storeClientManager == null)
			{
				return true;
			}
			try
			{
				instance2.storeClientManager.RemoveDuplicateClientsByIdentifier(text);
			}
			catch
			{
			}
			instance2.QueueFuturClient(text, CALL_TO_ARRIVE_DAYS);
			if (phoneClientByNumber != null)
			{
				phoneClientByNumber.phoneState = (PhoneState)5;
				phoneClientByNumber.currentCooldown = CALL_COOLDOWN_DAYS;
				phoneClientByNumber.cooldownDuration = CALL_COOLDOWN_DAYS;
				phoneClientByNumber.dialedBefore = true;
			}
			try
			{
				StoreUIManager.Instance.Notify(LangHelper.T("已预约" + text2 + " " + CALL_TO_ARRIVE_DAYS + " 天后到店", text2 + " will arrive in " + CALL_TO_ARRIVE_DAYS + " days."), "green");
			}
			catch
			{
			}
			Core.LogMsg("[空间站鲁滨逊] 电话叫货成功：" + text2 + " " + CALL_TO_ARRIVE_DAYS + " 天后到店");
			try
			{
				PhoneUIManager.Instance.StopCall();
			}
			catch
			{
			}
			return false;
		}
		catch
		{
			return true;
		}
	}

