	private static void TickOnePhoneCooldown(long number)
	{
		//IL_002f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0035: Invalid comparison between Unknown and I4
		try
		{
			StorePhoneClient phoneClientByNumber = StorePhoneClient.GetPhoneClientByNumber(number);
			if (phoneClientByNumber != null && phoneClientByNumber.currentCooldown > 0)
			{
				int currentCooldown = phoneClientByNumber.currentCooldown;
				phoneClientByNumber.currentCooldown = currentCooldown - 1;
				if (phoneClientByNumber.currentCooldown <= 0 && (int)phoneClientByNumber.phoneState == 5)
				{
					phoneClientByNumber.phoneState = (PhoneState)4;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.PhoneVendor] 异常: " + ex.Message);
		}
	}

