	public static bool PrefixCheckRentDay()
	{
		try
		{
			if (!IsActive())
			{
				return true;
			}
			int currentDay = DeterministicSchedule.CurrentDay;
			int num = RentForDay(currentDay);
			if (num <= 0)
			{
				return false;
			}
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				return false;
			}
			if (WageSaveStore.GetInt("RobinCrusoe", "rent_paid_day", -1) == currentDay)
			{
				return false;
			}
			bool flag = instance.playerCash >= num;
			instance.playerCash -= num;
			WageSaveStore.SetInt("RobinCrusoe", "rent_paid_day", currentDay);
			if (flag)
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("交租 " + num + "（第" + currentDay + "天）", "Rent due: " + num + " (day " + currentDay + ")"), "green");
				}
				catch
				{
				}
			}
			else
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("房东来收 " + num + "，现金不足，强制扣除！", "The landlord is here for " + num + " - not enough cash, forcibly deducted!"), "red");
				}
				catch
				{
				}
			}
			return false;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[空间站鲁滨逊] PrefixCheckRentDay 异常: " + ex.Message);
		}
		return true;
	}

