	private static int RentForDay(int day)
	{
		if (day == 49 || day == 50)
		{
			return 2500;
		}
		if (day == 100)
		{
			return 10000;
		}
		if (day == 150)
		{
			return 20000;
		}
		if (day == 200)
		{
			return 50000;
		}
		if (day == 250)
		{
			return 70000;
		}
		if (day > 250 && day % 50 == 0)
		{
			return 70000;
		}
		return 0;
	}

	private static int NextRentDay(int day)
	{
		if (day < 49)
		{
			return 49;
		}
		if (day < 50)
		{
			return 50;
		}
		if (day < 100)
		{
			return 100;
		}
		if (day < 150)
		{
			return 150;
		}
		if (day < 200)
		{
			return 200;
		}
		if (day < 250)
		{
			return 250;
		}
		return (day / 50 + 1) * 50;
	}

