	public static void PostfixGetScavTimeLeft(ref int __result)
	{
		try
		{
			if (IsActive())
			{
				if (IsBloodWeak() || IsForcedRest())
				{
					__result = 0;
				}
				else
				{
					__result = Math.Max(0, GetScavCap() - GetScavAttempts());
				}
			}
