		}
	}

	private static int GetScavCap()
	{
		try
		{
			if (IsWounded() && !IsWoundStable())
			{
				return 0;
			}
			int num = 5 + GetMoodScavBonus();
			if (BuildConfig.HardMode && LuckScoutPerk.IsActive())
			{
				num += 10;
			}
			if (IsHomebrewWineBuffActive())
			{
				num++;
			}
			return Math.Max(1, num);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Scavenge] 异常: " + ex.Message);
		}
		return 5;
	}

