	internal static int ApplyIncomePunish(int pct)
	{
		try
		{
			int num = WageSaveStore.GetInt("RobinCrusoe", "revenue");
			if (num <= 0 || pct <= 0)
			{
				return 0;
			}
			int num2 = (int)((double)(num * pct) / 100.0);
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null && num2 > 0)
			{
				int playerCash = Math.Max(0, instance.playerCash - num2);
				instance.playerCash = playerCash;
				WageSaveStore.SetInt("RobinCrusoe", "revenue", 0);
				return num2;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex.Message);
		}
		return 0;
	}

	internal static int LostSmallItem(int count)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return 0;
			}
			List<GameItem> allItems = instance.GetAllItems();
			if (allItems == null)
			{
				return 0;
			}
			int num = 0;
			Enumerator<GameItem> enumerator = allItems.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (num >= count)
				{
					break;
				}
				if (current == null)
				{
					continue;
				}
				GetId(current);
				if (IsToolOrKeyOrContainer(current) || (!IsFood(current) && !IsDrink(current)))
				{
					continue;
				}
				try
				{
					GameInventory val = FindContainingInventory(current);
					if (val != null)
					{
						val.Expel(current);
						num++;
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex.Message);
				}
			}
			return num;
		}
		catch
		{
			return 0;
		}
	}

