	private static GameInventory FindContainingInventory(GameItem target)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return null;
			}
			List<GameInventory> val = new List<GameInventory>();
			try
			{
				if (instance.frontInvinvElement != null)
				{
					val.Add((GameInventory)(object)instance.frontInvinvElement);
				}
				if (instance.backInvinvElement != null)
				{
					val.Add((GameInventory)(object)instance.backInvinvElement);
				}
				if (instance.hiddenElement != null)
				{
					val.Add((GameInventory)(object)instance.hiddenElement);
				}
				if (instance.afterhourInventory != null)
				{
					val.Add((GameInventory)(object)instance.afterhourInventory);
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex.Message);
			}
			Enumerator<GameInventory> enumerator = val.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameInventory current = enumerator.Current;
				try
				{
					if (current == null || current.childItems == null)
					{
						continue;
					}
					for (int i = 0; i < current.childItems.Count; i++)
					{
						if (current.childItems[i] == target)
						{
							return current;
						}
					}
				}
				catch (Exception ex2)
				{
					Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex2.Message);
				}
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex3.Message);
		}
		return null;
	}

	private static bool IsToolOrKeyOrContainer(GameItem item)
	{
		try
		{
			string id = GetId(item);
			if (item.IsTag("IMPORTANT_TAG"))
			{
				return true;
			}
			if (item.IsTag("MACHINE"))
			{
				return true;
			}
			if (item.IsTag("LOCKED"))
			{
				return true;
			}
			if (id != null && (id.Contains("storage") || id.Contains("key") || id.Contains("tool") || id.Contains("machine") || id.Contains("module")))
			{
				return true;
			}
			return false;
		}
		catch
		{
			return false;
		}
	}

