	public static bool PrefixPickClient()
	{
		try
		{
			if (!IsActive())
			{
				return true;
			}
			int clientReduction = GetClientReduction();
			if (_pickSkipToday < clientReduction)
			{
				_pickSkipToday++;
				return false;
			}
			if (_burstClientCut >= 50)
			{
				_burstSkipFlip = !_burstSkipFlip;
				if (_burstSkipFlip)
				{
					return false;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex.Message);
		}
		return true;
	}

