	public static bool PrefixCanClientExposeAnyFeature(GameItem gameItem)
	{
		try
		{
			if (IsActive() && gameItem != null && IsFood(gameItem))
			{
				bool flag = false;
				if (GetFoodQuality(gameItem) >= 3)
				{
					flag = true;
				}
				else if (IsEaten(gameItem))
				{
					flag = true;
				}
				if (flag)
				{
					_rejectLogCount++;
					if (_rejectLogCount % 60 == 1)
					{
						return false;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex.Message);
		}
		return true;
	}

