	public static void PostfixOnNewDay()
	{
		try
		{
			if (!IsActive())
			{
				return;
			}
			_pickSkipToday = 0;
			SyncRentDisplay();
			RollNodeFx();
			int num = Math.Max(0, GetSatiety() - DAILY_SAT_LOSS - FxNum("satD"));
			int num2 = (int)((double)DAILY_THIRST_LOSS * GetThirstEffMult());
			int num3 = Math.Max(0, GetThirstPct() - num2 - FxNum("thD"));
			int health = GetHealth();
			int num4 = DAILY_HEALTH_GAIN + FxNum("hR");
			int num5 = (int)((double)FxNum("hD") * GetWearEffMult());
			int num6 = Math.Min(100, Math.Max(0, health + num4 - num5));
			if (IsBloodWeak())
			{
				num6 = Math.Max(0, num6 - 10);
			}
			SetSatiety(num);
			SetThirstPct(num3);
			SetHealth(num6);
			SetClean(Math.Max(0, Math.Min(100, GetClean() - DAILY_CLEAN_LOSS - FxNum("cleanD") + FxNum("cleanR"))));
			SetSleep(Math.Min(100, Math.Max(0, GetSleep() + DAILY_SLEEP_GAIN + FxNum("sleepR") + GetCompBuffSleepRestore())));
			AddBlood(100);
			TickBloodRest();
			int num7 = WageSaveStore.GetInt("RobinCrusoe", "deals");
			int val = GetSocial() + ((num7 > 0) ? DAILY_SOCIAL_GAIN : (-DAILY_SOCIAL_LOSS)) + FxNum("socD") + FxNum("socR");
			SetSocial(Math.Max(0, Math.Min(100, val)));
			WageSaveStore.SetInt("RobinCrusoe", "deals", 0);
			TickCompBuffs();
			int num8 = GetMood();
			bool flag = num >= 80;
			bool flag2 = num3 >= 80;
			bool flag3 = num6 >= 80;
			if (flag & flag2 & flag3)
			{
				num8 = Math.Min(100, num8 + MOOD_UP);
			}
			else if (num < 60 || num3 < 60 || num6 < 60)
			{
				num8 = Math.Max(0, num8 - (int)((double)MOOD_DOWN * GetMoodDampMult()));
			}
			num8 = Math.Max(0, Math.Min(100, num8 + FxNum("mood")));
			num8 = Math.Min(100, num8 + GetCompBuffMoodBonus());
			SetMood(num8);
			if (GetSickChanceAdd() > 0)
			{
				TryInfect((double)GetSickChanceAdd() / 100.0);
			}
			int health2 = GetHealth();
			int clean = GetClean();
			int forageBonus = GetForageBonus();
			if (health2 < 20 && Random.value < 0.3f + (float)forageBonus / 100f)
			{
				ForageIndoor((!(Random.value < 0.5f)) ? 1 : 2, LangHelper.T("躺板板翻找", "Bedridden rummaging"));
