			else if (clean < 50 && Random.value < 0.15f + (float)forageBonus / 100f)
			{
				ForageIndoor(1, LangHelper.T("店内翻找", "In-store rummaging"));
			}
			int num9 = ((num < 20 || num3 < 20) ? (GetStarveDays() + 1) : 0);
			int num10 = ((num3 < 20) ? (GetThirstDeathDays() + 1) : 0);
			int num11 = ((num6 < 20) ? (GetCritDays() + 1) : 0);
			WageSaveStore.SetInt("RobinCrusoe", "starveDays", num9);
			WageSaveStore.SetInt("RobinCrusoe", "thirstDeath", num10);
			WageSaveStore.SetInt("RobinCrusoe", "critDays", num11);
			if (num9 == 5)
			{
				RescueFeed();
			}
			else if (num10 >= 3 && num9 < 5)
			{
				RescueWater();
			}
			else if (num11 == 3 && num9 < 5 && num10 < 3)
			{
				RescueMedicine();
			}
			if (num9 > 5)
			{
				ExecuteGameOverBy("starvation");
				return;
			}
			if (num10 >= 4 && num9 < 5)
			{
				ExecuteGameOverBy("thirst");
				return;
			}
			if (num11 > 3 && num9 < 5 && num10 < 4)
			{
				ExecuteGameOverBy("disease");
				return;
			}
			int num12 = ((num >= 80) ? (GetGranaryDays() + 1) : 0);
			WageSaveStore.SetInt("RobinCrusoe", "granary", num12);
			int num13 = ((num >= 80 && num6 >= 80) ? (GetElevStreak() + 1) : 0);
			int num14 = GetElevCount();
			if (num13 >= ELEV_EVERY)
			{
				num14 = Math.Min(ELEV_MAX, num14 + 1);
