			}
			string text5 = LangHelper.T("心情 ", "Mood ") + num8 + ((sellBonusPct > 0 || budgetBonusPct > 0) ? ("｜" + LangHelper.T("售价+" + sellBonusPct + "% 预算+" + budgetBonusPct + "%", "Sell +" + sellBonusPct + "% Budget +" + budgetBonusPct + "%")) : "");
			string text6;
