			ClearMemBlood();
			WandererPerk.ClearBackpack();
			bool flag = (Object)(object)NewGameData.Instance != (Object)null && NewGameData.Instance.hardMode;
			WageSaveStore.SetInt("RobinCrusoe", "robinson_hard", flag ? 1 : 0);
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null)
			{
				if (flag)
