	private static void GiveToBackpack(string id, int count)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.backInvinvElement == null)
			{
				return;
			}
			GameInventory backInvinvElement = (GameInventory)(object)instance.backInvinvElement;
			for (int i = 0; i < count; i++)
			{
				GameItem val = DirectoryMaster.Item(id, true);
				if (val == null)
				{
					continue;
				}
				try
				{
					GeneralHelper.SetItemOwned(val, true);
				}
				catch
				{
				}
				SlotMarker val2 = instance.backInvinvElement.TryFindOneValidInventorySlot(val, false);
				if (val2 != null)
				{
					try
					{
						val2.TryAcceptOnce(-1);
					}
					catch
					{
						goto IL_0061;
					}
					continue;
				}
				goto IL_0061;
				IL_0061:
				try
				{
					List<GameItem> val3 = new List<GameItem>();
					val3.Add(val);
					backInvinvElement.UncheckedAcceptAll(val3);
				}
				catch
				{
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex.Message);
		}
	}

	private static void GivePureWaterToBackpack(int count)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.backInvinvElement == null)
			{
				return;
			}
			GameInventory backInvinvElement = (GameInventory)(object)instance.backInvinvElement;
			for (int i = 0; i < count; i++)
			{
				GameItem val = WaterPremadeHelper.AccurateHighQualityWater("large_bottled_water");
				try
				{
					GeneralHelper.SetItemOwned(val, true);
				}
				catch
				{
				}
				try
				{
					val.DisableTag("stolen", true);
				}
				catch
				{
				}
				SlotMarker val2 = instance.backInvinvElement.TryFindOneValidInventorySlot(val, false);
				if (val2 != null)
				{
					try
					{
						val2.TryAcceptOnce(-1);
					}
					catch
					{
						goto IL_0073;
					}
					continue;
				}
				goto IL_0073;
				IL_0073:
				try
				{
					List<GameItem> val3 = new List<GameItem>();
					val3.Add(val);
					backInvinvElement.UncheckedAcceptAll(val3);
				}
				catch
				{
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[RobinCrusoePerk.Survival] 异常: " + ex.Message);
		}
	}

