internal static class TagHelper
{
	public static int GetInt(GameItem item, string tag)
	{
		try
		{
			TagState tagReadonly = item.GetTagReadonly(tag);
			if (tagReadonly != null)
			{
				return tagReadonly.valueInt;
			}
		}
		catch
		{
		}
		return 0;
	}

	public static bool Has(GameItem item, string tag)
	{
		try
		{
			return item != null && item.GetTagReadonly(tag) != null;
		}
		catch
		{
			return false;
		}
	}

	public static void SetInt(GameItem item, string tag, int value)
	{
		try
		{
			if (!item.IsTag(tag))
			{
				item.EnableTag(tag, true);
			}
			Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState state) =>
			{
				state.SetInt(value);
			}));
			item.ModifyTag(tag, val, false);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[TagHelper] 异常: " + ex.Message);
		}
	}

	public static void AddInt(GameItem item, string tag, int delta)
	{
		try
		{
			SetInt(item, tag, GetInt(item, tag) + delta);
		}
		catch
		{
		}
	}

	public static float GetFloat(GameItem item, string tag)
	{
		try
		{
			TagState tagReadonly = item.GetTagReadonly(tag);
			if (tagReadonly != null)
			{
				return tagReadonly.GetFloat();
			}
		}
		catch
		{
		}
		return 0f;
	}

	public static void SetFloat(GameItem item, string tag, float value)
	{
		try
		{
			if (!item.IsTag(tag))
			{
				item.EnableTag(tag, true);
			}
			Action<TagState> val = DelegateSupport.ConvertDelegate<Action<TagState>>((Delegate)(Action<TagState>)((TagState state) =>
			{
				state.SetFloat(value);
			}));
			item.ModifyTag(tag, val, false);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[TagHelper] SetFloat异常: " + ex.Message);
		}
	}
}
