internal static class TraitEffects
{
	private static string GetItemId(GameItem item)
	{
		if (item == null)
		{
			return "";
		}
		try
		{
			if (!string.IsNullOrEmpty(item.identifier))
			{
				return item.identifier;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[TraitEffects] 异常: " + ex.Message);
		}
		try
		{
			PropertyInfo property = ((object)item).GetType().GetProperty("id");
			if (property != null)
			{
				return property.GetValue(item)?.ToString() ?? "";
			}
			FieldInfo field = ((object)item).GetType().GetField("id");
			if (field != null)
			{
				return field.GetValue(item)?.ToString() ?? "";
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[TraitEffects] 异常: " + ex2.Message);
		}
		return item.name ?? "";
	}

	private static int GetItemValue(GameItem item)
	{
		if (item == null)
		{
			return 0;
		}
		try
		{
			PropertyInfo property = ((object)item).GetType().GetProperty("value");
			if (property != null)
			{
				return (int)property.GetValue(item);
			}
			FieldInfo field = ((object)item).GetType().GetField("value");
			if (field != null)
			{
				return (int)field.GetValue(item);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[TraitEffects] 异常: " + ex.Message);
		}
		return 0;
	}

	public static bool IsContraband(GameItem item)
	{
		if (item == null)
		{
			return false;
		}
		try
		{
			try
			{
				return item.IsTag("contraband");
			}
			catch (Exception ex)
			{
				Core.LogMsg("[TraitEffects] 异常: " + ex.Message);
			}
			try
			{
				TagState tagReadonly = item.GetTagReadonly("contraband");
				if (tagReadonly != null)
				{
					return tagReadonly.IsEnabled();
				}
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[TraitEffects] 异常: " + ex2.Message);
			}
			string itemId = GetItemId(item);
			string text = item.name ?? "";
			string[] array = new string[19]
			{
				"dream_dust", "nightmare_dust", "unlicensed_phagimycin_pill", "handmade_pistol", "heavy_handmade_pistol", "smg", "shotgun", "c4", "smoke_grenade", "stun_gun",
				"system_capped_neural_core", "ancient_alien_relics", "blank_module", "crypto_module_cmd", "crypto_module_sec", "smuggler_bay_mod", "smuggler_bay_mini", "neural_core", "神经核心"
			};
			foreach (string value in array)
			{
				if (itemId.Contains(value, StringComparison.OrdinalIgnoreCase) || text.Contains(value, StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
			}
			array = new string[6] { "违禁", "非法", "赃物", "走私", "未授权", "黑市" };
			foreach (string value2 in array)
			{
				if (text.Contains(value2, StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[TraitEffects] 异常: " + ex3.Message);
		}
		return false;
	}

	public static bool IsAlcohol(GameItem item)
	{
		if (item == null)
		{
			return false;
		}
		try
		{
			string itemId = GetItemId(item);
			if (itemId.Contains("rubbing", StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
			string text = item.name ?? "";
			string[] array = new string[15]
			{
				"alcohol", "beer", "wine", "liquor", "vodka", "whiskey", "酒", "啤", "葡萄", "白干",
				"伏特加", "威士忌", "酿", "莓果", "wine_bottle"
			};
			foreach (string value in array)
			{
				if (itemId.Contains(value, StringComparison.OrdinalIgnoreCase) || text.Contains(value, StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[TraitEffects] 异常: " + ex.Message);
		}
		return false;
	}

	public static bool IsJunk(GameItem item)
	{
		if (item == null)
		{
			return false;
		}
		try
		{
			string itemId = GetItemId(item);
			string[] array = new string[12]
			{
				"junk", "scrap", "old", "used", "broken", "rusty", "杂物", "旧物", "破烂", "废",
				"碎", "残"
			};
			foreach (string value in array)
			{
				if (itemId.Contains(value, StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
			}
			int itemValue = GetItemValue(item);
			if (itemValue > 0 && itemValue < 20)
			{
				return true;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[TraitEffects] 异常: " + ex.Message);
		}
		return false;
	}
}
public static class TurboBoostN
{
	private static int _pendingN;

	private static GameItem _turboMachine;

	private static int _turboN;

	private static bool _inTurboCatchUp;

	public static void PostfixTarget(GameItem __instance, GameItem targetItem)
	{
		try
		{
			if (__instance != null && targetItem != null && __instance.identifier != null && __instance.identifier.StartsWith("turbo_booster_adv"))
			{
				int tagIntSafe = RobinCrusoePerk.GetTagIntSafe(__instance, "wage_turbo_n");
				Core.LogMsg("[涡轮N] Target source=" + __instance.identifier + " target=" + targetItem.identifier + " n=" + tagIntSafe);
				if (tagIntSafe > 1)
				{
					_turboMachine = targetItem;
					_turboN = tagIntSafe;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[涡轮N] Target异常: " + ex.Message);
		}
	}

	public static void PostfixUpdateSprite(GameItem item, GameSlotInventory batterySlot)
	{
		try
		{
			int tagIntSafe = RobinCrusoePerk.GetTagIntSafe(item, "wage_turbo_n");
			Core.LogMsg("[涡轮N] UpdateSprite id=" + item.identifier + " n=" + tagIntSafe);
			if (tagIntSafe > 1)
			{
				_pendingN = tagIntSafe;
			}
		}
		catch
		{
		}
	}

	private static int FindTurboNInMachine(GameItem machine)
	{
		try
		{
			GameSlotInventory batterySlot = MachineHelper.GetBatterySlot(machine);
			if (batterySlot == null)
			{
				return 0;
			}
			Enumerator<GameItem> enumerator = ((GameInventory)batterySlot).childItems.GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current != null && current.identifier != null && current.identifier.StartsWith("turbo_booster_adv"))
				{
					int tagIntSafe = RobinCrusoePerk.GetTagIntSafe(current, "wage_turbo_n");
					if (tagIntSafe > 1)
					{
						return tagIntSafe;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[涡轮N] FindTurboN异常: " + ex.Message);
		}
		return 0;
	}

	public static void PrefixFill(string quality, GameItem container, ref int volume)
	{
		try
		{
			if (_turboMachine != null && _turboN > 1)
			{
				object obj;
				if (container == null)
				{
					obj = null;
				}
				else
				{
					GameInventory parentInventory = container.parentInventory;
					obj = ((parentInventory != null) ? parentInventory.GetParentItem() : null);
				}
				if (obj == _turboMachine)
				{
					Core.LogMsg("[涡轮N] Fill放大 n=" + _turboN + " vol=" + volume);
					volume *= _turboN;
					_turboN = 0;
					_turboMachine = null;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[涡轮N] Fill异常: " + ex.Message);
		}
	}

	public static void PostfixPurifyContainer(GameItem machine, GameItem waterContainer, bool ignoreBonus)
	{
		if (_inTurboCatchUp)
		{
			return;
		}
		try
		{
			int num = FindTurboNInMachine(machine);
			if (num <= 1)
			{
				return;
			}
			_inTurboCatchUp = true;
			for (int i = 0; i < num - 1; i++)
			{
				try
				{
					MachinePurifier.PurifyContainer(machine, waterContainer, ignoreBonus);
				}
				catch
				{
				}
			}
			Core.LogMsg("[涡轮N] Purify补产 " + (num - 1) + "次");
		}
		catch (Exception ex)
		{
			Core.LogMsg("[涡轮N] Purify异常: " + ex.Message);
		}
		finally
		{
			_inTurboCatchUp = false;
		}
	}

	public static void PostfixOnAgeWine(GameItem item)
	{
		if (_inTurboCatchUp)
		{
			return;
		}
		try
		{
			object machine;
			if (item == null)
			{
				machine = null;
			}
			else
			{
				GameInventory parentInventory = item.parentInventory;
				machine = ((parentInventory != null) ? parentInventory.GetParentItem() : null);
			}
			int num = FindTurboNInMachine((GameItem)machine);
			if (num <= 1)
			{
				return;
			}
			_inTurboCatchUp = true;
			for (int i = 0; i < num - 1; i++)
			{
				try
				{
					WineHelper.OnAgeWine(item);
				}
				catch
				{
				}
			}
			Core.LogMsg("[涡轮N] Wine补产 " + (num - 1) + "次");
		}
		catch (Exception ex)
		{
			Core.LogMsg("[涡轮N] Wine异常: " + ex.Message);
		}
		finally
		{
			_inTurboCatchUp = false;
		}
	}

	public static void PostfixContinueProgress(GameItem machine)
	{
		if (_inTurboCatchUp)
		{
			return;
		}
		try
		{
			int num = FindTurboNInMachine(machine);
			if (num <= 1)
			{
				return;
			}
			_inTurboCatchUp = true;
			for (int i = 0; i < num - 1; i++)
			{
				try
				{
					MachineProgressHelper.ContinueProgressTypeMachine(machine);
				}
				catch
				{
				}
			}
			Core.LogMsg("[涡轮N] Progress补产 " + (num - 1) + "次");
		}
		catch (Exception ex)
		{
			Core.LogMsg("[涡轮N] Progress异常: " + ex.Message);
		}
		finally
		{
			_inTurboCatchUp = false;
		}
	}

	public static void PostfixCreateTooltip(RichTextBuilder builder, GameItem item)
	{
		try
		{
			if (item != null)
			{
				int tagIntSafe = RobinCrusoePerk.GetTagIntSafe(item, "wage_turbo_n");
				if (tagIntSafe > 1)
				{
					builder.AddLine("◆ 互食加持：额外加速 " + (tagIntSafe - 1) + " 次", true, (ColorPalette)(-1), true, false, false, false, (ColorPalette)(-1), (ColorPalette)(-1), (ColorPalette)(-1));
				}
			}
		}
		catch
		{
		}
	}
}
internal static class WageBrother
{
	internal const string CLIENT_ID = "wage_brother";

	internal const string CARD_ID = "wage_brother_card";

	private static bool _cardSpawned;

	private static Sprite _portrait;

	private static Sprite _cardSprite;

	internal const string CARD_SPRITE_KEY = "wage_brother_card_sprite";

	internal static bool ScheduleToday()
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				return false;
			}
			int dayCounter = StoreStation.GetDayCounter();
			if (HasQueued())
			{
				return false;
			}
			int num = ((BuildConfig.WageBrotherVisitInterval > 0) ? BuildConfig.WageBrotherVisitInterval : 10);
			int num2 = WageSaveStore.GetInt("wage_brother", "last_scheduled_day", -1);
			if (num2 >= 0 && dayCounter - num2 < num)
			{
				return false;
			}
			WageSaveStore.SetInt("wage_brother", "last_scheduled_day", dayCounter);
			Core.LogMsg("[蛙哥] 门控已删，day=" + dayCounter + " 尝试塞队 HasQueued=" + HasQueued());
			instance.QueueFuturClient("wage_brother", 1);
			Core.LogMsg("[蛙哥] 已排队，明天到访");
			return true;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙哥] ScheduleToday异常: " + ex.Message);
			return false;
		}
	}

	private static bool HasQueued()
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				return false;
			}
			List<string> futurStoreClientIdQueue = instance.futurStoreClientIdQueue;
			if (futurStoreClientIdQueue != null)
			{
				for (int i = 0; i < futurStoreClientIdQueue.Count; i++)
				{
					if (futurStoreClientIdQueue[i] == "wage_brother")
					{
						return true;
					}
				}
			}
			StoreClientManager storeClientManager = instance.storeClientManager;
			if (storeClientManager != null && storeClientManager.clientStack != null)
			{
				for (int j = 0; j < storeClientManager.clientStack.Count; j++)
				{
					StoreClient val = storeClientManager.clientStack[j];
					if (val != null && val.identifier == "wage_brother")
					{
						return true;
					}
				}
			}
		}
		catch
		{
		}
		return false;
	}

	internal static void OnClientArrived(StoreClient client)
	{
		//IL_0079: Unknown result type (might be due to invalid IL or missing references)
		//IL_007e: Unknown result type (might be due to invalid IL or missing references)
		//IL_0243: Unknown result type (might be due to invalid IL or missing references)
		//IL_024a: Expected Obj, but got Unknown
		try
		{
			if (client == null || client.identifier != "wage_brother")
			{
				if (Core.DebugMode)
