	internal static void CleanupCardIfGone()
	{
		try
		{
			if (!_cardSpawned || HasQueued())
			{
				return;
			}
			_cardSpawned = false;
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return;
			}
			Enumerator<GameItem> enumerator = instance.GetAllItems().GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				bool flag = false;
				try
				{
					flag = current.IsTag("wage_bro_card");
				}
				catch
				{
				}
				if (flag)
				{
					try
					{
						current.Destroy();
					}
					catch
					{
					}
				}
			}
			Core.LogMsg("[蛙哥] 走了，服务卡已清");
		}
		catch
		{
		}
	}

	internal static int PriceForCost(int cost)
	{
		if (cost <= -20)
		{
			return 8000;
		}
		if (cost <= -15)
		{
			return 5000;
		}
		if (cost <= -7)
		{
			return 2000;
		}
		return 500;
	}

	internal static void ShowRemovePerkWindow()
	{
		//IL_0070: Unknown result type (might be due to invalid IL or missing references)
		try
		{
