				return;
			}
			CustomUIManager instance = CustomUIManager.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return;
			}
			if (instance.IsOpen("wage_bro_window"))
			{
				instance.CloseWindow("wage_bro_window");
			}
			CustomUIBuilder val = instance.CreateWindow("wage_bro_window", LangHelper.T("蛙哥 · 消业障", "Wage Brother · Remove Burden"), "overlay");
			if (val == null)
			{
				return;
			}
			val.SetSize(360f, 480f).SetPosition(Vector2.zero);
			val.BeginColumn(4f);
			val.AddLabel(LangHelper.T("蛙哥：花钱消个负面特性。钱货两清。", "Wage Brother: pay to remove a negative perk. No refunds."), "wb_hint");
			PlayerStore instance2 = PlayerStore.Instance;
			val.AddLabel(LangHelper.T("当前现金：" + instance2.playerCash, "Cash: " + instance2.playerCash), "wb_cash");
