					{
						continue;
					}
					int num2 = PriceForCost(perk.Cost);
					string displayName = perk.DisplayName;
					_ = perk.Cost;
					int pr = num2;
					Action val2 = DelegateSupport.ConvertDelegate<Action>((Delegate)(Action)(() =>
					{
						try
						{
							DoRemovePerk(perk.Id, pr);
						}
						catch (Exception ex2)
						{
							Core.LogMsg("[蛙哥] 消perk异常: " + ex2.Message);
						}
					}));
					string text = LangHelper.T(displayName, displayName);
					val.AddButton(text, val2, "wb_perk_" + num);
					num++;
				}
				catch
				{
				}
			}
			if (num == 0)
			{
				val.AddLabel(LangHelper.T("没有可消除的负面特性", "No removable negative perks"), "wb_empty");
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙哥] ShowWindow异常: " + ex.Message);
		}
	}

	private static void DoRemovePerk(string perkId, int price)
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				return;
			}
			if (instance.playerCash < price)
			{
				StoreUIManager.Instance.Notify(LangHelper.T("钱不够", "Not enough credits"), "default");
				return;
			}
			instance.playerCash -= price;
			StartingPerk.RemovePerk(perkId);
			if (perkId == "声名狼藉")
			{
				try
				{
					ShowRepFactionWindow();
					return;
				}
				catch (Exception ex)
				{
					Core.LogMsg("[蛙哥] 弹势力窗口异常: " + ex.Message);
				}
			}
			Core.LogMsg("[蛙哥] 已消除 " + perkId + "，扣 " + price);
			StoreUIManager.Instance.Notify(LangHelper.T("蛙哥收了" + price + "块，" + perkId + "消了", "Wage Brother took " + price + ", removed " + perkId), "default");
			_cardSpawned = false;
			CleanupCardIfGone();
			try
			{
				if ((Object)(object)CustomUIManager.Instance != (Object)null)
				{
					CustomUIManager.Instance.CloseWindow("wage_bro_window");
				}
			}
			catch
			{
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[蛙哥] DoRemovePerk异常: " + ex2.Message);
		}
	}

