				string fnm = array2[i];
				try
				{
					StoreReputation storeReputation = StoreReputation.GetStoreReputation(fid);
					if (storeReputation == null)
					{
						continue;
					}
					int num = (int)storeReputation.GetReputationExact();
					if (num >= 0)
					{
						continue;
					}
					string text = LangHelper.T(fnm + "（" + num + "→0，3000块）", fnm + " (" + num + "→0, 3000cr)");
					Action val2 = DelegateSupport.ConvertDelegate<Action>((Delegate)(Action)(() =>
					{
						try
						{
							PlayerStore instance3 = PlayerStore.Instance;
							if (instance3 != null)
							{
								if (instance3.playerCash < 3000)
								{
									StoreUIManager.Instance.Notify(LangHelper.T("钱不够", "Not enough credits"), "default");
								}
								else
								{
									instance3.playerCash -= 3000;
									StoreReputation storeReputation2 = StoreReputation.GetStoreReputation(fid);
									if (storeReputation2 != null)
									{
										int num2 = (int)storeReputation2.GetReputationExact();
										if (num2 < 0)
										{
											storeReputation2.ModReputation((double)(-num2));
										}
									}
									Core.LogMsg("[蛙哥] " + fnm + " 声望恢复，扣3000");
									StoreUIManager.Instance.Notify(LangHelper.T(fnm + "声望恢复", fnm + " rep restored"), "default");
									ShowRepFactionWindow();
								}
							}
						}
						catch (Exception ex2)
						{
							Core.LogMsg("[蛙哥] 恢复声望异常: " + ex2.Message);
						}
					}));
					val.AddButton(text, val2, "wr_fac_" + i);
				}
				catch
				{
				}
			}
			val.AddButton(LangHelper.T("关闭", "Close"), DelegateSupport.ConvertDelegate<Action>((Delegate)(Action)(() =>
			{
				try
				{
					CustomUIManager.Instance.CloseWindow("wage_rep_window");
				}
				catch
				{
				}
			})), "wr_close");
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙哥] ShowRepFactionWindow异常: " + ex.Message);
		}
	}

	internal static bool PrefixDoubleClickAction(GameItem newItem, Vector2 mousePosition)
	{
		try
		{
			if (newItem == null)
			{
				return true;
			}
			bool flag = false;
			try
			{
				flag = newItem.IsTag("wage_bro_card");
			}
			catch
			{
			}
			if (!flag)
			{
				return true;
			}
			if (PlayerStore.Instance == null)
			{
				return false;
			}
			ShowRemovePerkWindow();
			return false;
		}
		catch
		{
			return true;
		}
	}
