	private static string EvalState()
	{
		try
		{
			if (_animMode == 2)
			{
				return "angry";
			}
			if (_animMode == 1)
			{
				return "walk";
			}
			try
			{
				if (_walking)
				{
					return "walk";
				}
			}
			catch
			{
			}
			try
			{
				if (GetStat("leaveDay") > 0 && _cachedGirlItem == null)
				{
					return "away";
				}
			}
			catch
			{
			}
			int stat = GetStat("mood");
			int stat2 = GetStat("health");
			int stat3 = GetStat("sat");
			int stat4 = GetStat("th");
			int stat5 = GetStat("clean");
			int stat6 = GetStat("sleep");
			int affection = GetAffection();
			if (stat <= 20)
			{
				return "angry";
			}
			if (stat2 <= 30)
			{
				return "sick";
			}
			if (stat3 <= 30)
			{
				return "hungry";
			}
			if (stat4 <= 30)
			{
				return "thirsty";
			}
			if (stat5 <= 30)
			{
				return "dirty";
			}
			if (stat6 <= 30)
			{
				return "sleepy";
			}
			if (stat >= 70)
			{
				return "happy";
			}
			if (affection >= 80)
			{
				return "shy";
			}
			if (stat3 >= 80 && stat >= 60)
			{
				return "full";
			}
			return "idle";
		}
		catch
		{
			return "idle";
		}
	}

	private static void SetAnimMode(int mode, bool force = false)
	{
		try
		{
			if (_animMode != mode || force)
			{
				_animMode = mode;
				_frameIndex = 0;
				_frameTimer = 0f;
				_animModeTimer = 0f;
				_curAnimSprites = mode switch
				{
					2 => _spAngry, 
					1 => _spWalk, 
					_ => _spIdle, 
				};
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageGirlSystem.Anim] 异常: " + ex.Message);
		}
	}

	private static bool ExistsCached()
	{
		try
		{
			int frameCount = Time.frameCount;
			if (frameCount - _existsCacheFrame < 15)
			{
				return _existsCache;
			}
			_existsCacheFrame = frameCount;
			_existsCache = Exists();
			return _existsCache;
		}
		catch
		{
			return Exists();
		}
	}

	public static void OnUpdateTick()
	{
		try
		{
			if (Time.frameCount == _lastTickFrame)
			{
				return;
			}
			_lastTickFrame = Time.frameCount;
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageGirlSystem.Anim] 异常: " + ex.Message);
		}
		try
		{
			if (!ExistsCached() || Patches.CurrentUITradeMode != 0)
			{
				return;
			}
			float deltaTime = Time.deltaTime;
			if (deltaTime <= 0f)
			{
				return;
			}
			EnsureSprites();
			bool flag = _curAnimSprites != null && _curAnimSprites.Length != 0;
			if (_leavingTimer > 0f)
			{
				_leavingTimer -= deltaTime;
				if (_leavingTimer <= 0f)
				{
					try
					{
						RemoveGirlFromScene();
					}
					catch
					{
					}
				}
			}
			if (_returnTimer > 0f)
			{
				_returnTimer -= deltaTime;
				_curState = "return";
				_curAnimSprites = _spReturn;
				_stateFrameSec = 0.125f;
				_frameTimer += deltaTime;
				if (_frameTimer >= _stateFrameSec)
				{
					_frameTimer = 0f;
					if (_spReturn != null && _spReturn.Length > 1)
					{
						_frameIndex = (_frameIndex + 1) % _spReturn.Length;
					}
				}
				TryApplyAnimFrame();
				if (_returnTimer <= 0f)
				{
					_curState = "";
					_frameIndex = 0;
					_frameTimer = 0f;
				}
			}
			else
			{
				try
				{
					string text = EvalState();
					if (text != _curState)
					{
						_curState = text;
						_frameIndex = 0;
						_frameTimer = 0f;
						_curAnimSprites = text switch
						{
							"walk" => _spWalk, 
							"return" => _spReturn, 
							"away" => _spAway, 
							"full" => _spFull, 
							"shy" => _spShy, 
							"angry" => _spAngry, 
							"sleepy" => _spSleepy, 
							"dirty" => _spDirty, 
							"sick" => _spSick, 
							"thirsty" => _spThirsty, 
							"hungry" => _spHungry, 
							"happy" => _spHappy, 
							_ => _spIdle, 
						};
						float stateFrameSec;
						switch (text)
						{
						default:
							stateFrameSec = 2f;
							break;
						case "away":
						case "return":
						case "walk":
							stateFrameSec = 0.125f;
							break;
						case "angry":
							stateFrameSec = 0.2f;
							break;
						case "sleepy":
							stateFrameSec = 0.5f;
							break;
						case "sick":
							stateFrameSec = 0.5f;
							break;
						case "dirty":
							stateFrameSec = 0.3f;
							break;
						case "hungry":
							stateFrameSec = 0.3f;
							break;
						case "happy":
							stateFrameSec = 0.25f;
							break;
						}
						_stateFrameSec = stateFrameSec;
					}
				}
				catch
				{
				}
			}
			if (flag)
			{
				if (_animMode == 2)
				{
					_animModeTimer += deltaTime;
					if (_animModeTimer >= _frameMs[2] * (float)_curAnimSprites.Length)
					{
						SetAnimMode(0);
					}
				}
				_frameTimer += deltaTime;
				if (_frameTimer >= _stateFrameSec)
				{
					_frameTimer = 0f;
					if (_curAnimSprites.Length > 1)
					{
						_frameIndex = (_frameIndex + 1) % _curAnimSprites.Length;
					}
				}
				TryApplyAnimFrame();
			}
			if (_walking)
			{
				_moveTimer += deltaTime;
				if (_moveTimer >= 2.5f)
				{
					_moveTimer = 0f;
					_stepsTaken++;
					if (TryMoveStep())
					{
						SetAnimMode(1, force: true);
					}
					else
					{
						SetAnimMode(0);
					}
					if (_stepsTaken >= _walkSteps)
					{
						_walking = false;
						_pauseTimer = 0f;
						SetAnimMode(0);
					}
				}
				return;
			}
			_pauseTimer += deltaTime;
			if (_pauseTimer >= _pauseDuration)
			{
				if (GetAffection() < 50)
				{
