	public static void PostfixApplyBudgetModifier(StoreClient __instance)
	{
		try
		{
			if (__instance == null || __instance.identifier == "wage_girl" || __instance.identifier == "wage_brother" || Patches._inBudgetOverride)
			{
				return;
			}
			int budget = __instance.GetBudget();
			if (budget <= 0)
			{
				return;
			}
			if (WineLoverPerk.IsHungover())
			{
				long num = (long)((float)budget * 0.9f);
				__instance.OverrideBudget((int)num);
			}
			else if (DryAirPerk.IsActive() && BuysWaterOrBooze(__instance))
			{
				long num2 = (long)((float)budget * DryAirPerk.GetWaterBoozeBudgetBonus());
				__instance.OverrideBudget((int)num2);
			}
			else if (Exists())
			{
				int affection = GetAffection();
				float num3;
				if (affection < BuildConfig.WageGirlBudgetAffLow)
				{
					num3 = BuildConfig.WageGirlBudgetMultLow;
				}
				else
				{
					num3 = ((affection < BuildConfig.WageGirlBudgetAffMid) ? BuildConfig.WageGirlBudgetMultMid : BuildConfig.WageGirlBudgetMultHigh);
				}
				long num4 = (long)((float)budget * num3);
				if (num4 > BuildConfig.WageGirlBudgetCap)
				{
					num4 = BuildConfig.WageGirlBudgetCap;
				}
				__instance.OverrideBudget((int)num4);
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageGirlSystem.Budget] 异常: " + ex.Message);
		}
	}

	private static bool BuysWaterOrBooze(StoreClient c)
	{
		try
		{
			if (c.clientBuyingIdList == null)
			{
				return false;
			}
			Enumerator<string> enumerator = c.clientBuyingIdList.GetEnumerator();
			while (enumerator.MoveNext())
			{
				string current = enumerator.Current;
				if (current != null && WaterBoozeIds.Contains(current))
				{
					return true;
				}
			}
		}
		catch
		{
		}
		return false;
	}

