	private static bool TryFeed(GameItem item, GameItem girl)
	{
		try
		{
			if (item == null)
			{
				return false;
			}
			if (ProvisionMode)
			{
				bool flag = false;
				try
				{
					flag = RobinCrusoePerk.IsFood(item);
				}
				catch
				{
				}
				if (flag)
				{
					SetStat("provision", GetStat("provision") + 1);
					try
					{
						item.Destroy();
					}
					catch
					{
					}
					ProvisionMode = false;
					ReportLine(LangHelper.T("已收1份口粮（当前" + GetStat("provision") + "份）", "Stored 1 provision (total: " + GetStat("provision") + ")"));
					ShowPanel();
					return true;
				}
				ProvisionMode = false;
			}
			if (IsContraband(item))
			{
				if (Patches.CurrentUITradeMode != 0)
				{
					return false;
				}
				if (GetStat("washMode") == 0)
				{
					int num = 0;
					try
					{
						num = ContrabandHelper.GetContrabandLevel(item);
					}
					catch
					{
						num = 1;
					}
					if (num <= 0)
					{
						num = 1;
					}
					int num2 = num * 50;
					int stat = GetStat("savings");
					if (stat < num2)
					{
						ReportLine(LangHelper.T("蛙娘：小金库余额不足（洗白需要 " + num2 + " 块）", "Wage Girl: not enough savings (need " + num2 + ")"));
						try
						{
							StoreUIManager.Instance.Notify(LangHelper.T("小金库余额不足", "Not enough savings"), "orange");
						}
						catch
						{
						}
						return false;
					}
					SetStat("savings", stat - num2);
					try
					{
						ContrabandHelper.RemoveContrabandStatus(item);
						try
						{
							item.EnableTag("wage_washed", true);
						}
						catch
						{
						}
					}
					catch
					{
					}
					try
					{
						item.shortDescription += LangHelper.T("【被蛙哥的大手洗白】", "[Laundered by Wage's big hand]");
					}
					catch
					{
					}
					string name = ModCannibalism.GetName(item);
					ReportLine(LangHelper.T("蛙娘把 " + name + " 洗白了（L" + num + " -" + num2 + " 块小金库）", "Wage Girl laundered " + name + " (L" + num + " -" + num2 + " savings)"));
					try
					{
						if ((Object)(object)CustomUIManager.Instance != (Object)null && CustomUIManager.Instance.IsOpen("wage_girl_panel"))
						{
							ShowPanel();
						}
					}
					catch
					{
					}
					SetAnimMode(2);
					return true;
				}
				long num3 = 0L;
				try
				{
					num3 = (int)item.GetCurrentValue(false, true, true, false, 0L);
				}
				catch
				{
				}
				if (num3 <= 0)
				{
					try
					{
						num3 = item.unitValue;
					}
					catch
					{
					}
				}
				if (num3 <= 0)
				{
					return false;
				}
				bool flag2 = false;
				try
				{
					item.Destroy();
					flag2 = true;
				}
				catch (Exception ex)
				{
					Core.LogMsg("[蛙娘销赃] Destroy失败: " + ex.Message);
					try
					{
