					return false;
				}
				int waterMl = RobinCrusoePerk.GetWaterMl(item);
				if (waterMl <= 0)
				{
					string text2 = "";
					try
					{
						text2 = item.identifier;
					}
					catch
					{
					}
					switch (text2)
