					int num11 = -1;
					try
					{
						num11 = WaterHelper.GetWaterPurity(item);
					}
					catch
					{
					}
					int num12 = ((num11 < 9900) ? ((num11 >= 9600) ? 1 : ((num11 >= 9200) ? 2 : ((num11 >= 8800) ? 3 : 4))) : 0);
					num4 = (int)Math.Round((float)(new int[5] { 25, 18, 12, 6, 2 })[num12] * ((float)num10 / 200f));
					if (num4 < 1)
