	private static void CheckAffection50Reward()
	{
		try
		{
			if (GetAffection() >= 50 && WageSaveStore.GetInt("WageGirl", "gift50_sent") == 0)
			{
				WageSaveStore.SetInt("WageGirl", "gift50_sent", 1);
				GiveRewardItem("wage_ai_generator", 1);
				GiveRewardItem("system_capped_neural_core", 2);
				Core.LogMsg("[蛙娘] 好感破50，送出（不稳定AI制造器x1+原生AI神经模组x2，进背包）");
			}
		}
		catch (Exception ex)
