			Core.LogMsg("[蛙娘] 好感50三件套失败: " + ex.Message);
		}
	}

	private static void GiveRewardItem(string id, int count)
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.invElement == null)
			{
				return;
			}
			for (int i = 0; i < count; i++)
			{
				GameItem val = null;
				try
				{
					val = DirectoryMaster.Item(id, true);
				}
				catch
				{
				}
				if (val == null)
				{
					continue;
				}
				SlotMarker val2 = instance.invElement.TryFindOneValidInventorySlot(val, false);
				if (val2 != null)
				{
					try
					{
						val2.TryAcceptOnce(-1);
					}
					catch
					{
						goto IL_004e;
					}
					continue;
				}
				goto IL_004e;
				IL_004e:
				try
				{
					List<GameItem> val3 = new List<GameItem>();
					val3.Add(val);
					((GameInventory)instance.invElement).UncheckedAcceptAll(val3);
				}
				catch
				{
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙娘] GiveRewardItem异常: " + ex.Message);
		}
	}

