	public static void PostfixOnDayStart()
	{
		try
		{
			try
			{
				EmporiumEntry instance = EmporiumEntry.Instance;
				if ((Object)(object)instance != (Object)null)
				{
					Enumerator<GameItem> enumerator = instance.GetAllItems().GetEnumerator();
					while (enumerator.MoveNext())
					{
						GameItem current = enumerator.Current;
						try
						{
							if (current != null && current.IsTag("wage_washed") && ContrabandHelper.GetContrabandLevel(current) > 0)
							{
								ContrabandHelper.RemoveContrabandStatus(current);
								Core.LogMsg("[蛙娘] 日切防御重洗白: " + current.identifier);
							}
						}
						catch
						{
						}
					}
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[蛙娘] 日切重洗白扫描异常: " + ex.Message);
			}
			if (!Exists() && WageGirlPerk.IsActive())
			{
				TryGiveToBackpack();
			}
			if (!Exists() && !WageGirlPerk.IsActive())
			{
				return;
			}
			string[] array = new string[5] { "sat", "th", "health", "mood", "clean" };
			foreach (string k in array)
			{
				int num = GetStat(k);
				if (num <= 0)
				{
					num = BuildConfig.WageGirlStatInit;
				}
				SetStat(k, num - BuildConfig.WageGirlDailyDecay);
			}
			SetStat("allowanceCount", 0);
			int sleepDebt = GetSleepDebt();
			SetSleepDebt(0);
			SetStat("sleep", GetStat("sleep") - sleepDebt + BuildConfig.WageGirlSleepRecover);
			int num2 = 0;
			if (!WasFedToday())
			{
				num2 += Random.Range(BuildConfig.WageGirlAffDecayMin, BuildConfig.WageGirlAffDecayMax + 1);
			}
			if (IsAnyStatLow())
			{
				num2 += Random.Range(BuildConfig.WageGirlAffDecayLowMin, BuildConfig.WageGirlAffDecayLowMax + 1);
			}
			if (num2 > 0)
			{
				SetAffection(GetAffection() - num2);
			}
			RunDayEvents();
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[WageGirlSystem.NeedsAffection] 异常: " + ex2.Message);
		}
	}

	private static void RunDayEvents()
	{
		try
		{
			if (!Exists())
			{
				return;
			}
			if (GetStat("fencePending") > 0 && GetStat("leaveDay") <= 0)
			{
				FenceReturn();
			}
			int num = CurrentDay();
			int stat = GetStat("leaveDay");
			if (stat > 0 && num >= stat)
			{
				int stat2 = GetStat("leaveReason");
				SetStat("leaveDay", 0);
				SetStat("leaveReason", 0);
				int stat3 = GetStat("allowance");
				if (stat3 > 0)
				{
					GiveBackItem(stat3);
					SetStat("allowance", 0);
					ReportLine(LangHelper.T("蛙娘逛街回来了，带了点东西", "Wage Girl is back from shopping"));
				}
				else
				{
					switch (stat2)
					{
					case 1:
						FenceReturn();
						break;
					case 2:
						RunawayReturn();
						break;
					case 4:
						TravelReturn(early: false);
						break;
					default:
					{
						int stat4 = GetStat("lastStealAmount");
						if (stat4 > 0)
						{
							GiveBackItem(stat4);
							SetStat("lastStealAmount", 0);
						}
						else
						{
							ReportLine(LangHelper.T("蛙娘回来了", "Wage Girl is back"));
						}
						break;
					}
					}
				}
				TryGiveToBackpack();
				return;
			}
			TravelDailyTick(num);
			if (stat > 0 && num < stat)
			{
				return;
			}
			int num2 = GetStat("starveStreak");
			if (IsAnyStatLow())
			{
				num2++;
				SetStat("starveStreak", num2);
			}
			else
			{
				SetStat("starveStreak", 0);
			}
			if (num2 >= BuildConfig.WageGirlRunawayStreak)
			{
				SetStat("starveStreak", 0);
				SetStat("leaveDay", num + BuildConfig.WageGirlRunawayDays);
				SetStat("leaveReason", 2);
				_curState = "away";
				_curAnimSprites = _spAway;
				_stateFrameSec = 0.125f;
				_leavingTimer = 0.5f;
				ReportLine(LangHelper.T("蛙娘连续几天没吃好没睡好，离家出走了（" + BuildConfig.WageGirlRunawayDays + " 天后回来）", "Wage Girl ran away after days of neglect (back in " + BuildConfig.WageGirlRunawayDays + " days)"));
				return;
			}
			int stat5 = GetStat("lastStealDay");
			if (stat5 <= 0)
			{
				int wageGirlStealFirstAmount = BuildConfig.WageGirlStealFirstAmount;
				List<string> stolenNames = null;
				int num3 = StealItems("food", 1, "highest", out stolenNames);
				ModCashN(-wageGirlStealFirstAmount);
				if (num3 > 0 && stolenNames != null && stolenNames.Count > 0)
				{
					ReportLine(LangHelper.T("蛙娘偷走了 " + wageGirlStealFirstAmount + " 块钱和" + string.Join("、", stolenNames), "Wage Girl stole " + wageGirlStealFirstAmount + " credits and " + string.Join(", ", stolenNames)));
				}
				else
				{
					ReportLine(LangHelper.T("蛙娘偷走了 " + wageGirlStealFirstAmount + " 块钱", "Wage Girl stole " + wageGirlStealFirstAmount + " credits"));
				}
				SetStat("lastStealDay", num);
				return;
			}
			int stat6 = GetStat("stolenValue", 0);
			if (GetStat("mood") >= 80 && stat6 > 0)
			{
				GiveBackItem(stat6);
				SetStat("stolenValue", 0);
				ReportLine(LangHelper.T("蛙娘心情大好，把之前偷的东西都还回来了", "Wage Girl is in a great mood and returned everything she stole"));
			}
			if (GetStat("allowance") <= 0)
			{
				TrySnatch();
			}
			int stat7 = GetStat("lastGiftDay");
			if (GetAffection() >= BuildConfig.WageGirlGiftAff && num - stat7 >= BuildConfig.WageGirlGiftInterval)
			{
				GiveGift();
				SetStat("lastGiftDay", num);
			}
			int stat8 = GetStat("allowance");
			int num4 = ((BuildConfig.WageGirlAllowanceSteps.Length != 0) ? BuildConfig.WageGirlAllowanceSteps[0] : 100);
			if (stat8 >= num4 && Random.Range(0, 2) == 0)
			{
				SetStat("lastStealDay", num);
			}
			else if (num - stat5 >= BuildConfig.WageGirlStealInterval && GetAffection() < BuildConfig.WageGirlStealNoStealAff)
			{
				int affection = GetAffection();
				int num5 = BuildConfig.WageGirlStealBaseMax - (int)((float)affection / (float)BuildConfig.WageGirlAffMax * (float)BuildConfig.WageGirlStealAffReduction);
				ModCashN(-num5);
				SetStat("lastStealAmount", num5);
				SetSleepDebt(GetSleepDebt() + BuildConfig.WageGirlStealSleepDebt);
				SetStat("leaveDay", num + 1);
				SetStat("leaveReason", 0);
				SetStat("lastStealDay", num);
				_curState = "away";
				_curAnimSprites = _spAway;
				_stateFrameSec = 0.125f;
				_leavingTimer = 0.5f;
				ReportLine(LangHelper.T("蛙娘偷走了 " + num5 + " 块钱，出门躲债去了（明天回来）", "Wage Girl stole " + num5 + " credits and went out (back tomorrow)"));
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageGirlSystem.NeedsAffection] 异常: " + ex.Message);
		}
	}

	private static bool IsAnyStatLow()
	{
		try
		{
			int wageGirlRunawayLowStat = BuildConfig.WageGirlRunawayLowStat;
			return GetStat("sat") < wageGirlRunawayLowStat || GetStat("th") < wageGirlRunawayLowStat || GetStat("health") < wageGirlRunawayLowStat || GetStat("mood") < wageGirlRunawayLowStat || GetStat("clean") < wageGirlRunawayLowStat || GetStat("sleep") < wageGirlRunawayLowStat;
		}
		catch
		{
			return false;
		}
	}

	private static void GiveGift()
	{
		try
		{
			GameItem val = null;
			if (Core.Rng.Next(100) < 5)
			{
				string[] itemPool = WagePowerPerk.ItemPool;
				if (itemPool != null && itemPool.Length != 0)
				{
					int num = Core.Rng.Next(itemPool.Length);
					try
					{
						val = DirectoryMaster.Item(itemPool[num], true);
					}
					catch
					{
					}
				}
			}
			else
			{
				List<string> identifierList = DirectoryMaster.GetIdentifierList<GameItem>((string)null);
				if (identifierList == null || identifierList.Count == 0)
				{
					return;
				}
				List<string> list = new List<string>();
				for (int i = 0; i < identifierList.Count; i++)
				{
					if (!string.IsNullOrEmpty(identifierList[i]) && !(identifierList[i] == "wage_girl") && Array.IndexOf(Core.ExcludedItemIds, identifierList[i]) < 0)
					{
						list.Add(identifierList[i]);
					}
				}
				int num2 = 0;
				while (num2 < 12 && list.Count > 0)
				{
					int index = Core.Rng.Next(list.Count);
					string text = list[index];
					try
					{
						GameItem val2 = DirectoryMaster.Item(text, true);
						if (val2 == null)
						{
							list.RemoveAt(index);
							num2++;
							continue;
						}
						if (val2.IsTag("STANDARD_MACHINE_TAG") || val2.IsTag("CONTAINER_TAG"))
						{
							list.RemoveAt(index);
							num2++;
							continue;
						}
						int num3 = 500 + GetAffection() / 100 * 200;
						if (val2.unitValue < num3)
						{
							list.RemoveAt(index);
							num2++;
							continue;
						}
						val = val2;
					}
					catch
					{
						list.RemoveAt(index);
						num2++;
						continue;
					}
					break;
				}
			}
			if (val != null)
			{
				GameItem val3 = CreateSupplyCrate(val.unitValue, out var _);
				if (val3 != null)
				{
					AddToFront(val3);
					ReportLine(LangHelper.T("蛙娘今天心情好，带回来一只物资箱！", "Wage Girl brought a supply crate today!"));
				}
				else
				{
					AddToFront(val);
					ReportLine(LangHelper.T("蛙娘今天心情好，带回来一件好东西！", "Wage Girl brought a nice gift today!"));
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageGirlSystem.NeedsAffection] 异常: " + ex.Message);
		}
	}

	private static void GiveAllowance(int amt)
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				return;
			}
			if (instance.playerCash < amt)
			{
				ReportLine(LangHelper.T("蛙娘想拿零花钱，但你钱不够……", "Wage Girl wants allowance, but you are broke..."));
				return;
			}
			instance.playerCash -= amt;
			SetStat("savings", GetStat("savings") + amt);
			SetStat("allowance", amt);
			int stat = GetStat("allowanceCount");
			if (stat < 3)
			{
				int num = Array.IndexOf(BuildConfig.WageGirlAllowanceSteps, _allowanceSel);
				int num2 = ((num < 0) ? 1 : (num + 1));
				SetAffection(GetAffection() + num2);
				SetStat("allowanceCount", stat + 1);
				ReportLine(LangHelper.T("蛙娘把 " + amt + " 块零花钱存进小金库（好感 +" + num2 + "，今日第 " + (stat + 1) + "/3 次）", "Wage Girl saved " + amt + " credits (affection +" + num2 + ", today " + (stat + 1) + "/3)"));
			}
			else
			{
				ReportLine(LangHelper.T("蛙娘把 " + amt + " 块零花钱存进小金库（今日已给三次，不再加好感）", "Wage Girl saved " + amt + " credits (no more affection today)"));
			}
			try
			{
				if ((Object)(object)CustomUIManager.Instance != (Object)null && CustomUIManager.Instance.IsOpen("wage_girl_panel"))
				{
					ShowPanel();
				}
			}
			catch
			{
			}
		}
		catch
		{
		}
	}

	private static void CycleAllowanceSel()
	{
		try
		{
			int[] wageGirlAllowanceSteps = BuildConfig.WageGirlAllowanceSteps;
			if (wageGirlAllowanceSteps.Length != 0)
			{
				int num = Array.IndexOf(wageGirlAllowanceSteps, _allowanceSel);
				if (num < 0)
				{
					num = 0;
				}
				_allowanceSel = wageGirlAllowanceSteps[(num + 1) % wageGirlAllowanceSteps.Length];
			}
		}
		catch
		{
		}
	}

