	internal static int GetStat(string k)
	{
		return GetStat(k, 0);
	}

	internal static int GetStat(string k, int def)
	{
		try
		{
			if (_memStats.TryGetValue(k, out var value))
			{
				return value;
			}
			if (WageSaveStore.HasKey("wage_girl", k))
			{
				int num = WageSaveStore.GetInt("wage_girl", k, def);
				_memStats[k] = num;
				return num;
			}
			return def;
		}
		catch
		{
			return def;
		}
	}

	internal static void SetStat(string k, int v)
	{
		try
		{
			switch (k)
			{
			case "sat":
			case "th":
			case "health":
			case "mood":
			case "clean":
			case "sleep":
				v = Math.Max(0, Math.Min(BuildConfig.WageGirlStatMax, v));
				break;
			}
			_memStats[k] = v;
		}
		catch
		{
		}
	}

