	private static void GiveBackItem(int stealAmt)
	{
		try
		{
			int affection = GetAffection();
			float num = 0.5f + (float)affection / 100f * 1.5f;
			long num2 = Math.Max(1, (int)((float)stealAmt * num));
			EmporiumEntry instance = EmporiumEntry.Instance;
			List<string> identifierList = DirectoryMaster.GetIdentifierList<GameItem>((string)null);
			if (identifierList == null || identifierList.Count == 0)
			{
				ReportLine(LangHelper.T("蛙娘回来了（没带什么值钱的东西）", "Wage Girl is back (empty-handed)"));
				return;
			}
			List<string> list = new List<string>();
			for (int i = 0; i < identifierList.Count; i++)
			{
				if (!string.IsNullOrEmpty(identifierList[i]) && !(identifierList[i] == "wage_girl") && Array.IndexOf(Core.ExcludedItemIds, identifierList[i]) < 0)
				{
					list.Add(identifierList[i]);
				}
			}
			long num3 = 0L;
			List<string> list2 = new List<string>();
			for (int j = 0; j < 2; j++)
			{
				if (list.Count <= 0)
				{
					break;
				}
				if (num3 >= num2)
				{
					break;
				}
				GameItem val = null;
				string text = null;
				int num4 = 0;
				while (num4 < 12 && list.Count > 0)
				{
					int index = Core.Rng.Next(list.Count);
					text = list[index];
					try
					{
						val = DirectoryMaster.Item(text, true);
						if (val == null)
						{
							list.RemoveAt(index);
							num4++;
							continue;
						}
						if (val.IsTag("STANDARD_MACHINE_TAG") || val.IsTag("CONTAINER_TAG"))
						{
							list.RemoveAt(index);
							num4++;
							continue;
						}
						long unitValue = val.unitValue;
						if (unitValue <= 0 || unitValue > num2 - num3)
						{
							list.RemoveAt(index);
							num4++;
							continue;
						}
					}
					catch
					{
						list.RemoveAt(index);
						num4++;
						continue;
					}
					break;
				}
				if (val == null)
				{
					continue;
				}
				num3 += val.unitValue;
				try
				{
					if (!((Object)(object)instance != (Object)null) || instance.frontInvinvElement == null)
					{
						continue;
					}
					GameInventory frontInvinvElement = (GameInventory)(object)instance.frontInvinvElement;
					SlotMarker val2 = instance.frontInvinvElement.TryFindOneValidInventorySlot(val, false);
					if (val2 != null)
					{
						try
						{
							val2.TryAcceptOnce(-1);
						}
						catch
						{
						}
					}
					else
					{
						try
						{
							List<GameItem> val3 = new List<GameItem>();
							val3.Add(val);
							frontInvinvElement.UncheckedAcceptAll(val3);
						}
						catch
						{
						}
					}
					list2.Add(ModCannibalism.GetName(val));
				}
				catch (Exception ex)
				{
					Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex.Message);
				}
			}
			if (list2.Count > 0)
			{
				ReportLine(LangHelper.T("蛙娘回来了，带了点东西回来：" + string.Join("、", list2), "Wage Girl is back with: " + string.Join(", ", list2)));
			}
			else
			{
				ReportLine(LangHelper.T("蛙娘回来了（没带什么值钱的东西）", "Wage Girl is back (empty-handed)"));
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex2.Message);
		}
	}

	private static void RemoveGirlFromScene()
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return;
			}
			GameInventory[] array = new GameInventory[5]
			{
				(GameInventory)instance.invElement,
				(GameInventory)instance.backInvinvElement,
				(GameInventory)instance.backInvinvElementCounter,
				(GameInventory)instance.frontInvinvElement,
				(GameInventory)instance.showcaseElement
			};
			for (int i = 0; i < array.Length; i++)
			{
				RemoveGirlFromInv(array[i]);
			}
			try
			{
				List<GameItem> val = PlayerStore.Instance.FindAllItem(true);
				if (val == null)
				{
					return;
				}
				for (int j = 0; j < val.Count; j++)
				{
					GameItem val2 = val[j];
					if (val2 == null || val2.identifier != "wage_girl")
					{
						continue;
					}
					try
					{
						GameInventory parentInventory = val2.parentInventory;
						if (parentInventory != null)
						{
							parentInventory.Expel(val2);
						}
					}
					catch
					{
					}
					try
					{
						val2.Destroy();
					}
					catch
					{
					}
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex.Message);
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex2.Message);
		}
	}

	private static void RemoveGirlFromInv(GameInventory inv)
	{
		if (inv == null || inv.childItems == null)
		{
			return;
		}
		for (int num = inv.childItems.Count - 1; num >= 0; num--)
		{
			try
			{
				GameItem val = inv.childItems[num];
				if (val != null)
				{
					if (val.identifier == "wage_girl")
					{
						try
						{
							GameInventory parentInventory = val.parentInventory;
							if (parentInventory != null)
							{
								parentInventory.Expel(val);
							}
						}
						catch
						{
						}
						try
						{
							val.Destroy();
						}
						catch
						{
						}
						try
						{
							inv.childItems.RemoveAt(num);
						}
						catch
						{
						}
					}
					else if (val.contentWindow != null)
					{
						GameInventory innerInventory = AddictOfficerEvent.GetInnerInventory(val);
						if (innerInventory != null)
						{
							RemoveGirlFromInv(innerInventory);
						}
					}
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex.Message);
			}
		}
	}

	private static bool IsContraband(GameItem it)
	{
		try
		{
			if (ContrabandHelper.GetContrabandLevel(it) > 0)
			{
				return true;
			}
		}
		catch
		{
		}
		try
		{
			if (IsWeaponOrTool((it.identifier ?? "").ToLowerInvariant()))
			{
				return true;
			}
		}
		catch
		{
		}
		try
		{
			if (it.IsTag("stolen") || it.IsTag("TAG_STOLEN"))
			{
				return true;
			}
		}
		catch
		{
		}
		return false;
	}

	private static void TryFence()
	{
		try
		{
			if (!Exists())
			{
				return;
			}
			if (Patches.CurrentUITradeMode != 0)
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("交易模式下不能销赃", "Can't fence while trading"), "orange");
					return;
				}
				catch
				{
					return;
				}
			}
			if (GetStat("leaveDay") > 0)
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("蛙娘不在店里，返程结算后再安排", "Wage Girl is out, wait for return"), "orange");
					return;
				}
				catch
				{
					return;
				}
			}
			int stat = GetStat("fenceAmount");
			if (stat <= 0)
			{
				try
				{
					StoreUIManager.Instance.Notify(LangHelper.T("没有违禁品可销——先拖违禁品给蛙娘吃掉", "No contraband to fence - feed her contraband first"), "orange");
					return;
				}
				catch
				{
					return;
				}
			}
			SetStat("fencePending", stat);
			SetStat("fenceAmount", 0);
			SetSleepDebt(GetSleepDebt() + BuildConfig.WageGirlFenceSleepDebt);
			SetStat("leaveDay", CurrentDay() + BuildConfig.WageGirlFenceDays);
			SetStat("leaveReason", 1);
			_curState = "away";
			_curAnimSprites = _spAway;
			_stateFrameSec = 0.125f;
			_leavingTimer = 0.5f;
			ReportLine(LangHelper.T("蛙娘带着 " + stat + " 价值的货出去销赃了（" + BuildConfig.WageGirlFenceDays + " 天后回来）", "Wage Girl took " + stat + " worth of goods to fence (back in " + BuildConfig.WageGirlFenceDays + " days)"));
			try
			{
				if ((Object)(object)CustomUIManager.Instance != (Object)null && CustomUIManager.Instance.IsOpen("wage_girl_panel"))
				{
					ShowPanel();
				}
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙娘] 销赃异常: " + ex.Message);
		}
	}

	private static void FenceReturn()
	{
		try
		{
			int stat = GetStat("fencePending");
			SetStat("fencePending", 0);
			if (stat <= 0)
			{
				ReportLine(LangHelper.T("蛙娘销赃回来了", "Wage Girl is back from fencing"));
				return;
			}
			float num = (float)GetAffection() / (float)BuildConfig.WageGirlAffMax * (float)BuildConfig.WageGirlFenceAffBonusPct / 100f + (float)BuildConfig.WageGirlFenceMarginBasePct / 100f + (float)Core.Rng.Next(BuildConfig.WageGirlFenceMarginLow, BuildConfig.WageGirlFenceMarginHigh + 1) / 100f;
			long num2 = (long)((float)stat * (1f + num));
			if (num2 < 1)
			{
				num2 = 1L;
			}
			int stat2 = GetStat("fenceCat");
			switch (stat2)
			{
			case 0:
			{
				int num3 = Core.Rng.Next(BuildConfig.WageGirlFenceBoxMin, BuildConfig.WageGirlFenceBoxMax + 1);
				long num4 = 0L;
				int num5 = 0;
				for (int i = 0; i < num3; i++)
				{
					long num6 = num2 / Math.Max(1, num3);
					if (i == num3 - 1)
					{
						num6 = num2 - num4;
					}
					if (num6 < 1)
					{
						num6 = 1L;
					}
					long filledValue = 0L;
					GameItem val = CreateSupplyCrate(num6, out filledValue);
					if (val != null)
					{
						AddToFront(val);
						num4 += filledValue;
						num5++;
					}
				}
				if (num5 > 0)
				{
					int num7 = (int)(num2 - num4);
					if (num7 > 0)
					{
						SetStat("savings", GetStat("savings") + num7);
					}
					ReportLine(BuildFenceReport(stat, num7, LangHelper.T(num5 + "只物资箱", num5 + " supply crates")));
				}
				else
				{
					ReportLine(BuildFenceReport(stat, 0, LangHelper.T("（没弄到箱子）", "(no crate)")));
				}
				return;
			}
			case 5:
			{
				int num8 = Core.Rng.Next(BuildConfig.WageGirlFenceCardMin, BuildConfig.WageGirlFenceCardMax + 1);
				long num9 = 0L;
				List<string> list = new List<string>();
