	private static string BuildFenceReport(int amt, int keep, string items)
	{
		int stat = GetStat("savings");
		string text = ((keep > 0) ? LangHelper.T("克扣" + keep + "块", "kept " + keep) : LangHelper.T("贴补" + -keep + "块", "topped up " + -keep));
		return LangHelper.T("蛙娘销赃归来：投入" + amt + "块，" + text + "，小金库" + stat + "块。带了：" + items, "Wage Girl fenced: invested " + amt + ", " + text + ", savings " + stat + ". Brought: " + items);
	}

	private static void RunawayReturn()
	{
		try
		{
			int stat = GetStat("sat");
			int stat2 = GetStat("th");
			int stat3 = GetStat("health");
			int stat4 = GetStat("mood");
			int stat5 = GetStat("clean");
			int stat6 = GetStat("sleep");
			string mode = "food";
			int num = stat;
			if (stat2 < num)
			{
				num = stat2;
				mode = "drink";
			}
			if (stat3 < num)
			{
				num = stat3;
				mode = "medicine";
			}
			if (stat4 < num)
			{
				num = stat4;
				mode = "care";
			}
			if (stat5 < num)
			{
				num = stat5;
				mode = "care";
			}
			if (stat6 < num)
			{
				num = stat6;
				mode = "sleep";
			}
			GameItem val = FindCategoryItem(mode);
			if (val != null)
			{
				GameItem val2 = CreateSupplyCrate(val.unitValue, out var _);
				if (val2 != null)
				{
					AddToFront(val2);
				}
				else
				{
					AddToFront(val);
				}
				ReportLine(LangHelper.T("蛙娘回来了，带了份物资箱补偿你", "Wage Girl is back with a supply crate to make up"));
