			else
			{
				ReportLine(LangHelper.T("蛙娘回来了", "Wage Girl is back"));
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex.Message);
		}
	}

	private static GameItem FindCategoryItem(string mode)
	{
		try
		{
			List<string> identifierList = DirectoryMaster.GetIdentifierList<GameItem>((string)null);
			if (identifierList == null || identifierList.Count == 0)
			{
				return null;
			}
			List<string> list = new List<string>();
			for (int i = 0; i < identifierList.Count; i++)
			{
				if (!string.IsNullOrEmpty(identifierList[i]) && !(identifierList[i] == "wage_girl") && Array.IndexOf(Core.ExcludedItemIds, identifierList[i]) < 0)
				{
					list.Add(identifierList[i]);
				}
			}
			int num = 0;
			while (num < 12 && list.Count > 0)
			{
				int index = Core.Rng.Next(list.Count);
				string text = list[index];
				try
				{
					GameItem val = DirectoryMaster.Item(text, true);
					if (val == null)
					{
						list.RemoveAt(index);
						num++;
						continue;
					}
					if (val.IsTag("STANDARD_MACHINE_TAG") || val.IsTag("CONTAINER_TAG"))
					{
						list.RemoveAt(index);
						num++;
						continue;
					}
					bool flag = false;
					if (mode == "food" && RobinCrusoePerk.IsFood(val))
					{
						flag = true;
					}
					else if (mode == "drink" && RobinCrusoePerk.IsDrink(val))
					{
						flag = true;
					}
					else if (mode == "care" && RobinCrusoePerk.IsDailyNeed(val))
					{
						flag = true;
					}
					else if (mode == "medicine" && (RobinCrusoePerk.IsFood(val) || RobinCrusoePerk.IsDailyNeed(val)))
					{
						flag = true;
					}
					else if (mode == "sleep")
					{
						flag = true;
					}
					if (flag)
					{
						return val;
					}
					list.RemoveAt(index);
					num++;
				}
				catch
				{
					list.RemoveAt(index);
					num++;
				}
			}
			return null;
		}
		catch
		{
			return null;
		}
	}

	private static void EnsureItemCache()
	{
		if (_itemInfoCache != null)
		{
			return;
		}
		try
		{
			_itemInfoCache = new Dictionary<string, ItemInfo>();
			List<string> identifierList = DirectoryMaster.GetIdentifierList<GameItem>((string)null);
			if (identifierList == null)
			{
				return;
			}
			Enumerator<string> enumerator = identifierList.GetEnumerator();
			while (enumerator.MoveNext())
			{
				string current = enumerator.Current;
				try
				{
					if (string.IsNullOrEmpty(current) || current == "wage_girl" || Array.IndexOf(Core.ExcludedItemIds, current) >= 0)
					{
						continue;
					}
					GameItem val = DirectoryMaster.Item(current, true);
					if (val == null || IsContraband(val) || current.StartsWith("wage_") || current.Contains("book") || current.Contains("guide") || current.Contains("paper") || current.Contains("note") || ContainerUpgradeV2.IsBuildingContainerId(current))
					{
						continue;
					}
					bool flag = false;
					try
					{
						flag = val.IsTag("STANDARD_MACHINE_TAG") || val.IsTag("SYSTEM_TAG") || val.IsTag("SYSTEM_TAG_UTILITY") || val.IsTag("ITEM_HIDDEN_TAG");
					}
					catch
					{
					}
					if (flag)
					{
						continue;
					}
					ItemInfo itemInfo = new ItemInfo();
					try
					{
						itemInfo.Value = (int)val.GetCurrentValue(false, true, true, false, 0L);
					}
					catch
					{
					}
					if (itemInfo.Value <= 0)
					{
						try
						{
							itemInfo.Value = val.unitValue;
						}
						catch
						{
						}
					}
					itemInfo.FoodDrink = RobinCrusoePerk.IsFood(val) || RobinCrusoePerk.IsDrink(val);
					itemInfo.Daily = RobinCrusoePerk.IsDailyNeed(val);
					itemInfo.WeaponTool = IsWeaponOrTool(current);
					try
					{
						itemInfo.Module = false;
						if (val.IsTag("MODULE_TAG") && current != "system_module_ruined" && current != "wage_ai_module")
						{
							int tagIntSafe = RobinCrusoePerk.GetTagIntSafe(val, "BONUS_PERCENTAGE_PERFORMANCE_INT");
							int tagIntSafe2 = RobinCrusoePerk.GetTagIntSafe(val, "BONUS_PERCENTAGE_EFFICIENCY_INT");
							int tagIntSafe3 = RobinCrusoePerk.GetTagIntSafe(val, "BONUS_PERCENTAGE_QUALITY_INT");
							itemInfo.Module = tagIntSafe + tagIntSafe2 + tagIntSafe3 > 0;
						}
					}
					catch
					{
					}
					_itemInfoCache[current] = itemInfo;
					try
					{
						val.Destroy();
					}
					catch
					{
					}
				}
				catch (Exception ex)
				{
					Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex.Message);
				}
			}
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex2.Message);
		}
	}

	private static bool IsWeaponOrTool(string id)
	{
		if (string.IsNullOrEmpty(id))
		{
			return false;
		}
		string text = id.ToLowerInvariant();
		if (!text.Contains("weapon") && !text.Contains("tool") && !text.Contains("knife") && !text.Contains("gun") && !text.Contains("pistol") && !text.Contains("shotgun") && !text.Contains("smg") && !text.Contains("rifle") && !text.Contains("tazer") && !text.Contains("stun") && !text.Contains("grenade") && !text.Contains("baton") && !text.Contains("machete") && !text.Contains("sword") && !text.Contains("axe") && !text.Contains("c4") && !text.Contains("screwdriver") && !text.Contains("welder") && !text.Contains("flashlight") && !text.Contains("scanner") && !text.Contains("hammer") && !text.Contains("wrench") && !text.Contains("surgery"))
		{
			return text.Contains("combat");
		}
		return true;
	}

	private static bool CategoryMatch(ItemInfo info, int cat)
	{
		if (info == null)
		{
			return false;
		}
		return cat switch
		{
			0 => true, 
			1 => info.FoodDrink, 
			2 => info.Daily, 
			3 => info.WeaponTool, 
			7 => info.Module, 
			_ => true, 
		};
	}

	private static GameItem FindItemNearValue(long target, int cat, bool geq)
	{
		try
		{
			EnsureItemCache();
			if (_itemInfoCache == null)
			{
				return null;
			}
			string[] itemPool = WagePowerPerk.ItemPool;
			string text = null;
			long num = long.MaxValue;
			string[] array = itemPool;
			foreach (string text2 in array)
			{
				if (_itemInfoCache.TryGetValue(text2, out var value) && value != null && value.Value > 0 && CategoryMatch(value, cat) && (!geq || value.Value >= target) && (geq || value.Value <= target))
				{
					long num2 = Math.Abs(value.Value - target);
					if (num2 < num)
					{
						num = num2;
						text = text2;
					}
				}
			}
			if (text == null)
			{
				foreach (KeyValuePair<string, ItemInfo> item in _itemInfoCache)
				{
					ItemInfo value2 = item.Value;
					if (!string.IsNullOrEmpty(item.Key) && value2 != null && value2.Value > 0 && CategoryMatch(value2, cat) && (!geq || value2.Value >= target) && (geq || value2.Value <= target))
					{
						long num3 = Math.Abs(value2.Value - target);
						if (num3 < num)
						{
							num = num3;
							text = item.Key;
						}
					}
				}
			}
			if (text == null)
			{
				return null;
			}
			return DirectoryMaster.Item(text, true);
		}
		catch
		{
			return null;
		}
	}

	private static void AddToFront(GameItem it)
	{
		try
		{
			if (it == null)
			{
				return;
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.backInvinvElement == null)
			{
				return;
			}
			GameInventory backInvinvElement = (GameInventory)(object)instance.backInvinvElement;
			try
			{
				List<GameItem> val = new List<GameItem>();
				val.Add(it);
				backInvinvElement.UncheckedAcceptAll(val);
			}
			catch
			{
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex.Message);
		}
	}

