	private static GameItem CreateSupplyCrate(long targetValue, out long filledValue)
	{
		try
		{
			filledValue = 0L;
			if (targetValue < 1)
			{
				targetValue = 1L;
			}
			filledValue = 0L;
			string[] array = new string[5] { "evidence_box", "med_box", "sec_box", "service_box", "eng_box" };
			GameItem val = CustomStorageContainer.CreateLootCrate(array[Core.Rng.Next(array.Length)]);
			if (val == null)
			{
				return null;
			}
			GameInventory val2 = null;
			try
			{
				PixelWindow contentWindow = val.contentWindow;
				if (contentWindow != null)
				{
					PropertyInfo property = ((object)contentWindow).GetType().GetProperty("inventory", BindingFlags.Instance | BindingFlags.Public);
					object? obj;
					if (!(property != null))
					{
						obj = null;
					}
					else
					{
						object? value = property.GetValue(contentWindow);
						obj = ((value is GameInventory) ? value : null);
					}
					val2 = (GameInventory)obj;
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex.Message);
			}
			if (val2 == null)
			{
				filledValue = ((val != null) ? val.unitValue : 0);
				return val;
			}
			string[] collection = WagePowerPerk.ItemPool ?? new string[0];
			long num = 0L;
			int num2 = 0;
			int num3 = 0;
			List<string> list = new List<string>(collection);
			while (num < targetValue && num2 < 40 && list.Count > 0)
			{
				int index = Core.Rng.Next(list.Count);
				string text = list[index];
				list.RemoveAt(index);
				GameItem val3 = null;
				try
				{
					val3 = DirectoryMaster.Item(text, true);
				}
				catch
				{
				}
				if (val3 == null)
				{
					num2++;
					continue;
				}
				try
				{
					List<GameItem> val4 = new List<GameItem>();
					val4.Add(val3);
					val2.UncheckedAcceptAll(val4);
					num += val3.unitValue;
					num3++;
				}
				catch
				{
					num2++;
				}
			}
			if (num3 == 0)
			{
				List<string> list2 = new List<string>(collection);
				int num4 = 0;
				while (num3 == 0 && num4 < 40 && list2.Count > 0)
				{
					int index2 = Core.Rng.Next(list2.Count);
					string text2 = list2[index2];
					list2.RemoveAt(index2);
					num4++;
					GameItem val5 = null;
					try
					{
						val5 = DirectoryMaster.Item(text2, true);
					}
					catch
					{
					}
					if (val5 != null)
					{
						try
						{
							List<GameItem> val6 = new List<GameItem>();
							val6.Add(val5);
							val2.UncheckedAcceptAll(val6);
							num3++;
						}
						catch
						{
						}
					}
				}
			}
			filledValue = num;
			return val;
		}
		catch
		{
			filledValue = 0L;
			return null;
		}
	}

	private static void TrySnatch()
	{
		try
		{
			if (GetAffection() >= BuildConfig.WageGirlStealNoStealAff)
			{
				return;
			}
			int stat = GetStat("sat");
			int stat2 = GetStat("th");
			int stat3 = GetStat("mood");
			string text = null;
			string text2 = null;
			if (stat < 30)
			{
				text = "food";
				text2 = "蛙娘饿坏了，偷吃了你的食物";
			}
			else if (stat2 < 30)
			{
				text = "drink";
				text2 = "蛙娘渴坏了，偷喝了你的饮品";
			}
			else
			{
				if (stat3 >= 30)
				{
					_ = 60;
					return;
				}
				if (GetStat("clean") >= 100)
				{
					return;
				}
				text = "care";
				text2 = "蛙娘心情很差，拿走了你的日用品";
			}
			int affection = GetAffection();
			int count = ((affection < 30) ? 1 : ((affection < 70) ? 2 : 3));
			string valueMode = "random";
			int num = StealItems(text, count, valueMode, out var stolenNames);
			if (num > 0)
			{
				SetSleepDebt(GetSleepDebt() + BuildConfig.WageGirlSnatchSleepDebt);
				switch (text)
				{
				case "food":
					SetStat("sat", GetStat("sat") + 30);
					break;
				case "drink":
					SetStat("th", GetStat("th") + 30);
					break;
				case "care":
					SetStat("mood", GetStat("mood") + 20);
					SetStat("clean", GetStat("clean") + 10);
					break;
				}
				string text3 = ((stolenNames != null && stolenNames.Count > 0) ? ("：" + string.Join("、", stolenNames)) : "");
				ReportLine(LangHelper.T(text2 + text3 + "（" + num + " 件）", text2 + " (" + ((stolenNames != null) ? string.Join(", ", stolenNames) : "") + ", " + num + " items)"));
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageGirlSystem.StealAI_Fence] 异常: " + ex.Message);
		}
	}

	private static bool HasDrinkContent(GameItem it)
	{
		try
		{
			if (it == null)
			{
				return false;
			}
		}
		catch
		{
			return false;
		}
		try
		{
			if (RobinCrusoePerk.GetWaterMl(it) > 0)
			{
				return true;
			}
		}
		catch
		{
		}
		try
		{
			if (RobinCrusoePerk.GetCalorie(it) > 0)
			{
				return true;
			}
		}
		catch
		{
		}
		return false;
	}

	private static int StealItems(string mode, int count, string valueMode, out List<string> stolenNames)
	{
		stolenNames = new List<string>();
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return 0;
			}
			GameInventory[] array = new GameInventory[3]
			{
				(GameInventory)instance.frontInvinvElement,
				(GameInventory)instance.showcaseElement,
				(GameInventory)instance.invElement
			};
			List<GameItem> list = new List<GameItem>();
			GameInventory[] array2 = array;
			foreach (GameInventory val in array2)
			{
				if (val == null || val.childItems == null)
				{
					continue;
				}
				for (int j = 0; j < val.childItems.Count; j++)
				{
					GameItem val2 = val.childItems[j];
					if (val2 == null || val2.identifier == "wage_girl")
					{
						continue;
					}
					bool flag = false;
					if (mode switch
					{
						"food" => RobinCrusoePerk.IsFood(val2), 
						"drink" => RobinCrusoePerk.IsDrink(val2) && HasDrinkContent(val2), 
						"care" => RobinCrusoePerk.IsDailyNeed(val2), 
						_ => RobinCrusoePerk.IsFood(val2) || RobinCrusoePerk.IsDrink(val2) || RobinCrusoePerk.IsDailyNeed(val2), 
					})
					{
						int affection = GetAffection();
						int num;
						if (affection < 30)
						{
							num = BuildConfig.WageGirlSnatchValueLow;
						}
						else
						{
							num = ((affection < 70) ? BuildConfig.WageGirlSnatchValueMid : BuildConfig.WageGirlSnatchValueHigh);
						}
						if (val2.unitValue <= num)
						{
							list.Add(val2);
						}
					}
				}
			}
			if (list.Count == 0)
			{
				return 0;
			}
			List<GameItem> list2 = new List<GameItem>();
			if (valueMode == "highest")
			{
				GameItem val3 = list[0];
				foreach (GameItem item in list)
				{
					if (item.unitValue > val3.unitValue)
					{
						val3 = item;
					}
				}
				list2.Add(val3);
			}
			else if (valueMode == "low")
			{
				List<GameItem> list3 = new List<GameItem>(list);
				list3.Sort((GameItem a, GameItem b) => a.unitValue.CompareTo(b.unitValue));
				for (int num2 = 0; num2 < Math.Min(count, list3.Count); num2++)
				{
					list2.Add(list3[num2]);
				}
			}
			else
			{
				List<GameItem> list4 = new List<GameItem>(list);
				for (int num3 = 0; num3 < Math.Min(count, list4.Count); num3++)
				{
					int index = Core.Rng.Next(list4.Count);
					list2.Add(list4[index]);
					list4.RemoveAt(index);
				}
			}
			int num4 = 0;
			long num5 = 0L;
			foreach (GameItem item2 in list2)
			{
				try
				{
					num5 += item2.unitValue;
				}
				catch
				{
				}
				try
				{
					item2.Destroy();
					num4++;
					stolenNames.Add(ModCannibalism.GetName(item2));
				}
				catch
				{
					try
					{
						if (item2.parentInventory != null)
						{
							item2.parentInventory.Expel(item2);
							num4++;
							stolenNames.Add(ModCannibalism.GetName(item2));
						}
					}
					catch
					{
					}
				}
			}
			try
			{
				SetStat("stolenValue", GetStat("stolenValue", 0) + (int)Math.Min(num5, 2147483647L));
			}
			catch
			{
			}
			return num4;
		}
		catch
		{
			stolenNames = null;
			return 0;
		}
	}

	internal static void TryStartTravel()
	{
		try
		{
			if (Exists())
			{
				if (GetStat("leaveDay") > 0)
				{
					ReportLine(LangHelper.T("蛙娘不在店里，返程后再旅行", "Wage Girl is out, wait for return"));
					return;
				}
				if (GetAffection() < 20)
				{
					ReportLine(LangHelper.T("好感不够，她不愿出远门（需好感≥20）", "Affection too low for travel (need ≥20)"));
					return;
				}
				if (GetStat("provision") < 1)
				{
					ReportLine(LangHelper.T("没有口粮，她不愿出远门（点给予口粮备1份食物）", "No provisions (give food first)"));
					return;
				}
				SetStat("provision", GetStat("provision") - 1);
				int num = CurrentDay();
				SetStat("leaveDay", num + 3);
				SetStat("leaveReason", 4);
				_curState = "away";
				_curAnimSprites = _spAway;
				_stateFrameSec = 0.125f;
				_leavingTimer = 0.5f;
				ReportLine(LangHelper.T("蛙娘出门旅行了（" + 3 + " 天后回来）", "Wage Girl went traveling (back in " + 3 + " days)"));
				Core.LogMsg("[蛙娘旅行] 出发");
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙娘旅行] TryStartTravel异常: " + ex.Message);
		}
	}

	internal static void RecallTravel()
	{
		try
		{
			if (GetStat("leaveReason") != 4)
			{
				return;
			}
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null)
			{
				if (instance.playerCash < 200)
				{
					ReportLine(LangHelper.T("钱不够，召不回她", "Not enough credits to recall"));
					return;
				}
				instance.playerCash -= 200;
				SetStat("leaveDay", 0);
				SetStat("leaveReason", 0);
				TravelReturn(early: true);
				TryGiveToBackpack();
				ShowPanel();
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙娘旅行] Recall异常: " + ex.Message);
		}
	}

	internal static void TravelDailyTick(int day)
	{
		try
		{
			if (GetStat("leaveReason") == 4 && GetStat("leaveDay") > 0)
			{
				if (GetStat("provision") < 1)
				{
					SetStat("leaveDay", 0);
					SetStat("leaveReason", 0);
					TravelReturn(early: true);
					_curState = "";
					_curAnimSprites = _spIdle;
					TryGiveToBackpack();
					ShowPanel();
					ReportLine(LangHelper.T("口粮吃完了，她提前回来了", "She ran out of food and came back early"));
					Core.LogMsg("[蛙娘旅行] 口粮耗尽提前结束");
				}
				else
				{
					SetStat("provision", GetStat("provision") - 1);
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙娘旅行] DailyTick异常: " + ex.Message);
		}
	}

	internal static void TravelReturn(bool early)
	{
		try
		{
			int num = Core.Rng.Next(100);
			float num2 = (early ? 0.5f : 1f);
			if (num < 50)
			{
				int num3 = (int)((float)(200 + Core.Rng.Next(300)) * num2);
				PlayerStore instance = PlayerStore.Instance;
				if (instance != null)
				{
					instance.playerCash += num3;
				}
				ReportLine(LangHelper.T("蛙娘旅行回来了，带了" + num3 + "块", "She came back from travel with " + num3 + " credits"));
			}
			else if (num < 70)
			{
				try
				{
					EmporiumEntry instance2 = EmporiumEntry.Instance;
					if ((Object)(object)instance2 != (Object)null && instance2.invElement != null)
					{
						string[] array = new string[5] { "energy_credit", "bottled_water", "processed_meat", "bandage_item", "metal_ingot" };
						GameItem val = DirectoryMaster.Item(array[Core.Rng.Next(array.Length)], true);
						if (val != null)
						{
							try
							{
								val.DisableTag("STOLEN_TAG", false);
							}
							catch
							{
							}
							try
							{
								val.DisableTag("CONTRABAND_TAG", false);
							}
							catch
							{
							}
							SlotMarker val2 = instance2.invElement.TryFindOneValidInventorySlot(val, false);
							if (val2 != null)
							{
								try
								{
									val2.TryAcceptOnce(-1);
								}
								catch
								{
									try
									{
										List<GameItem> val3 = new List<GameItem>();
										val3.Add(val);
										((GameInventory)instance2.invElement).UncheckedAcceptAll(val3);
									}
									catch
									{
									}
								}
							}
							else
							{
								try
								{
									List<GameItem> val4 = new List<GameItem>();
									val4.Add(val);
									((GameInventory)instance2.invElement).UncheckedAcceptAll(val4);
								}
								catch
								{
								}
							}
						}
					}
				}
				catch
				{
				}
				ReportLine(LangHelper.T("蛙娘旅行回来了，带了件小礼物", "She came back from travel with a small gift"));
			}
			else
			{
				SetAffection(GetAffection() + 5);
				ReportLine(LangHelper.T("蛙娘旅行回来了，心情很好（好感+5）", "She came back from travel, in great mood (+5 affection)"));
			}
			Core.LogMsg("[蛙娘旅行] 回归 early=" + early);
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙娘旅行] Return异常: " + ex.Message);
		}
	}

	internal static void GiveProvision()
	{
		try
		{
			if (Exists())
			{
				if (!FindAndConsumeFood())
				{
					ReportLine(LangHelper.T("背包没有食物", "No food in stock"));
					return;
				}
				SetStat("provision", GetStat("provision") + 1);
				ReportLine(LangHelper.T("已备好1份口粮（当前" + GetStat("provision") + "份）", "Stored 1 provision (total: " + GetStat("provision") + ")"));
				ShowPanel();
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙娘旅行] GiveProvision异常: " + ex.Message);
		}
	}

	private static bool FindAndConsumeFood()
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return false;
			}
			Enumerator<GameItem> enumerator = instance.GetAllItems().GetEnumerator();
			while (enumerator.MoveNext())
			{
				GameItem current = enumerator.Current;
				if (current == null)
				{
					continue;
				}
				bool flag = false;
				try
				{
					flag = current.IsTag("FOOD_TAG");
				}
				catch
				{
				}
				if (!flag)
				{
					continue;
				}
				try
				{
					GameInventory parentInventory = current.parentInventory;
					if (parentInventory != null)
					{
						parentInventory.Expel(current);
					}
				}
				catch
				{
				}
				try
				{
					current.Destroy();
				}
				catch
				{
				}
				Core.LogMsg("[蛙娘旅行] 消耗口粮: " + (current.identifier ?? "?"));
				return true;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙娘旅行] FindFood异常: " + ex.Message);
		}
		return false;
	}
}
