	internal static void GlobalModifyDialogue(StoreClient client, string clientName)
	{
		//IL_00dc: Unknown result type (might be due to invalid IL or missing references)
		//IL_00e2: Expected Obj, but got Unknown
		try
		{
			if (clientName.Contains("博士") || clientName.Contains("Jackson") || clientName.Contains("王尔德") || clientName.Contains("Wilde") || clientName.Contains("鉴定") || clientName.Contains("Appraisal") || clientName.Contains("appraisal") || clientName.Contains("奥丁") || clientName.Contains("Odin") || clientName.Contains("哈拉尔德森") || clientName.Contains("Haraldsson"))
			{
				return;
			}
			string text = GenerateGlobalDialogue(client, clientName);
			if (text == null || string.IsNullOrWhiteSpace(text))
			{
				return;
			}
			string text2 = (clientName ?? "").Trim();
			if (client.mainDialogue != null)
			{
				client.mainDialogue.SetText(text2, text);
			}
			else
			{
				Dialogue val = new Dialogue();
				val.SetText(text2, text);
				client.mainDialogue = val;
			}
			try
			{
				if ((Object)(object)NegociationUIManager.Instance != (Object)null)
				{
					NegociationUIManager.Instance.DispatchUpdateForCurrentIntent();
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[全局对话] 刷新NegociationUIManager失败: " + ex.Message);
			}
			try
			{
				foreach (MethodInfo item in (from m in typeof(NegociationUIManager).GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
					where (m.Name.Contains("Refresh") || m.Name.Contains("UpdateUI") || m.Name.Contains("Reload") || m.Name.Contains("Redraw") || m.Name.Contains("UpdateDialogue") || m.Name.Contains("ShowDialogue")) && m.GetParameters().Length == 0
					select m).ToList())
				{
					try
					{
						item.Invoke(NegociationUIManager.Instance, null);
					}
					catch (Exception ex2)
					{
						Core.LogMsg("[WagePowerPerk.Dialogue.Global] 异常: " + ex2.Message);
					}
				}
			}
			catch (Exception ex3)
			{
				Core.LogMsg("[全局对话] 反射刷新UI失败: " + ex3.Message);
			}
		}
		catch (Exception ex4)
		{
			Core.LogMsg("[全局对话] 修改对话失败: " + ex4.Message);
		}
	}

	private static string GenerateGlobalDialogue(StoreClient client, string clientName)
	{
		//IL_002f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0035: Invalid comparison between Unknown and I4
		//IL_0081: Unknown result type (might be due to invalid IL or missing references)
		//IL_0087: Invalid comparison between Unknown and I4
		//IL_022f: Unknown result type (might be due to invalid IL or missing references)
		//IL_0235: Invalid comparison between Unknown and I4
		//IL_034a: Unknown result type (might be due to invalid IL or missing references)
		//IL_0350: Invalid comparison between Unknown and I4
		//IL_02db: Unknown result type (might be due to invalid IL or missing references)
		//IL_02e1: Invalid comparison between Unknown and I4
		//IL_0296: Unknown result type (might be due to invalid IL or missing references)
		//IL_029c: Invalid comparison between Unknown and I4
		//IL_0353: Unknown result type (might be due to invalid IL or missing references)
		//IL_0359: Invalid comparison between Unknown and I4
		//IL_0366: Unknown result type (might be due to invalid IL or missing references)
		//IL_036c: Invalid comparison between Unknown and I4
		try
		{
			string text = client.identifier ?? clientName;
			RecordClientVisit(text);
			GetClientVisitCount(text);
			string clientMainItemCategory = GetClientMainItemCategory(client);
			if (clientMainItemCategory == "水")
			{
				if ((int)client.clientIntent == 1)
				{
					return UpperWaterMerchantBuyerDialogues[Core.Rng.Next(UpperWaterMerchantBuyerDialogues.Length)];
				}
				return WaterMerchantDialogues[Core.Rng.Next(WaterMerchantDialogues.Length)];
			}
			if (clientMainItemCategory == "化学药品")
			{
				if ((int)client.clientIntent == 1)
				{
					return UpperPharmaBuyerDialogues[Core.Rng.Next(UpperPharmaBuyerDialogues.Length)];
				}
				return UpperPharmaSellerDialogues[Core.Rng.Next(UpperPharmaSellerDialogues.Length)];
			}
			if (clientName.Contains("医生") || clientName.Contains("大夫") || clientName.Contains("诊所") || clientName.Contains("doctor") || clientName.Contains("Doctor") || clientName.Contains("medic") || clientName.Contains("Medic"))
			{
				return LowerDoctorDialogues[Core.Rng.Next(LowerDoctorDialogues.Length)];
			}
			if (clientName.Contains("退休枪匠") || clientName.Contains("枪匠") || text.Contains("retired_gunsmith") || text.Contains("gunsmith"))
			{
				return GunsmithDialogues[Core.Rng.Next(GunsmithDialogues.Length)];
			}
			if (clientName.Contains("水商") || clientName.Contains("水贩") || text.Contains("water_merchant"))
			{
				return WaterMerchantDialogues[Core.Rng.Next(WaterMerchantDialogues.Length)];
			}
			if (clientName.Contains("酒商") || clientName.Contains("酒贩") || text.Contains("winemaker"))
			{
				return AlcoholMerchantDialogues[Core.Rng.Next(AlcoholMerchantDialogues.Length)];
			}
			string factionKey = GetFactionKey(client);
			if (factionKey == "tourist")
			{
				if ((int)client.clientIntent == 1)
				{
					return TouristBuyerDialogues[Core.Rng.Next(TouristBuyerDialogues.Length)];
				}
				return TouristSellerDialogues[Core.Rng.Next(TouristSellerDialogues.Length)];
			}
			if (factionKey == "upper")
			{
				if (Core.Rng.Next(100) < 30)
				{
					if ((int)client.clientIntent == 1)
					{
						return BankruptUpperBuyerDialogues[Core.Rng.Next(BankruptUpperBuyerDialogues.Length)];
					}
					return BankruptUpperSellerDialogues[Core.Rng.Next(BankruptUpperSellerDialogues.Length)];
				}
				if ((int)client.clientIntent == 1)
				{
					return UpperBuyerDialogues[Core.Rng.Next(UpperBuyerDialogues.Length)];
				}
				return UpperSellerDialogues[Core.Rng.Next(UpperSellerDialogues.Length)];
			}
			string[] factionDialoguePool = GetFactionDialoguePool(factionKey);
			if (factionDialoguePool != null && Core.Rng.Next(100) < 60)
			{
				return factionDialoguePool[Core.Rng.Next(factionDialoguePool.Length)];
			}
			if ((int)client.clientIntent == 2 || (int)client.clientIntent == 3)
			{
				return BuildDynamicTradeLine(client);
			}
			if ((int)client.clientIntent == 1)
			{
				return BuildDynamicTradeLine(client);
			}
			return GeneralDialogues[Core.Rng.Next(GeneralDialogues.Length)];
		}
		catch
		{
			return null;
		}
	}

