	private static string GetMilestoneDialogue()
	{
		if (_totalPurchases >= 100)
		{
			return LangHelper.T("老板，你这都收了上百件货了，真是业界传奇啊！", "Boss, you've taken in over a hundred items! A legend of the trade!");
		}
		if (_totalPurchases >= 50)
		{
			return LangHelper.T("听说你这收了不少好东西，我也来凑凑热闹。", "Heard you've collected quite the treasures. Figured I'd join in.");
		}
		if (_totalPurchases >= 10)
		{
			return LangHelper.T("你这店开得有模有样的，以后我常来。", "Your shop's shaping up nicely. I'll be a regular.");
		}
		return null;
	}

	private static string GetFactionKey(StoreClient client)
	{
		if (client == null)
		{
			return "lower";
		}
		string text = client.clientFaction ?? "";
		if ((client.identifier ?? "").ToLowerInvariant().StartsWith("scav"))
		{
			return "scav";
		}
		if (text.Contains("UPPER"))
		{
			return "upper";
		}
		if (text.Contains("SECURITY"))
		{
			return "security";
		}
		if (text.Contains("TOURIST"))
		{
			return "tourist";
		}
		if (text.Contains("BLACK_MARKET"))
		{
			return "blackmarket";
		}
		if (text.Contains("CARTEL"))
		{
			return "cartel";
		}
		if (text.Contains("REVOLUTION"))
		{
			return "rev";
		}
		if (text.Contains("CHURCH"))
		{
			return "church";
		}
		return "lower";
	}

	private static string[] GetFactionDialoguePool(string factionKey)
	{
		return factionKey switch
		{
			"scav" => null, 
			"upper" => UpperDialogues, 
			"security" => SecurityDialogues, 
			"tourist" => TouristDialogues, 
			"blackmarket" => BlackMarketDialogues, 
			"cartel" => CartelDialogues, 
			"rev" => RevDialogues, 
			"church" => ChurchDialogues, 
			_ => null, 
		};
	}

	private static string GetPlayerStatusDialogue()
	{
		try
		{
			PlayerEconomy playerEconomy = GetPlayerEconomy();
			PlayerLevel playerLevel = GetPlayerLevel();
			PlayerReputation playerReputation = GetPlayerReputation();
			switch (Core.Rng.Next(3))
			{
			case 0:
				switch (playerEconomy)
				{
				case PlayerEconomy.Poor:
					return PoorPlayerDialogues[Core.Rng.Next(PoorPlayerDialogues.Length)];
				case PlayerEconomy.Rich:
				case PlayerEconomy.Loaded:
					return RichPlayerDialogues[Core.Rng.Next(RichPlayerDialogues.Length)];
				}
				break;
			case 1:
				switch (playerLevel)
				{
				case PlayerLevel.Newbie:
					return NewbiePlayerDialogues[Core.Rng.Next(NewbiePlayerDialogues.Length)];
				case PlayerLevel.Veteran:
				case PlayerLevel.Legend:
					return VeteranPlayerDialogues[Core.Rng.Next(VeteranPlayerDialogues.Length)];
				}
				break;
			default:
				switch (playerReputation)
				{
				case PlayerReputation.Shady:
					return ShadyPlayerDialogues[Core.Rng.Next(ShadyPlayerDialogues.Length)];
				case PlayerReputation.Reputable:
				case PlayerReputation.Legendary:
					return ReputablePlayerDialogues[Core.Rng.Next(ReputablePlayerDialogues.Length)];
				}
				break;
			}
			return null;
		}
		catch
		{
			return null;
		}
	}

	private static string[] GetFactionIntentPool(string factionKey, ClientIntent intent)
	{
		//IL_0000: Unknown result type (might be due to invalid IL or missing references)
		//IL_0002: Invalid comparison between Unknown and I4
		//IL_0030: Unknown result type (might be due to invalid IL or missing references)
		//IL_0032: Invalid comparison between Unknown and I4
		if ((int)intent == 1)
		{
			if (factionKey == "upper")
			{
				return UpperBuyerDialogues;
			}
			if (factionKey == "tourist")
			{
				return TouristBuyerDialogues;
			}
			return BuyerDialogues;
		}
		if ((int)intent == 2)
		{
			if (factionKey == "upper")
			{
				return UpperSellerDialogues;
			}
			if (factionKey == "tourist")
			{
				return TouristSellerDialogues;
			}
			return SellerDialogues;
		}
		return factionKey switch
		{
			"scav" => null, 
			"upper" => UpperDialogues, 
			"security" => SecurityDialogues, 
			"tourist" => TouristDialogues, 
			"blackmarket" => BlackMarketDialogues, 
			"cartel" => CartelDialogues, 
			"rev" => RevDialogues, 
			"church" => ChurchDialogues, 
			_ => null, 
		};
	}

