			if (clientName.Contains("警察") || clientName.Contains("治安") || clientName.Contains("警官") || clientName.Contains("巡捕") || clientName.Contains("保安") || clientName.Contains("安保") || clientName.Contains("执法") || clientName.Contains("稽查") || clientName.Contains("搜查") || text.Contains("police") || text.Contains("security") || text.Contains("guard") || text.Contains("officer") || text.Contains("inspection") || text.Contains("inspector"))
			{
				return null;
			}
			if (clientName.Contains("医生") || clientName.Contains("护士") || clientName.Contains("大夫") || clientName.Contains("诊所") || clientName.Contains("医院") || clientName.Contains("药剂师") || clientName.Contains("药师") || clientName.Contains("医药") || text.Contains("doctor") || text.Contains("nurse") || text.Contains("medic") || text.Contains("clinic") || text.Contains("hospital") || text.Contains("pharmacist"))
			{
				return null;
			}
			if (clientName.Contains("律师") || clientName.Contains("会计师") || clientName.Contains("金融") || clientName.Contains("银行") || clientName.Contains("保险") || clientName.Contains("顾问") || clientName.Contains("经纪人") || clientName.Contains("中介") || clientName.Contains("代理") || text.Contains("lawyer") || text.Contains("accountant") || text.Contains("banker") || text.Contains("agent") || text.Contains("broker") || text.Contains("consultant"))
			{
				return null;
			}
			if (clientName.Contains("工程师") || clientName.Contains("技术员") || clientName.Contains("机械师") || clientName.Contains("维修工") || clientName.Contains("科学家") || clientName.Contains("研究员") || clientName.Contains("学者") || clientName.Contains("教授") || clientName.Contains("黑客") || text.Contains("engineer") || text.Contains("mechanic") || text.Contains("scientist") || text.Contains("researcher") || text.Contains("hacker") || text.Contains("professor"))
			{
				return null;
			}
			if (clientName.Contains("士兵") || clientName.Contains("军官") || clientName.Contains("退伍军人") || clientName.Contains("雇佣兵") || clientName.Contains("保镖") || clientName.Contains("武装") || text.Contains("soldier") || text.Contains("mercenary") || text.Contains("veteran") || text.Contains("bodyguard") || text.Contains("military"))
			{
				return null;
			}
			if (clientName.Contains("商人") || clientName.Contains("贸易商") || clientName.Contains("经销商") || clientName.Contains("代理商") || clientName.Contains("供货商") || clientName.Contains("批发商") || text.Contains("merchant") || text.Contains("trader") || text.Contains("dealer") || text.Contains("supplier") || text.Contains("wholesaler"))
			{
				return null;
			}
			if (clientName.Contains("治安部") || clientName.Contains("反抗军") || clientName.Contains("黑市") || clientName.Contains("派系") || clientName.Contains("组织") || clientName.Contains("帮会") || text.Contains("faction") || text.Contains("guild") || text.Contains("syndicate") || text.Contains("cartel"))
			{
				return null;
			}
			if (clientName.Contains("任务") || clientName.Contains("委托") || clientName.Contains("悬赏") || text.Contains("quest") || text.Contains("mission") || text.Contains("bounty") || text.Contains("contract"))
			{
				return null;
			}
			if (clientName.Contains("小偷") || clientName.Contains("可疑") || clientName.Contains("神秘") || clientName.Contains("陌生人") || clientName.Contains("流浪汉") || clientName.Contains("乞丐") || text.Contains("thief") || text.Contains("suspicious") || text.Contains("mysterious") || text.Contains("stranger") || text.Contains("beggar") || text.Contains("homeless"))
			{
				return null;
			}
			if (text.StartsWith("story_") || text.StartsWith("quest_") || text.StartsWith("event_") || text.StartsWith("special_") || text.StartsWith("unique_") || text.StartsWith("boss_"))
			{
				return null;
			}
			if (clientName.Contains("博士") || clientName.Contains("Jackson") || clientName.Contains("王尔德") || clientName.Contains("Wilde"))
			{
				return SpecialDialogues[Core.Rng.Next(SpecialDialogues.Length)];
			}
			if (clientName.Contains("医生") || clientName.Contains("大夫") || clientName.Contains("诊所") || clientName.Contains("doctor") || clientName.Contains("Doctor") || clientName.Contains("medic") || clientName.Contains("Medic"))
			{
				return LowerDoctorDialogues[Core.Rng.Next(LowerDoctorDialogues.Length)];
			}
			if (clientName.Contains("退休枪匠") || clientName.Contains("枪匠") || client.identifier.Contains("retired_gunsmith") || client.identifier.Contains("gunsmith"))
			{
				return GunsmithDialogues[Core.Rng.Next(GunsmithDialogues.Length)];
			}
			if (clientName.Contains("水商") || clientName.Contains("水贩") || client.identifier.Contains("water_merchant"))
			{
				return WaterMerchantDialogues[Core.Rng.Next(WaterMerchantDialogues.Length)];
			}
			if (clientName.Contains("酒商") || clientName.Contains("酒贩") || client.identifier.Contains("winemaker"))
			{
				return AlcoholMerchantDialogues[Core.Rng.Next(AlcoholMerchantDialogues.Length)];
			}
			string factionKey = GetFactionKey(client);
			if (factionKey == "tourist")
			{
				if ((int)client.clientIntent == 1)
				{
					return TouristBuyerDialogues[Core.Rng.Next(TouristBuyerDialogues.Length)];
				}
				return TouristSellerDialogues[Core.Rng.Next(TouristSellerDialogues.Length)];
			}
			if (factionKey == "upper")
			{
				string text2 = (client.identifier ?? "").ToLowerInvariant();
				if (clientName.Contains("药") || clientName.Contains("医药") || text2.Contains("pharma") || text2.Contains("pharm") || text2.Contains("drug") || text2.Contains("medic") || text2.Contains("chemist") || text2.Contains("apothecary"))
				{
					if ((int)client.clientIntent == 1)
					{
						return UpperPharmaBuyerDialogues[Core.Rng.Next(UpperPharmaBuyerDialogues.Length)];
					}
					return UpperPharmaSellerDialogues[Core.Rng.Next(UpperPharmaSellerDialogues.Length)];
				}
				if (clientName.Contains("厨") || clientName.Contains("厨师") || clientName.Contains("大厨") || text2.Contains("chef") || text2.Contains("cook") || text2.Contains("culinary"))
				{
					if ((int)client.clientIntent == 1)
					{
						return UpperChefBuyerDialogues[Core.Rng.Next(UpperChefBuyerDialogues.Length)];
					}
					return UpperChefSellerDialogues[Core.Rng.Next(UpperChefSellerDialogues.Length)];
				}
				if (clientName.Contains("水商") || clientName.Contains("水贩") || clientName.Contains("代买水") || text2.Contains("water") || text2.Contains("aquatic") || text2.Contains("hydro"))
				{
					if ((int)client.clientIntent == 1)
					{
						return UpperWaterMerchantBuyerDialogues[Core.Rng.Next(UpperWaterMerchantBuyerDialogues.Length)];
					}
					return UpperWaterMerchantSellerDialogues[Core.Rng.Next(UpperWaterMerchantSellerDialogues.Length)];
				}
				if (Core.Rng.Next(100) < 30)
				{
					if ((int)client.clientIntent == 1)
					{
						return BankruptUpperBuyerDialogues[Core.Rng.Next(BankruptUpperBuyerDialogues.Length)];
					}
					return BankruptUpperSellerDialogues[Core.Rng.Next(BankruptUpperSellerDialogues.Length)];
				}
				if ((int)client.clientIntent == 1)
				{
					return UpperBuyerDialogues[Core.Rng.Next(UpperBuyerDialogues.Length)];
				}
				return UpperSellerDialogues[Core.Rng.Next(UpperSellerDialogues.Length)];
			}
			string milestoneDialogue = GetMilestoneDialogue();
			if (milestoneDialogue != null && Core.Rng.Next(100) < 15)
			{
				return milestoneDialogue;
			}
			string[] factionIntentPool = GetFactionIntentPool(factionKey, client.clientIntent);
			if (factionIntentPool != null && Core.Rng.Next(100) < 45)
			{
				return factionIntentPool[Core.Rng.Next(factionIntentPool.Length)];
			}
			if ((int)client.clientIntent != 1 && (int)client.clientIntent != 2 && Core.Rng.Next(100) < 30)
			{
				string playerStatusDialogue = GetPlayerStatusDialogue();
				if (playerStatusDialogue != null)
				{
					return playerStatusDialogue;
				}
			}
			string storyPhase = GetStoryPhase();
			string[] array = null;
			switch (storyPhase)
			{
			case "新手期":
				array = NewbieDialogues;
				break;
			case "成长期":
				array = GrowthDialogues;
				break;
			case "名声期":
				array = FamousDialogues;
				break;
			}
			if ((int)client.clientIntent != 1 && (int)client.clientIntent != 2 && array != null && Core.Rng.Next(100) < 15)
			{
				return array[Core.Rng.Next(array.Length)];
			}
			string[] array2;
			if ((int)client.clientIntent == 2)
			{
				array2 = SellerDialogues;
			}
			else
			{
				array2 = (((int)client.clientIntent != 1) ? GeneralDialogues : BuyerDialogues);
			}
			string text3 = array2[Core.Rng.Next(array2.Length)];
			if (Core.Rng.Next(10) == 0)
			{
				text3 = LangHelper.T("我是", "I'm ") + clientName + LangHelper.T("，", ", ") + text3;
			}
			return text3;
		}
		catch
		{
			return LangHelper.T("看货吧。", "Just take a look.");
		}
	}

