	internal static void ModifyFirstDialogue(StoreClient client, string name)
	{
		//IL_0001: Unknown result type (might be due to invalid IL or missing references)
		//IL_0007: Invalid comparison between Unknown and I4
		//IL_0064: Unknown result type (might be due to invalid IL or missing references)
		//IL_006a: Expected Obj, but got Unknown
		try
		{
			if ((int)client.clientIntent == 1)
			{
				EnsureBuyTagsForClient(client);
			}
			string text = GenerateStoryDialogue(client, name);
			if (text == null)
			{
				return;
			}
			if (string.IsNullOrWhiteSpace(text))
			{
				Core.LogMsg("[蛙哥牛逼] 生成的对话为空，跳过: client=" + name);
				return;
			}
			string text2 = (name ?? "").Trim();
			if (client.mainDialogue != null)
			{
				client.mainDialogue.SetText(text2, text);
			}
			else
			{
				Dialogue val = new Dialogue();
				val.SetText(text2, text);
				client.mainDialogue = val;
			}
			try
			{
				if ((Object)(object)NegociationUIManager.Instance != (Object)null)
				{
					NegociationUIManager.Instance.DispatchUpdateForCurrentIntent();
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[蛙哥牛逼] 刷新NegociationUIManager失败: " + ex.Message);
			}
			try
			{
				foreach (MethodInfo item in (from m in typeof(NegociationUIManager).GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
					where (m.Name.Contains("Refresh") || m.Name.Contains("UpdateUI") || m.Name.Contains("Reload") || m.Name.Contains("Redraw") || m.Name.Contains("UpdateDialogue") || m.Name.Contains("ShowDialogue")) && m.GetParameters().Length == 0
					select m).ToList())
				{
					try
					{
						item.Invoke(NegociationUIManager.Instance, null);
					}
					catch (Exception ex2)
					{
						Core.LogMsg("[WagePowerPerk.Dialogue.Trade] 异常: " + ex2.Message);
					}
				}
			}
			catch (Exception ex3)
			{
				Core.LogMsg("[蛙哥牛逼] 反射刷新UI失败: " + ex3.Message);
			}
		}
		catch
		{
		}
	}

	internal static void AddRandomItemsToCounter(StoreClient client)
	{
		try
		{
			if (!BuildConfig.HardMode)
			{
				return;
			}
			PlayerStore instance = PlayerStore.Instance;
			if (instance == null)
			{
				Core.LogMsg("[蛙哥牛逼] PlayerStore.Instance为null");
				return;
			}
			try
			{
				instance.RemoveNotOwnedItemFromTable();
			}
			catch (Exception ex)
			{
				Core.LogMsg("[蛙哥牛逼] 清空柜台失败: " + ex.Message);
			}
			int num = 1;
			int num2 = 0;
			List<string> list = new List<string>();
			long num3 = (long)((double)GetPlayerCash() * 0.5);
			if (num3 < 50)
			{
				num3 = 50L;
			}
			for (int i = 0; i < num; i++)
			{
				if (num2 >= num)
				{
					break;
				}
				string text = SmartRandomItemByBudget(num3);
				ItemCategory itemCategory = GetItemCategory(text);
				if ((itemCategory == ItemCategory.Container && !IsLootableContainer(text)) || list.Contains(text))
				{
					continue;
				}
				try
				{
					if (!DirectoryMaster.Has<GameItem>(text))
					{
						continue;
					}
					GameItem val = null;
					val = ((itemCategory != ItemCategory.Container) ? DirectoryMaster.Item(text, true) : CreateLootCrate(text));
					if (val == null)
					{
						Core.LogMsg("[蛙哥牛逼] 创建物品失败: " + text);
						continue;
					}
					try
					{
						val.DisableTag("stolen", true);
					}
					catch
					{
					}
					try
					{
						val.DisableTag("TAG_STOLEN", true);
					}
					catch
					{
					}
					GameItem val2 = val;
					try
					{
						val2.DisableTag("not_purchased", true);
					}
					catch
					{
					}
					try
					{
						val2.DisableTag("TAG_NOT_PURCHASED", true);
					}
					catch
					{
					}
					try
					{
						val2.EnableTag("IS_OWNED_TAG", true);
					}
					catch
					{
					}
					instance.AddDirectSellingItemToTable(val2, true, false, false, 100);
					try
					{
						val2.DisableTag("not_purchased", true);
					}
					catch
					{
					}
					try
					{
						val2.DisableTag("TAG_NOT_PURCHASED", true);
					}
					catch
					{
					}
					try
					{
						val2.EnableTag("IS_OWNED_TAG", true);
					}
					catch
					{
					}
					num2++;
					list.Add(text);
					long itemWholesalePrice = GetItemWholesalePrice(text);
					if (itemWholesalePrice > 0 && itemWholesalePrice <= num3)
					{
						num3 -= itemWholesalePrice;
					}
				}
				catch (Exception ex2)
				{
					Core.LogMsg("[蛙哥牛逼] 添加" + text + "失败: " + ex2.Message);
				}
			}
			if (num2 != 0)
			{
				return;
			}
			try
			{
				GameItem val3 = DirectoryMaster.Item("raw_meat", true);
				if (val3 != null)
				{
					try
					{
						val3.DisableTag("stolen", true);
					}
					catch
					{
					}
					GameItem val4 = val3;
					try
					{
						val4.DisableTag("not_purchased", true);
					}
					catch
					{
					}
					try
					{
						val4.EnableTag("IS_OWNED_TAG", true);
					}
					catch
					{
					}
					try
					{
						val4.DisableTag("TAG_NOT_PURCHASED", true);
					}
					catch
					{
					}
					instance.AddDirectSellingItemToTable(val4, true, false, false, 100);
					try
					{
						val4.DisableTag("not_purchased", true);
					}
					catch
					{
					}
					try
					{
						val4.DisableTag("TAG_NOT_PURCHASED", true);
					}
					catch
					{
					}
					num2++;
				}
			}
			catch (Exception ex3)
			{
				Core.LogMsg("[蛙哥牛逼] 保底添加失败: " + ex3.Message);
			}
		}
		catch
		{
		}
	}

	private static string GetStoryPhase()
	{
		if (_gameDay <= 7)
		{
			return "新手期";
		}
		if (_gameDay <= 21)
		{
			return "成长期";
		}
		return "名声期";
	}

