	internal static string SmartRandomItemByBudget(long remainingBudget = -1L)
	{
		try
		{
			long num = remainingBudget;
			if (num < 0)
			{
				num = (long)((double)GetPlayerCash() * 0.5);
			}
			if (num < 50)
			{
				num = 50L;
			}
			ItemCategory topCategory = GetTopCategory();
			List<string> list = new List<string>();
			string[] itemPool = ItemPool;
			foreach (string text in itemPool)
			{
				long num2 = (long)((double)GetItemBaseValue(text) * 0.6);
				if (num2 < 1)
				{
					num2 = 1L;
				}
				if (num2 <= num)
				{
					list.Add(text);
				}
			}
			if (list.Count == 0)
			{
				return "raw_meat";
			}
			if (topCategory != ItemCategory.Unknown && _purchaseStats.ContainsKey(topCategory) && _purchaseStats[topCategory] >= 3 && Core.Rng.Next(2) == 0)
			{
				List<string> list2 = list.FindAll((string id) => GetItemCategory(id) == topCategory);
				if (list2.Count > 0)
				{
					return list2[Core.Rng.Next(list2.Count)];
				}
			}
			return list[Core.Rng.Next(list.Count)];
		}
		catch (Exception ex)
		{
			Core.LogMsg("[蛙哥牛逼] SmartRandomItemByBudget失败: " + ex.Message);
			return "raw_meat";
		}
	}

	private static PlayerEconomy GetPlayerEconomy()
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null)
			{
				FieldInfo[] fields = typeof(PlayerStore).GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				foreach (FieldInfo fieldInfo in fields)
				{
					string text = fieldInfo.Name.ToLower();
					if (!text.Contains("cash") && !text.Contains("money") && !text.Contains("currency"))
					{
						continue;
					}
					object value = fieldInfo.GetValue(instance);
					if (value is long num)
					{
						if (num < 500)
						{
							return PlayerEconomy.Poor;
						}
						if (num < 5000)
						{
							return PlayerEconomy.Normal;
						}
						if (num < 20000)
						{
							return PlayerEconomy.Rich;
						}
						return PlayerEconomy.Loaded;
					}
					if (value is int num2)
					{
						if (num2 < 500)
						{
							return PlayerEconomy.Poor;
						}
						if (num2 < 5000)
						{
							return PlayerEconomy.Normal;
						}
						if (num2 < 20000)
						{
							return PlayerEconomy.Rich;
						}
						return PlayerEconomy.Loaded;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WagePowerPerk.SmartItem] 异常: " + ex.Message);
		}
		if (_totalPurchases < 10)
		{
			return PlayerEconomy.Poor;
		}
		if (_totalPurchases < 30)
		{
			return PlayerEconomy.Normal;
		}
		if (_totalPurchases < 80)
		{
			return PlayerEconomy.Rich;
		}
		return PlayerEconomy.Loaded;
	}

	private static PlayerLevel GetPlayerLevel()
	{
		if (_gameDay <= 7)
		{
			return PlayerLevel.Newbie;
		}
		if (_gameDay <= 21)
		{
			return PlayerLevel.Experienced;
		}
		if (_gameDay <= 50)
		{
			return PlayerLevel.Veteran;
		}
		return PlayerLevel.Legend;
	}

	private static PlayerReputation GetPlayerReputation()
	{
		int num = _totalPurchases - _inspectionCount * 5 - _contrabandSold * 3;
		if (num < 0)
		{
			return PlayerReputation.Shady;
		}
		if (num < 20)
		{
			return PlayerReputation.Neutral;
		}
		if (num < 60)
		{
			return PlayerReputation.Reputable;
		}
		return PlayerReputation.Legendary;
	}

	private static ItemCategory GetItemCategory(string itemId)
	{
		if (ItemCategoryMap.TryGetValue(itemId, out var value))
		{
			return value;
		}
		return ItemCategory.Unknown;
	}

	private static void RecordPurchase(string itemId)
	{
		try
		{
			ItemCategory itemCategory = GetItemCategory(itemId);
			if (!_purchaseStats.ContainsKey(itemCategory))
			{
				_purchaseStats[itemCategory] = 0;
			}
			_purchaseStats[itemCategory]++;
			_totalPurchases++;
			if (_totalPurchases % 10 == 0)
			{
				SaveState();
			}
		}
		catch
		{
		}
	}

	private static ItemCategory GetTopCategory()
	{
		ItemCategory result = ItemCategory.Unknown;
		int num = 0;
		foreach (KeyValuePair<ItemCategory, int> purchaseStat in _purchaseStats)
		{
			if (purchaseStat.Value > num && purchaseStat.Key != ItemCategory.Unknown)
			{
				num = purchaseStat.Value;
				result = purchaseStat.Key;
			}
		}
		return result;
	}

	internal static string SmartRandomItem()
	{
		try
		{
			ItemCategory topCategory = GetTopCategory();
			if (topCategory != ItemCategory.Unknown && _purchaseStats[topCategory] >= 3 && Core.Rng.Next(2) == 0)
			{
				List<string> list = new List<string>();
				string[] itemPool = ItemPool;
				foreach (string text in itemPool)
				{
					ItemCategory itemCategory = GetItemCategory(text);
					if (itemCategory == topCategory && (itemCategory != ItemCategory.Container || IsLootableContainer(text)))
					{
						list.Add(text);
					}
				}
				if (list.Count > 0)
				{
					return list[Core.Rng.Next(list.Count)];
				}
			}
			for (int j = 0; j < 20; j++)
			{
				string text2 = ItemPool[Core.Rng.Next(ItemPool.Length)];
				if (GetItemCategory(text2) != ItemCategory.Container || IsLootableContainer(text2))
				{
					return text2;
				}
			}
			return "raw_meat";
		}
		catch
		{
			for (int k = 0; k < 20; k++)
			{
				string text3 = ItemPool[Core.Rng.Next(ItemPool.Length)];
				if (GetItemCategory(text3) != ItemCategory.Container || IsLootableContainer(text3))
				{
					return text3;
				}
			}
			return "raw_meat";
		}
	}

	private static bool IsLootableContainer(string itemId)
	{
		switch (itemId)
		{
		case "evidence_box":
		case "sec_box":
		case "med_box":
		case "eng_box":
		case "service_box":
			return true;
		default:
			return false;
		}
	}

	private static GameItem CreateLootCrate(string itemId)
	{
		try
		{
			if (new Dictionary<string, string>
			{
				{ "evidence_box", "LootCrateEvidence" },
				{ "med_box", "LootCrateMedical" },
				{ "sec_box", "LootCrateSecurity" },
				{ "service_box", "LootCrateService" },
				{ "eng_box", "LootCrateEngineering" }
			}.TryGetValue(itemId, out var value))
			{
				MethodInfo method = typeof(PreBuiltItemHelper).GetMethod(value, BindingFlags.Static | BindingFlags.Public);
				if (method != null)
				{
					object? obj = method.Invoke(null, null);
					GameItem val = (GameItem)((obj is GameItem) ? obj : null);
					if (val != null)
					{
						try
						{
							LockHelper.LockUpContainer(val);
						}
						catch
						{
						}
						return val;
					}
				}
			}
			GameItem val2 = DirectoryMaster.Item(itemId, true);
			if (val2 != null)
			{
				try
				{
					List<GameItem> val3 = new List<GameItem>();
					string[] array = new string[4] { "raw_meat", "med_bottle_blue", "energy_credit", "morsel" };
					foreach (string text in array)
					{
						try
						{
							GameItem val4 = DirectoryMaster.Item(text, true);
							if (val4 != null)
							{
								val3.Add(val4);
							}
						}
						catch
						{
						}
					}
					DropTableFournitureDirectory.AddLootToFourniture(val2, val3);
				}
				catch (Exception ex)
				{
					Core.LogMsg("[WagePowerPerk.SmartItem] 异常: " + ex.Message);
				}
			}
			return val2;
		}
		catch (Exception ex2)
		{
			Core.LogMsg("[蛙哥牛逼] CreateLootCrate失败 " + itemId + ": " + ex2.Message);
			return null;
		}
	}

	private static long GetItemWholesalePrice(string itemId)
	{
		long num = (long)((double)GetItemBaseValue(itemId) * 0.6);
		if (num < 1)
		{
			num = 1L;
		}
		return num;
	}

	private static string[] GetItemBuyTags(string itemId)
	{
		if (_itemBuyTagsCache.TryGetValue(itemId, out var value))
		{
			return value;
		}
		List<string> list = new List<string>();
		try
		{
			if (DirectoryMaster.Has<GameItem>(itemId))
			{
				GameItem val = DirectoryMaster.Item(itemId, false);
				if (val != null)
				{
					FieldInfo field = ((object)val).GetType().GetField("tagSystem", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if (field == null)
					{
						field = ((object)val).GetType().GetField("myTags", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					}
					if (field != null)
					{
						object value2 = field.GetValue(val);
						if (value2 != null)
						{
							PropertyInfo property = value2.GetType().GetProperty("dict", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
							if (property != null && property.GetValue(value2) is IDictionary dictionary)
							{
								foreach (DictionaryEntry item in dictionary)
								{
									string text = item.Key?.ToString() ?? "";
									if (string.IsNullOrEmpty(text) || _nonBuyTagBlacklist.Contains(text) || text.StartsWith("TAG_") || text.StartsWith("tag_") || text.StartsWith("ITEM_"))
									{
										continue;
									}
									bool flag = false;
									try
									{
										object value3 = item.Value;
										if (value3 != null)
										{
											MethodInfo method = value3.GetType().GetMethod("IsEnabled");
											if (method != null)
											{
												flag = (bool)method.Invoke(value3, null);
											}
										}
									}
									catch
									{
										flag = false;
									}
									if (flag && !list.Contains(text))
									{
										list.Add(text);
									}
								}
							}
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WagePowerPerk.SmartItem] 异常: " + ex.Message);
		}
		if (list.Count == 0)
		{
			ItemCategory itemCategory = GetItemCategory(itemId);
			if (CategoryBuyTagFallback.TryGetValue(itemCategory, out var value4))
			{
				list.AddRange(value4);
			}
		}
		_itemBuyTagsCache[itemId] = list.ToArray();
		return list.ToArray();
	}

	internal static void EnsureBuyTagsForClient(StoreClient client)
	{
		//IL_0004: Unknown result type (might be due to invalid IL or missing references)
		//IL_000a: Invalid comparison between Unknown and I4
		try
		{
			if (client == null || (int)client.clientIntent != 1)
			{
				return;
			}
			try
			{
				if (client.clientBuyingTagList != null)
				{
					string.Join(",", Il2CppArrayBase<string>.op_Implicit(client.clientBuyingTagList.ToArray()));
				}
				if (client.clientBuyingIdList != null)
				{
					string.Join(",", Il2CppArrayBase<string>.op_Implicit(client.clientBuyingIdList.ToArray()));
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[WagePowerPerk.SmartItem] 异常: " + ex.Message);
			}
			if (client.clientBuyingTagList != null && client.clientBuyingTagList.Count > 0)
			{
				return;
			}
			List<string> list = new List<string>();
			if (client.clientBuyingIdList != null)
			{
				Enumerator<string> enumerator = client.clientBuyingIdList.GetEnumerator();
				while (enumerator.MoveNext())
				{
					string current = enumerator.Current;
					if (!string.IsNullOrEmpty(current) && !list.Contains(current))
					{
						list.Add(current);
					}
				}
			}
			if (list.Count == 0)
			{
				SetRandomBuyItems(client);
				return;
			}
			List<string> list2 = new List<string>();
			foreach (string item2 in list)
			{
				try
				{
					string[] itemBuyTags = GetItemBuyTags(item2);
					foreach (string item in itemBuyTags)
					{
						if (!list2.Contains(item))
						{
							list2.Add(item);
						}
					}
				}
				catch (Exception ex2)
				{
					Core.LogMsg("[WagePowerPerk.SmartItem] 异常: " + ex2.Message);
				}
			}
			if (client.clientBuyingTagList == null)
			{
				client.clientBuyingTagList = new List<string>();
			}
			else
			{
				client.clientBuyingTagList.Clear();
			}
			foreach (string item3 in list2)
			{
				client.clientBuyingTagList.Add(item3);
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[蛙哥牛逼] EnsureBuyTagsForClient异常: " + ex3.Message);
		}
	}

	internal static void SetRandomBuyItems(StoreClient client)
	{
		try
		{
			int num = Core.Rng.Next(3, 7);
			List<string> list = new List<string>();
			for (int i = 0; i < num; i++)
			{
				string text = ItemPool[Core.Rng.Next(ItemPool.Length)];
				if (DirectoryMaster.Has<GameItem>(text) && !list.Contains(text))
				{
					list.Add(text);
				}
			}
			if (list.Count == 0)
			{
				list.Add("raw_meat");
				list.Add("morsel");
			}
			if (client.clientBuyingIdList == null)
			{
				client.clientBuyingIdList = new List<string>();
			}
			else
			{
				client.clientBuyingIdList.Clear();
			}
			foreach (string item2 in list)
			{
				client.clientBuyingIdList.Add(item2);
			}
			try
			{
				List<string> list2 = new List<string>();
				foreach (string item3 in list)
				{
					string[] itemBuyTags = GetItemBuyTags(item3);
					foreach (string item in itemBuyTags)
					{
						if (!list2.Contains(item))
						{
							list2.Add(item);
						}
					}
				}
				if (client.clientBuyingTagList == null)
				{
					client.clientBuyingTagList = new List<string>();
				}
				else
				{
					client.clientBuyingTagList.Clear();
				}
				foreach (string item4 in list2)
				{
					client.clientBuyingTagList.Add(item4);
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[蛙哥牛逼] 设置需求标签失败: " + ex.Message);
			}
		}
		catch
		{
		}
	}
