			{
				return 0;
			}
		}
	}

	internal static bool HasPendingChange => _dirty;

	internal static string GetString(string ns, string key, string def = "")
	{
		try
		{
			string key2 = ns + "." + key;
			if (_mem.TryGetValue(key2, out var value))
			{
				return value;
			}
			EnsureLegacyFresh();
			if (LegacyHasKey(ns, key))
			{
				string text = LegacyGetString(ns, key, def);
				_mem[key2] = text;
				_dirty = true;
				return text;
			}
			return def;
		}
		catch
		{
			return def;
		}
	}

