	internal static void ClearNamespace(string ns)
	{
		try
		{
			string value = ns + ".";
			List<string> list = new List<string>();
			foreach (string key in _mem.Keys)
			{
				if (key.StartsWith(value))
				{
					list.Add(key);
				}
			}
			foreach (string item in list)
			{
				_mem.Remove(item);
			}
			if (list.Count > 0)
			{
				_dirty = true;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageSaveStore] 异常: " + ex.Message);
		}
	}

