			return LegacyHasKey(ns, key);
		}
		catch
		{
			return false;
		}
	}

	internal static void ResetForNewRun()
	{
		try
		{
			ClearMem();
			string text = FilePathFor("pending");
			if (text != null && File.Exists(text))
			{
				File.Delete(text);
			}
