	private static void ClearMem()
	{
		try
		{
			_mem.Clear();
		}
		catch
		{
		}
	}

	private static string FilePathFor(string key)
	{
		try
		{
			string dirPath = DirPath;
			if (string.IsNullOrEmpty(dirPath))
			{
				return null;
			}
			return Path.Combine(dirPath, "wages_data_" + key + ".txt");
		}
		catch
		{
			return null;
		}
	}

	internal static string Serialize()
	{
		try
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("#storeVersion=1").Append('\n');
			stringBuilder.Append("#runID=").Append(GetRunIdRaw() ?? "").Append('\n');
			stringBuilder.Append("#saved=").Append(DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")).Append('\n');
			foreach (KeyValuePair<string, string> item in _mem)
			{
				stringBuilder.Append(item.Key).Append('=').Append((item.Value ?? "").Replace('\n', ' '))
					.Append('\n');
			}
			return stringBuilder.ToString();
		}
		catch
		{
			return "";
		}
	}

	internal static void Deserialize(string content)
	{
		try
		{
			if (string.IsNullOrEmpty(content))
			{
				return;
			}
			string[] array = content.Split('\n');
			for (int i = 0; i < array.Length; i++)
			{
				string text = array[i].TrimEnd('\r');
				if (text.Length != 0 && text[0] != '#')
				{
					int num = text.IndexOf('=');
					if (num > 0)
					{
						_mem[text.Substring(0, num)] = text.Substring(num + 1);
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageSaveStore] 异常: " + ex.Message);
		}
	}

	private static void ReadInto(string path)
	{
		Dictionary<string, string> dictionary = new Dictionary<string, string>(_mem);
		_mem.Clear();
		Deserialize(File.ReadAllText(path, Encoding.UTF8));
		foreach (KeyValuePair<string, string> item in dictionary)
		{
			_mem[item.Key] = item.Value;
		}
		if (dictionary.Count > 0)
		{
			_dirty = true;
		}
	}

	internal static void Flush()
	{
		try
		{
			string text = ResolveKey();
			string text2 = FilePathFor(text);
			if (string.IsNullOrEmpty(text2))
			{
				return;
			}
			string dirPath = DirPath;
			if (!Directory.Exists(dirPath))
			{
				Directory.CreateDirectory(dirPath);
			}
			string text3 = text2 + ".tmp";
			File.WriteAllText(text3, Serialize(), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
			if (File.Exists(text2))
			{
				File.Delete(text2);
			}
			File.Move(text3, text2);
			if (text != "pending")
			{
				string text4 = FilePathFor("pending");
				if (text4 != null && File.Exists(text4))
				{
					File.Delete(text4);
				}
			}
			_dirty = false;
			_curKey = text;
			Core.LogMsg("[SaveStore] 已落盘 " + text + "（" + _mem.Count + " 项）");
		}
		catch (Exception ex)
		{
			Core.LogMsg("[SaveStore] 落盘失败: " + ex.Message);
		}
	}

	internal static bool ValidateRunId()
	{
		try
		{
			string text = ResolveKey();
			if (text == "pending")
			{
				return true;
			}
			return _curKey == text;
		}
		catch
		{
			return true;
		}
	}

	internal static bool ValidateAfterLoad()
	{
		try
		{
			if (!ValidateRunId())
			{
				Core.LogMsg("[SaveStore] 校验失败：runID 不一致（串档风险）");
				return false;
			}
			foreach (string key in _mem.Keys)
			{
				if (string.IsNullOrEmpty(key) || key.IndexOf('.') <= 0)
				{
					Core.LogMsg("[SaveStore] 校验失败：异常 key「" + key + "」");
					return false;
				}
			}
			return true;
		}
		catch
		{
			return false;
		}
	}

	internal static string GetRunIdRaw()
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			return (instance != null) ? (instance.runID ?? "") : "";
		}
		catch
		{
			return "";
		}
	}

	private static string ResolveKey()
	{
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null)
			{
				string runID = instance.runID;
				if (!string.IsNullOrEmpty(runID))
				{
					return Sanitize(runID);
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageSaveStore] 异常: " + ex.Message);
		}
		return "pending";
	}

	private static string Sanitize(string raw)
	{
		if (string.IsNullOrEmpty(raw))
		{
			return "pending";
		}
		StringBuilder stringBuilder = new StringBuilder(raw.Length);
		foreach (char c in raw)
		{
			if (char.IsLetterOrDigit(c) || c == '_' || c == '-')
			{
				stringBuilder.Append(c);
			}
			else
			{
				stringBuilder.Append('_');
			}
		}
		string text = stringBuilder.ToString();
		if (text.Length <= 64)
		{
			return text;
		}
		return text.Substring(0, 64);
	}

	private static void EnsureLegacyFresh()
	{
		try
		{
			_legacyRunId = null;
		}
		catch
		{
		}
	}

	private static string LegacyGetRunId()
	{
		if (!string.IsNullOrEmpty(_legacyRunId))
		{
			return _legacyRunId;
		}
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null)
			{
				string text = instance.runID ?? "";
				if (!string.IsNullOrEmpty(text))
				{
					_legacyRunId = text;
					return text;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageSaveStore] 异常: " + ex.Message);
		}
		return "default_run";
	}

	private static string LegacyKey(string perkId, string key)
	{
		return "WagesPerks_" + LegacyGetRunId() + "_" + perkId + "_" + key;
	}

	private static string LegacyDefaultKey(string perkId, string key)
	{
		return "WagesPerks_default_run_" + perkId + "_" + key;
	}

	private static bool LegacyHasKey(string perkId, string key)
	{
		try
		{
			if (PlayerPrefs.HasKey(LegacyKey(perkId, key)))
			{
				return true;
			}
			return PlayerPrefs.HasKey(LegacyDefaultKey(perkId, key));
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageSaveStore] 异常: " + ex.Message);
		}
		return false;
	}

	private static string LegacyGetString(string perkId, string key, string defaultValue = "")
	{
		try
		{
			string text = LegacyKey(perkId, key);
			if (PlayerPrefs.HasKey(text))
			{
				return PlayerPrefs.GetString(text, defaultValue);
			}
			string text2 = LegacyDefaultKey(perkId, key);
			if (PlayerPrefs.HasKey(text2))
			{
				string text3 = PlayerPrefs.GetString(text2, defaultValue);
				try
				{
					PlayerPrefs.SetString(text, text3 ?? "");
					PlayerPrefs.DeleteKey(text2);
					PlayerPrefs.Save();
				}
				catch
				{
				}
				return text3;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageSaveStore] 异常: " + ex.Message);
		}
		return defaultValue;
	}

