	internal static void CleanLegacyDefaultRun(string perkId, string[] keys)
	{
		try
		{
			if (keys == null)
			{
				return;
			}
			foreach (string key in keys)
			{
				string text = LegacyDefaultKey(perkId, key);
				if (PlayerPrefs.HasKey(text))
				{
					PlayerPrefs.DeleteKey(text);
				}
			}
			PlayerPrefs.Save();
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageSaveStore] 异常: " + ex.Message);
		}
	}

	public static void PostfixSaveGame()
	{
		Flush();
	}

	internal static void OnLoadGame()
	{
		try
		{
			ClearMem();
			_loadingComplete = false;
			_pendingLoad = true;
			_pendingLoadFrames = 0;
			_loadedOnce = false;
			TryDoLoad();
			Core.LogMsg("[SaveStore] 读档挂点触发，键值" + (_loadedOnce ? "已同步加载" : "待轮询补读"));
		}
		catch (Exception ex)
		{
			Core.LogMsg("[WageSaveStore] 异常: " + ex.Message);
		}
	}

	internal static void LoadIfPending()
	{
		if (!_pendingLoad)
		{
			return;
		}
		try
		{
			if (!_loadedOnce)
			{
				TryDoLoad();
				if (!_loadedOnce)
				{
					return;
				}
			}
			if (++_pendingLoadFrames < 30)
			{
				return;
			}
			_pendingLoad = false;
			try
			{
				CustomStartingPerks.NotifyGameLoaded();
			}
			catch (Exception ex)
			{
				Core.LogMsg("[SaveStore] OnGameLoaded 驱动失败: " + ex.Message);
			}
			try
			{
				EmporiumEntry instance = EmporiumEntry.Instance;
				if (!((Object)(object)instance != (Object)null))
				{
					return;
				}
				Enumerator<GameItem> enumerator = instance.GetAllItems().GetEnumerator();
				while (enumerator.MoveNext())
				{
					GameItem current = enumerator.Current;
					try
					{
						if (current != null && current.IsTag("wage_washed") && ContrabandHelper.GetContrabandLevel(current) > 0)
						{
							ContrabandHelper.RemoveContrabandStatus(current);
							Core.LogMsg("[蛙娘] 读档防御重洗白: " + current.identifier);
						}
					}
					catch
					{
					}
				}
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[蛙娘] 读档重洗白扫描异常: " + ex2.Message);
			}
		}
		catch (Exception ex3)
		{
			_pendingLoad = false;
			Core.LogMsg("[SaveStore] 加载失败: " + ex3.Message);
		}
	}

	private static bool TryDoLoad()
	{
		try
		{
			string text = ResolveKey();
			if (text == "pending")
			{
				return false;
			}
			string text2 = FilePathFor(text);
			if (text2 == null || !File.Exists(text2))
			{
				string text3 = FilePathFor("pending");
				if (text3 != null && File.Exists(text3))
				{
					ReadInto(text3);
					File.Delete(text3);
					_curKey = text;
					_loadedOnce = true;
					_loadingComplete = true;
					Core.LogMsg("[SaveStore] 正式文件未建立，已从 pending 并入（" + _mem.Count + " 项）");
					return true;
				}
				Core.LogMsg("[SaveStore] 无存档文件（新档）：" + text);
				_curKey = text;
				_loadedOnce = true;
				_loadingComplete = true;
				return true;
			}
			ReadInto(text2);
			_curKey = text;
			_loadedOnce = true;
			_loadingComplete = true;
			Core.LogMsg("[SaveStore] 已加载 " + text + "（" + _mem.Count + " 项）");
			return true;
		}
		catch
		{
			return false;
		}
	}
}
internal sealed class WandererPerk : CustomStartingPerk
{
	internal const string PerkId = "流浪者";

	private static readonly string[] TOOL_IDS = new string[10] { "screwdriver", "welder", "wire_cutter", "flashlight", "toolbox", "aquascan", "uv_filter", "metal_scanner", "aug_scanner", "black_lamp" };

	private static readonly string[] HOUSEHOLD_IDS = new string[13]
	{
		"cigarette_color", "shampoo", "toothpaste", "paper_towel", "toilet_paper", "box_tampon", "pack_condom", "packet_red_cigarette", "skincare_cream", "neuroactive_perfume",
		"pheromone_perfume", "salve", "rubbing_alcohol"
	};

	private static readonly string[] DOCUMENT_IDS = new string[9] { "tutorial_book", "wanted_paper", "joe_card", "cigarette_guide", "stamp_guide", "logo_checker", "mentor_note", "mentor_notes", "tutorial_note" };

	internal override string Id => "流浪者";

	internal override string DisplayName => LangHelper.T("流浪者", "Wanderer");

	internal override string Description => LangHelper.T("你两手空空地来到空间站——开局现金随机（可能一文不名，也可能小有积蓄），随身只有 6 件随机物品（必含 1 件工具 + 1 件日用品），原版开局物资不会给你。", "You arrive at the station empty-handed - starting cash is random (maybe nothing, maybe a little), and you carry only 6 random items (1 tool + 1 household item included). Original starting supplies are not given.");

	internal override int Cost => 0;

	internal override int Type => 2;

	internal override void OnNewGame()
	{
	}

	internal static bool IsActive()
	{
		return Core.PerkActive("流浪者");
	}

	private static bool IsDocumentId(string id)
	{
		if (string.IsNullOrEmpty(id))
		{
			return true;
		}
		string text = id.ToLowerInvariant();
		if (Array.IndexOf(DOCUMENT_IDS, text) >= 0)
		{
			return true;
		}
		if (!text.Contains("book") && !text.Contains("guide") && !text.Contains("paper") && !text.Contains("note"))
		{
			return text.Contains("mentor");
		}
		return true;
	}

	public static void PostfixStartNewGame()
	{
		try
		{
			if (!IsActive())
			{
				return;
			}
			PlayerStore instance = PlayerStore.Instance;
			if (instance != null && !Core.PerkActive("声名狼藉"))
			{
				if (Core.Rng.Next(2) == 0)
				{
					instance.playerCash = 0;
				}
				else
				{
					instance.playerCash = Core.Rng.Next(1, 601);
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[流浪者] PostfixStartNewGame 异常: " + ex.Message);
		}
	}

	public static void PostfixHandleSkipIntro()
	{
		try
		{
			if (IsActive())
			{
				ClearBackpack();
				GiveRandomItems();
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[流浪者] PostfixHandleSkipIntro 异常: " + ex.Message);
		}
	}

	internal static void GiveRandomItems()
	{
		try
		{
			string text = RandomFromPool(TOOL_IDS);
			string text2 = RandomFromPool(HOUSEHOLD_IDS);
			if (text != null)
			{
				GiveToBackpack(text);
			}
			if (text2 != null)
			{
				GiveToBackpack(text2);
			}
			List<string> list = new List<string>(WagePowerPerk.ItemPool ?? new string[0]);
			int num = 0;
			int num2 = 0;
			while (num < 4 && list.Count > 0 && num2 < 20)
			{
				num2++;
				int index = Core.Rng.Next(list.Count);
				string text3 = list[index];
				list.RemoveAt(index);
				if (!(text3 == "topical_bandage_item") && !(text3 == "fanny_pack") && !IsDocumentId(text3) && GiveToBackpack(text3) != null)
				{
					num++;
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[NewTraits] 异常: " + ex.Message);
		}
	}

	private static string RandomFromPool(string[] pool)
	{
		if (pool == null || pool.Length == 0)
		{
			return null;
		}
		List<string> list = new List<string>(pool);
		while (list.Count > 0)
		{
			int index = Core.Rng.Next(list.Count);
			string text = list[index];
			list.RemoveAt(index);
			try
			{
				if (DirectoryMaster.Item(text, true) != null)
				{
					return text;
				}
			}
			catch
			{
			}
		}
		return null;
	}

	private static List<string> GetAllItemIds()
	{
		List<string> list = new List<string>();
		try
		{
			List<string> identifierList = DirectoryMaster.GetIdentifierList<GameItem>((string)null);
			if (identifierList != null)
			{
				for (int i = 0; i < identifierList.Count; i++)
				{
					string text = identifierList[i];
					if (!string.IsNullOrEmpty(text) && Array.IndexOf(TOOL_IDS, text) < 0 && Array.IndexOf(HOUSEHOLD_IDS, text) < 0 && !IsDocumentId(text) && Array.IndexOf(Core.ExcludedItemIds, text) < 0)
					{
						list.Add(text);
					}
				}
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[NewTraits] 异常: " + ex.Message);
		}
		return list;
	}

	private static string SafeId(GameItem it)
	{
		try
		{
			if (it == null)
			{
				return "null";
			}
			string identifier = it.identifier;
			if (!string.IsNullOrEmpty(identifier))
			{
				return identifier;
			}
		}
		catch
		{
		}
		try
		{
			string name = it.name;
			if (!string.IsNullOrEmpty(name))
			{
				return name;
			}
		}
		catch
		{
		}
		return "?";
	}

	private static GameItem GiveToBackpack(string id)
	{
		try
		{
			GameItem val = DirectoryMaster.Item(id, true);
			if (val == null)
			{
				return null;
			}
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null || instance.invElement == null)
			{
				return null;
			}
			SlotMarker val2 = instance.invElement.TryFindOneValidInventorySlot(val, false);
			if (val2 != null)
			{
				try
				{
					val2.TryAcceptOnce(-1);
					return val;
				}
				catch
				{
				}
			}
			try
			{
				List<GameItem> val3 = new List<GameItem>();
				val3.Add(val);
				((GameInventory)instance.invElement).UncheckedAcceptAll(val3);
			}
			catch
			{
			}
			return val;
		}
		catch
		{
			return null;
		}
	}

	private static bool ShouldClear(GameItem it)
	{
		try
		{
			string identifier = it.identifier;
			if (string.IsNullOrEmpty(identifier))
			{
				return false;
			}
			switch (identifier)
			{
			case "magnifier":
			case "labeler":
			case "topical_bandage_item":
			case "fanny_pack":
				return true;
			default:
				if (Array.IndexOf(DOCUMENT_IDS, identifier) >= 0)
				{
					return true;
				}
				return false;
			}
		}
		catch
		{
			return false;
		}
	}

	internal static void ClearBackpack()
	{
		try
		{
			EmporiumEntry instance = EmporiumEntry.Instance;
			if ((Object)(object)instance == (Object)null)
			{
				return;
			}
			List<GameInventory> list = new List<GameInventory>();
			try
			{
				GameInventory invElement = (GameInventory)(object)instance.invElement;
				if (invElement != null)
				{
					list.Add(invElement);
				}
			}
			catch
			{
			}
			try
			{
				GameInventory backInvinvElement = (GameInventory)(object)instance.backInvinvElement;
				if (backInvinvElement != null)
				{
					list.Add(backInvinvElement);
				}
			}
			catch
			{
			}
			try
			{
				GameItem dossier = instance.dossier;
				if (dossier != null)
				{
					GameInventory innerInventory = AddictOfficerEvent.GetInnerInventory(dossier);
					if (innerInventory != null)
					{
						list.Add(innerInventory);
					}
				}
			}
			catch (Exception ex)
			{
				Core.LogMsg("[NewTraits] 异常: " + ex.Message);
			}
			foreach (GameInventory item in list)
			{
				if (item == null || item.childItems == null)
				{
					continue;
				}
				for (int num = item.childItems.Count - 1; num >= 0; num--)
				{
					try
					{
						GameItem val = item.childItems[num];
						if (val == null)
						{
							try
							{
								item.childItems.RemoveAt(num);
							}
							catch
							{
							}
						}
						else if (ShouldClear(val))
						{
							try
							{
								val.Destroy();
							}
							catch
							{
							}
							try
							{
								item.childItems.RemoveAt(num);
							}
							catch
							{
							}
						}
					}
					catch (Exception ex2)
					{
						Core.LogMsg("[NewTraits] 异常: " + ex2.Message);
					}
				}
			}
		}
		catch (Exception ex3)
		{
			Core.LogMsg("[NewTraits] 异常: " + ex3.Message);
		}
	}
}
