internal static class DetectiveUpgradePatch
{
	internal static bool _blockNextResetCrime;

	private static int _evidenceBefore;

	private static List<string> _typesBefore;

	private static List<int> _amountsBefore;

	private static List<int> _totalsBefore;

	public static bool Prefix(NetworkUpgrade __instance)
	{
		try
		{
			bool flag = false;
			try
			{
				flag = DetectivePerk.IsActive();
			}
			catch (Exception ex)
			{
				Core.LogMsg("[狄仁杰之手] IsActive异常: " + ex.Message);
			}
			string text = "?";
			try
			{
				text = __instance.id;
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[狄仁杰之手] 读id异常: " + ex2.Message);
			}
			Core.LogMsg($"[狄仁杰之手] Unlock触发 id={text} 狄仁杰={flag}");
			if (flag && string.Equals(text, "EVIDENCE_REMOVAL", StringComparison.OrdinalIgnoreCase))
			{
				_blockNextResetCrime = true;
				try
				{
					PlayerStore instance = PlayerStore.Instance;
					SecData val = ((instance != null) ? instance.secData : null);
					if (val != null)
					{
						_evidenceBefore = val.evidenceLevel;
						_typesBefore = new List<string>();
						_amountsBefore = new List<int>();
						_totalsBefore = new List<int>();
						if (val.crimeTypes != null)
						{
							int count = val.crimeTypes.Count;
							for (int i = 0; i < count; i++)
							{
								_typesBefore.Add(val.crimeTypes[i]);
							}
						}
						if (val.crimeAmount != null)
						{
							int count2 = val.crimeAmount.Count;
							for (int j = 0; j < count2; j++)
							{
								_amountsBefore.Add(val.crimeAmount[j]);
							}
						}
						if (val.crimeAmountTotal != null)
						{
							int count3 = val.crimeAmountTotal.Count;
							for (int k = 0; k < count3; k++)
							{
								_totalsBefore.Add(val.crimeAmountTotal[k]);
							}
						}
						Core.LogMsg($"[狄仁杰之手] 快照: evidence={_evidenceBefore} types={_typesBefore.Count} amts={_amountsBefore.Count} totals={_totalsBefore.Count}");
					}
					else
					{
						Core.LogMsg("[狄仁杰之手] 快照失败: secData 为空");
					}
				}
				catch (Exception ex3)
				{
					Core.LogMsg("[狄仁杰之手] 快照异常: " + ex3.Message);
				}
			}
		}
		catch (Exception ex4)
		{
			Core.LogMsg("[狄仁杰之手] Unlock Prefix异常: " + ex4.Message);
		}
		return true;
	}

	public static void Postfix(NetworkUpgrade __instance)
	{
		if (!_blockNextResetCrime)
		{
			return;
		}
		_blockNextResetCrime = false;
		try
		{
			PlayerStore instance = PlayerStore.Instance;
			SecData val = ((instance != null) ? instance.secData : null);
			if (val == null)
			{
				Core.LogMsg("[狄仁杰之手] Postfix恢复失败: secData 为空");
				return;
			}
			if (_typesBefore != null && val.crimeTypes != null)
			{
				val.crimeTypes.Clear();
				foreach (string item in _typesBefore)
				{
					val.crimeTypes.Add(item);
				}
			}
			if (_amountsBefore != null && val.crimeAmount != null)
			{
				val.crimeAmount.Clear();
				foreach (int item2 in _amountsBefore)
				{
					val.crimeAmount.Add(item2);
				}
			}
			if (_totalsBefore != null && val.crimeAmountTotal != null)
			{
				val.crimeAmountTotal.Clear();
				foreach (int item3 in _totalsBefore)
				{
					val.crimeAmountTotal.Add(item3);
				}
			}
			int evidenceBefore = _evidenceBefore;
			val.evidenceLevel = Math.Max(0, Math.Min(100, evidenceBefore));
			Core.LogMsg($"[狄仁杰之手] Unlock 后证据已恢复: evidenceLevel={val.evidenceLevel} types={val.crimeTypes?.Count} amts={val.crimeAmount?.Count}");
		}
		catch (Exception ex)
		{
			Core.LogMsg("[狄仁杰之手] Postfix恢复异常: " + ex.Message);
		}
	}
}
