			{
				flag = ContrabandHelper.GetContrabandLevel(val) > 0;
			}
			catch (Exception ex2)
			{
				Core.LogMsg("[销赃证据] GetContrabandLevel异常: " + ex2.Message);
			}
			bool flag2 = false;
			try
			{
				flag2 = StolenHelper.IsStolenItem(val);
			}
			catch (Exception ex3)
			{
				Core.LogMsg("[销赃证据] IsStolenItem异常: " + ex3.Message);
			}
			Core.LogMsg($"[销赃证据] 卖出触发: {val.name} contraband={flag} stolen={flag2}");
			if (!flag && !flag2)
			{
				return;
			}
			long num = 0L;
			try
			{
				num = val.GetCurrentValue(false, true, true, false, 0L);
			}
			catch
			{
				try
				{
					num = val.GetValue((List<GameCharacterItem>)null, (GameCharacterItem)null, false);
				}
				catch
				{
				}
			}
			_soldToday += (int)num;
			Core.LogMsg($"[销赃证据] 卖出违禁/赃物: {val.name} 值={num} 当日累计={_soldToday}");
		}
		catch (Exception ex4)
		{
			Core.LogMsg("[销赃证据] SellItem Postfix异常: " + ex4.Message);
		}
	}
}
internal static class SoldEvidenceOnNewDayPatch
{
	public static void Postfix(SecData __instance)
	{
		try
		{
			if (DetectivePerk.IsActive() && __instance != null)
			{
				int soldToday = SoldContrabandCounterPatch._soldToday;
				int num = soldToday / 5000 * 15;
				if (num > 0)
				{
					int evidenceLevel = __instance.evidenceLevel;
					__instance.evidenceLevel = Math.Min(100, evidenceLevel + num);
					Core.LogMsg($"[销赃证据] 打烊: 当日销赃={soldToday} → 证据 +{num}（{evidenceLevel} → {__instance.evidenceLevel}）");
				}
				SoldContrabandCounterPatch._soldToday = 0;
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[销赃证据] OnNewDay Postfix异常: " + ex.Message);
		}
	}
}
internal sealed class WineLoverPerk : CustomStartingPerk
{
	internal const string PerkId = "好酒之徒";

	private static bool _hungover;

	internal override string Id => "好酒之徒";

	internal override string DisplayName => LangHelper.T("好酒之徒", "Wine Lover");

	internal override string Description => LangHelper.T("内行懂酒，酒类买卖价+25%，客户觉得你是懂行的人。但代价是打烊后可能'宿醉'：次日-1客户或议价-10%。白天懂酒，晚上头痛。", "Alcohol connoisseur. Alcohol price +25 percent. Possible hangover after closing.");

	internal override int Cost => 1;

	internal override int Type => 2;

	internal override void OnNewGame()
	{
		_hungover = false;
	}

	internal override void OnDayStart()
	{
		if (IsActive() && _hungover)
		{
			try
			{
				NotifyHelper.NightLogRaw("好酒之徒：你昨晚宿醉了，今日客户预算-10%。");
			}
			catch
			{
			}
			ClearHangover();
		}
	}

	internal static bool IsActive()
	{
		return Core.PerkActive("好酒之徒");
	}

	public static float GetAlcoholPriceBonus()
	{
		if (!IsActive())
		{
			return 1f;
		}
		return 1.25f;
	}

	public static bool IsHungover()
	{
		return _hungover;
	}

	public static void RollHangover()
	{
		if (!IsActive())
		{
			return;
		}
		int dayCounter = StoreStation.GetDayCounter();
		if (!DeterministicRandom.NextBool("wine_lover_hangover", dayCounter, 0.3))
		{
			return;
		}
		_hungover = true;
		try
		{
			WageSaveStore.SetBool("好酒之徒", "hungover", value: true);
		}
		catch
		{
		}
	}

	public static void ClearHangover()
	{
		if (_hungover)
		{
			_hungover = false;
			try
			{
				WageSaveStore.SetBool("好酒之徒", "hungover", value: false);
			}
			catch
			{
			}
		}
	}

	public static void LoadHangoverState()
	{
		try
		{
			if (WageSaveStore.HasKey("好酒之徒", "hungover"))
			{
				_hungover = WageSaveStore.GetBool("好酒之徒", "hungover");
			}
		}
		catch (Exception ex)
		{
			Core.LogMsg("[NewTraits] 异常: " + ex.Message);
		}
	}
}
